def _direct_member_median_run_bounds(
    duration_seconds: float,
) -> tuple[float, float]:
    """Use section-level cadence for a bounded quality-proof render.

    A short excerpt can consist almost entirely of a chorus/build interval.
    Requiring the full-song 3.5-second median there contradicts the existing
    1.8-second highlight shot floor and can erase every proof-directed cut
    repair. Switch density, maximum hold, source balance, content validity,
    and transition continuity remain independently enforced.
    """

    if duration_seconds <= _DIRECT_MEMBER_SHORT_PROOF_MAXIMUM_DURATION_SECONDS:
        return (
            _DIRECT_MEMBER_HIGHLIGHT_MINIMUM_RUN_SECONDS,
            _DIRECT_MEMBER_MAX_MEDIAN_RUN_SECONDS,
        )
    return (
        _DIRECT_MEMBER_MIN_MEDIAN_RUN_SECONDS,
        _DIRECT_MEMBER_MAX_MEDIAN_RUN_SECONDS,
    )


def _direct_member_median_run_is_valid(
    duration_seconds: float,
    median_run_seconds: float,
) -> bool:
    minimum, maximum = _direct_member_median_run_bounds(duration_seconds)
    return minimum <= median_run_seconds <= maximum


def _direct_member_editorial_motion_config_from_visual_config(
    visual_config: DirectMemberVisualConfig,
) -> DirectMemberEditorialMotionConfig:
    """Build the exact dense-render camera contract used by production."""

    return DirectMemberEditorialMotionConfig(
        maximum_boundary_zoom=(
            visual_config.transform_repair_maximum_zoom
        ),
        maximum_boundary_upscale_ratio=(
            visual_config.transform_repair_maximum_upscale_ratio
        ),
        maximum_center_shift=(
            visual_config.transform_repair_maximum_center_shift
        ),
        maximum_boundary_center_distance=(
            visual_config.transform_repair_maximum_boundary_center_distance
        ),
        maximum_residual_center_distance=(
            visual_config.transform_repair_maximum_residual_center_distance
        ),
        minimum_mismatch_improvement_fraction=(
            visual_config.transform_repair_minimum_improvement_fraction
        ),
        minimum_face_visible_fraction=(
            visual_config.transform_repair_minimum_face_visible_fraction
        ),
        legacy_face_only_maximum_zoom=(
            visual_config.transform_repair_legacy_face_only_maximum_zoom
        ),
        legacy_face_only_maximum_center_shift=(
            visual_config.transform_repair_legacy_face_only_maximum_center_shift
        ),
        minimum_widened_subject_confidence=(
            visual_config.transform_repair_minimum_subject_confidence
        ),
        enable_interior_zoom_pulses=True,
        allow_partial_required_boundary_matches=True,
    )


def _direct_member_required_transform_resolution(
    required_boundary_indices: Sequence[int],
    accepted_boundary_indices: Sequence[int],
    natural_match_boundary_indices: Sequence[int],
) -> tuple[tuple[int, ...], tuple[int, ...]]:
    """Split required camera candidates without changing cut feasibility."""

    required = set(required_boundary_indices)
    resolved = required.intersection(accepted_boundary_indices).union(
        required.intersection(natural_match_boundary_indices)
    )
    return tuple(sorted(resolved)), tuple(sorted(required.difference(resolved)))


def _direct_member_focal_boundary_reference_mapping(
    source_indices: Sequence[int],
    captured_references: Sequence[
        tuple[
            int,
            int,
            FocalFaceCandidate | None,
            FocalFaceCandidate | None,
        ]
    ],
) -> dict[int, tuple[FocalFaceCandidate, FocalFaceCandidate]]:
    """Bind each transient dense face pair to its exact edit boundary."""

    source_path = tuple(int(value) for value in source_indices)
    cross_source_boundary_indices = tuple(
        boundary_index
        for boundary_index, (left, right) in enumerate(
            zip(source_path, source_path[1:])
        )
        if left != right
    )
    captures = tuple(captured_references)
    if len(captures) != len(cross_source_boundary_indices):
        raise ValueError(
            "dense focal boundary capture does not cover the selected source path"
        )
    resolved: dict[int, tuple[FocalFaceCandidate, FocalFaceCandidate]] = {}
    for boundary_index, captured in zip(
        cross_source_boundary_indices,
        captures,
        strict=True,
    ):
        (
            captured_left_source,
            captured_right_source,
            captured_left_reference,
            captured_right_reference,
        ) = captured
        if (
            captured_left_source != source_path[boundary_index]
            or captured_right_source != source_path[boundary_index + 1]
        ):
            raise ValueError(
                "dense focal boundary capture source path disagrees with the "
                "selected edit"
            )
        if (
            captured_left_reference is not None
            and captured_right_reference is not None
        ):
            resolved[boundary_index] = (
                captured_left_reference,
                captured_right_reference,
            )
    return resolved


@dataclass(frozen=True, slots=True)
class _GloballyIndexedVisualCandidate:
    """Preserve a materialized path while assigning one stream-global ID."""

    materialized: Any
    candidate_index: int

    def __post_init__(self) -> None:
        _exact_source_shot_path(self.materialized)
        for name in ("review_rank", "cadence_profile", "candidate_record"):
            if not hasattr(self.materialized, name):
                raise TypeError(
                    f"globally indexed candidate is missing {name}"
                )
        if (
            isinstance(self.candidate_index, bool)
            or not isinstance(self.candidate_index, int)
            or self.candidate_index < 0
        ):
            raise ValueError("global candidate index must be non-negative")

    def __getattr__(self, name: str) -> Any:
        return getattr(self.materialized, name)


def _exact_source_shot_path(candidate: Any) -> tuple[tuple[str, str], ...]:
    """Return the DP path identity without conflating shots from one source."""

    visual_plan = getattr(candidate, "visual_plan", None)
    if visual_plan is None:
        visual_plan = getattr(candidate, "visual_timeline", None)
    choices = getattr(visual_plan, "choices", None)
    if not isinstance(choices, tuple) or not choices:
        raise TypeError("visual candidate must expose a non-empty visual path")
    path: list[tuple[str, str]] = []
    for choice in choices:
        source_index = getattr(choice, "source_index", None)
        shot_id = getattr(choice, "shot_id", None)
        if (
            isinstance(source_index, bool)
            or not isinstance(source_index, int)
            or source_index < 0
            or not isinstance(shot_id, str)
            or not shot_id
            or shot_id != shot_id.strip()
        ):
            raise ValueError("visual candidate source/shot path is invalid")
        path.append((str(source_index), shot_id))
    return tuple(path)


_JOINT_CUMULATIVE_PROOF_MATERIALIZATION_LIMIT = 32
_JOINT_REQUIRED_DECODED_PASS_COUNT = JOINT_RELEASE_CANDIDATE_COUNT
_JOINT_MAXIMUM_VARIANTS_PER_SOURCE_SHOT_PATH = 2

_JOINT_LOCALIZED_BOUNDARY_FAILURE_CODES = frozenset(
    {
        "structure_shock",
        "face_scale_discontinuity",
        "face_position_discontinuity",
        "silhouette_scale_discontinuity",
        "silhouette_position_discontinuity",
        "motion_direction_discontinuity",
        "introduced_cross_source_duplicate_or_freeze",
        "introduced_cross_source_black_frame",
    }
)
_JOINT_LOOK_VARIANT_BOUNDARY_FAILURE_CODES = frozenset(
    {
        "sharpness_discontinuity",
        "exposure_discontinuity",
        "color_shock",
    }
)
_JOINT_LOOK_REFINEMENT_AESTHETIC_BOUNDARY_CODES = frozenset(
    {
        *_JOINT_LOOK_VARIANT_BOUNDARY_FAILURE_CODES,
        "weighted_boundary_score",
    }
)
_JOINT_KNOWN_CROSS_SOURCE_BOUNDARY_ISSUE_CODES = frozenset(
    {
        *_JOINT_LOCALIZED_BOUNDARY_FAILURE_CODES,
        *_JOINT_LOOK_REFINEMENT_AESTHETIC_BOUNDARY_CODES,
    }
)
_JOINT_NONLOCAL_RENDER_CONTRACT_DOMAINS = frozenset(
    {"tier_d_continuity", "native_source_cut"}
)
_JOINT_NONLOCAL_ZERO_TOLERANCE_TOKENS = (
    "duplicate_or_freeze",
    "black_frame",
    "decoded_frame_unavailable",
    "render_contract_mismatch",
)


def _joint_decoded_materialized_candidate_attempt_allowed(
    *,
    attempted_materialized_candidate_count: int,
    base_render_count: int,
    maximum_materialized_candidate_count: int = (
        _JOINT_CUMULATIVE_PROOF_MATERIALIZATION_LIMIT
    ),
    maximum_base_render_count: int = JOINT_DECODED_DISTINCT_CANDIDATE_LIMIT,
) -> bool:
    """Keep pre-render rejection capacity separate from decoded render budget.

    Materializing/deriving a candidate is bounded by the existing proof budget,
    while only a candidate that reaches the decoded renderer consumes the base
    render ledger.  A derivation or timeline rejection therefore cannot steal
    one of the 24 decoded base-render opportunities.
    """

    values = {
        "attempted materialized candidate count": (
            attempted_materialized_candidate_count
        ),
        "base render count": base_render_count,
        "maximum materialized candidate count": (
            maximum_materialized_candidate_count
        ),
        "maximum base render count": maximum_base_render_count,
    }
    for name, value in values.items():
        if (
            isinstance(value, bool)
            or not isinstance(value, int)
            or value < 0
        ):
            raise ValueError(f"{name} must be a non-negative integer")
    if maximum_materialized_candidate_count <= 0:
        raise ValueError(
            "maximum materialized candidate count must be positive"
        )
    if maximum_base_render_count <= 0:
        raise ValueError("maximum base render count must be positive")
    if attempted_materialized_candidate_count > (
        maximum_materialized_candidate_count
    ):
        raise ValueError("materialized candidate accounting exceeded its cap")
    if base_render_count > maximum_base_render_count:
        raise ValueError("base render accounting exceeded its cap")
    return bool(
        attempted_materialized_candidate_count
        < maximum_materialized_candidate_count
        and base_render_count < maximum_base_render_count
    )


def _joint_exact_boundary_reason_list(
    boundary: Mapping[str, Any],
    field: str,
) -> tuple[str, ...] | None:
    """Return one exact decoded reason list, rejecting lossy coercion."""

    value = boundary.get(field)
    if not isinstance(value, list) or any(
        not isinstance(item, str) or not item or item != item.strip()
        for item in value
    ):
        return None
    return tuple(value)


def _joint_decoded_feedback_authoring_audit(
    candidate: Any,
    review_payload: Mapping[str, Any],
    *,
    eligible_indices: Sequence[int],
) -> dict[str, Any]:
    """Fail closed before decoded reasons can author an exact no-good.

    New or malformed technical-integrity codes are evidence that the causal
    vocabulary has changed, not proof that a selected cut is structurally
    impossible.  Keep the exact path eligible and expose the cause for audit.
    """

    reasons: list[str] = []
    unknown_technical_codes: list[dict[str, Any]] = []
    underlying = _underlying_joint_materialized_candidate(candidate)
    if underlying is None:
        reasons.append("joint_candidate_contract_missing")
        choices: tuple[Any, ...] = ()
    else:
        choices = underlying.visual_plan.choices
    if not isinstance(review_payload.get("passed"), bool):
        reasons.append("decoded_review_pass_contract_missing")
    global_technical_reasons = review_payload.get(
        "introduced_cross_source_technical_issue_reasons"
    )
    if not isinstance(global_technical_reasons, list) or any(
        not isinstance(item, str) or not item or item != item.strip()
        for item in global_technical_reasons
    ):
        reasons.append("global_technical_reason_contract_invalid")
        global_technical_reasons = []
    for technical_reason in global_technical_reasons:
        if technical_reason in _JOINT_LOCALIZED_BOUNDARY_FAILURE_CODES:
            continue
        unknown_technical_codes.append(
            {
                "boundary_index": None,
                "review_domain": INTRODUCED_CROSS_SOURCE_DOMAIN,
                "code": technical_reason,
            }
        )
        reasons.append(
            "global_unknown_technical_integrity_code:"
            f"{technical_reason}"
        )
    boundaries = review_payload.get("boundaries")
    if not isinstance(boundaries, list):
        reasons.append("decoded_boundary_contract_missing")
        boundaries = []
    expected_boundary_count = max(0, len(choices) - 1)
    if len(boundaries) != expected_boundary_count:
        reasons.append("decoded_boundary_count_mismatch")
    seen_indices: set[int] = set()
    for position, boundary in enumerate(boundaries):
        if not isinstance(boundary, Mapping):
            reasons.append(f"boundary_{position}_contract_malformed")
            continue
        boundary_index = boundary.get("boundary_index")
        if (
            isinstance(boundary_index, bool)
            or not isinstance(boundary_index, int)
            or boundary_index < 0
            or boundary_index in seen_indices
        ):
            reasons.append(f"boundary_{position}_index_contract_malformed")
            continue
        seen_indices.add(boundary_index)
        if boundary_index != position or boundary_index >= expected_boundary_count:
            reasons.append(f"boundary_{boundary_index}_index_domain_mismatch")
            continue
        if not isinstance(boundary.get("passed"), bool):
            reasons.append(f"boundary_{boundary_index}_pass_contract_missing")
        issue_reasons = _joint_exact_boundary_reason_list(
            boundary,
            "issue_reasons",
        )
        technical_reasons = _joint_exact_boundary_reason_list(
            boundary,
            "technical_integrity_issue_reasons",
        )
        if issue_reasons is None:
            reasons.append(f"boundary_{boundary_index}_issue_reason_contract_invalid")
        if technical_reasons is None:
            reasons.append(
                f"boundary_{boundary_index}_technical_reason_contract_invalid"
            )
            technical_reasons = ()
        if boundary_index >= len(choices) - 1:
            continue
        outgoing = choices[boundary_index]
        incoming = choices[boundary_index + 1]
        expected_outgoing_source = _joint_report_source_index(
            outgoing.source_index,
            eligible_indices,
        )
        expected_incoming_source = _joint_report_source_index(
            incoming.source_index,
            eligible_indices,
        )
        if (
            boundary.get("outgoing_source_index") != expected_outgoing_source
            or boundary.get("incoming_source_index") != expected_incoming_source
        ):
            reasons.append(f"boundary_{boundary_index}_source_binding_mismatch")
        cross_source = outgoing.source_index != incoming.source_index
        domain = boundary.get("review_domain")
        if cross_source:
            domain_valid = domain == INTRODUCED_CROSS_SOURCE_DOMAIN
        else:
            domain_valid = domain in _JOINT_NONLOCAL_RENDER_CONTRACT_DOMAINS
        if not domain_valid:
            reasons.append(f"boundary_{boundary_index}_review_domain_mismatch")
        for technical_reason in technical_reasons:
            known = (
                technical_reason in _JOINT_LOCALIZED_BOUNDARY_FAILURE_CODES
                if cross_source
                else any(
                    token in technical_reason
                    for token in _JOINT_NONLOCAL_ZERO_TOLERANCE_TOKENS
                )
            )
            if known:
                continue
            unknown_technical_codes.append(
                {
                    "boundary_index": boundary_index,
                    "review_domain": domain,
                    "code": technical_reason,
                }
            )
            reasons.append(
                f"boundary_{boundary_index}_unknown_technical_integrity_code:"
                f"{technical_reason}"
            )
    unique_reasons = tuple(dict.fromkeys(reasons))
    return {
        "contract": "joint_decoded_feedback_authoring_audit_v1",
        "authoring_allowed": not unique_reasons,
        "block_reasons": list(unique_reasons),
        "unknown_technical_codes": unknown_technical_codes,
        "known_localized_structural_codes": sorted(
            _JOINT_LOCALIZED_BOUNDARY_FAILURE_CODES
        ),
        "unknown_or_malformed_reason_promoted_to_no_good": False,
    }


def _underlying_joint_materialized_candidate(
    candidate: Any,
) -> JointMaterializedVisualCandidate | None:
    """Unwrap a stream-global shell without losing the joint proof owner."""

    underlying = (
        candidate.materialized
        if isinstance(candidate, _GloballyIndexedVisualCandidate)
        else candidate
    )
    return (
        underlying
        if isinstance(underlying, JointMaterializedVisualCandidate)
        else None
    )


def _joint_complete_path_signature(
    candidate: Any,
) -> JointTimelinePathSignature:
    underlying = _underlying_joint_materialized_candidate(candidate)
    if underlying is None:
        raise TypeError("joint complete-path identity needs a joint candidate")
    signature = underlying.joint_result.complete_path_signature
    if not isinstance(signature, JointTimelinePathSignature):
        raise TypeError("joint candidate exposed an invalid complete-path identity")
    return signature


def _globally_index_joint_visual_candidate_batch(
    candidates: Sequence[JointMaterializedVisualCandidate],
    *,
    first_candidate_index: int,
    existing_complete_paths: Iterable[JointTimelinePathSignature] = (),
) -> tuple[_GloballyIndexedVisualCandidate, ...]:
    """Assign stable cross-batch IDs while rejecting exact proof replays."""

    if (
        isinstance(first_candidate_index, bool)
        or not isinstance(first_candidate_index, int)
        or first_candidate_index < 0
    ):
        raise ValueError("joint global candidate index must be non-negative")
    if isinstance(candidates, (str, bytes)) or not isinstance(
        candidates,
        Sequence,
    ):
        raise TypeError("joint candidate batch must be a sequence")
    seen = set(existing_complete_paths)
    if any(not isinstance(item, JointTimelinePathSignature) for item in seen):
        raise TypeError("existing joint complete paths are invalid")
    wrapped: list[_GloballyIndexedVisualCandidate] = []
    for offset, candidate in enumerate(candidates):
        if not isinstance(candidate, JointMaterializedVisualCandidate):
            raise TypeError("joint batch contains a non-joint candidate")
        signature = _joint_complete_path_signature(candidate)
        if signature in seen:
            raise RuntimeError(
                "joint selector replayed an exact complete path across batches"
            )
        seen.add(signature)
        wrapped.append(
            _GloballyIndexedVisualCandidate(
                materialized=candidate,
                candidate_index=first_candidate_index + offset,
            )
        )
    return tuple(wrapped)


def _joint_selection_proof_materialization_call_count(
    selection_set: JointVisualSelectionSet,
    *,
    available_budget: int,
) -> int:
    """Validate selector proof accounting before adding it to session usage."""

    if not isinstance(selection_set, JointVisualSelectionSet):
        raise TypeError("joint proof accounting needs a selection set")
    if (
        isinstance(available_budget, bool)
        or not isinstance(available_budget, int)
        or available_budget < selection_set.minimum_required_candidates
        or available_budget
        > _JOINT_CUMULATIVE_PROOF_MATERIALIZATION_LIMIT
    ):
        raise ValueError("joint available proof budget must cover the cohort within 1..32")
    value = selection_set.selection_retry_audit.get(
        "proof_materialization_call_count"
    )
    if (
        isinstance(value, bool)
        or not isinstance(value, int)
        or not len(selection_set.candidate_records)
        <= value
        <= available_budget
    ):
        raise RuntimeError("joint selector returned invalid proof usage")
    return value


def _joint_selection_retry_audit_payload(
    selection_set: JointVisualSelectionSet,
) -> dict[str, Any]:
    """Copy the selector audit through its public recursive thaw contract."""

    serialized = selection_set.to_dict()
    if not isinstance(serialized, Mapping):
        raise TypeError("joint selector serialization must be a mapping")
    raw_audit = serialized.get("selection_retry_audit")
    if not isinstance(raw_audit, Mapping):
        raise TypeError("joint selector retry audit must be a mapping")
    audit = deepcopy(dict(raw_audit))
    json.dumps(audit, allow_nan=False)
    return audit


def _materialize_joint_feedback_batch_with_fresh_provider(
    *,
    batch_index: int,
    provider_factory: Callable[[], Any],
    select_candidates: Callable[
        [
            Any,
            frozenset[BoundarySelectionNoGood],
            frozenset[JointTimelinePathSignature],
            int,
        ],
        JointVisualSelectionSet,
    ],
    materialize_candidates: Callable[
        [JointVisualSelectionSet, Any],
        Sequence[JointMaterializedVisualCandidate],
    ],
    forbidden_boundary_selections: Iterable[BoundarySelectionNoGood],
    forbidden_complete_paths: Iterable[JointTimelinePathSignature],
    maximum_proof_materialization_calls: int,
    provider_audit_sink: Callable[[Mapping[str, Any]], None],
) -> tuple[
    JointVisualSelectionSet,
    tuple[JointMaterializedVisualCandidate, ...],
]:
    """Open, use, audit, and close exactly one process-local provider batch."""

    if (
        isinstance(batch_index, bool)
        or not isinstance(batch_index, int)
        or batch_index < 0
    ):
        raise ValueError("joint feedback batch index must be non-negative")
    if (
        isinstance(maximum_proof_materialization_calls, bool)
        or not isinstance(maximum_proof_materialization_calls, int)
        or not JOINT_RELEASE_CANDIDATE_COUNT
        <= maximum_proof_materialization_calls
        <= _JOINT_CUMULATIVE_PROOF_MATERIALIZATION_LIMIT
    ):
        raise ValueError("joint feedback proof budget must be within 1..32")
    boundary_feedback = frozenset(forbidden_boundary_selections)
    complete_path_feedback = frozenset(forbidden_complete_paths)
    if any(
        not isinstance(item, tuple) or len(item) != 2
        for item in boundary_feedback
    ):
        raise TypeError("joint boundary feedback contains an invalid no-good")
    if any(
        not isinstance(item, JointTimelinePathSignature)
        for item in complete_path_feedback
    ):
        raise TypeError("joint complete-path feedback contains an invalid no-good")
    provider = provider_factory()
    if provider is None:
        raise RuntimeError("joint provider factory returned no provider")
    provider_audit_before_close: dict[str, Any] | None = None
    try:
        selection_set = select_candidates(
            provider,
            boundary_feedback,
            complete_path_feedback,
            maximum_proof_materialization_calls,
        )
        if not isinstance(selection_set, JointVisualSelectionSet):
            raise TypeError("joint selector returned an invalid selection set")
        materialized = tuple(
            materialize_candidates(selection_set, provider)
        )
        if (
            not selection_set.minimum_required_candidates
            <= len(materialized) <= JOINT_COMPARISON_CANDIDATE_BUDGET
            or any(
                not isinstance(item, JointMaterializedVisualCandidate)
                for item in materialized
            )
        ):
            raise RuntimeError(
                "joint feedback batch must materialize its passing cohort within comparison capacity"
            )
        return selection_set, materialized
    finally:
        try:
            raw_audit = provider.to_dict()
            if not isinstance(raw_audit, Mapping):
                raise TypeError("joint provider audit must be a mapping")
            provider_audit_before_close = deepcopy(dict(raw_audit))
        finally:
            provider.close()
        if provider_audit_before_close is not None:
            provider_audit_sink(
                {
                    **provider_audit_before_close,
                    "batch_index": batch_index,
                    "provider_closed_after_materialization": True,
                    "process_local_materialization_retained": True,
                }
            )


def _joint_report_source_index(
    local_source_index: int,
    eligible_indices: Sequence[int],
) -> int:
    if (
        isinstance(local_source_index, bool)
        or not isinstance(local_source_index, int)
        or not 0 <= local_source_index < len(eligible_indices)
    ):
        raise ValueError("joint local source index is outside eligible sources")
    report_index = eligible_indices[local_source_index]
    if (
        isinstance(report_index, bool)
        or not isinstance(report_index, int)
        or report_index < 0
    ):
        raise ValueError("joint eligible source mapping is invalid")
    return report_index


def _joint_localized_decoded_boundary_no_goods(
    candidate: Any,
    review_payload: Mapping[str, Any],
    *,
    eligible_indices: Sequence[int],
) -> frozenset[BoundarySelectionNoGood]:
    """Project only exact introduced-cross-source failures into the joint DP."""

    underlying = _underlying_joint_materialized_candidate(candidate)
    if underlying is None:
        return frozenset()
    boundaries = review_payload.get("boundaries")
    if not isinstance(boundaries, list):
        return frozenset()
    choices = underlying.visual_plan.choices
    options = underlying.joint_result.boundary_options
    if len(options) != max(0, len(choices) - 1):
        raise RuntimeError("joint decoded candidate lost exact boundary options")
    no_goods: set[BoundarySelectionNoGood] = set()
    for boundary in boundaries:
        if (
            not isinstance(boundary, Mapping)
            or boundary.get("review_domain")
            != INTRODUCED_CROSS_SOURCE_DOMAIN
            or boundary.get("passed") is not False
        ):
            continue
        boundary_index = boundary.get("boundary_index")
        if (
            isinstance(boundary_index, bool)
            or not isinstance(boundary_index, int)
            or not 0 <= boundary_index < len(options)
        ):
            continue
        outgoing = choices[boundary_index]
        incoming = choices[boundary_index + 1]
        if outgoing.source_index == incoming.source_index:
            continue
        expected_outgoing_source = _joint_report_source_index(
            outgoing.source_index,
            eligible_indices,
        )
        expected_incoming_source = _joint_report_source_index(
            incoming.source_index,
            eligible_indices,
        )
        if (
            boundary.get("outgoing_source_index")
            != expected_outgoing_source
            or boundary.get("incoming_source_index")
            != expected_incoming_source
        ):
            continue
        issue_reasons = _joint_exact_boundary_reason_list(
            boundary,
            "issue_reasons",
        )
        technical_reasons = _joint_exact_boundary_reason_list(
            boundary,
            "technical_integrity_issue_reasons",
        )
        if issue_reasons is None or technical_reasons is None:
            continue
        if any(
            reason not in _JOINT_LOCALIZED_BOUNDARY_FAILURE_CODES
            for reason in technical_reasons
        ):
            # A new technical code is not exact structural impossibility proof.
            continue
        reasons = set(issue_reasons).union(technical_reasons)
        if not reasons.intersection(_JOINT_LOCALIZED_BOUNDARY_FAILURE_CODES):
            continue
        option = options[boundary_index]
        key = option.measurement_key
        if (
            key.boundary_index != boundary_index
            or key.outgoing.source_id != str(outgoing.source_index)
            or key.incoming.source_id != str(incoming.source_index)
            or key.outgoing.shot_id != outgoing.shot_id
            or key.incoming.shot_id != incoming.shot_id
        ):
            raise RuntimeError(
                "decoded boundary failure does not bind the selected joint proof"
            )
        no_goods.add((key, option.frame_offset))
    return frozenset(no_goods)


def _joint_look_variant_boundary_failure_count(
    review_payload: Mapping[str, Any],
) -> int:
    """Count look-only boundary failures that must not poison cut-path search."""

    boundaries = review_payload.get("boundaries")
    if not isinstance(boundaries, list):
        return 0
    count = 0
    for boundary in boundaries:
        if (
            not isinstance(boundary, Mapping)
            or boundary.get("review_domain")
            != INTRODUCED_CROSS_SOURCE_DOMAIN
            or boundary.get("passed") is not False
        ):
            continue
        issue_reasons = _joint_exact_boundary_reason_list(
            boundary,
            "issue_reasons",
        )
        technical_reasons = _joint_exact_boundary_reason_list(
            boundary,
            "technical_integrity_issue_reasons",
        )
        if (
            issue_reasons
            and technical_reasons == ()
            and set(issue_reasons).issubset(
                _JOINT_LOOK_VARIANT_BOUNDARY_FAILURE_CODES
            )
        ):
            count += 1
    return count


def _joint_nonlocal_render_contract_failure_fingerprints(
    candidate: Any,
    review_payload: Mapping[str, Any],
    *,
    eligible_indices: Sequence[int],
) -> tuple[tuple[str, int, int, str], ...]:
    """Return only zero-tolerance, same-source renderer-contract failures."""

    underlying = _underlying_joint_materialized_candidate(candidate)
    if underlying is None:
        return ()
    boundaries = review_payload.get("boundaries")
    if not isinstance(boundaries, list):
        return ()
    choices = underlying.visual_plan.choices
    fingerprints: set[tuple[str, int, int, str]] = set()
    for boundary in boundaries:
        if not isinstance(boundary, Mapping) or boundary.get("passed") is not False:
            continue
        domain = boundary.get("review_domain")
        boundary_index = boundary.get("boundary_index")
        if (
            domain not in _JOINT_NONLOCAL_RENDER_CONTRACT_DOMAINS
            or isinstance(boundary_index, bool)
            or not isinstance(boundary_index, int)
            or not 0 <= boundary_index < len(choices) - 1
        ):
            continue
        outgoing = choices[boundary_index]
        incoming = choices[boundary_index + 1]
        if outgoing.source_index != incoming.source_index:
            continue
        expected_source = _joint_report_source_index(
            outgoing.source_index,
            eligible_indices,
        )
        if (
            boundary.get("outgoing_source_index") != expected_source
            or boundary.get("incoming_source_index") != expected_source
        ):
            continue
        technical = boundary.get("technical_integrity_issue_reasons")
        if not isinstance(technical, list):
            continue
        for reason in technical:
            if not isinstance(reason, str) or not any(
                token in reason
                for token in _JOINT_NONLOCAL_ZERO_TOLERANCE_TOKENS
            ):
                continue
            fingerprints.add(
                (str(domain), boundary_index, expected_source, reason)
            )
    return tuple(sorted(fingerprints))


def _record_joint_shared_render_contract_failure(
    observed_paths: dict[
        tuple[str, int, int, str],
        set[JointTimelinePathSignature],
    ],
    *,
    exact_path: JointTimelinePathSignature,
    fingerprints: Sequence[tuple[str, int, int, str]],
) -> dict[str, Any] | None:
    """Abort after two exact paths prove one invariant renderer defect."""

    if not isinstance(exact_path, JointTimelinePathSignature):
        raise TypeError("shared renderer failure needs an exact joint path")
    if any(
        not isinstance(item, tuple)
        or len(item) != 4
        or not isinstance(item[0], str)
        or isinstance(item[1], bool)
        or not isinstance(item[1], int)
        or item[1] < 0
        or isinstance(item[2], bool)
        or not isinstance(item[2], int)
        or item[2] < 0
        or not isinstance(item[3], str)
        or not item[3]
        for item in fingerprints
    ):
        raise ValueError("shared renderer failure fingerprint is invalid")
    for fingerprint in sorted(set(fingerprints)):
        paths = observed_paths.setdefault(fingerprint, set())
        if any(
            not isinstance(item, JointTimelinePathSignature)
            for item in paths
        ):
            raise TypeError("shared renderer failure path history is invalid")
        paths.add(exact_path)
        if len(paths) >= 2:
            return {
                "contract": "joint_decoded_shared_render_contract_failure_v1",
                "cause": "shared_render_contract_failure",
                "fingerprint": {
                    "review_domain": fingerprint[0],
                    "boundary_index": fingerprint[1],
                    "source_index": fingerprint[2],
                    "technical_integrity_reason": fingerprint[3],
                },
                "distinct_exact_path_count": len(paths),
                "minimum_distinct_exact_path_count": 2,
                "aggregate_aesthetic_failure_used": False,
                "same_source_failure_promoted_to_boundary_no_good": False,
                "thresholds_lowered": False,
                "production_use_forbidden": True,
            }
    return None


def _joint_decoded_render_variant_signature(
    review_payload: Mapping[str, Any],
) -> str:
    """Return the producer-bound RenderPlan identity for one decoded proxy."""

    interior = review_payload.get("segment_interior_geometry")
    signature = (
        interior.get("render_timeline_binding_sha256")
        if isinstance(interior, Mapping)
        else None
    )
    if not (
        isinstance(signature, str)
        and len(signature) == 64
        and all(character in "0123456789abcdef" for character in signature)
    ):
        raise ValueError("decoded review lacks a stable render variant signature")
    return signature


def _record_bound_joint_decoded_feedback(
    candidate: Any,
    bundle: "_GroupRenderCandidateBundle",
    review_payload: Mapping[str, Any],
    *,
    eligible_indices: Sequence[int],
    forbidden_boundary_selections: set[BoundarySelectionNoGood],
    feedback_classifications: dict[int, dict[str, Any]],
    nonlocal_contract_failure_paths: dict[
        tuple[str, int, int, str],
        set[JointTimelinePathSignature],
    ],
) -> tuple[dict[str, Any], dict[str, Any] | None]:
    """Author decoded feedback only after exact signed render binding."""

    candidate_index = getattr(candidate, "candidate_index", None)
    if (
        isinstance(candidate_index, bool)
        or not isinstance(candidate_index, int)
        or candidate_index < 0
    ):
        raise ValueError("joint decoded feedback candidate index is invalid")
    render_plan = getattr(bundle, "render_plan", None)
    invalid_classification: dict[str, Any] = {
        "feedback_binding_valid": False,
        "feedback_authoring_allowed": False,
        "localized_boundary_no_good_count": 0,
        "look_variant_boundary_failure_count": 0,
        "look_variant_boundary_promoted_to_path_no_good": False,
        "nonlocal_render_contract_failure_count": 0,
        "perceptual_source_admission_failed": False,
        "complete_path_no_good_deferred_for_render_variant": True,
        "complete_path_no_good_allowed": False,
        "aggregate_look_or_montage_promoted_to_boundary_no_good": False,
        "same_source_duplicate_or_freeze_promoted_to_boundary_no_good": False,
        "render_variant_signature": None,
        "feedback_authoring_audit": None,
        "feedback_authoring_block_reasons": [],
    }
    try:
        if not isinstance(review_payload, Mapping):
            raise TypeError("joint decoded feedback review must be a mapping")
        if not isinstance(render_plan, RenderPlan):
            raise TypeError("joint decoded feedback requires an exact RenderPlan")
        bound_render_variant = _bound_decoded_proxy_identity(
            review_payload,
            render_plan=render_plan,
        )[0]
        render_variant = _joint_decoded_render_variant_signature(
            review_payload
        )
        if bound_render_variant != render_variant:
            raise ValueError(
                "joint decoded feedback render variant binding changed"
            )
    except (OSError, TypeError, ValueError) as exc:
        classification = {
            **invalid_classification,
            "binding_error": f"{type(exc).__name__}: {exc}",
        }
        feedback_classifications[candidate_index] = classification
        return classification, None

    exact_path = _joint_complete_path_signature(candidate)
    feedback_authoring_audit = _joint_decoded_feedback_authoring_audit(
        candidate,
        review_payload,
        eligible_indices=eligible_indices,
    )
    feedback_authoring_allowed = bool(
        feedback_authoring_audit.get("authoring_allowed") is True
    )
    localized = (
        _joint_localized_decoded_boundary_no_goods(
            candidate,
            review_payload,
            eligible_indices=eligible_indices,
        )
        if feedback_authoring_allowed
        else frozenset()
    )
    look_variant_boundary_failure_count = (
        _joint_look_variant_boundary_failure_count(review_payload)
        if feedback_authoring_allowed
        else 0
    )
    nonlocal_fingerprints = (
        _joint_nonlocal_render_contract_failure_fingerprints(
            candidate,
            review_payload,
            eligible_indices=eligible_indices,
        )
        if feedback_authoring_allowed
        else ()
    )
    perceptual = review_payload.get("perceptual_source_admission")
    perceptual_admission_failed = bool(
        isinstance(perceptual, Mapping)
        and isinstance(perceptual.get("admission"), Mapping)
        and perceptual["admission"].get("passed") is False
    )
    classification = {
        "feedback_binding_valid": True,
        "feedback_authoring_allowed": feedback_authoring_allowed,
        "binding_error": None,
        "feedback_authoring_audit": feedback_authoring_audit,
        "feedback_authoring_block_reasons": list(
            feedback_authoring_audit.get("block_reasons", [])
        ),
        "localized_boundary_no_good_count": len(localized),
        "look_variant_boundary_failure_count": (
            look_variant_boundary_failure_count
        ),
        "look_variant_boundary_promoted_to_path_no_good": False,
        "nonlocal_render_contract_failure_count": len(
            nonlocal_fingerprints
        ),
        "perceptual_source_admission_failed": perceptual_admission_failed,
        "complete_path_no_good_deferred_for_render_variant": (
            not feedback_authoring_allowed
            or (
                review_payload.get("passed") is False
                and not localized
                and not nonlocal_fingerprints
            )
        ),
        "complete_path_no_good_allowed": feedback_authoring_allowed,
        "aggregate_look_or_montage_promoted_to_boundary_no_good": False,
        "same_source_duplicate_or_freeze_promoted_to_boundary_no_good": False,
        "render_variant_signature": render_variant,
    }
    feedback_classifications[candidate_index] = classification
    forbidden_boundary_selections.update(localized)
    shared_failure = _record_joint_shared_render_contract_failure(
        nonlocal_contract_failure_paths,
        exact_path=exact_path,
        fingerprints=nonlocal_fingerprints,
    )
    return classification, shared_failure


def _joint_complete_path_no_good_allowed_from_feedback(
    classification: Mapping[str, Any] | None,
) -> bool:
    """Keep unbound decoded evidence from promoting an exact path no-good."""

    if classification is None:
        # Pre-proxy structural/derivation failures do not depend on decoded
        # evidence and may still retire their exact complete path.
        return True
    return bool(
        classification.get("feedback_binding_valid") is True
        and classification.get("feedback_authoring_allowed") is True
        and classification.get(
            "complete_path_no_good_deferred_for_render_variant"
        )
        is False
    )


def _joint_require_refined_render_variant_lineage(
    proposal: GroupDecodedLookRefinement,
    render_variant_signature: str,
) -> None:
    """Reject a rerender that is not the proposal's exact signed output."""

    if not isinstance(proposal, GroupDecodedLookRefinement):
        raise TypeError("joint look proposal lineage is invalid")
    if (
        render_variant_signature
        != proposal.lineage.output_render_plan_binding_sha256
    ):
        raise ValueError("refined decoded render variant lineage mismatch")


def _joint_decoded_look_already_passed_audit_fields(
    *,
    decoded_review_passed: bool,
) -> dict[str, Any]:
    """Classify an aggregate failure after the decoded look already passed."""

    if not isinstance(decoded_review_passed, bool):
        raise TypeError("decoded aggregate review pass flag must be boolean")
    aggregate_nonlook_failure = not decoded_review_passed
    return {
        "applicable": False,
        "evidence_complete": True,
        "exhausted": True,
        "budget_exhausted": False,
        "look_rerender_required": False,
        "path_invariant_nonlook_failure": aggregate_nonlook_failure,
        "reason": (
            "decoded_look_admission_passed_aggregate_nonlook_failed"
            if aggregate_nonlook_failure
            else "decoded_look_admission_already_passed"
        ),
        "complete_path_no_good_allowed": aggregate_nonlook_failure,
    }


def _joint_group_look_boundary_reason_contract(
    review_payload: Mapping[str, Any],
) -> dict[str, Any]:
    """Validate exact cross-source boundary reasons before look rerendering.

    A look-only repair may proceed only when every introduced cross-source
    boundary has a typed reason contract, no unknown reason code, no structural
    issue, and an exactly empty technical-integrity list.  This is deliberately
    independent of the later no-good authoring audit.
    """

    boundaries = review_payload.get("boundaries")
    if not isinstance(boundaries, list):
        return {
            "contract": "joint_group_look_boundary_reason_contract_v1",
            "contract_complete": False,
            "nonlook_boundary_gates_passed": False,
            "introduced_cross_source_boundary_count": 0,
            "unknown_reason_codes": [],
            "structural_reason_codes": [],
            "technical_reason_codes": [],
            "block_reasons": ["decoded_boundary_contract_missing"],
        }

    block_reasons: list[str] = []
    unknown_reason_codes: list[str] = []
    structural_reason_codes: list[str] = []
    technical_reason_codes: list[str] = []
    introduced_count = 0
    seen_indices: set[int] = set()
    for position, boundary in enumerate(boundaries):
        if not isinstance(boundary, Mapping):
            block_reasons.append(f"boundary_{position}_contract_malformed")
            continue
        boundary_index = boundary.get("boundary_index")
        if (
            isinstance(boundary_index, bool)
            or not isinstance(boundary_index, int)
            or boundary_index < 0
            or boundary_index in seen_indices
        ):
            block_reasons.append(f"boundary_{position}_index_contract_malformed")
            continue
        seen_indices.add(boundary_index)
        if boundary_index != position:
            block_reasons.append(
                f"boundary_{boundary_index}_index_domain_mismatch"
            )
        review_domain = boundary.get("review_domain")
        if not isinstance(review_domain, str) or not review_domain:
            block_reasons.append(
                f"boundary_{boundary_index}_review_domain_contract_malformed"
            )
            continue
        if review_domain not in {
            INTRODUCED_CROSS_SOURCE_DOMAIN,
            *_JOINT_NONLOCAL_RENDER_CONTRACT_DOMAINS,
        }:
            block_reasons.append(
                f"boundary_{boundary_index}_unknown_review_domain"
            )
            continue
        if review_domain != INTRODUCED_CROSS_SOURCE_DOMAIN:
            continue
        introduced_count += 1
        outgoing_source = boundary.get("outgoing_source_index")
        incoming_source = boundary.get("incoming_source_index")
        if (
            isinstance(outgoing_source, bool)
            or not isinstance(outgoing_source, int)
            or outgoing_source < 0
            or isinstance(incoming_source, bool)
            or not isinstance(incoming_source, int)
            or incoming_source < 0
            or outgoing_source == incoming_source
        ):
            block_reasons.append(
                f"boundary_{boundary_index}_cross_source_binding_contract_invalid"
            )
        passed = boundary.get("passed")
        issue_reasons = _joint_exact_boundary_reason_list(
            boundary,
            "issue_reasons",
        )
        technical_reasons = _joint_exact_boundary_reason_list(
            boundary,
            "technical_integrity_issue_reasons",
        )
        if not isinstance(passed, bool):
            block_reasons.append(
                f"boundary_{boundary_index}_pass_contract_missing"
            )
        if issue_reasons is None:
            block_reasons.append(
                f"boundary_{boundary_index}_issue_reason_contract_invalid"
            )
            issue_reasons = ()
        if technical_reasons is None:
            block_reasons.append(
                f"boundary_{boundary_index}_technical_reason_contract_invalid"
            )
            technical_reasons = ()
        unknown = tuple(
            reason
            for reason in (*issue_reasons, *technical_reasons)
            if reason not in _JOINT_KNOWN_CROSS_SOURCE_BOUNDARY_ISSUE_CODES
        )
        if unknown:
            unknown_reason_codes.extend(unknown)
            block_reasons.append(
                f"boundary_{boundary_index}_unknown_reason_code"
            )
        if technical_reasons:
            technical_reason_codes.extend(technical_reasons)
            block_reasons.append(
                f"boundary_{boundary_index}_technical_reason_not_empty"
            )
        structural = tuple(
            reason
            for reason in issue_reasons
            if reason in _JOINT_LOCALIZED_BOUNDARY_FAILURE_CODES
        )
        if structural:
            structural_reason_codes.extend(structural)
            block_reasons.append(
                f"boundary_{boundary_index}_structural_reason_present"
            )
        if passed is True and (issue_reasons or technical_reasons):
            block_reasons.append(
                f"boundary_{boundary_index}_passing_reason_contract_inconsistent"
            )
        if (
            passed is False
            and not issue_reasons
            and not technical_reasons
        ):
            block_reasons.append(
                f"boundary_{boundary_index}_failing_reason_contract_empty"
            )

    unique_block_reasons = tuple(dict.fromkeys(block_reasons))
    contract_incomplete = any(
        "contract" in reason
        or "unknown" in reason
        or "index_domain_mismatch" in reason
        for reason in unique_block_reasons
    )
    return {
        "contract": "joint_group_look_boundary_reason_contract_v1",
        "contract_complete": not contract_incomplete,
        "nonlook_boundary_gates_passed": not unique_block_reasons,
        "introduced_cross_source_boundary_count": introduced_count,
        "unknown_reason_codes": sorted(set(unknown_reason_codes)),
        "structural_reason_codes": sorted(set(structural_reason_codes)),
        "technical_reason_codes": sorted(set(technical_reason_codes)),
        "block_reasons": list(unique_block_reasons),
    }


def _joint_group_look_refinement_eligibility(
    review_payload: Mapping[str, Any],
    *,
    exact_evidence: bool,
    look_admission_passed: bool,
    decoded_review_passed: bool,
) -> tuple[JointDecodedLookRefinementEligibility, dict[str, Any]]:
    """Authorize rerenders only for complete, look-only decoded failures.

    Visible/color scores and the aggregate technical-proxy boolean are not
    eligibility inputs: source-level look correction may legitimately change
    them.  Exact binding, geometry-provider integrity, global technical
    issues, interior completeness, and the professional/montage gates remain
    fail-closed.
    """

    if not isinstance(review_payload, Mapping):
        raise TypeError("joint look eligibility review must be a mapping")
    for name, value in (
        ("exact_evidence", exact_evidence),
        ("look_admission_passed", look_admission_passed),
        ("decoded_review_passed", decoded_review_passed),
    ):
        if not isinstance(value, bool):
            raise TypeError(f"{name} must be boolean")

    def exact_nonnegative_integer(value: Any) -> int | None:
        return (
            value
            if isinstance(value, int)
            and not isinstance(value, bool)
            and value >= 0
            else None
        )

    def exact_issue_list(value: Any) -> list[str] | None:
        if not isinstance(value, list) or any(
            not isinstance(item, str) or not item for item in value
        ):
            return None
        return value

    def exact_gate(value: Any) -> bool | None:
        resolved = value.get("passed") if isinstance(value, Mapping) else value
        return resolved if isinstance(resolved, bool) else None

    geometry_failure_count = exact_nonnegative_integer(
        review_payload.get("geometry_provider_failure_count")
    )
    global_technical_issues = exact_issue_list(
        review_payload.get(
            "introduced_cross_source_technical_issue_reasons"
        )
    )
    interior = review_payload.get("segment_interior_geometry")
    interior_complete = (
        interior.get("complete") if isinstance(interior, Mapping) else None
    )
    interior_failure_count = exact_nonnegative_integer(
        interior.get("geometry_provider_failure_count")
        if isinstance(interior, Mapping)
        else None
    )
    professional_gate_passed = exact_gate(
        review_payload.get("professional_reference_gate")
    )
    montage_gate_passed = exact_gate(
        review_payload.get("rendered_montage_grammar_review")
    )
    boundary_reason_contract = _joint_group_look_boundary_reason_contract(
        review_payload
    )
    contracts_complete = bool(
        exact_evidence
        and geometry_failure_count is not None
        and global_technical_issues is not None
        and isinstance(interior_complete, bool)
        and interior_failure_count is not None
        and professional_gate_passed is not None
        and montage_gate_passed is not None
        and boundary_reason_contract["contract_complete"] is True
    )
    nonlook_gates_passed = bool(
        contracts_complete
        and geometry_failure_count == 0
        and not global_technical_issues
        and interior_complete is True
        and interior_failure_count == 0
        and professional_gate_passed is True
        and montage_gate_passed is True
        and boundary_reason_contract[
            "nonlook_boundary_gates_passed"
        ]
        is True
    )
    eligibility = JointDecodedLookRefinementEligibility(
        evidence_complete=contracts_complete,
        nonlook_gates_passed=nonlook_gates_passed,
        look_admission_passed=look_admission_passed,
        decoded_review_passed=decoded_review_passed,
    )
    diagnostics = {
        **eligibility.to_dict(),
        "exact_evidence": exact_evidence,
        "geometry_provider_failure_count": geometry_failure_count,
        "global_technical_issue_count": (
            len(global_technical_issues)
            if global_technical_issues is not None
            else None
        ),
        "segment_interior_complete": interior_complete,
        "segment_interior_geometry_provider_failure_count": (
            interior_failure_count
        ),
        "professional_reference_gate_passed": professional_gate_passed,
        "rendered_montage_grammar_gate_passed": montage_gate_passed,
        "boundary_reason_contract": boundary_reason_contract,
        "visible_boundary_score_used": False,
        "technical_proxy_boolean_used": False,
        "look_or_color_threshold_changed": False,
    }
    return eligibility, diagnostics


def _joint_look_refinement_complete_path_no_good_allowed(
    *,
    decoded_review_passed: bool,
    exhausted: bool,
    budget_exhausted: bool,
    evidence_complete: bool,
) -> bool:
    """Return the exact fail-closed full-path retirement disposition."""

    values = (
        decoded_review_passed,
        exhausted,
        budget_exhausted,
        evidence_complete,
    )
    if any(not isinstance(value, bool) for value in values):
        raise TypeError("joint look refinement disposition flags must be boolean")
    return bool(
        not decoded_review_passed
        and exhausted
        and not budget_exhausted
        and evidence_complete
    )


def _joint_record_invalid_look_refinement_evidence(
    audit: dict[str, Any],
    iteration_audit: dict[str, Any],
    error: Exception,
) -> None:
    """Record invalid rerender evidence without enabling path retirement."""

    iterations = audit.get("iterations")
    if not isinstance(iterations, list):
        raise TypeError("joint look refinement audit iterations are invalid")
    if not isinstance(iteration_audit, dict) or not isinstance(error, Exception):
        raise TypeError("joint look refinement evidence failure is invalid")
    audit["evidence_complete"] = False
    iteration_audit.update(
        {
            "accepted": False,
            "rollback": True,
            "error": f"{type(error).__name__}: {error}",
            "nonlook_regression_reasons": [
                "decoded_refinement_evidence_invalid"
            ],
        }
    )
    iterations.append(iteration_audit)


def _joint_apply_look_refinement_feedback_classification(
    classification: dict[str, Any],
    refinement_audit: Mapping[str, Any],
    *,
    decoded_review_passed: bool,
) -> None:
    """Apply a refinement disposition without weakening binding feedback."""

    if not isinstance(classification, dict) or not isinstance(
        refinement_audit,
        Mapping,
    ):
        raise TypeError("joint look refinement feedback audit is invalid")
    if not isinstance(decoded_review_passed, bool):
        raise TypeError("decoded aggregate review pass flag must be boolean")
    classification["look_refinement"] = deepcopy(dict(refinement_audit))
    if refinement_audit.get("pending_second_look") is True:
        classification[
            "complete_path_no_good_deferred_for_render_variant"
        ] = True
        classification["complete_path_no_good_allowed"] = False
    elif refinement_audit.get("complete_path_no_good_allowed") is True:
        classification[
            "complete_path_no_good_deferred_for_render_variant"
        ] = False
        classification["same_path_bounded_refinement_exhausted"] = True
        if refinement_audit.get("path_invariant_nonlook_failure") is True:
            classification["path_invariant_nonlook_failure"] = True
    elif decoded_review_passed:
        classification[
            "complete_path_no_good_deferred_for_render_variant"
        ] = False


def _drain_joint_look_continuations(
    scheduler: JointLookBreadthScheduler,
    *,
    resume: Callable[[Any], Any],
    should_stop: Callable[[], bool],
) -> None:
    """Close the global first-attempt stream before revisiting retained paths."""
    scheduler.close_admission()
    for candidate_index in scheduler.pending_indices:
        if should_stop():
            break
        state = scheduler.get(candidate_index)
        assert state is not None
        resume(state.materialized)
        if scheduler.get(candidate_index) is not None:
            raise RuntimeError("resumed look candidate failed to reach a terminal verdict")


def _joint_group_look_sensitive_visible_audit(
    previous_review: Mapping[str, Any],
    proposed_review: Mapping[str, Any],
) -> dict[str, Any]:
    """Audit look-sensitive aggregate scores without using them as rollback."""

    def finite_scalar(value: Any) -> float | None:
        if (
            isinstance(value, bool)
            or not isinstance(value, (int, float))
            or not math.isfinite(float(value))
        ):
            return None
        return float(value)

    def decode(
        review: Mapping[str, Any],
        label: str,
    ) -> tuple[dict[str, float | None], tuple[str, ...]]:
        raw = review.get("visible_boundary_score")
        issues: list[str] = []
        if not isinstance(raw, Mapping):
            return {"p10": None, "issue_fraction": None}, (
                f"{label}_visible_boundary_score_contract_missing",
            )
        p10 = finite_scalar(raw.get("p10"))
        issue_fraction = finite_scalar(raw.get("issue_fraction"))
        if p10 is None:
            issues.append(f"{label}_visible_boundary_p10_invalid")
        if issue_fraction is None or not 0.0 <= issue_fraction <= 1.0:
            issues.append(f"{label}_visible_boundary_issue_fraction_invalid")
            issue_fraction = None
        return {"p10": p10, "issue_fraction": issue_fraction}, tuple(issues)

    previous, previous_issues = decode(previous_review, "previous")
    proposed, proposed_issues = decode(proposed_review, "proposed")
    contract_issues = (*previous_issues, *proposed_issues)
    p10_regressed = (
        proposed["p10"] < previous["p10"] - 1e-9
        if previous["p10"] is not None and proposed["p10"] is not None
        else None
    )
    issue_fraction_regressed = (
        proposed["issue_fraction"] > previous["issue_fraction"] + 1e-9
        if previous["issue_fraction"] is not None
        and proposed["issue_fraction"] is not None
        else None
    )
    return {
        "contract": "joint_group_look_sensitive_visible_audit_v1",
        "contract_valid": not contract_issues,
        "contract_issues": list(contract_issues),
        "previous": previous,
        "proposed": proposed,
        "p10_regressed": p10_regressed,
        "issue_fraction_regressed": issue_fraction_regressed,
        "acceptance_blocker": False,
        "used_for_nonlook_rollback": False,
    }


def _joint_group_exact_decoded_path_invariant_reasons(
    previous_review: Mapping[str, Any],
    proposed_review: Mapping[str, Any],
    *,
    previous_render_timeline_binding_sha256: str | None = None,
    proposed_render_timeline_binding_sha256: str | None = None,
) -> tuple[str, ...]:
    """Compare exact decoded cut, clock, transition, and geometry identities."""

    reasons: list[str] = []

    def exact_integer(value: Any, *, positive: bool = False) -> int | None:
        minimum = 1 if positive else 0
        return (
            value
            if isinstance(value, int)
            and not isinstance(value, bool)
            and value >= minimum
            else None
        )

    def finite_scalar(value: Any, *, positive: bool = False) -> float | None:
        if (
            isinstance(value, bool)
            or not isinstance(value, (int, float))
            or not math.isfinite(float(value))
        ):
            return None
        scalar = float(value)
        if scalar < (1e-12 if positive else 0.0):
            return None
        return scalar

    def exact_text(value: Any) -> str | None:
        return (
            value
            if isinstance(value, str) and value and value == value.strip()
            else None
        )

    def exact_sha256(value: Any) -> str | None:
        return (
            value
            if isinstance(value, str)
            and len(value) == 64
            and all(character in "0123456789abcdef" for character in value)
            else None
        )

    def exact_integer_tuple(
        value: Any,
        *,
        nonnegative: bool = True,
    ) -> tuple[int, ...] | None:
        if not isinstance(value, list) or not value or any(
            isinstance(item, bool)
            or not isinstance(item, int)
            or (nonnegative and item < 0)
            for item in value
        ):
            return None
        return tuple(value)

    def indexed_boundaries(
        review: Mapping[str, Any],
        label: str,
    ) -> dict[int, Mapping[str, Any]] | None:
        raw = review.get("boundaries")
        if not isinstance(raw, list):
            reasons.append(f"{label}_decoded_boundary_contract_missing")
            return None
        indexed: dict[int, Mapping[str, Any]] = {}
        for item in raw:
            boundary_index = (
                item.get("boundary_index")
                if isinstance(item, Mapping)
                else None
            )
            if (
                exact_integer(boundary_index) is None
                or boundary_index in indexed
            ):
                reasons.append(f"{label}_decoded_boundary_contract_invalid")
                return None
            assert isinstance(boundary_index, int)
            indexed[boundary_index] = item
        if set(indexed) != set(range(len(raw))):
            reasons.append(f"{label}_decoded_boundary_index_domain_invalid")
            return None
        return indexed

    previous_by_index = indexed_boundaries(previous_review, "previous")
    proposed_by_index = indexed_boundaries(proposed_review, "proposed")
    if previous_by_index is not None and proposed_by_index is not None:
        if len(previous_by_index) != len(proposed_by_index):
            reasons.append("decoded_boundary_count_changed")
        if previous_by_index.keys() != proposed_by_index.keys():
            reasons.append("decoded_boundary_index_domain_changed")
        for boundary_index in sorted(
            previous_by_index.keys() & proposed_by_index.keys()
        ):
            previous_boundary = previous_by_index[boundary_index]
            proposed_boundary = proposed_by_index[boundary_index]
            field_specs = (
                ("review_domain", exact_text),
                ("outgoing_source_index", exact_integer),
                ("incoming_source_index", exact_integer),
                ("cut_frame_index", exact_integer),
                ("frame_indices", exact_integer_tuple),
                (
                    "sample_offsets",
                    lambda value: exact_integer_tuple(
                        value,
                        nonnegative=False,
                    ),
                ),
                ("transition_reason", exact_text),
                ("transition_tier", exact_text),
                ("transition_kind", exact_text),
                ("transition_frame_count", exact_integer),
                ("transition_duration_seconds", finite_scalar),
                (
                    "source_clock_contiguous",
                    lambda value: value if isinstance(value, bool) else None,
                ),
            )
            for field, validator in field_specs:
                previous_value = validator(previous_boundary.get(field))
                proposed_value = validator(proposed_boundary.get(field))
                if previous_value is None or proposed_value is None:
                    reasons.append(
                        f"boundary_{boundary_index}_{field}_contract_missing"
                    )
                elif previous_value != proposed_value:
                    reasons.append(f"boundary_{boundary_index}_{field}_changed")
            for label, boundary in (
                ("previous", previous_boundary),
                ("proposed", proposed_boundary),
            ):
                cut_frame_index = exact_integer(
                    boundary.get("cut_frame_index")
                )
                frame_indices = exact_integer_tuple(
                    boundary.get("frame_indices")
                )
                sample_offsets = exact_integer_tuple(
                    boundary.get("sample_offsets"),
                    nonnegative=False,
                )
                if (
                    cut_frame_index is not None
                    and frame_indices is not None
                    and sample_offsets is not None
                    and frame_indices
                    != tuple(cut_frame_index + offset for offset in sample_offsets)
                ):
                    reasons.append(
                        f"{label}_boundary_{boundary_index}_source_clock_binding_invalid"
                    )
            previous_technical = _joint_exact_boundary_reason_list(
                previous_boundary,
                "technical_integrity_issue_reasons",
            )
            proposed_technical = _joint_exact_boundary_reason_list(
                proposed_boundary,
                "technical_integrity_issue_reasons",
            )
            if previous_technical is None or proposed_technical is None:
                reasons.append(
                    f"boundary_{boundary_index}_technical_contract_missing"
                )
            elif not set(proposed_technical).issubset(previous_technical):
                reasons.append(
                    f"boundary_{boundary_index}_technical_integrity_regressed"
                )

    def interior_identity(
        review: Mapping[str, Any],
        label: str,
        expected_binding: str | None,
    ) -> dict[str, Any] | None:
        raw = review.get("segment_interior_geometry")
        if not isinstance(raw, Mapping):
            reasons.append(f"{label}_segment_interior_geometry_missing")
            return None
        identity: dict[str, Any] = {}
        scalar_specs = (
            ("schema_version", lambda value: exact_integer(value, positive=True)),
            ("contract", exact_text),
            ("analysis_basis", exact_text),
            ("source_index_domain", exact_text),
            ("output_frame_index_domain", exact_text),
            ("sampling_schedule_sha256", exact_sha256),
            ("segment_count", exact_integer),
            ("sample_count", exact_integer),
        )
        for field, validator in scalar_specs:
            value = validator(raw.get(field))
            if value is None:
                reasons.append(f"{label}_segment_interior_{field}_invalid")
            identity[field] = value
        for field in ("sampling_policy", "geometry_backend_provenance"):
            value = raw.get(field)
            if not isinstance(value, Mapping):
                reasons.append(f"{label}_segment_interior_{field}_invalid")
                identity[field] = None
            else:
                identity[field] = deepcopy(dict(value))
        provenance = identity.get("geometry_backend_provenance")
        if isinstance(provenance, Mapping):
            for backend_field in ("face_backends", "silhouette_backends"):
                backends = provenance.get(backend_field)
                if not isinstance(backends, list) or any(
                    not isinstance(item, str)
                    or not item
                    or item != item.strip()
                    for item in backends
                ):
                    reasons.append(
                        f"{label}_geometry_backend_{backend_field}_invalid"
                    )
        binding = exact_sha256(raw.get("render_timeline_binding_sha256"))
        if binding is None:
            reasons.append(f"{label}_render_timeline_binding_invalid")
        identity["render_timeline_binding_sha256"] = binding
        if expected_binding is not None:
            exact_expected = exact_sha256(expected_binding)
            if exact_expected is None:
                reasons.append(f"{label}_expected_render_timeline_binding_invalid")
            elif binding != exact_expected:
                reasons.append(f"{label}_render_timeline_binding_mismatch")

        proxy = raw.get("proxy_identity")
        proxy_identity: dict[str, Any] = {}
        if not isinstance(proxy, Mapping):
            reasons.append(f"{label}_proxy_clock_identity_missing")
        else:
            proxy_specs = (
                ("width", lambda value: exact_integer(value, positive=True)),
                ("height", lambda value: exact_integer(value, positive=True)),
                ("fps", lambda value: finite_scalar(value, positive=True)),
                (
                    "decoded_frame_count",
                    lambda value: exact_integer(value, positive=True),
                ),
                (
                    "duration_seconds",
                    lambda value: finite_scalar(value, positive=True),
                ),
                ("render_codec", exact_text),
            )
            for field, validator in proxy_specs:
                value = validator(proxy.get(field))
                if value is None:
                    reasons.append(f"{label}_proxy_{field}_invalid")
                proxy_identity[field] = value
        identity["proxy_clock_identity"] = proxy_identity

        raw_segments = raw.get("segments")
        segment_identity: list[tuple[Any, ...]] = []
        if not isinstance(raw_segments, list) or not raw_segments:
            reasons.append(f"{label}_segment_identity_contract_missing")
        else:
            previous_segment_end: int | None = None
            for position, segment in enumerate(raw_segments):
                if not isinstance(segment, Mapping):
                    reasons.append(f"{label}_segment_{position}_contract_invalid")
                    continue
                values = (
                    exact_integer(segment.get("segment_index")),
                    exact_integer(segment.get("source_index")),
                    exact_integer(segment.get("segment_frame_start")),
                    exact_integer(segment.get("segment_frame_end")),
                    exact_integer(segment.get("segment_frame_count"), positive=True),
                    exact_sha256(segment.get("source_content_sha256")),
                )
                if any(value is None for value in values):
                    reasons.append(f"{label}_segment_{position}_identity_invalid")
                elif values[0] != position:
                    reasons.append(f"{label}_segment_{position}_index_invalid")
                else:
                    segment_start = values[2]
                    segment_end = values[3]
                    segment_count = values[4]
                    assert isinstance(segment_start, int)
                    assert isinstance(segment_end, int)
                    assert isinstance(segment_count, int)
                    if segment_end - segment_start != segment_count:
                        reasons.append(
                            f"{label}_segment_{position}_frame_clock_invalid"
                        )
                    if (
                        (position == 0 and segment_start != 0)
                        or (
                            position > 0
                            and previous_segment_end != segment_start
                        )
                    ):
                        reasons.append(
                            f"{label}_segment_{position}_continuity_invalid"
                        )
                    previous_segment_end = segment_end
                segment_identity.append(values)
        if identity.get("segment_count") != len(segment_identity):
            reasons.append(f"{label}_segment_count_binding_mismatch")
        identity["segments"] = tuple(segment_identity)
        decoded_frame_count = proxy_identity.get("decoded_frame_count")
        if (
            isinstance(decoded_frame_count, int)
            and segment_identity
            and segment_identity[-1][3] != decoded_frame_count
        ):
            reasons.append(f"{label}_segment_output_clock_binding_mismatch")
        return identity

    previous_interior = interior_identity(
        previous_review,
        "previous",
        previous_render_timeline_binding_sha256,
    )
    proposed_interior = interior_identity(
        proposed_review,
        "proposed",
        proposed_render_timeline_binding_sha256,
    )
    if previous_interior is not None and proposed_interior is not None:
        for field in (
            "schema_version",
            "contract",
            "analysis_basis",
            "source_index_domain",
            "output_frame_index_domain",
            "sampling_schedule_sha256",
            "segment_count",
            "sample_count",
            "sampling_policy",
            "geometry_backend_provenance",
            "proxy_clock_identity",
            "segments",
        ):
            if previous_interior.get(field) != proposed_interior.get(field):
                reasons.append(f"segment_interior_{field}_changed")
    return tuple(dict.fromkeys(reasons))


def _joint_group_nonlook_regression_reasons(
    previous_review: Mapping[str, Any],
    proposed_review: Mapping[str, Any],
    *,
    previous_render_timeline_binding_sha256: str | None = None,
    proposed_render_timeline_binding_sha256: str | None = None,
) -> tuple[str, ...]:
    """Keep exact path identity and non-look gates safe during look repair.

    Aggregate visible p10/issue-fraction values remain audited, but their
    monotonic movement is intentionally not an acceptance blocker because look
    correction changes the pixels those aggregate metrics measure.
    """

    reasons: list[str] = []

    def integer_count(payload: Mapping[str, Any], name: str) -> int | None:
        value = payload.get(name)
        return (
            value
            if isinstance(value, int)
            and not isinstance(value, bool)
            and value >= 0
            else None
        )

    def issue_set(value: Any) -> frozenset[str] | None:
        if not isinstance(value, list) or any(
            not isinstance(item, str) or not item for item in value
        ):
            return None
        return frozenset(value)

    def gate_passed(payload: Mapping[str, Any], name: str) -> bool | None:
        raw = payload.get(name)
        value = raw.get("passed") if isinstance(raw, Mapping) else raw
        return value if isinstance(value, bool) else None

    previous_geometry = integer_count(
        previous_review,
        "geometry_provider_failure_count",
    )
    proposed_geometry = integer_count(
        proposed_review,
        "geometry_provider_failure_count",
    )
    if (
        previous_geometry is None
        or proposed_geometry is None
        or proposed_geometry > previous_geometry
    ):
        reasons.append("geometry_provider_failure_count_regressed")

    previous_global_technical = issue_set(
        previous_review.get("introduced_cross_source_technical_issue_reasons")
    )
    proposed_global_technical = issue_set(
        proposed_review.get("introduced_cross_source_technical_issue_reasons")
    )
    if previous_global_technical is None or proposed_global_technical is None:
        reasons.append("global_technical_integrity_contract_missing")
    elif not proposed_global_technical.issubset(previous_global_technical):
        reasons.append("global_technical_integrity_issue_set_regressed")

    # Contract validity and score movement are retained in the iteration audit.
    # They are deliberately absent from this acceptance-blocker list.
    _joint_group_look_sensitive_visible_audit(previous_review, proposed_review)

    previous_interior = previous_review.get("segment_interior_geometry")
    proposed_interior = proposed_review.get("segment_interior_geometry")
    if not isinstance(previous_interior, Mapping) or not isinstance(
        proposed_interior,
        Mapping,
    ):
        reasons.append("segment_interior_geometry_missing")
    else:
        previous_complete = previous_interior.get("complete")
        proposed_complete = proposed_interior.get("complete")
        if not isinstance(previous_complete, bool) or not isinstance(
            proposed_complete,
            bool,
        ):
            reasons.append("segment_interior_geometry_contract_missing")
        elif previous_complete and not proposed_complete:
            reasons.append("segment_interior_geometry_completeness_regressed")
        previous_failures = integer_count(
            previous_interior,
            "geometry_provider_failure_count",
        )
        proposed_failures = integer_count(
            proposed_interior,
            "geometry_provider_failure_count",
        )
        if (
            previous_failures is None
            or proposed_failures is None
            or proposed_failures > previous_failures
        ):
            reasons.append("segment_interior_geometry_failures_regressed")

    for gate_name in (
        "technical_proxy_passed_before_montage_grammar",
        "professional_reference_gate",
        "rendered_montage_grammar_review",
    ):
        previous_passed = gate_passed(previous_review, gate_name)
        proposed_passed = gate_passed(proposed_review, gate_name)
        if previous_passed is None or proposed_passed is None:
            reasons.append(f"{gate_name}_contract_missing")
        elif previous_passed and not proposed_passed:
            reasons.append(f"{gate_name}_regressed")

    reasons.extend(
        _joint_group_exact_decoded_path_invariant_reasons(
            previous_review,
            proposed_review,
            previous_render_timeline_binding_sha256=(
                previous_render_timeline_binding_sha256
            ),
            proposed_render_timeline_binding_sha256=(
                proposed_render_timeline_binding_sha256
            ),
        )
    )
    return tuple(dict.fromkeys(reasons))


def _joint_group_look_refinement_acceptance(
    previous_objective: DecodedLookObjective,
    previous_review: Mapping[str, Any],
    proposed_review: Mapping[str, Any],
    *,
    previous_render_timeline_binding_sha256: str | None = None,
    proposed_render_timeline_binding_sha256: str | None = None,
) -> tuple[DecodedLookObjective, tuple[str, ...], bool]:
    """Apply the production strict-improvement plus non-look rollback gate."""

    if not isinstance(previous_objective, DecodedLookObjective):
        raise TypeError("previous GROUP decoded look objective is invalid")
    proposed_objective = decoded_look_objective(proposed_review)
    nonlook_regressions = _joint_group_nonlook_regression_reasons(
        previous_review,
        proposed_review,
        previous_render_timeline_binding_sha256=(
            previous_render_timeline_binding_sha256
        ),
        proposed_render_timeline_binding_sha256=(
            proposed_render_timeline_binding_sha256
        ),
    )
    accepted = bool(
        proposed_objective.strictly_improves(previous_objective)
        and not nonlook_regressions
    )
    return proposed_objective, nonlook_regressions, accepted


def _select_joint_decoded_passing_cohort(
    bundles: Sequence["_GroupRenderCandidateBundle"],
    reviews: Sequence[RenderedCandidateReview],
) -> tuple[
    tuple["_GroupRenderCandidateBundle", RenderedCandidateReview], ...
]:
    """Choose a quality-passing deliverable, not eight redundant deliverables."""

    if len(bundles) != len(reviews):
        raise ValueError("joint decoded bundles and reviews must align")
    ranked: list[
        tuple[_GroupRenderCandidateBundle, RenderedCandidateReview]
    ] = []
    seen_indices: set[int] = set()
    for bundle, review in zip(bundles, reviews, strict=True):
        if not isinstance(bundle, _GroupRenderCandidateBundle):
            raise TypeError("joint decoded cohort contains an invalid bundle")
        if not isinstance(review, RenderedCandidateReview) or not review.passed:
            raise ValueError("joint decoded cohort may contain only passing reviews")
        if bundle.candidate_index in seen_indices:
            raise ValueError("joint decoded cohort repeats a candidate index")
        seen_indices.add(bundle.candidate_index)
        ranked.append((bundle, review))
    ranked.sort(
        key=lambda pair: (
            -pair[1].ranking_weighted_score,
            -pair[1].weighted_score,
            -pair[0].pre_render_score,
            pair[0].candidate_index,
        )
    )
    selected: list[
        tuple[_GroupRenderCandidateBundle, RenderedCandidateReview]
    ] = []
    path_counts: dict[tuple[tuple[str, str], ...], int] = {}
    for pair in ranked:
        path = _exact_source_shot_path(pair[0])
        if (
            path_counts.get(path, 0)
            >= _JOINT_MAXIMUM_VARIANTS_PER_SOURCE_SHOT_PATH
        ):
            continue
        path_counts[path] = path_counts.get(path, 0) + 1
        selected.append(pair)
        if len(selected) == _JOINT_REQUIRED_DECODED_PASS_COUNT:
            break
    if len(selected) < _JOINT_REQUIRED_DECODED_PASS_COUNT:
        return ()
    if not path_counts:
        raise RuntimeError("joint delivery cohort has no source/shot path")
    return tuple(selected)


class _GlobalVisualCandidateStream:
    """Allocate monotonic IDs and reject exact source+shot path replays."""

    def __init__(self) -> None:
        self._seen_paths: set[tuple[tuple[str, str], ...]] = set()
        self._next_candidate_index = 0

    @property
    def seen_path_count(self) -> int:
        return len(self._seen_paths)

    @property
    def next_candidate_index(self) -> int:
        return self._next_candidate_index

    def admit_unseen(
        self,
        candidate: Any,
    ) -> _GloballyIndexedVisualCandidate | None:
        path = _exact_source_shot_path(candidate)
        if path in self._seen_paths:
            return None
        self._seen_paths.add(path)
        candidate_index = self._next_candidate_index
        self._next_candidate_index += 1
        return _GloballyIndexedVisualCandidate(
            materialized=candidate,
            candidate_index=candidate_index,
        )


def _cross_source_timeline_edge_keys(
    plan_or_choices: Any,
) -> tuple[TimelineNoGoodEdgeKey, ...]:
    choices = getattr(plan_or_choices, "choices", plan_or_choices)
    if not isinstance(choices, tuple) or not choices:
        raise TypeError("timeline edge extraction needs a non-empty tuple")
    return tuple(
        build_timeline_no_good_edge_key(
            boundary_index,
            outgoing,
            incoming,
        )
        for boundary_index, (outgoing, incoming) in enumerate(
            zip(choices, choices[1:])
        )
        if outgoing.source_index != incoming.source_index
    )


def _cross_source_timeline_edge_contexts(
    plan: VisualTimelinePlan,
) -> tuple[tuple[TimelineNoGoodEdgeKey, str], ...]:
    """Bind each compact DP edge to its exact candidate clock/span context."""

    if not isinstance(plan, VisualTimelinePlan):
        raise TypeError("timeline edge contexts need a VisualTimelinePlan")
    return tuple(
        (
            build_timeline_no_good_edge_key(
                boundary_index,
                outgoing,
                incoming,
            ),
            splice_feedback_edge_context_identity(plan, boundary_index),
        )
        for boundary_index, (outgoing, incoming) in enumerate(
            zip(plan.choices, plan.choices[1:])
        )
        if outgoing.source_index != incoming.source_index
    )


def _splice_graph_keys_for_plan(
    plan: VisualTimelinePlan,
) -> tuple[LazySpliceFeasibilityKey, ...]:
    return tuple(
        LazySpliceFeasibilityKey(edge, edge_context_identity)
        for edge, edge_context_identity in (
            _cross_source_timeline_edge_contexts(plan)
        )
    )


def _splice_result_graph_keys_for_plan(
    plan: VisualTimelinePlan,
) -> tuple[LazySpliceFeasibilityKey, ...]:
    return tuple(
        LazySpliceFeasibilityKey(
            build_timeline_no_good_edge_key(
                boundary_index,
                outgoing,
                incoming,
            ),
            splice_feedback_result_context_identity(plan, boundary_index),
        )
        for boundary_index, (outgoing, incoming) in enumerate(
            zip(plan.choices, plan.choices[1:])
        )
        if outgoing.source_index != incoming.source_index
    )


def _optimizer_blocked_set_for_contexts(
    graph: LazySpliceFeasibilityGraph,
    optimizer_context_keys: Iterable[LazySpliceFeasibilityKey],
) -> TimelineNoGoodSet:
    # Only a complete non-waivable visual failure may alter the cheap DP
    # graph. Missing descriptors and other indeterminate contexts can stop
    # expensive work in this run, but can never prove structural infeasibility.
    return graph.hard_no_goods_for_contexts(tuple(optimizer_context_keys))


def _incomplete_splice_context_keys(
    graph: LazySpliceFeasibilityGraph,
    optimizer_context_keys: Iterable[LazySpliceFeasibilityKey],
) -> tuple[LazySpliceFeasibilityKey, ...]:
    """Return exact contexts that are missing or still indeterminate."""

    keys = tuple(optimizer_context_keys)
    if any(not isinstance(key, LazySpliceFeasibilityKey) for key in keys):
        raise TypeError("optimizer splice context keys are invalid")
    return tuple(
        sorted(
            key
            for key in keys
            for assessment in (
                graph.assessment_for(
                    key.edge,
                    key.edge_context_identity,
                ),
            )
            if assessment is None
            or assessment.status is SpliceFeasibilityStatus.INDETERMINATE
        )
    )


def _splice_authorization_evidence_incomplete(
    authorization: object,
) -> bool:
    """Separate missing/indeterminate proof from complete hard rejection."""

    if not isinstance(authorization, Mapping):
        return True
    raw_evidence = authorization.get("evidence")
    if not isinstance(raw_evidence, list) or not raw_evidence:
        return True
    for item in raw_evidence:
        if not isinstance(item, Mapping):
            return True
        reason = item.get("authorization_failure")
        if reason is None:
            continue
        if not isinstance(reason, str) or not reason:
            return True
        if "missing" in reason or "incomplete" in reason:
            return True
        if reason == "fresh_candidate_result_proof_invalid":
            if not (
                item.get("fresh_result_status")
                == SpliceFeasibilityStatus.HARD_INCOMPATIBLE.value
                and item.get("fresh_result_terminal") is True
            ):
                return True
            continue
        if reason == "analysis_graph_result_proof_invalid":
            if not (
                item.get("retained_result_status")
                == SpliceFeasibilityStatus.HARD_INCOMPATIBLE.value
                and item.get("retained_result_terminal") is True
            ):
                return True
            continue
        if reason.startswith("fresh_candidate_edge_"):
            if not (
                item.get("fresh_status")
                == SpliceFeasibilityStatus.HARD_INCOMPATIBLE.value
                and item.get("fresh_terminal") is True
            ):
                return True
            continue
        return True
    return False


def _claim_exact_splice_refinement_keys(
    attempted: set[LazySpliceFeasibilityKey],
    requested: Sequence[LazySpliceFeasibilityKey],
) -> tuple[LazySpliceFeasibilityKey, ...]:
    """Claim one exact raw-context/domain search at most once per candidate."""

    if not isinstance(attempted, set):
        raise TypeError("attempted splice refinement keys must be a set")
    keys = tuple(requested)
    if not keys or any(
        not isinstance(key, LazySpliceFeasibilityKey) for key in keys
    ):
        raise TypeError("requested splice refinement keys are invalid")
    if len(set(keys)) != len(keys):
        raise ValueError("requested splice refinement keys cannot repeat")
    claimed = tuple(key for key in keys if key not in attempted)
    attempted.update(claimed)
    return claimed


def _optimizer_workspace_cross_source_edge_bound(
    candidate_set: VisualTimelineCandidateSet,
) -> int:
    """Count the complete finite exact-edge domain retained by the DP."""

    workspace = candidate_set.optimizer_workspace
    if workspace is None:
        raise ValueError("candidate set has no optimizer workspace")
    edge_keys: set[TimelineNoGoodEdgeKey] = set()
    for boundary_index, (outgoing_candidates, incoming_candidates) in enumerate(
        zip(
            workspace.candidates_by_segment,
            workspace.candidates_by_segment[1:],
        )
    ):
        edge_keys.update(
            build_timeline_no_good_edge_key(
                boundary_index,
                outgoing,
                incoming,
            )
            for outgoing in outgoing_candidates
            for incoming in incoming_candidates
            if outgoing.source_id != incoming.source_id
        )
    return len(edge_keys)


def _constraint_terminal_status(
    *,
    structural_hard_no_path: bool,
    resource_incomplete: bool,
    incomplete_exact_context_count: int,
    authorized_path_count: int,
    required_authorized_path_count: int = 8,
) -> str:
    """Classify one incomplete stream without conflating proof domains."""

    for name, value in (
        ("incomplete_exact_context_count", incomplete_exact_context_count),
        ("authorized_path_count", authorized_path_count),
        ("required_authorized_path_count", required_authorized_path_count),
    ):
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise ValueError(f"{name} must be a non-negative integer")
    if required_authorized_path_count < 1:
        raise ValueError("required authorized path count must be positive")
    if not isinstance(structural_hard_no_path, bool) or not isinstance(
        resource_incomplete,
        bool,
    ):
        raise TypeError("constraint terminal proof flags must be booleans")
    if structural_hard_no_path and resource_incomplete:
        raise ValueError(
            "structural and resource terminal proofs are mutually exclusive"
        )
    if resource_incomplete:
        return "resource_incomplete"
    if structural_hard_no_path:
        return "structural_hard_no_path"
    if incomplete_exact_context_count:
        return "evidence_incomplete_before_authorized_cohort"
    if authorized_path_count < required_authorized_path_count:
        return "authorized_path_count_insufficient"
    raise ValueError("complete authorized cohort has no terminal failure")


class _BoundarySearchBudgetExhausted(RuntimeError):
    """Raised before an ordinary candidate search would exceed its audit cap."""

    def __init__(self, payload: Mapping[str, Any]) -> None:
        self.payload = deepcopy(dict(payload))
        super().__init__(
            "ordinary splice boundary-search budget exhausted; "
            "production use is forbidden"
        )


class _BoundarySearchNoProgress(RuntimeError):
    """Raised before re-decoding an already measured exact raw context."""

    def __init__(self, payload: Mapping[str, Any]) -> None:
        self.payload = deepcopy(dict(payload))
        super().__init__(
            "exact boundary context was already measured under this domain; "
            "the branch made no new evidence and production use is forbidden"
        )


class _BoundarySearchBudget:
    """Bound decoded boundary searches by unique exact input context.

    Descriptor-cache hits are still audited, but do not create a second unique
    search token for the same exact edge, input clock/span, and radius.  This
    prevents the constrained loop from scaling decoded work as
    ``rounds * top-k * segment-count`` while keeping cheap graph/DP work free.
    """

    def __init__(self, *, structural_edge_bound: int) -> None:
        if (
            isinstance(structural_edge_bound, bool)
            or not isinstance(structural_edge_bound, int)
            or structural_edge_bound < 0
        ):
            raise ValueError(
                "boundary-search structural edge bound must be non-negative"
            )
        self._structural_edge_bound = structural_edge_bound
        self._maximum_unique_boundary_searches = min(
            MAX_CONSTRAINT_UNIQUE_BOUNDARY_SEARCHES,
            max(
                CONSTRAINT_FINALIST_STABILIZATION_ALLOWANCE,
                structural_edge_bound
                + CONSTRAINT_FINALIST_STABILIZATION_ALLOWANCE,
            ),
        )
        self._maximum_offset_evaluations = min(
            MAX_CONSTRAINT_OFFSET_EVALUATIONS,
            self._maximum_unique_boundary_searches
            * len(DEFAULT_WIDE_FRAME_OFFSETS),
        )
        self._unique_search_tokens: set[
            tuple[TimelineNoGoodEdgeKey, str, int]
        ] = set()
        self._planned_offset_evaluation_count = 0
        self._repair_call_count = 0
        self._requested_boundary_count = 0
        self._descriptor_cache_hit_count = 0
        self._descriptor_cache_miss_count = 0
        self._geometry_provider_attempt_count = 0
        self._phase_call_counts: dict[str, int] = {}
        self._exhaustion: dict[str, Any] | None = None
        self._repair_result_memo: dict[
            str, VisualBoundaryRepairPlan
        ] = {}
        self._repair_result_memo_hit_count = 0

    def memoized_repair(
        self,
        request_identity: str,
    ) -> VisualBoundaryRepairPlan | None:
        result = self._repair_result_memo.get(request_identity)
        if result is not None:
            self._repair_result_memo_hit_count += 1
        return result

    def remember_repair(
        self,
        request_identity: str,
        repair_plan: VisualBoundaryRepairPlan,
    ) -> None:
        if not isinstance(repair_plan, VisualBoundaryRepairPlan):
            raise TypeError("boundary repair memo value is invalid")
        existing = self._repair_result_memo.get(request_identity)
        if existing is not None and existing != repair_plan:
            raise RuntimeError("boundary repair memo identity collision")
        self._repair_result_memo[request_identity] = repair_plan

    def expand_structural_edge_bound(self, value: int) -> None:
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise ValueError(
                "boundary-search structural edge bound must be non-negative"
            )
        if value <= self._structural_edge_bound:
            return
        self._structural_edge_bound = value
        self._maximum_unique_boundary_searches = min(
            MAX_CONSTRAINT_UNIQUE_BOUNDARY_SEARCHES,
            value + CONSTRAINT_FINALIST_STABILIZATION_ALLOWANCE,
        )
        self._maximum_offset_evaluations = min(
            MAX_CONSTRAINT_OFFSET_EVALUATIONS,
            self._maximum_unique_boundary_searches
            * len(DEFAULT_WIDE_FRAME_OFFSETS),
        )

    @staticmethod
    def _cache_counts(
        descriptor_cache: BoundaryDescriptorCache | None,
    ) -> tuple[int, int]:
        if descriptor_cache is None:
            return 0, 0
        diagnostics = descriptor_cache.diagnostics()
        return (
            int(diagnostics["hit_count"]),
            int(diagnostics["miss_count"]),
        )

    def reserve(
        self,
        *,
        phase: str,
        visual_timeline: VisualTimelinePlan,
        boundary_indices: Sequence[int] | None,
        search_radius_frames: int,
    ) -> dict[str, Any]:
        if not isinstance(phase, str) or not phase or phase != phase.strip():
            raise ValueError("boundary-search phase must be an exact identifier")
        if not isinstance(visual_timeline, VisualTimelinePlan):
            raise TypeError("boundary-search timeline is invalid")
        if (
            isinstance(search_radius_frames, bool)
            or not isinstance(search_radius_frames, int)
            or search_radius_frames < 0
        ):
            raise ValueError("boundary-search radius must be non-negative")
        all_contexts = {
            edge.boundary_index: (edge, context_identity)
            for edge, context_identity in (
                _cross_source_timeline_edge_contexts(visual_timeline)
            )
        }
        if boundary_indices is None:
            requested = tuple(sorted(all_contexts))
        else:
            requested = tuple(boundary_indices)
            if any(
                isinstance(value, bool)
                or not isinstance(value, int)
                or value < 0
                or value + 1 >= len(visual_timeline.choices)
                for value in requested
            ):
                raise ValueError("boundary-search indices are invalid")
            if len(set(requested)) != len(requested):
                raise ValueError("boundary-search indices cannot be duplicated")
            requested = tuple(sorted(requested))
        cross_source_requested = tuple(
            boundary_index
            for boundary_index in requested
            if boundary_index in all_contexts
        )
        candidate_tokens = {
            (
                all_contexts[boundary_index][0],
                all_contexts[boundary_index][1],
                search_radius_frames,
            )
            for boundary_index in cross_source_requested
        }
        new_tokens = candidate_tokens.difference(self._unique_search_tokens)
        existing_tokens = candidate_tokens.intersection(
            self._unique_search_tokens
        )
        if existing_tokens:
            no_progress = {
                "contract": "ordinary_exact_boundary_search_no_progress_v1",
                "phase": phase,
                "reason": "exact_context_no_progress",
                "requested_boundary_count": len(cross_source_requested),
                "previously_measured_boundary_count": len(existing_tokens),
                "new_unique_boundary_search_count": len(new_tokens),
                "previously_measured_contexts": [
                    {
                        "edge": edge.to_dict(),
                        "edge_context_identity": context_identity,
                        "search_radius_frames": radius,
                    }
                    for edge, context_identity, radius in sorted(
                        existing_tokens
                    )
                ],
                "production_use_forbidden": True,
                "thresholds_lowered": False,
            }
            raise _BoundarySearchNoProgress(no_progress)
        offset_count = search_radius_frames * 2 + 1
        new_offset_evaluations = len(new_tokens) * offset_count
        projected_unique = len(self._unique_search_tokens) + len(new_tokens)
        projected_offsets = (
            self._planned_offset_evaluation_count + new_offset_evaluations
        )
        if (
            projected_unique > self._maximum_unique_boundary_searches
            or projected_offsets > self._maximum_offset_evaluations
        ):
            self._exhaustion = {
                "contract": "ordinary_exact_boundary_search_budget_v1",
                "phase": phase,
                "requested_boundary_count": len(cross_source_requested),
                "new_unique_boundary_search_count": len(new_tokens),
                "projected_unique_boundary_search_count": projected_unique,
                "maximum_unique_boundary_search_count": (
                    self._maximum_unique_boundary_searches
                ),
                "projected_offset_evaluation_count": projected_offsets,
                "maximum_offset_evaluation_count": (
                    self._maximum_offset_evaluations
                ),
                "production_use_forbidden": True,
                "thresholds_lowered": False,
            }
            raise _BoundarySearchBudgetExhausted(self._exhaustion)
        self._unique_search_tokens.update(new_tokens)
        self._planned_offset_evaluation_count = projected_offsets
        self._repair_call_count += 1
        self._requested_boundary_count += len(cross_source_requested)
        self._phase_call_counts[phase] = self._phase_call_counts.get(phase, 0) + 1
        return {
            "phase": phase,
            "requested_boundary_count": len(cross_source_requested),
            "new_unique_boundary_search_count": len(new_tokens),
            "new_offset_evaluation_count": new_offset_evaluations,
        }

    def observe(
        self,
        *,
        descriptor_cache_before: tuple[int, int],
        descriptor_cache_after: tuple[int, int],
        repair_plan: VisualBoundaryRepairPlan | None,
    ) -> None:
        before_hits, before_misses = descriptor_cache_before
        after_hits, after_misses = descriptor_cache_after
        if after_hits < before_hits or after_misses < before_misses:
            raise RuntimeError("boundary descriptor-cache counters regressed")
        self._descriptor_cache_hit_count += after_hits - before_hits
        self._descriptor_cache_miss_count += after_misses - before_misses
        if repair_plan is not None:
            self._geometry_provider_attempt_count += (
                repair_plan.geometry_provider_attempt_count
            )

    def to_dict(self) -> dict[str, Any]:
        return {
            "contract": "ordinary_exact_boundary_search_budget_v1",
            "structural_edge_bound": self._structural_edge_bound,
            "maximum_unique_boundary_search_count": (
                self._maximum_unique_boundary_searches
            ),
            "maximum_offset_evaluation_count": (
                self._maximum_offset_evaluations
            ),
            "repair_call_count": self._repair_call_count,
            "requested_boundary_count": self._requested_boundary_count,
            "unique_boundary_search_count": len(self._unique_search_tokens),
            "planned_offset_evaluation_count": (
                self._planned_offset_evaluation_count
            ),
            "descriptor_cache_hit_count": self._descriptor_cache_hit_count,
            "descriptor_cache_miss_count": self._descriptor_cache_miss_count,
            "geometry_provider_attempt_count": (
                self._geometry_provider_attempt_count
            ),
            "phase_call_counts": dict(sorted(self._phase_call_counts.items())),
            "repair_result_memo_entry_count": len(
                self._repair_result_memo
            ),
            "repair_result_memo_hit_count": (
                self._repair_result_memo_hit_count
            ),
            "exhausted": self._exhaustion is not None,
            "exhaustion": deepcopy(self._exhaustion),
            "production_use_forbidden": self._exhaustion is not None,
            "thresholds_lowered": False,
        }


def _boundary_repair_request_identity(
    *,
    visual_timeline: VisualTimelinePlan,
    sources: Sequence[Path],
    audio_offsets: Sequence[float],
    scene_cut_times: Sequence[Sequence[float]],
    beat_period_seconds: float | None,
    source_timewarps: Sequence[TimeWarpMap | None],
    boundary_indices: Sequence[int] | None,
    config: BoundaryRepairConfig,
) -> str:
    """Bind an immutable repair memo to every result-affecting input."""

    return canonical_json_sha256(
        {
            "contract": "exact_boundary_repair_request_identity_v1",
            "visual_timeline": visual_timeline.to_dict(),
            "sources": [str(Path(path).resolve()) for path in sources],
            "audio_offsets": [float(value) for value in audio_offsets],
            "scene_cut_times": [
                [float(value) for value in values]
                for values in scene_cut_times
            ],
            "beat_period_seconds": (
                float(beat_period_seconds)
                if beat_period_seconds is not None
                else None
            ),
            "source_timewarps": [
                value.to_dict() if value is not None else None
                for value in source_timewarps
            ],
            "boundary_indices": (
                sorted(int(value) for value in boundary_indices)
                if boundary_indices is not None
                else None
            ),
            "boundary_repair_config": asdict(config),
        }
    )


def _budgeted_repair_visual_timeline_boundaries(
    *,
    budget: _BoundarySearchBudget,
    phase: str,
    visual_timeline: VisualTimelinePlan,
    sources: Sequence[Path],
    audio_offsets: Sequence[float],
    scene_cut_times: Sequence[Sequence[float]],
    beat_period_seconds: float | None,
    source_timewarps: Sequence[TimeWarpMap | None],
    boundary_indices: Sequence[int] | None = None,
    descriptor_cache: BoundaryDescriptorCache | None = None,
    feature_cache_directory: Path | None = None,
    feature_derived_cache_directory: Path | None = None,
    require_persistent_feature_cache: bool = False,
    config: BoundaryRepairConfig | None = None,
) -> VisualBoundaryRepairPlan:
    if not isinstance(budget, _BoundarySearchBudget):
        raise TypeError("ordinary boundary repair needs a search budget")
    if not isinstance(require_persistent_feature_cache, bool):
        raise TypeError("require_persistent_feature_cache must be boolean")
    if require_persistent_feature_cache:
        if feature_derived_cache_directory is None:
            raise PersistentVisualFeatureCacheInitializationError(
                "persistent visual feature cache is required but was not configured"
            )
        try:
            assert_visual_feature_derived_cache_root_available(
                feature_derived_cache_directory
            )
        except PersistentVisualFeatureCacheStorageUnavailableError:
            raise PersistentVisualFeatureCacheRuntimeError(
                "required persistent visual feature cache failed during analysis"
            ) from None
    settings = config or BoundaryRepairConfig()
    request_identity = _boundary_repair_request_identity(
        visual_timeline=visual_timeline,
        sources=sources,
        audio_offsets=audio_offsets,
        scene_cut_times=scene_cut_times,
        beat_period_seconds=beat_period_seconds,
        source_timewarps=source_timewarps,
        boundary_indices=boundary_indices,
        config=settings,
    )
    memoized = budget.memoized_repair(request_identity)
    if memoized is not None:
        return memoized
    budget.reserve(
        phase=phase,
        visual_timeline=visual_timeline,
        boundary_indices=boundary_indices,
        search_radius_frames=settings.search_radius_frames,
    )
    before = budget._cache_counts(descriptor_cache)
    result: VisualBoundaryRepairPlan | None = None
    try:
        result = repair_visual_timeline_boundaries(
            visual_timeline=visual_timeline,
            sources=sources,
            audio_offsets=audio_offsets,
            scene_cut_times=scene_cut_times,
            beat_period_seconds=beat_period_seconds,
            source_timewarps=source_timewarps,
            boundary_indices=boundary_indices,
            descriptor_cache=descriptor_cache,
            feature_cache_directory=feature_cache_directory,
            feature_derived_cache_directory=feature_derived_cache_directory,
            require_persistent_feature_cache=(
                require_persistent_feature_cache
            ),
            config=settings,
        )
        budget.remember_repair(request_identity, result)
        return result
    finally:
        budget.observe(
            descriptor_cache_before=before,
            descriptor_cache_after=budget._cache_counts(descriptor_cache),
            repair_plan=result,
        )


def _group_splice_analysis_basis_identity(
    *,
    selector_input_identity_sha256: str,
    selector_input_identity_basis: str,
    timeline_review_config: TimelineReviewConfig | None = None,
    normal_boundary_repair_config: BoundaryRepairConfig | None = None,
    wide_boundary_repair_config: BoundaryRepairConfig | None = None,
    splice_feasibility_contract: str = SPLICE_FEASIBILITY_CONTRACT,
    splice_failure_feedback_contract: str = (
        SPLICE_FAILURE_FEEDBACK_CONTRACT
    ),
) -> str:
    """Bind splice evidence to the exact verified optimizer/checkpoint input."""

    review_config = timeline_review_config or TimelineReviewConfig()
    normal_repair_config = (
        normal_boundary_repair_config or BoundaryRepairConfig()
    )
    wide_repair_config = wide_boundary_repair_config or BoundaryRepairConfig(
        search_radius_frames=8,
        interior_scene_cut_guard_frames=9,
    )
    for value, name in (
        (splice_feasibility_contract, "splice_feasibility_contract"),
        (
            splice_failure_feedback_contract,
            "splice_failure_feedback_contract",
        ),
    ):
        if not isinstance(value, str) or not value or value != value.strip():
            raise ValueError(f"{name} must be an exact non-blank string")
    selector_identity = build_no_good_selector_identity(
        base_candidate_input_identity_sha256=(
            selector_input_identity_sha256
        ),
        base_identity_basis=selector_input_identity_basis,
        timeline_no_goods=TimelineNoGoodSet(),
    )
    return canonical_json_sha256(
        {
            "contract": "group_boundary_repair_splice_analysis_basis_v4",
            "selector_identity": selector_identity.to_dict(),
            "timeline_review_config": asdict(review_config),
            "normal_boundary_repair_config": asdict(normal_repair_config),
            "wide_boundary_repair_config": asdict(wide_repair_config),
            "constrained_preflight_frame_offsets": list(
                DEFAULT_WIDE_FRAME_OFFSETS
            ),
            "splice_feasibility_contract": splice_feasibility_contract,
            "splice_failure_feedback_contract": (
                splice_failure_feedback_contract
            ),
            "lazy_splice_feasibility_graph_contract": (
                LAZY_SPLICE_FEASIBILITY_GRAPH_CONTRACT
            ),
            "visual_boundary_repair_analysis_basis": (
                VISUAL_BOUNDARY_REPAIR_ANALYSIS_BASIS
            ),
            "semantic_analyzer_contract": (
                "exact_context_splice_evidence_analyzer_v1"
            ),
            "dependency_fingerprints": {
                "timeline_review": python_symbol_dependency_sha256(
                    Path(__file__).with_name("timeline_review.py"),
                    root_symbols=("review_timeline",),
                ),
                "boundary_repair": python_symbol_dependency_sha256(
                    Path(__file__).with_name("boundary_repair.py"),
                    root_symbols=("repair_boundary",),
                ),
                "visual_boundary_repair": python_symbol_dependency_sha256(
                    Path(__file__).with_name("visual_boundary_repair.py"),
                    root_symbols=("repair_visual_timeline_boundaries",),
                ),
                "rendered_boundary_clock": python_symbol_dependency_sha256(
                    Path(__file__).with_name("render_boundary_clock.py"),
                    root_symbols=("hard_cut_boundary_sample_clocks",),
                ),
                "verified_source_frame_clock": python_symbol_dependency_sha256(
                    Path(__file__).with_name("render_frame_schedule.py"),
                    root_symbols=("probe_render_frame_clock",),
                ),
                "splice_failure_feedback": python_symbol_dependency_sha256(
                    Path(__file__).with_name(
                        "visual_splice_failure_feedback.py"
                    ),
                    root_symbols=("build_splice_failure_feedback",),
                ),
                "splice_feasibility": python_symbol_dependency_sha256(
                    Path(__file__).with_name("visual_splice_feasibility.py"),
                    root_symbols=(
                        "classify_splice_evidence_audit",
                        "merge_splice_feasibility_assessments",
                    ),
                ),
            },
            "transition_thresholds_lowered": False,
        }
    )


def _boundary_repair_assessments(
    repair_plan: VisualBoundaryRepairPlan,
) -> tuple[
    tuple[TimelineNoGoodEdgeKey, str, SpliceFeasibilityAssessment], ...
]:
    """Aggregate one complete normal+wide repair before graph insertion."""

    if not isinstance(repair_plan, VisualBoundaryRepairPlan):
        raise TypeError("repair_plan must be a VisualBoundaryRepairPlan")
    if len(repair_plan.attempt_input_timelines) != 1:
        raise ValueError(
            "splice graph recording requires one atomic boundary repair attempt"
        )
    attempt_input_timeline = repair_plan.attempt_input_timelines[0]
    feedback = build_splice_failure_feedback(
        attempt_input_timeline,
        repair_plan.failures,
        expected_frame_offsets=DEFAULT_WIDE_FRAME_OFFSETS,
    )
    assessments: list[
        tuple[TimelineNoGoodEdgeKey, str, SpliceFeasibilityAssessment]
    ] = [
        (
            item.edge,
            item.edge_context_identity,
            assessment,
        )
        for item in feedback.edges
        for assessment in item.assessments
    ]
    choices = attempt_input_timeline.choices
    for repair in repair_plan.repairs:
        if not (
            repair.selected_visual_evidence.evidence_coverage
            .professional_gate_passed
        ):
            raise RuntimeError(
                "successful boundary repair lacks professional gate evidence"
            )
        edge = build_timeline_no_good_edge_key(
            repair.boundary_index,
            choices[repair.boundary_index],
            choices[repair.boundary_index + 1],
        )
        assessments.append(
            (
                edge,
                repair.observed_edge_context_identity,
                classify_splice_evidence_audit(
                    repair.candidate_evidence_audit,
                    expected_frame_offsets=DEFAULT_WIDE_FRAME_OFFSETS,
                ),
            )
        )
        assessments.append(
            (
                edge,
                repair.result_edge_context_identity,
                build_splice_feasibility_assessment(
                    expected_frame_offsets=DEFAULT_WIDE_FRAME_OFFSETS,
                    offsets=(
                        SpliceOffsetAssessment(
                            frame_offset=(
                                repair.result.selected_frame_offset
                            ),
                            production_gate_passed=True,
                            failure_codes=(),
                            evidence_complete=True,
                        ),
                    ),
                ),
            )
        )
    # Preserve each feedback item's canonical assessment sequence.  The graph
    # performs the monotonic offset-union; reducing or reprioritizing statuses
    # here would lose the partial -> wide refinement evidence.
    return tuple(assessments)


def _record_boundary_repair_assessments(
    graph: LazySpliceFeasibilityGraph,
    repair_plan: VisualBoundaryRepairPlan | None,
) -> int:
    if repair_plan is None:
        return 0
    try:
        assessments = _boundary_repair_assessments(repair_plan)
    except (TypeError, ValueError) as exc:
        raise RuntimeError(
            "boundary repair emitted invalid splice evidence"
        ) from exc
    changed = 0
    for edge, edge_context_identity, assessment in assessments:
        before = graph.assessment_for(edge, edge_context_identity)
        try:
            after = graph.record_assessment(
                edge,
                edge_context_identity,
                assessment,
            )
        except ValueError as exc:
            raise RuntimeError(
                "conflicting exact splice evidence in one analysis basis"
            ) from exc
        if before != after:
            changed += 1
    return changed


def _assessment_has_final_boundary_geometry_evidence(
    assessment: SpliceFeasibilityAssessment,
) -> bool:
    """Accept output proof only for the nominal boundary being rendered."""

    if not isinstance(assessment, SpliceFeasibilityAssessment):
        raise TypeError("geometry authorization assessment is invalid")
    return any(
        offset.frame_offset == 0 and offset.geometry_proof_eligible
        for offset in assessment.offsets
    )


_SPLICE_AUTHORIZATION_REFINEMENT_FAILURES = frozenset(
    {
        "fresh_candidate_edge_evidence_missing",
        "fresh_candidate_edge_evidence_incomplete",
        "analysis_graph_edge_evidence_missing",
        "analysis_graph_edge_evidence_incomplete",
    }
)


def _splice_authorization_refinement_boundary_indices(
    authorization: Mapping[str, Any],
) -> tuple[int, ...]:
    """Return exact edges that need one terminal wide-domain refinement."""

    if not isinstance(authorization, Mapping):
        raise TypeError("splice authorization must be a mapping")
    evidence = authorization.get("evidence")
    if not isinstance(evidence, list):
        raise RuntimeError("splice authorization evidence is malformed")
    boundary_indices: set[int] = set()
    for item in evidence:
        if not isinstance(item, Mapping):
            raise RuntimeError("splice authorization evidence item is malformed")
        if (
            item.get("authorization_failure")
            not in _SPLICE_AUTHORIZATION_REFINEMENT_FAILURES
        ):
            continue
        key = item.get("key")
        edge = key.get("edge") if isinstance(key, Mapping) else None
        boundary_index = (
            edge.get("boundary_index")
            if isinstance(edge, Mapping)
            else None
        )
        if (
            isinstance(boundary_index, bool)
            or not isinstance(boundary_index, int)
            or boundary_index < 0
        ):
            raise RuntimeError(
                "splice authorization refinement boundary is malformed"
            )
        boundary_indices.add(boundary_index)
    return tuple(sorted(boundary_indices))


def _candidate_local_splice_proxy_authorization(
    graph: LazySpliceFeasibilityGraph,
    *,
    final_timeline: VisualTimelinePlan,
    repair_plan: VisualBoundaryRepairPlan | None,
) -> dict[str, Any]:
    """Require fresh exact-context evidence before any decoded proxy work."""

    final_raw_keys = _splice_graph_keys_for_plan(final_timeline)
    final_result_keys = _splice_result_graph_keys_for_plan(final_timeline)
    if len(final_raw_keys) != len(final_result_keys):
        raise RuntimeError("final splice authorization key domains diverged")
    if repair_plan is None:
        fresh_assessments: tuple[
            tuple[TimelineNoGoodEdgeKey, str, SpliceFeasibilityAssessment],
            ...,
        ] = ()
    else:
        attempts_by_identity = {
            splice_feedback_plan_identity(attempt): attempt
            for attempt in repair_plan.attempt_input_timelines
        }
        records: list[
            tuple[TimelineNoGoodEdgeKey, str, SpliceFeasibilityAssessment]
        ] = []
        for attempt_identity, attempt in attempts_by_identity.items():
            attempt_failures = tuple(
                failure
                for failure in repair_plan.failures
                if failure.get("timeline_path_identity") == attempt_identity
            )
            feedback = build_splice_failure_feedback(
                attempt,
                attempt_failures,
                expected_frame_offsets=DEFAULT_WIDE_FRAME_OFFSETS,
            )
            records.extend(
                (item.edge, item.edge_context_identity, assessment)
                for item in feedback.edges
                for assessment in item.assessments
            )
        for repair in repair_plan.repairs:
            choices = final_timeline.choices
            if repair.boundary_index + 1 >= len(choices):
                raise RuntimeError(
                    "candidate repair boundary is outside the final timeline"
                )
            outgoing = choices[repair.boundary_index]
            incoming = choices[repair.boundary_index + 1]
            if (
                outgoing.source_index != repair.outgoing_source_index
                or incoming.source_index != repair.incoming_source_index
            ):
                raise RuntimeError(
                    "candidate repair source direction is stale"
                )
            if not (
                repair.selected_visual_evidence.evidence_coverage
                .professional_gate_passed
            ):
                raise RuntimeError(
                    "candidate repair success lacks professional evidence"
                )
            records.append(
                (
                    build_timeline_no_good_edge_key(
                        repair.boundary_index,
                        outgoing,
                        incoming,
                    ),
                    repair.observed_edge_context_identity,
                    classify_splice_evidence_audit(
                        repair.candidate_evidence_audit,
                        expected_frame_offsets=DEFAULT_WIDE_FRAME_OFFSETS,
                    ),
                )
            )
            records.append(
                (
                    build_timeline_no_good_edge_key(
                        repair.boundary_index,
                        outgoing,
                        incoming,
                    ),
                    repair.result_edge_context_identity,
                    build_splice_feasibility_assessment(
                        expected_frame_offsets=DEFAULT_WIDE_FRAME_OFFSETS,
                        offsets=(
                            SpliceOffsetAssessment(
                                frame_offset=(
                                    repair.result.selected_frame_offset
                                ),
                                production_gate_passed=True,
                                failure_codes=(),
                                evidence_complete=True,
                            ),
                        ),
                    ),
                )
            )
        fresh_assessments = tuple(records)

    fresh_graph = LazySpliceFeasibilityGraph(
        f"candidate-local:{graph.analysis_basis_identity}"
    )
    for edge, edge_context_identity, assessment in fresh_assessments:
        try:
            fresh_graph.record_assessment(
                edge,
                edge_context_identity,
                assessment,
            )
        except ValueError as exc:
            raise RuntimeError(
                "candidate-local splice evidence conflicts"
            ) from exc

    evidence: list[dict[str, Any]] = []
    unauthorized: list[LazySpliceFeasibilityKey] = []
    geometry_proof_boundary_indices: list[int] = []
    for raw_key, result_key in zip(
        final_raw_keys,
        final_result_keys,
        strict=True,
    ):
        if raw_key.edge != result_key.edge:
            raise RuntimeError("final splice authorization edges diverged")
        fresh_result = fresh_graph.assessment_for(
            result_key.edge,
            result_key.edge_context_identity,
        )
        retained_result = graph.assessment_for(
            result_key.edge,
            result_key.edge_context_identity,
        )
        fresh_raw = fresh_graph.assessment_for(
            raw_key.edge,
            raw_key.edge_context_identity,
        )
        retained_raw = graph.assessment_for(
            raw_key.edge,
            raw_key.edge_context_identity,
        )
        reason: str | None = None
        if (
            fresh_result is not None
            and retained_result is not None
            and fresh_result.status is SpliceFeasibilityStatus.RAW_PASS
            and retained_result.status is SpliceFeasibilityStatus.RAW_PASS
            and fresh_result.terminal_for_expected_domain
            and retained_result.terminal_for_expected_domain
        ):
            pass
        elif (
            fresh_raw is not None
            and retained_raw is not None
            and fresh_raw.status
            is SpliceFeasibilityStatus.RAW_GEOMETRY_PROOF_REQUIRED
            and retained_raw.status
            is SpliceFeasibilityStatus.RAW_GEOMETRY_PROOF_REQUIRED
            and fresh_raw.terminal_for_expected_domain
            and retained_raw.terminal_for_expected_domain
            and _assessment_has_final_boundary_geometry_evidence(fresh_raw)
            and _assessment_has_final_boundary_geometry_evidence(retained_raw)
        ):
            geometry_proof_boundary_indices.append(
                raw_key.edge.boundary_index
            )
        elif (
            fresh_raw is not None
            and retained_raw is not None
            and fresh_raw.status
            is SpliceFeasibilityStatus.RAW_GEOMETRY_PROOF_REQUIRED
            and retained_raw.status
            is SpliceFeasibilityStatus.RAW_GEOMETRY_PROOF_REQUIRED
        ):
            reason = "final_boundary_geometry_evidence_missing"
        elif fresh_result is not None and (
            fresh_result.status is not SpliceFeasibilityStatus.RAW_PASS
            or not fresh_result.terminal_for_expected_domain
        ):
            reason = "fresh_candidate_result_proof_invalid"
        elif retained_result is not None and (
            retained_result.status is not SpliceFeasibilityStatus.RAW_PASS
            or not retained_result.terminal_for_expected_domain
        ):
            reason = "analysis_graph_result_proof_invalid"
        elif fresh_raw is None:
            reason = "fresh_candidate_edge_evidence_missing"
        elif not fresh_raw.terminal_for_expected_domain:
            reason = "fresh_candidate_edge_evidence_incomplete"
        elif retained_raw is None:
            reason = "analysis_graph_edge_evidence_missing"
        elif not retained_raw.terminal_for_expected_domain:
            reason = "analysis_graph_edge_evidence_incomplete"
        else:
            reason = f"fresh_candidate_edge_{fresh_raw.status.value}"
        if reason is not None:
            unauthorized.append(raw_key)
        evidence.append(
            {
                "key": raw_key.to_dict(),
                "result_key": result_key.to_dict(),
                "fresh_result_status": (
                    fresh_result.status.value
                    if fresh_result is not None
                    else None
                ),
                "fresh_result_terminal": (
                    fresh_result.terminal_for_expected_domain
                    if fresh_result is not None
                    else False
                ),
                "retained_result_status": (
                    retained_result.status.value
                    if retained_result is not None
                    else None
                ),
                "retained_result_terminal": (
                    retained_result.terminal_for_expected_domain
                    if retained_result is not None
                    else False
                ),
                "fresh_status": (
                    fresh_raw.status.value if fresh_raw is not None else None
                ),
                "fresh_terminal": (
                    fresh_raw.terminal_for_expected_domain
                    if fresh_raw is not None
                    else False
                ),
                "retained_status": (
                    retained_raw.status.value
                    if retained_raw is not None
                    else None
                ),
                "retained_terminal": (
                    retained_raw.terminal_for_expected_domain
                    if retained_raw is not None
                    else False
                ),
                "authorization_failure": reason,
            }
        )
    return {
        "contract": "fresh_candidate_exact_context_splice_authorization_v2",
        "cross_source_edge_count": len(final_raw_keys),
        "proxy_eligible": not unauthorized,
        "unauthorized_keys": [key.to_dict() for key in unauthorized],
        "geometry_proof_boundary_indices": sorted(
            set(geometry_proof_boundary_indices)
        ),
        "fresh_evidence_record_count": len(fresh_assessments),
        "evidence": evidence,
        "thresholds_lowered": False,
    }


def _validate_constrained_precomputed_repair_origin(
    materialized_plan: VisualTimelinePlan,
    repair_plan: VisualBoundaryRepairPlan,
) -> None:
    if len(repair_plan.attempt_input_timelines) != 1:
        raise RuntimeError(
            "constrained preflight must provide one atomic repair plan"
        )
    preflight_input_timeline = repair_plan.attempt_input_timelines[0]
    if (
        splice_feedback_plan_identity(preflight_input_timeline)
        != splice_feedback_plan_identity(materialized_plan)
        or splice_feedback_plan_context(preflight_input_timeline)
        != splice_feedback_plan_context(materialized_plan)
    ):
        raise RuntimeError(
            "constrained preflight repair origin does not match the "
            "materialized candidate"
        )


def _merge_visual_boundary_repair_plans(
    earlier: VisualBoundaryRepairPlan,
    later: VisualBoundaryRepairPlan,
    *,
    analysis_suffix: str,
) -> VisualBoundaryRepairPlan:
    """Combine renderer lineage after each atomic plan was graph-recorded."""

    if not isinstance(earlier, VisualBoundaryRepairPlan) or not isinstance(
        later,
        VisualBoundaryRepairPlan,
    ):
        raise TypeError("boundary repair plans are invalid")
    return VisualBoundaryRepairPlan(
        timeline=later.timeline,
        attempt_input_timelines=(
            earlier.attempt_input_timelines
            + later.attempt_input_timelines
        ),
        repairs=earlier.repairs + later.repairs,
        skipped_same_source_boundaries=(
            earlier.skipped_same_source_boundaries
            + later.skipped_same_source_boundaries
        ),
        failures=earlier.failures + later.failures,
        requested_boundary_indices=None,
        geometry_provider_attempt_count=(
            earlier.geometry_provider_attempt_count
            + later.geometry_provider_attempt_count
        ),
        geometry_provider_failure_count=(
            earlier.geometry_provider_failure_count
            + later.geometry_provider_failure_count
        ),
        temporal_pose_motion_thresholds=later.temporal_pose_motion_thresholds,
        temporal_pose_motion_preference_weight=(
            later.temporal_pose_motion_preference_weight
        ),
        analysis_basis=f"{earlier.analysis_basis}+{analysis_suffix}",
    )


def _authorize_partial_reedit_splice_lineage(
    graph: LazySpliceFeasibilityGraph,
    *,
    selected_repairs: VisualBoundaryRepairPlan,
    targeted_repairs: VisualBoundaryRepairPlan,
    final_timeline: VisualTimelinePlan,
) -> tuple[VisualBoundaryRepairPlan, dict[str, Any]]:
    """Reauthorize a targeted edit with prior proof for untouched edges."""

    if not isinstance(graph, LazySpliceFeasibilityGraph):
        raise TypeError("partial re-edit splice graph is invalid")
    merged = _merge_visual_boundary_repair_plans(
        selected_repairs,
        targeted_repairs,
        analysis_suffix="decoded_proxy_targeted_partial_reedit_v1",
    )
    authorization = _candidate_local_splice_proxy_authorization(
        graph,
        final_timeline=final_timeline,
        repair_plan=merged,
    )
    return merged, authorization


def _run_initial_edge_constrained_stream(
    candidates: Sequence[Any],
    *,
    preflight: Callable[
        [Any],
        tuple[
            tuple[TimelineNoGoodEdgeKey, ...],
            VisualBoundaryRepairPlan | None,
            int,
        ],
    ],
    derive: Callable[[Any, VisualBoundaryRepairPlan | None], None],
    reject: Callable[[Any, Sequence[TimelineNoGoodEdgeKey]], None],
    should_stop: Callable[[], bool],
) -> dict[str, int]:
    """Cheap-check every remaining path after each graph-changing attempt."""

    if not all(callable(value) for value in (preflight, derive, reject, should_stop)):
        raise TypeError("initial constrained stream callbacks must be callable")
    derived_count = 0
    blocked_count = 0
    evidence_change_count = 0
    for candidate in candidates:
        if should_stop():
            break
        blocked_edges, precomputed_repairs, changed = preflight(candidate)
        evidence_change_count += int(changed)
        if blocked_edges:
            reject(candidate, blocked_edges)
            blocked_count += 1
            continue
        derive(candidate, precomputed_repairs)
        derived_count += 1
    return {
        "derived_count": derived_count,
        "blocked_before_expensive_derivation_count": blocked_count,
        "preflight_evidence_change_count": evidence_change_count,
    }


def _regenerate_visual_candidate_set_or_no_path(
    candidate_set: VisualTimelineCandidateSet,
    *,
    forbidden_boundary_edges: TimelineNoGoodSet,
) -> tuple[VisualTimelineCandidateSet | None, dict[str, object] | None]:
    """Handle only typed graph exhaustion; every other error must propagate."""

    try:
        return (
            regenerate_visual_timeline_candidate_set(
                candidate_set,
                forbidden_boundary_edges=forbidden_boundary_edges,
            ),
            None,
        )
    except NoCompleteTimelinePath as exc:
        evidence = deepcopy(exc.to_dict())
        nested_profile_diagnostics: list[dict[str, Any]] = []
        raw_nested = getattr(exc, "profile_failures", ())
        if isinstance(raw_nested, Sequence) and not isinstance(
            raw_nested,
            (str, bytes),
        ):
            for item in raw_nested:
                if (
                    isinstance(item, tuple)
                    and len(item) == 2
                    and isinstance(item[0], str)
                    and isinstance(item[1], NoCompleteTimelinePath)
                ):
                    nested_profile_diagnostics.append(
                        {
                            "cadence_profile": item[0],
                            "no_complete_path": deepcopy(
                                item[1].to_dict()
                            ),
                        }
                    )
        if not nested_profile_diagnostics:
            rejection_counts = evidence.get("rejection_counts")
            if isinstance(rejection_counts, Mapping):
                for compound_reason, count in sorted(
                    rejection_counts.items(),
                    key=lambda item: str(item[0]),
                ):
                    if (
                        not isinstance(compound_reason, str)
                        or ":" not in compound_reason
                        or isinstance(count, bool)
                        or not isinstance(count, int)
                        or count < 0
                    ):
                        continue
                    profile, reason_code = compound_reason.split(":", 1)
                    nested_profile_diagnostics.append(
                        {
                            "cadence_profile": profile,
                            "no_complete_path": {
                                "reason_code": reason_code,
                                "occurrence_count": count,
                            },
                        }
                    )
        if nested_profile_diagnostics:
            evidence["nested_profile_diagnostics"] = (
                nested_profile_diagnostics
            )
        return None, evidence


def _resume_or_reset_splice_feasibility_graph(
    payload: Mapping[str, Any],
    *,
    expected_analysis_basis_identity: str,
) -> tuple[LazySpliceFeasibilityGraph, bool, str | None]:
    """Discard known recreatable legacy caches; reject current tampering."""

    if not isinstance(payload, Mapping):
        raise TypeError("persisted splice graph payload must be a mapping")
    contract = payload.get("contract")
    legacy_contracts = frozenset(
        {
            "analysis_bound_exact_splice_feasibility_graph_v1",
            "analysis_bound_exact_splice_feasibility_graph_v2",
            "analysis_bound_exact_splice_feasibility_graph_v3",
        }
    )
    if contract in legacy_contracts:
        return (
            LazySpliceFeasibilityGraph(expected_analysis_basis_identity),
            False,
            f"known_legacy_recreatable_graph_contract:{contract}",
        )
    if contract != LAZY_SPLICE_FEASIBILITY_GRAPH_CONTRACT:
        raise RuntimeError("persisted splice graph contract is unknown")
    try:
        resumed = LazySpliceFeasibilityGraph.from_dict(payload)
    except (TypeError, ValueError) as exc:
        raise RuntimeError(
            "persisted splice graph failed canonical validation"
        ) from exc
    if resumed.analysis_basis_identity != expected_analysis_basis_identity:
        return (
            LazySpliceFeasibilityGraph(expected_analysis_basis_identity),
            False,
            "stale_recreatable_graph_analysis_basis_mismatch",
        )
    reopened = resumed.for_new_run()
    reopened_count = len(resumed) - len(reopened)
    return (
        reopened,
        True,
        (
            f"dropped_run_local_indeterminate_contexts:{reopened_count}"
            if reopened_count
            else None
        ),
    )


@dataclass(frozen=True, slots=True)
class AnalysisArtifact:
    manifest_path: Path
    manifest: dict[str, Any]
    output_paths: tuple[Path, ...]


def _alignment_result_sha256(alignment: AlignmentResult) -> str:
    encoded = json.dumps(
        alignment.to_dict(),
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


@dataclass(frozen=True, slots=True)
class VerifiedAutomaticMemberAlignmentPeerConsensus(Mapping[str, Any]):
    """Immutable, process-local authority for a member alignment rescue.

    Serialized dictionaries are diagnostics only.  Eligibility accepts this
    sealed result, bound to the exact ordered ``AlignmentResult``, so a caller
    cannot promote a weak source by replaying or forging manifest JSON.
    """

    _payload_json: str
    _alignment_sha256: str
    _seal: object

    def __post_init__(self) -> None:
        if self._seal is not _AUTOMATIC_MEMBER_ALIGNMENT_PEER_CONSENSUS_SEAL:
            raise TypeError(
                "member alignment peer consensus must come from the verifier"
            )
        if not re.fullmatch(r"[0-9a-f]{64}", self._alignment_sha256):
            raise ValueError("member alignment consensus binding is invalid")
        payload = json.loads(self._payload_json)
        if not isinstance(payload, dict) or payload.get("contract") != (
            AUTOMATIC_MEMBER_ALIGNMENT_PEER_CONSENSUS_CONTRACT
        ):
            raise ValueError("member alignment consensus payload is invalid")

    def _payload(self) -> dict[str, Any]:
        payload = json.loads(self._payload_json)
        if not isinstance(payload, dict):  # pragma: no cover - constructor guard
            raise RuntimeError("sealed member alignment consensus was corrupted")
        return payload

    def __getitem__(self, key: str) -> Any:
        return self._payload()[key]

    def __iter__(self):
        return iter(self._payload())

    def __len__(self) -> int:
        return len(self._payload())

    def verified_for(self, alignment: AlignmentResult) -> bool:
        return self._seal is _AUTOMATIC_MEMBER_ALIGNMENT_PEER_CONSENSUS_SEAL and (
            self._alignment_sha256 == _alignment_result_sha256(alignment)
        )

    def to_dict(self) -> dict[str, Any]:
        return self._payload()


def _json_payload_matches(left: object, right: object) -> bool:
    """Compare the persisted JSON contract, not Python container identities.

    Tuples serialize as arrays and numeric object keys serialize as strings.
    Conversely Python considers True == 1, which is not a matching JSON
    boolean. No nonfinite values or colliding serialized keys are accepted.
    File hashes, source binding and stable-inode checks remain independent.
    """
    def unique_object(pairs):
        result = {}
        for key, value in pairs:
            if key in result:
                raise ValueError('duplicate serialized JSON object key')
            result[key] = value
        return result

    def canonical(payload):
        normalized = json.loads(json.dumps(payload, allow_nan=False), object_pairs_hook=unique_object)
        return json.dumps(normalized, sort_keys=True, separators=(',', ':'), allow_nan=False)

    try:
        return canonical(left) == canonical(right)
    except (TypeError, ValueError, OverflowError):
        return False


def _write_analysis_manifest_atomically(
    path: Path,
    manifest: Mapping[str, Any],
) -> Path:
    """Replace one analysis manifest without exposing a partial JSON state."""

    destination = Path(path)
    encoded = json.dumps(
        manifest,
        ensure_ascii=False,
        indent=2,
        allow_nan=False,
    )
    descriptor, temporary_name = tempfile.mkstemp(
        prefix=f".{destination.name}.",
        suffix=".tmp",
        dir=destination.parent,
    )
    temporary = Path(temporary_name)
    try:
        with os.fdopen(descriptor, "w", encoding="utf-8") as stream:
            stream.write(encoded)
            stream.flush()
            os.fsync(stream.fileno())
        temporary.replace(destination)
    except Exception:
        try:
            os.close(descriptor)
        except OSError:
            pass
        temporary.unlink(missing_ok=True)
        raise
    persisted, _fingerprint = _read_stable_regular_file(destination)
    if persisted != encoded.encode("utf-8"):
        raise OSError("analysis manifest changed during atomic replacement")
    return destination


def _read_stable_regular_file(path: Path) -> tuple[bytes, dict[str, Any]]:
    """Read bytes from a path-bound regular descriptor without following links."""

    source = Path(path)
    try:
        path_before = source.lstat()
        if not stat.S_ISREG(path_before.st_mode):
            raise ValueError(f"not a regular non-symlink file: {source.name}")
        resolved_before = source.resolve(strict=True)
        flags = os.O_RDONLY
        if hasattr(os, "O_CLOEXEC"):
            flags |= os.O_CLOEXEC
        if hasattr(os, "O_NOFOLLOW"):
            flags |= os.O_NOFOLLOW
        descriptor = os.open(source, flags)
        with os.fdopen(descriptor, "rb") as stream:
            before = os.fstat(stream.fileno())
            if (
                not stat.S_ISREG(before.st_mode)
                or (path_before.st_dev, path_before.st_ino)
                != (before.st_dev, before.st_ino)
            ):
                raise ValueError(f"path changed before reading: {source.name}")
            content = stream.read()
            after = os.fstat(stream.fileno())
            path_after = source.lstat()
            resolved_after = source.resolve(strict=True)
    except OSError as exc:
        raise ValueError(f"could not read stable file {source.name}: {exc}") from exc
    descriptor_identity = (
        before.st_dev,
        before.st_ino,
        before.st_size,
        before.st_mtime_ns,
        before.st_ctime_ns,
    )
    final_descriptor_identity = (
        after.st_dev,
        after.st_ino,
        after.st_size,
        after.st_mtime_ns,
        after.st_ctime_ns,
    )
    final_path_identity = (
        path_after.st_dev,
        path_after.st_ino,
        path_after.st_size,
        path_after.st_mtime_ns,
        path_after.st_ctime_ns,
    )
    if (
        not stat.S_ISREG(path_after.st_mode)
        or descriptor_identity != final_descriptor_identity
        or final_path_identity != final_descriptor_identity
        or resolved_before != resolved_after
        or len(content) != after.st_size
    ):
        raise ValueError(f"file changed while being read: {source.name}")
    return (
        content,
        {
            "path": str(resolved_after),
            "size_bytes": len(content),
            "sha256": hashlib.sha256(content).hexdigest(),
        },
    )


def _fingerprint_stable_regular_file_streaming(path: Path) -> dict[str, Any]:
    """Hash a potentially large regular file through one stable descriptor."""

    source = Path(path)
    try:
        path_before = source.lstat()
        if not stat.S_ISREG(path_before.st_mode):
            raise ValueError(f"not a regular non-symlink file: {source.name}")
        resolved_before = source.resolve(strict=True)
        flags = os.O_RDONLY
        if hasattr(os, "O_CLOEXEC"):
            flags |= os.O_CLOEXEC
        if hasattr(os, "O_NOFOLLOW"):
            flags |= os.O_NOFOLLOW
        descriptor = os.open(source, flags)
        digest = hashlib.sha256()
        size = 0
        with os.fdopen(descriptor, "rb") as stream:
            before = os.fstat(stream.fileno())
            if (
                not stat.S_ISREG(before.st_mode)
                or (path_before.st_dev, path_before.st_ino)
                != (before.st_dev, before.st_ino)
            ):
                raise ValueError(f"path changed before hashing: {source.name}")
            while True:
                chunk = stream.read(1024 * 1024)
                if not chunk:
                    break
                digest.update(chunk)
                size += len(chunk)
            after = os.fstat(stream.fileno())
        path_after = source.lstat()
        resolved_after = source.resolve(strict=True)
    except OSError as exc:
        raise ValueError(f"could not hash stable file {source.name}: {exc}") from exc
    before_identity = (
        before.st_dev,
        before.st_ino,
        before.st_size,
        before.st_mtime_ns,
        before.st_ctime_ns,
    )
    after_identity = (
        after.st_dev,
        after.st_ino,
        after.st_size,
        after.st_mtime_ns,
        after.st_ctime_ns,
    )
    path_identity = (
        path_after.st_dev,
        path_after.st_ino,
        path_after.st_size,
        path_after.st_mtime_ns,
        path_after.st_ctime_ns,
    )
    if (
        not stat.S_ISREG(path_after.st_mode)
        or before_identity != after_identity
        or after_identity != path_identity
        or resolved_before != resolved_after
        or size != after.st_size
    ):
        raise ValueError(f"file changed while hashing: {source.name}")
    return {
        "path": str(resolved_after),
        "size_bytes": size,
        "sha256": digest.hexdigest(),
    }


def _persist_qa_input_analysis_snapshot(
    analysis_path: Path,
    *,
    expected_sha256: str,
) -> dict[str, Any]:
    """Preserve the exact pre-promotion analysis bytes for later audit."""

    source = Path(analysis_path)
    content, source_fingerprint = _read_stable_regular_file(source)
    digest = str(source_fingerprint["sha256"])
    if digest != expected_sha256:
        raise ValueError("analysis content changed before QA snapshot persistence")
    suffix = "-analysis.json"
    if not source.name.endswith(suffix):
        raise ValueError("QA input analysis path has an unsupported name")
    base_name = source.name[: -len(suffix)]
    destination = source.with_name(
        f"{base_name}-qa-input-analysis-{digest[:16]}.json"
    )
    if destination.exists():
        existing, _existing_fingerprint = _read_stable_regular_file(
            destination
        )
        if existing != content:
            raise FileExistsError("QA input analysis snapshot collision")
    else:
        descriptor, temporary_name = tempfile.mkstemp(
            prefix=f".{destination.name}.",
            suffix=".tmp",
            dir=destination.parent,
        )
        temporary = Path(temporary_name)
        try:
            with os.fdopen(descriptor, "wb") as stream:
                stream.write(content)
                stream.flush()
                os.fsync(stream.fileno())
            temporary.replace(destination)
        except Exception:
            try:
                os.close(descriptor)
            except OSError:
                pass
            temporary.unlink(missing_ok=True)
            raise
    persisted, persisted_fingerprint = _read_stable_regular_file(destination)
    if persisted != content or persisted_fingerprint["sha256"] != digest:
        raise ValueError("QA input analysis snapshot changed before promotion")
    return persisted_fingerprint


def _atomically_materialize_verified_snapshot_file(
    source: Path,
    destination: Path,
    *,
    expected_fingerprint: Mapping[str, Any],
) -> dict[str, Any]:
    """Move one verified snapshot inode onto its canonical delivery path."""

    source_path = Path(source)
    destination_path = Path(destination)
    before = source_path.lstat()
    expected_size = expected_fingerprint.get("size_bytes")
    expected_sha256 = expected_fingerprint.get("sha256")
    if (
        not stat.S_ISREG(before.st_mode)
        or isinstance(expected_size, bool)
        or not isinstance(expected_size, int)
        or before.st_size != expected_size
        or not isinstance(expected_sha256, str)
    ):
        raise RuntimeError(
            f"verified QA snapshot is no longer promotable: {source_path.name}"
        )
    source_identity = (before.st_dev, before.st_ino, before.st_size)
    os.replace(source_path, destination_path)
    after = destination_path.lstat()
    destination_identity = (after.st_dev, after.st_ino, after.st_size)
    if not stat.S_ISREG(after.st_mode) or destination_identity != source_identity:
        raise RuntimeError(
            f"QA snapshot inode promotion lost authority: {destination_path.name}"
        )
    return {
        "path": str(destination_path.resolve()),
        "size_bytes": expected_size,
        "sha256": expected_sha256,
        "materialization": "same_filesystem_atomic_inode_replace",
        "snapshot_device": before.st_dev,
        "snapshot_inode": before.st_ino,
        "canonical_device": after.st_dev,
        "canonical_inode": after.st_ino,
        "inode_identity_preserved": True,
    }


def _enforce_automatic_stage_edit_post_render_qa(
    *,
    registered_stage_edit_bundle: RegisteredStageEditProductionBundle | None,
    manifest: dict[str, Any],
    manifest_path: Path,
    reporter: EventReporter,
    automatic_ive_group_delivery: bool | None = None,
    rendered_montage_config: RenderedMontageGrammarConfig | None = None,
) -> Path | None:
    """Require PASS from final-media QA for every automatic IVE GROUP delivery.

    The evaluator consumes the already persisted timestamp-bound analysis,
    render-plan, candidate-selection, and final MP4.  Automatic product media
    remains an unexposed ``pending_qa`` artifact until this function atomically
    promotes a passing report to ``delivery``.  A failed report is persisted
    as ``rejected`` and can never be restored by the app as a completed result.
    ``None`` retains the old direct-call inference for compatibility; the
    production caller always supplies the explicit request-scoped decision.
    """

    required = (
        registered_stage_edit_bundle is not None
        if automatic_ive_group_delivery is None
        else automatic_ive_group_delivery
    )
    if not isinstance(required, bool):
        raise TypeError("automatic_ive_group_delivery must resolve to boolean")
    if not required:
        return None
    if required:
        request_payload = manifest.get("request")
        if not (
            isinstance(request_payload, Mapping)
            and str(request_payload.get("group", "")).strip().upper()
            == "IVE"
            and str(request_payload.get("edit_mode", "")).strip().lower()
            == "group"
            and str(request_payload.get("source_mode", "")).strip().lower()
            == "automatic"
        ):
            raise RuntimeError(
                "mandatory automatic IVE GROUP post-render QA lost its exact "
                "request scope"
            )
        exposure = manifest.get("app_result_exposure")
        render_payload = manifest.get("render")
        if not (
            manifest.get("artifact_role") == "pending_qa"
            and isinstance(exposure, Mapping)
            and exposure.get("contract") == APP_RESULT_EXPOSURE_CONTRACT
            and exposure.get("video_output_exposed") is False
            and exposure.get("delivery_completion_message_allowed") is False
            and isinstance(render_payload, Mapping)
            and render_payload.get("artifact_role") == "pending_qa"
        ):
            raise RuntimeError(
                "mandatory automatic IVE GROUP post-render QA requires an "
                "unexposed pending_qa artifact"
            )
    if rendered_montage_config is not None and not isinstance(
        rendered_montage_config, RenderedMontageGrammarConfig
    ):
        raise TypeError(
            "rendered_montage_config must be RenderedMontageGrammarConfig"
        )

    declared_artifact_set = PostRenderArtifactSet.from_analysis_path(
        manifest_path
    )
    evaluation_snapshot = materialize_post_render_qa_snapshot(
        declared_artifact_set
    )
    try:
        return _complete_automatic_stage_edit_post_render_qa(
            registered_stage_edit_bundle=registered_stage_edit_bundle,
            manifest=manifest,
            manifest_path=manifest_path,
            reporter=reporter,
            rendered_montage_config=rendered_montage_config,
            evaluation_snapshot=evaluation_snapshot,
        )
    finally:
        cleanup_post_render_qa_snapshot(evaluation_snapshot)


def _complete_automatic_stage_edit_post_render_qa(
    *,
    registered_stage_edit_bundle: RegisteredStageEditProductionBundle | None,
    manifest: dict[str, Any],
    manifest_path: Path,
    reporter: EventReporter,
    rendered_montage_config: RenderedMontageGrammarConfig | None,
    evaluation_snapshot: PostRenderQAEvaluationSnapshot,
) -> Path:
    """Evaluate, bind, and materialize one already-frozen QA artifact set."""

    declared_artifact_set = evaluation_snapshot.declared_artifact_set
    artifact_set = evaluation_snapshot.artifact_set
    reporter.status(
        "IVE GROUP 최종 MP4를 전체 디코딩하고 "
        "전문 후처리 QA를 실행하는 중…"
    )
    qa_arguments: dict[str, Any] = {
        "trusted_registered_stage_edit": (
            True if registered_stage_edit_bundle is not None else None
        )
    }
    if rendered_montage_config is not None:
        qa_arguments["config"] = PostRenderQAConfig(
            rendered_montage_grammar=rendered_montage_config
        )
    report, report_path = evaluate_and_write_post_render_qa(
        artifact_set,
        output_path=artifact_set.default_report_path,
        declared_artifact_set=declared_artifact_set,
        **qa_arguments,
    )
    report_payload = report.to_dict()
    reported_input_fingerprints = report_payload.get(
        "input_artifact_fingerprints"
    )
    try:
        expected_input_fingerprints = (
            normalize_post_render_artifact_fingerprints(
                reported_input_fingerprints,
                declared_artifact_set,
            )
            if isinstance(reported_input_fingerprints, Mapping)
            else {}
        )
    except ValueError:
        expected_input_fingerprints = {}
    try:
        current_input_fingerprints = (
            normalize_post_render_artifact_fingerprints(
                fingerprint_post_render_artifacts(artifact_set),
                declared_artifact_set,
            )
        )
    except ValueError:
        current_input_fingerprints = {}
    input_content_matches = bool(
        expected_input_fingerprints.get("contract")
        == INPUT_ARTIFACT_FINGERPRINT_CONTRACT
        and expected_input_fingerprints == current_input_fingerprints
    )
    persisted_analysis_payload: dict[str, Any] | None = None
    try:
        raw_persisted_analysis = json.loads(
            artifact_set.analysis_path.read_text(encoding="utf-8")
        )
        if isinstance(raw_persisted_analysis, dict):
            persisted_analysis_payload = raw_persisted_analysis
    except (OSError, UnicodeError, json.JSONDecodeError):
        persisted_analysis_payload = None
    in_memory_manifest_matches_evaluated_analysis = bool(
        persisted_analysis_payload is not None
        and _json_payload_matches(persisted_analysis_payload, manifest)
    )
    qa_input_analysis_snapshot: dict[str, Any] = {}
    expected_analysis_fingerprint = (
        expected_input_fingerprints.get("analysis")
    )
    expected_analysis_sha256 = (
        expected_analysis_fingerprint.get("sha256")
        if isinstance(expected_analysis_fingerprint, Mapping)
        else None
    )
    if (
        input_content_matches
        and in_memory_manifest_matches_evaluated_analysis
        and isinstance(expected_analysis_sha256, str)
    ):
        try:
            qa_input_analysis_snapshot = _persist_qa_input_analysis_snapshot(
                artifact_set.analysis_path,
                expected_sha256=expected_analysis_sha256,
            )
        except (OSError, ValueError, FileExistsError):
            qa_input_analysis_snapshot = {}
    input_binding_matches = bool(
        input_content_matches
        and in_memory_manifest_matches_evaluated_analysis
        and qa_input_analysis_snapshot.get("sha256")
        == expected_analysis_sha256
    )
    expected_report_path = artifact_set.default_report_path
    candidate_report_path = Path(report_path)
    report_path_contract_matches = False
    try:
        report_path_contract_matches = bool(
            candidate_report_path.name == expected_report_path.name
            and candidate_report_path.parent.resolve(strict=True)
            == expected_report_path.parent.resolve(strict=True)
            and not candidate_report_path.is_symlink()
        )
    except OSError:
        report_path_contract_matches = False
    report_content_fingerprint: dict[str, Any] = {}
    persisted_report_matches = False
    try:
        report_bytes, report_content_fingerprint = _read_stable_regular_file(
            candidate_report_path
        )
        persisted_report = json.loads(report_bytes.decode("utf-8"))
        persisted_report_matches = bool(
            report_path_contract_matches
            and isinstance(persisted_report, Mapping)
            and _json_payload_matches(dict(persisted_report), report_payload)
        )
    except (OSError, ValueError, UnicodeError, json.JSONDecodeError):
        persisted_report_matches = False
    snapshot_stable_through_promotion = False
    if qa_input_analysis_snapshot:
        try:
            _snapshot_bytes, final_snapshot_fingerprint = (
                _read_stable_regular_file(
                    Path(str(qa_input_analysis_snapshot["path"]))
                )
            )
            snapshot_stable_through_promotion = bool(
                final_snapshot_fingerprint == qa_input_analysis_snapshot
            )
        except (KeyError, TypeError, ValueError):
            snapshot_stable_through_promotion = False
    report_stable_through_promotion = False
    if persisted_report_matches:
        try:
            final_report_bytes, final_report_fingerprint = (
                _read_stable_regular_file(candidate_report_path)
            )
            final_report_payload = json.loads(
                final_report_bytes.decode("utf-8")
            )
            report_stable_through_promotion = bool(
                final_report_fingerprint == report_content_fingerprint
                and isinstance(final_report_payload, Mapping)
                and _json_payload_matches(dict(final_report_payload), report_payload)
            )
        except (OSError, ValueError, UnicodeError, json.JSONDecodeError):
            report_stable_through_promotion = False
    pre_promotion_input_fingerprints: dict[str, Any] = {}
    try:
        pre_promotion_input_fingerprints = (
            normalize_post_render_artifact_fingerprints(
                fingerprint_post_render_artifacts(artifact_set),
                declared_artifact_set,
            )
        )
    except ValueError:
        pre_promotion_input_fingerprints = {}
    inputs_stable_through_promotion = bool(
        input_content_matches
        and pre_promotion_input_fingerprints == current_input_fingerprints
    )
    promotion_binding_passed = bool(
        input_binding_matches
        and persisted_report_matches
        and inputs_stable_through_promotion
        and snapshot_stable_through_promotion
        and report_stable_through_promotion
    )
    request_payload = manifest.get("request")
    review_first_enabled = bool(
        isinstance(request_payload, Mapping)
        and request_payload.get("review_first_enabled") is True
    )
    qa_disposition = classify_review_first_qa(
        {**report_payload, "passed": bool(report.passed)},
        content_binding_passed=promotion_binding_passed,
        review_first_enabled=review_first_enabled,
        member=False,
    )
    effective_passed = qa_disposition.status is ReviewFirstStatus.APPROVED
    delivery_gate_verdict = (
        "PASS" if effective_passed else qa_disposition.status.value
    )
    delivery_materialization: dict[str, Any] = {
        "contract": "post_render_qa_verified_snapshot_materialization_v1",
        "performed": False,
        "input_artifacts": {},
        "report": {},
        "analysis_snapshot": {},
    }
    if promotion_binding_passed:
        promoted_inputs: dict[str, Any] = {}
        promotion_inputs = (
            (
                "render_plan",
                artifact_set.render_plan_path,
                declared_artifact_set.render_plan_path,
            ),
            (
                "selection",
                artifact_set.selection_path,
                declared_artifact_set.selection_path,
            ),
            (
                "video",
                artifact_set.video_path,
                declared_artifact_set.video_path,
            ),
        )
        if "frame_clock" in pre_promotion_input_fingerprints:
            from .render_clock_artifact import render_clock_path
            promotion_inputs += (("frame_clock", render_clock_path(artifact_set.video_path), render_clock_path(declared_artifact_set.video_path)),)
        for key, source, destination in promotion_inputs:
            promoted_inputs[key] = (
                _atomically_materialize_verified_snapshot_file(
                    source,
                    destination,
                    expected_fingerprint=pre_promotion_input_fingerprints[key],
                )
            )
        delivery_materialization["performed"] = True
        delivery_materialization["input_artifacts"] = promoted_inputs
    if report_stable_through_promotion:
        delivery_materialization["report"] = (
            _atomically_materialize_verified_snapshot_file(
                candidate_report_path,
                declared_artifact_set.default_report_path,
                expected_fingerprint=report_content_fingerprint,
            )
        )
    else:
        # A mismatched report must never authorize delivery. Retain the
        # evaluator's payload as explicitly UNBOUND diagnostic evidence before
        # removing its private read snapshot; do not publish a dead report URL
        # or require another expensive media decode just to inspect the failure.
        diagnostic_path = declared_artifact_set.output_directory / (
            f"{declared_artifact_set.base_name}-post-render-qa-unbound-diagnostic.json"
        )
        _write_analysis_manifest_atomically(diagnostic_path, {
            "contract": "post_render_qa_unbound_evaluator_diagnostic_v1",
            "artifact_role": "diagnostic",
            "render_authorized": False,
            "content_binding_passed": False,
            "persisted_report_matches_evaluator_payload": persisted_report_matches,
            "report_path_matches_bound_default": report_path_contract_matches,
            "evaluator_report": report_payload,
        })
        _diagnostic_bytes, diagnostic_fingerprint = _read_stable_regular_file(diagnostic_path)
        delivery_materialization["unbound_diagnostic"] = diagnostic_fingerprint
    if snapshot_stable_through_promotion:
        snapshot_source = Path(str(qa_input_analysis_snapshot["path"]))
        snapshot_destination = declared_artifact_set.output_directory / (
            snapshot_source.name
        )
        delivery_materialization["analysis_snapshot"] = (
            _atomically_materialize_verified_snapshot_file(
                snapshot_source,
                snapshot_destination,
                expected_fingerprint=qa_input_analysis_snapshot,
            )
        )
        qa_input_analysis_snapshot = {
            "path": delivery_materialization["analysis_snapshot"]["path"],
            "size_bytes": delivery_materialization["analysis_snapshot"][
                "size_bytes"
            ],
            "sha256": delivery_materialization["analysis_snapshot"]["sha256"],
        }
    promotion_binding = {
        "contract": "post_render_qa_delivery_promotion_binding_v1",
        "input_artifact_contract": INPUT_ARTIFACT_FINGERPRINT_CONTRACT,
        "evaluated_input_artifacts": (
            dict(expected_input_fingerprints)
            if isinstance(expected_input_fingerprints, Mapping)
            else {}
        ),
        "current_inputs_match_evaluated_content": input_content_matches,
        "inputs_stable_through_promotion": inputs_stable_through_promotion,
        "pre_promotion_input_artifacts": pre_promotion_input_fingerprints,
        "in_memory_manifest_matches_evaluated_analysis": (
            in_memory_manifest_matches_evaluated_analysis
        ),
        "pre_promotion_analysis_snapshot": qa_input_analysis_snapshot,
        "persisted_report_matches_evaluator_payload": (
            persisted_report_matches
        ),
        "report_path_matches_bound_default": report_path_contract_matches,
        "report_stable_through_promotion": report_stable_through_promotion,
        "report_content_fingerprint": report_content_fingerprint,
        "evaluation_snapshot": evaluation_snapshot.to_dict(),
        "delivery_materialization": delivery_materialization,
        "passed": promotion_binding_passed,
    }
    promoted_report = delivery_materialization.get("report")
    unbound_diagnostic = delivery_materialization.get("unbound_diagnostic", {})
    report_audit_path = str(
        promoted_report.get("path")
        if isinstance(promoted_report, Mapping) and promoted_report.get("path")
        else unbound_diagnostic["path"] if unbound_diagnostic.get("path")
        else report_content_fingerprint.get(
            "path",
            candidate_report_path.absolute(),
        )
    )
    provenance = {
        "contract": AUTOMATIC_STAGE_EDIT_POST_RENDER_QA_CONTRACT,
        "required": True,
        "activation": (
            "automatic_registered_production_bundle"
            if registered_stage_edit_bundle is not None
            else "automatic_request_scoped_ive_group_delivery"
        ),
        "ive_product_floor_required_independent_of_activation": True,
        "success_requires_pass": True,
        "report_path": report_audit_path,
        "report_preservation_kind": (
            "unbound_evaluator_diagnostic" if unbound_diagnostic else "verified_qa_report"
        ),
        "verdict": report.verdict.value,
        "passed": effective_passed,
        "review_first_disposition": qa_disposition.to_dict(),
        "delivery_gate_verdict": delivery_gate_verdict,
        "report_verdict": report.verdict.value,
        "report_passed": report.passed,
        "analysis_basis": report.analysis_basis,
        "issue_count": report_payload.get("issue_count"),
        "fail_issue_count": report_payload.get("fail_issue_count"),
        "conditional_issue_count": report_payload.get(
            "conditional_issue_count"
        ),
        "failure_artifact_policy": {
            "final_mp4_preserved": True,
            "qa_report_preserved": True,
            "analysis_manifest_preserved": True,
            "app_result_exposure_blocked": (
                not qa_disposition.video_output_exposed
            ),
        },
        "promotion_binding": promotion_binding,
    }
    # No delivery manifest is published until every unpromoted private clone,
    # including a fallback full video copy, has been removed. The outer
    # ``finally`` repeats this idempotently for evaluator and promotion errors.
    cleanup_post_render_qa_snapshot(evaluation_snapshot)
    final_role = qa_disposition.artifact_role
    exposure = {
        "contract": APP_RESULT_EXPOSURE_CONTRACT,
        "video_output_exposed": qa_disposition.video_output_exposed,
        "delivery_completion_message_allowed": (
            qa_disposition.delivery_completion_message_allowed
        ),
    }
    if (
        not in_memory_manifest_matches_evaluated_analysis
        and persisted_analysis_payload is not None
    ):
        manifest.clear()
        manifest.update(deepcopy(persisted_analysis_payload))
    manifest["artifact_role"] = final_role
    manifest["app_result_exposure"] = dict(exposure)
    manifest["post_render_qa"] = dict(provenance)
    review_runtime_payload = manifest.get("review_first_runtime")
    finalize_review_first_runtime_payload(review_runtime_payload, qa_disposition.status)
    from .first_result_controller import finalize_first_result_manifest
    finalize_first_result_manifest(manifest, qa_disposition)
    render_payload = manifest.get("render")
    if isinstance(render_payload, dict):
        render_payload["artifact_role"] = final_role
        render_payload["app_result_exposure"] = dict(exposure)
        render_payload["post_render_qa"] = dict(provenance)
    generation_payload = manifest.get("stage_edit_generation")
    if isinstance(generation_payload, dict):
        generation_payload["post_render_qa"] = dict(provenance)
    _write_analysis_manifest_atomically(manifest_path, manifest)
    reporter.log(
        "IVE GROUP 최종 후처리 QA "
        f"{report.verdict.value} · 보고서 {report_audit_path}"
    )
    if qa_disposition.status is ReviewFirstStatus.REVIEW_READY:
        reporter.log(
            "IVE GROUP 최종 파일은 기술 무결성을 유지했으나 "
            "편집 품질 QA는 통과하지 못해 검토본으로 공개합니다."
        )
    elif not effective_passed:
        failure_reason = (
            f"post-render QA verdict {report.verdict.value}"
            if not report.passed
            else "post-render QA artifact content binding failure"
            if not promotion_binding_passed
            else "post-render QA integrity contract failure: "
            + ", ".join(qa_disposition.technical_issue_codes)
        )
        raise RuntimeError(
            "automatic IVE GROUP final render blocked by mandatory "
            f"{failure_reason}; rejected media "
            "is retained only for diagnostics and is not exposed as a "
            f"completed result; QA report preserved at {report_audit_path}"
        )
    return Path(report_audit_path)


def _enforce_automatic_member_post_render_qa(
    *,
    manifest: dict[str, Any],
    manifest_path: Path,
    reporter: EventReporter,
    focal_reference_candidates_by_boundary_index: Mapping[
        int,
        tuple[FocalFaceCandidate, FocalFaceCandidate],
    ]
    | None = None,
    rendered_continuity_evaluator=None,
) -> Path | None:
    """Promote an automatic direct-member MP4 only after final pixel QA.

    Activation is resolved from the persisted request plus
    ``render.direct_full_frame``.  The caller cannot opt a matching product out
    of this gate, and no result path is exposed while its role is
    ``pending_qa``.
    """

    if not automatic_member_post_render_qa_required(manifest):
        return None
    request_payload = manifest.get("request")
    render_payload = manifest.get("render")
    exposure = manifest.get("app_result_exposure")
    if not (
        isinstance(request_payload, Mapping)
        and isinstance(render_payload, Mapping)
        and render_payload.get("direct_full_frame") is True
        and manifest.get("artifact_role") == "pending_qa"
        and render_payload.get("artifact_role") == "pending_qa"
        and isinstance(exposure, Mapping)
        and exposure.get("contract")
        == AUTOMATIC_IVE_MEMBER_APP_RESULT_EXPOSURE_CONTRACT
        and exposure.get("video_output_exposed") is False
        and exposure.get("delivery_completion_message_allowed") is False
    ):
        raise RuntimeError(
            "mandatory automatic IVE MEMBER post-render QA requires an "
            "unexposed pending_qa direct-full-frame artifact"
        )
    try:
        persisted = json.loads(manifest_path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise RuntimeError(
            "automatic IVE MEMBER pending analysis manifest is unreadable"
        ) from exc
    if not isinstance(persisted, dict) or not _json_payload_matches(persisted, manifest):
        raise RuntimeError(
            "automatic IVE MEMBER pending analysis differs from persisted QA input"
        )

    artifacts = AutomaticMemberPostRenderArtifactSet.from_manifest(
        manifest_path, manifest
    )
    reporter.status(
        "IVE 멤버 최종 MP4 전체 디코드·화질·소스별 픽셀 출처·"
        "컷 위치·포즈·동작 연결성을 검증하는 중…"
    )
    report, report_path = (
        evaluate_and_write_automatic_member_post_render_qa(
            artifacts,
            **({"rendered_continuity_evaluator": rendered_continuity_evaluator}
                if rendered_continuity_evaluator is not None else {}),
            focal_reference_candidates_by_boundary_index=(
                focal_reference_candidates_by_boundary_index
            ),
        )
    )
    report_payload = report.to_dict()
    try:
        pre_exposure_fingerprints = fingerprint_automatic_member_artifacts(
            artifacts
        )
    except ValueError:
        pre_exposure_fingerprints = {}
    content_binding_passed = bool(
        report.input_artifact_fingerprints
        and report.final_artifact_fingerprints
        and report.input_artifact_fingerprints
        == report.final_artifact_fingerprints
        == pre_exposure_fingerprints
    )
    qa_disposition = classify_review_first_qa(
        {**report_payload, "passed": bool(report.passed)},
        content_binding_passed=content_binding_passed,
        review_first_enabled=(
            isinstance(request_payload, Mapping)
            and request_payload.get("review_first_enabled") is True
        ),
        member=True,
    )
    effective_passed = qa_disposition.status is ReviewFirstStatus.APPROVED
    final_role = qa_disposition.artifact_role
    final_exposure = {
        "contract": AUTOMATIC_IVE_MEMBER_APP_RESULT_EXPOSURE_CONTRACT,
        "video_output_exposed": qa_disposition.video_output_exposed,
        "delivery_completion_message_allowed": (
            qa_disposition.delivery_completion_message_allowed
        ),
    }
    provenance = {
        "contract": AUTOMATIC_IVE_MEMBER_POST_RENDER_QA_CONTRACT,
        "required": True,
        "activation": (
            "persisted_request_automatic_ive_member_and_render_direct_full_frame"
        ),
        "success_requires_pass": True,
        "report_path": str(Path(report_path).resolve()),
        "verdict": report.verdict,
        "report_passed": report.passed,
        "content_binding_passed": content_binding_passed,
        "passed": effective_passed,
        "review_first_disposition": qa_disposition.to_dict(),
        "issue_count": report_payload.get("issue_count"),
        "input_artifact_fingerprints": dict(
            report.input_artifact_fingerprints
        ),
        "pre_exposure_artifact_fingerprints": pre_exposure_fingerprints,
        "render_receipt": dict(report.render_receipt),
        "failure_artifact_policy": {
            "final_mp4_preserved": True,
            "qa_report_preserved": True,
            "analysis_manifest_preserved": True,
            "app_result_exposure_blocked": (
                not qa_disposition.video_output_exposed
            ),
        },
    }
    manifest["artifact_role"] = final_role
    manifest["app_result_exposure"] = dict(final_exposure)
    manifest["post_render_qa"] = dict(provenance)
    review_runtime_payload = manifest.get("review_first_runtime")
    finalize_review_first_runtime_payload(review_runtime_payload, qa_disposition.status)
    from .first_result_controller import finalize_first_result_manifest
    finalize_first_result_manifest(manifest, qa_disposition)
    mutable_render = manifest.get("render")
    if isinstance(mutable_render, dict):
        mutable_render["artifact_role"] = final_role
        mutable_render["app_result_exposure"] = dict(final_exposure)
        mutable_render["post_render_qa"] = dict(provenance)
    _write_analysis_manifest_atomically(manifest_path, manifest)
    reporter.log(
        "IVE MEMBER 최종 후처리 QA "
        f"{report.verdict} · 보고서 {Path(report_path).resolve()}"
    )
    if qa_disposition.status is ReviewFirstStatus.REVIEW_READY:
        reporter.log(
            "IVE MEMBER 최종 파일은 기술 무결성을 유지했으나 "
            "편집 품질 QA는 통과하지 못해 검토본으로 공개합니다."
        )
    elif not effective_passed:
        reason = (
            f"verdict {report.verdict}"
            if not report.passed
            else "artifact content binding failure"
            if not content_binding_passed
            else "integrity contract failure: " + ", ".join(qa_disposition.technical_issue_codes)
        )
        raise RuntimeError(
            "automatic IVE MEMBER final render blocked by mandatory "
            f"post-render QA {reason}; rejected media is retained only for "
            "diagnostics and is not exposed as a completed result; QA report "
            f"preserved at {Path(report_path).resolve()}"
        )
    return Path(report_path).resolve()


def _materialize_ranked_visual_proxy_candidates(
    candidate_set: VisualTimelineCandidateSet,
    *,
    request: AnalysisRequest,
    rhythm_analysis: Any,
    section_plan: SectionPlan | None,
    reporter: EventReporter,
) -> tuple[
    tuple[MaterializedVisualTimelineCandidate, ...],
    StageEditCandidateRerankResult | None,
]:
    """Retain the compatibility surface for explicit scorer unit contracts."""

    if request.stage_edit_checkpoint_directory is None:
        return (
            materialize_visual_timeline_candidates(
                candidate_set,
                maximum_candidates=8,
                passed_only=True,
            ),
            None,
        )
    report = request.stage_edit_production_training_report
    if report is None:
        raise RuntimeError(
            "StageEdit checkpoint activation requires its exact production report"
        )
    reporter.status(
        "검증된 StageEdit Transformer로 시각 후보 순서를 평가하는 중…"
    )
    result = rerank_visual_timeline_candidates_with_stage_edit(
        candidate_set,
        checkpoint_directory=request.stage_edit_checkpoint_directory,
        production_training_report=report,
        rhythm=rhythm_analysis,
        section_plan=section_plan,
    )
    ordered_records = result.ordered_records(candidate_set)
    materialized_values: list[MaterializedVisualTimelineCandidate] = []
    for record in ordered_records:
        if not record.review.passed:
            continue
        materialized_values.append(
            materialize_visual_timeline_candidate_record(candidate_set, record)
        )
        if len(materialized_values) >= 8:
            break
    reporter.log(
        "StageEdit Transformer가 보존된 시각 후보 "
        f"{len(ordered_records)}개의 1차 렌더 순서를 재평가"
    )
    return tuple(materialized_values), result


def _materialize_crop_aware_ranked_visual_proxy_candidates(
    candidate_set: VisualTimelineCandidateSet,
    *,
    request: AnalysisRequest,
    rhythm_analysis: Any,
    section_plan: SectionPlan | None,
    source_aspect_ratios: Sequence[float],
    visual_montage_selection_policy: (
        ProfessionalMontageSelectionPolicy | None
    ),
    rendered_montage_config: RenderedMontageGrammarConfig | None,
    reporter: EventReporter,
) -> tuple[
    tuple[MaterializedVisualTimelineCandidate, ...],
    StageEditCandidateRerankResult | None,
    CropAwareCandidateRerankResult | None,
]:
    """Project safe crops before choosing the eight decoded-proxy candidates."""

    if request.stage_edit_checkpoint_directory is None:
        ordered_records = candidate_set.role_conditioned_ranked_candidates
        stage_edit_result = None
    else:
        report = request.stage_edit_production_training_report
        if report is None:  # AnalysisRequest enforces the pair; fail close here.
            raise RuntimeError(
                "StageEdit checkpoint activation requires its exact production report"
            )
        reporter.status(
            "검증된 StageEdit Transformer로 시각 후보 순서를 평가하는 중…"
        )
        stage_edit_result = rerank_visual_timeline_candidates_with_stage_edit(
            candidate_set,
            checkpoint_directory=request.stage_edit_checkpoint_directory,
            production_training_report=report,
            rhythm=rhythm_analysis,
            section_plan=section_plan,
        )
        ordered_records = stage_edit_result.ordered_records(candidate_set)
        reporter.log(
            "StageEdit Transformer가 보존된 시각 후보 "
            f"{len(ordered_records)}개의 1차 렌더 순서를 재평가"
        )
    ordered_materialized = tuple(
        materialize_visual_timeline_candidate_record(candidate_set, record)
        for record in ordered_records
        if record.review.passed or _is_boundary_repair_candidate(record)
    )
    repairable_count = sum(
        _is_boundary_repair_candidate(record) for record in ordered_records
    )
    if repairable_count:
        reporter.log(
            "초점·대형 경계만 탈락한 수선 가능 후보 "
            f"{repairable_count}개도 크롭 투영 순위에 포함 · "
            "파생 후 구조 하드 게이트는 유지"
        )
    if len(ordered_materialized) < 8:
        reporter.log(
            "안전 크롭 후보 재순위 전에 구조 통과 후보가 8개 미만 · "
            f"{len(ordered_materialized)}개를 유지하고 기존 복구 게이트로 전달"
        )
        return ordered_materialized, stage_edit_result, None
    if (
        section_plan is None
        or visual_montage_selection_policy is None
        or rendered_montage_config is None
    ):
        raise RuntimeError(
            "crop-aware proxy selection requires section and immutable "
            "professional montage policy evidence"
        )
    crop_result = rerank_materialized_visual_candidates_for_safe_crops(
        ordered_materialized,
        source_aspect_ratios=source_aspect_ratios,
        section_plan=section_plan,
        policy=visual_montage_selection_policy,
        rendered_config=rendered_montage_config,
        maximum_candidates=8,
    )
    qualified_count = sum(
        item.all_highlight_metadata_floors_passed
        for item in crop_result.evaluations
    )
    reporter.log(
        "안전 크롭 적용 후 화면을 투영해 "
        f"{len(crop_result.ordered_candidates)}개 후보 중 8개 선정 · "
        f"하이라이트 투영 하한 충족 {qualified_count}개 · "
        "최종 권한은 480p 디코딩 QA 유지"
    )
    return crop_result.selected_candidates, stage_edit_result, crop_result


def _visual_candidate_checkpoint_input_identity(
    *,
    sources: Sequence[Path],
    canonical_spans: Sequence[tuple[float, float]],
    audio_offsets: Sequence[float],
    sync_scores: Sequence[float],
    scene_cut_times: Sequence[Sequence[float]],
    source_timewarps: Sequence[TimeWarpMap | None],
    source_aspect_ratios: Sequence[float],
    preferred_source_indices: Sequence[int],
    section_plan: SectionPlan,
    phrase_times: Sequence[float],
    professional_policy: ProfessionalMontageSelectionPolicy,
    rendered_montage_config: RenderedMontageGrammarConfig,
    source_derivative_diversity: SourceDerivativeDiversityResult,
    aspect_ratio: AspectRatio,
) -> tuple[dict[str, Any], str]:
    """Bind restartable candidate plans to every selector-affecting input."""

    source_values = tuple(Path(path).resolve(strict=True) for path in sources)
    if not source_values:
        raise ValueError("candidate checkpoint identity needs sources")
    if not (
        len(source_values)
        == len(audio_offsets)
        == len(sync_scores)
        == len(scene_cut_times)
        == len(source_timewarps)
        == len(source_aspect_ratios)
    ):
        raise ValueError("candidate checkpoint source arrays must match")
    identity: dict[str, Any] = {
        "contract": "visual_candidate_restart_input_identity_v1",
        "sources": [
            {
                "path": str(path),
                "sha256": source_content_sha256(path),
                "size_bytes": path.stat().st_size,
            }
            for path in source_values
        ],
        "canonical_spans": [list(value) for value in canonical_spans],
        "audio_offsets": [float(value) for value in audio_offsets],
        "sync_scores": [float(value) for value in sync_scores],
        "scene_cut_times": [
            [float(value) for value in values]
            for values in scene_cut_times
        ],
        "source_timewarps": [
            value.to_dict() if value is not None else None
            for value in source_timewarps
        ],
        "source_aspect_ratios": [
            float(value) for value in source_aspect_ratios
        ],
        "preferred_source_indices": [
            int(value) for value in preferred_source_indices
        ],
        "section_plan": section_plan.to_dict(),
        "phrase_times": [float(value) for value in phrase_times],
        "professional_montage_selection_policy": (
            professional_policy.to_dict()
        ),
        "rendered_montage_config": asdict(rendered_montage_config),
        "source_derivative_audit_sha256": (
            source_derivative_diversity.audit_sha256
        ),
        "aspect_ratio": aspect_ratio.value,
        "maximum_candidate_results": 32,
        "code_fingerprint_contract": (
            PYTHON_SYMBOL_DEPENDENCY_AST_CONTRACT
        ),
        "selector_code_sha256": python_symbol_dependency_sha256(
            Path(__file__).with_name("visual_score.py"),
            root_symbols=("build_visual_timeline_candidate_set",),
        ),
        "crop_rerank_code_sha256": python_symbol_dependency_sha256(
            Path(__file__).with_name("crop_aware_candidate_rerank.py"),
            root_symbols=(
                "rerank_materialized_visual_candidates_for_safe_crops",
            ),
        ),
    }
    return identity, canonical_json_sha256(identity)


