@dataclass(frozen=True, slots=True)
class _DirectFullFramePartitionProfile:
    profile_id: str
    unit_counts: tuple[int, ...]
    spans: tuple[_DirectFullFrameSpan, ...]
    boundary_shifts: tuple[_DirectFullFrameBoundaryShift, ...] = ()
    window_redistributions: tuple[
        _DirectFullFrameProofDirectedWindowRedistribution,
        ...,
    ] = ()
    visual_frontier_splits: tuple[
        _DirectFullFrameVisualFrontierSplit,
        ...,
    ] = ()
    boundary_merges: tuple[
        _DirectFullFrameProofDirectedBoundaryMerge,
        ...,
    ] = ()
    latest_operation_kind: str | None = None
    warm_start_binding_sha256: str | None = None
    warm_start_cache_file_sha256: str | None = None

    @property
    def shifted_boundary_index(self) -> int | None:
        return self.boundary_shifts[0].boundary_index if self.boundary_shifts else None

    @property
    def boundary_shift_units(self) -> int:
        return self.boundary_shifts[0].shift_units if self.boundary_shifts else 0

    @property
    def shifted_boundary_reasons(self) -> tuple[str, ...]:
        return (
            self.boundary_shifts[0].boundary_reasons
            if self.boundary_shifts
            else ()
        )

    @property
    def secondary_shifted_boundary_index(self) -> int | None:
        return (
            self.boundary_shifts[1].boundary_index
            if len(self.boundary_shifts) >= 2
            else None
        )

    @property
    def secondary_boundary_shift_units(self) -> int:
        return self.boundary_shifts[1].shift_units if len(self.boundary_shifts) >= 2 else 0

    @property
    def secondary_shifted_boundary_reasons(self) -> tuple[str, ...]:
        return (
            self.boundary_shifts[1].boundary_reasons
            if len(self.boundary_shifts) >= 2
            else ()
        )

    @property
    def secondary_shift_trigger(self) -> str | None:
        return self.boundary_shifts[1].trigger if len(self.boundary_shifts) >= 2 else None

    @property
    def latest_proof_operation(self) -> Any | None:
        """Return the explicitly recorded final lineage operation.

        Profile identifiers are diagnostic labels, not ancestry depths.  A
        previous implementation compared their string lengths, which could
        misidentify a short but newer boundary shift after a long merge label.
        Constructors now seal the operation kind directly.  The single-kind
        fallback keeps simple test/legacy profiles readable while refusing an
        ambiguous multi-operation lineage.
        """

        operations = {
            "boundary_shift": (
                self.boundary_shifts[-1] if self.boundary_shifts else None
            ),
            "window_redistribution": (
                self.window_redistributions[-1]
                if self.window_redistributions
                else None
            ),
            "visual_frontier_split": (
                self.visual_frontier_splits[-1]
                if self.visual_frontier_splits
                else None
            ),
            "boundary_merge": (
                self.boundary_merges[-1] if self.boundary_merges else None
            ),
        }
        if self.latest_operation_kind is not None:
            if self.latest_operation_kind not in operations:
                raise RuntimeError(
                    "direct partition profile has an unknown lineage operation"
                )
            operation = operations[self.latest_operation_kind]
            if operation is None:
                raise RuntimeError(
                    "direct partition profile lineage operation is missing"
                )
            return operation
        populated = tuple(
            operation for operation in operations.values() if operation is not None
        )
        if len(populated) <= 1:
            return populated[0] if populated else None
        raise RuntimeError(
            "direct partition profile has ambiguous unsealed lineage"
        )

    @property
    def parent_profile_id(self) -> str | None:
        operation = self.latest_proof_operation
        return operation.parent_profile_id if operation is not None else None

    @property
    def changed_span_count(self) -> int:
        changed_indices: set[int] = set()
        for shift in self.boundary_shifts:
            changed_indices.update((shift.boundary_index, shift.boundary_index + 1))
        for redistribution in self.window_redistributions:
            changed_indices.update(
                range(
                    redistribution.window_start_span_index,
                    redistribution.window_start_span_index + 3,
                )
            )
        for split in self.visual_frontier_splits:
            changed_indices.update(
                (split.parent_span_index, split.parent_span_index + 1)
            )
        for merge in self.boundary_merges:
            changed_indices.update(
                (merge.boundary_index, merge.boundary_index + 1)
            )
        return len(changed_indices)

    @property
    def structural_change_count(self) -> int:
        return (
            len(self.boundary_shifts)
            + 2 * len(self.window_redistributions)
            + len(self.visual_frontier_splits)
            + len(self.boundary_merges)
        )

    @property
    def proof_directed_boundary_motion_count(self) -> int:
        return len(self.boundary_shifts) + 2 * len(
            self.window_redistributions
        )

    @property
    def total_unit_displacement(self) -> int:
        return sum(
            abs(shift.shift_units) for shift in self.boundary_shifts
        ) + sum(
            redistribution.boundary_displacement_units
            for redistribution in self.window_redistributions
        )

    @property
    def musical_boundary_penalty(self) -> int:
        def _penalty(reasons: Sequence[str]) -> int:
            values = set(reasons)
            if "phrase" in values:
                return 0
            if "strong_beat" in values:
                return 1
            if "beat" in values:
                return 2
            return 3

        penalties = [
            _penalty(shift.boundary_reasons) for shift in self.boundary_shifts
        ]
        penalties.extend(
            _penalty(reasons)
            for redistribution in self.window_redistributions
            for reasons in redistribution.replacement_boundary_reasons
        )
        penalties.extend(
            _penalty(split.boundary_reasons)
            for split in self.visual_frontier_splits
        )
        penalties.extend(
            _penalty(merge.boundary_reasons)
            for merge in self.boundary_merges
        )
        return sum(penalties) if penalties else 3

    def to_dict(self) -> dict[str, Any]:
        return {
            "profile_id": self.profile_id,
            "partition_unit_counts": list(self.unit_counts),
            "partition_signature_sha256": hashlib.sha256(
                json.dumps(
                    list(self.unit_counts),
                    ensure_ascii=False,
                    separators=(",", ":"),
                ).encode("utf-8")
            ).hexdigest(),
            "coarse_span_count": len(self.spans),
            "shifted_boundary_index": self.shifted_boundary_index,
            "boundary_shift_units": self.boundary_shift_units,
            "changed_span_count": self.changed_span_count,
            "shifted_boundary_count": len(self.boundary_shifts),
            "window_redistribution_count": len(
                self.window_redistributions
            ),
            "proof_directed_boundary_motion_count": (
                self.proof_directed_boundary_motion_count
            ),
            "total_unit_displacement": self.total_unit_displacement,
            "visual_frontier_split_count": len(self.visual_frontier_splits),
            "proof_directed_boundary_merge_count": len(
                self.boundary_merges
            ),
            "structural_change_count": self.structural_change_count,
            "shifted_boundary_reasons": list(self.shifted_boundary_reasons),
            "secondary_shifted_boundary_index": (
                self.secondary_shifted_boundary_index
            ),
            "secondary_boundary_shift_units": (
                self.secondary_boundary_shift_units
            ),
            "secondary_shifted_boundary_reasons": list(
                self.secondary_shifted_boundary_reasons
            ),
            "secondary_shift_trigger": self.secondary_shift_trigger,
            "parent_profile_id": self.parent_profile_id,
            "latest_operation_kind": self.latest_operation_kind,
            "input_bound_partition_warm_start": (
                {
                    "contract": _DIRECT_MEMBER_PARTITION_WARM_START_CONTRACT,
                    "binding_sha256": self.warm_start_binding_sha256,
                    "cache_file_sha256": self.warm_start_cache_file_sha256,
                    "full_selector_recheck_required": True,
                    "visual_gates_relaxed": False,
                }
                if self.warm_start_binding_sha256 is not None
                else None
            ),
            "proof_directed_boundary_shifts": [
                shift.to_dict() for shift in self.boundary_shifts
            ],
            "proof_directed_window_redistributions": [
                redistribution.to_dict()
                for redistribution in self.window_redistributions
            ],
            "proof_directed_visual_frontier_splits": [
                split.to_dict() for split in self.visual_frontier_splits
            ],
            "proof_directed_boundary_merges": [
                merge.to_dict() for merge in self.boundary_merges
            ],
            "musical_boundary_penalty": self.musical_boundary_penalty,
            "minimum_span_seconds": min(
                span.duration_seconds for span in self.spans
            ),
            "median_span_seconds": median(
                span.duration_seconds for span in self.spans
            ),
            "maximum_span_seconds": max(
                span.duration_seconds for span in self.spans
            ),
        }


def _direct_full_frame_spans_from_partition(
    timing_segments: Sequence[DraftSegment],
    unit_counts: Sequence[int],
) -> tuple[_DirectFullFrameSpan, ...]:
    """Materialize one contiguous musical partition without moving range edges."""

    items = tuple(timing_segments)
    counts = tuple(int(value) for value in unit_counts)
    if not items or not counts or any(value <= 0 for value in counts):
        raise ValueError("direct full-frame partition must contain positive units")
    if sum(counts) != len(items):
        raise ValueError("direct full-frame partition must consume every timing unit")
    spans: list[_DirectFullFrameSpan] = []
    cursor = 0
    for count in counts:
        group = items[cursor : cursor + count]
        duration = (
            group[-1].canonical_master_end
            - group[0].canonical_master_start
        )
        if duration <= 0.0 or duration > _DIRECT_MEMBER_MAX_RUN_SECONDS + 1e-9:
            raise ValueError(
                "direct full-frame partition violates the 7.2-second hold bound"
            )
        spans.append(
            _DirectFullFrameSpan(
                canonical_master_start=group[0].canonical_master_start,
                canonical_master_end=group[-1].canonical_master_end,
                timing_segment_count=count,
                estimated_beat_count=sum(
                    item.estimated_beat_count for item in group
                ),
                start_boundary_reasons=group[0].start_boundary_reasons,
                end_boundary_reasons=group[-1].end_boundary_reasons,
            )
        )
        cursor += count
    return tuple(spans)


def _coarsen_direct_full_frame_spans(
    timing_segments: Sequence[DraftSegment],
) -> tuple[_DirectFullFrameSpan, ...]:
    """Merge the one-strong-beat timing draft into reference-like shot holds.

    The metadata draft often exposes a boundary roughly every two detected
    tempo beats.  Four such units are therefore the stable default (about eight
    tempo beats / 3.9 seconds for IVE ``I AM``).  Two- and six-unit alternatives
    remain available when a phrase or strong-beat boundary is materially closer
    to the calibrated target.  A final short remainder is merged whenever the
    7.2-second hard maximum permits it.
    """

    items = tuple(timing_segments)
    if not items:
        raise ValueError("direct full-frame timing draft cannot be empty")
    spans: list[_DirectFullFrameSpan] = []
    cursor = 0
    while cursor < len(items):
        remaining = len(items) - cursor
        candidate_counts = [
            count for count in (2, 4, 6) if count <= remaining
        ]
        if remaining not in candidate_counts:
            candidate_counts.append(remaining)
        candidates: list[tuple[tuple[float, float, int], int]] = []
        for count in candidate_counts:
            end_index = cursor + count - 1
            duration = (
                items[end_index].canonical_master_end
                - items[cursor].canonical_master_start
            )
            if duration <= 0.0 or duration > _DIRECT_MEMBER_MAX_RUN_SECONDS + 1e-9:
                continue
            reasons = set(items[end_index].end_boundary_reasons)
            boundary_bonus = (
                0.18
                if "phrase" in reasons
                else 0.08
                if "strong_beat" in reasons
                else 0.0
            )
            candidates.append(
                (
                    (
                        abs(duration - _DIRECT_MEMBER_TARGET_RUN_SECONDS)
                        - boundary_bonus,
                        abs(float(count) - 4.0),
                        count,
                    ),
                    count,
                )
            )
        if not candidates:
            raise RuntimeError(
                "direct full-frame cadence cannot satisfy the 7.2-second hold bound"
            )
        count = min(candidates)[1]
        group = items[cursor : cursor + count]
        spans.append(
            _DirectFullFrameSpan(
                canonical_master_start=group[0].canonical_master_start,
                canonical_master_end=group[-1].canonical_master_end,
                timing_segment_count=len(group),
                estimated_beat_count=sum(
                    item.estimated_beat_count for item in group
                ),
                start_boundary_reasons=group[0].start_boundary_reasons,
                end_boundary_reasons=group[-1].end_boundary_reasons,
            )
        )
        cursor += count

    if len(spans) > 1 and spans[-1].duration_seconds < 2.0:
        left = spans[-2]
        right = spans[-1]
        merged_duration = right.canonical_master_end - left.canonical_master_start
        if merged_duration <= _DIRECT_MEMBER_MAX_RUN_SECONDS + 1e-9:
            spans[-2:] = [
                _DirectFullFrameSpan(
                    canonical_master_start=left.canonical_master_start,
                    canonical_master_end=right.canonical_master_end,
                    timing_segment_count=(
                        left.timing_segment_count + right.timing_segment_count
                    ),
                    estimated_beat_count=(
                        left.estimated_beat_count + right.estimated_beat_count
                    ),
                    start_boundary_reasons=left.start_boundary_reasons,
                    end_boundary_reasons=right.end_boundary_reasons,
                )
            ]
    return tuple(spans)


def _normalized_direct_member_highlight_intervals(
    intervals: Sequence[tuple[float, float]],
    *,
    range_start: float,
    range_end: float,
) -> tuple[tuple[float, float], ...]:
    """Clip and merge the section plan into one deterministic time union."""

    if not math.isfinite(range_start) or not math.isfinite(range_end):
        raise ValueError("direct-member highlight range must be finite")
    if range_end <= range_start:
        raise ValueError("direct-member highlight range must be positive")
    clipped: list[tuple[float, float]] = []
    for raw_start, raw_end in intervals:
        start = float(raw_start)
        end = float(raw_end)
        if not math.isfinite(start) or not math.isfinite(end) or end <= start:
            raise ValueError(
                "direct-member highlight intervals must be finite and positive"
            )
        start = max(range_start, start)
        end = min(range_end, end)
        if end > start + 1e-9:
            clipped.append((start, end))
    if not clipped:
        return ()
    clipped.sort()
    merged: list[tuple[float, float]] = [clipped[0]]
    for start, end in clipped[1:]:
        previous_start, previous_end = merged[-1]
        if start <= previous_end + 1e-7:
            merged[-1] = (previous_start, max(previous_end, end))
        else:
            merged.append((start, end))
    return tuple(merged)


def _direct_member_interval_overlap_seconds(
    start: float,
    end: float,
    intervals: Sequence[tuple[float, float]],
) -> float:
    return sum(
        max(0.0, min(end, interval_end) - max(start, interval_start))
        for interval_start, interval_end in intervals
    )


def _direct_member_boundary_is_highlight(
    boundary_seconds: float,
    intervals: Sequence[tuple[float, float]],
) -> bool:
    return any(
        start - 1e-7 <= boundary_seconds <= end + 1e-7
        for start, end in intervals
    )


def _direct_member_highlight_priority_boundary_indices(
    spans: Sequence[_DirectFullFrameSpan],
    intervals: Sequence[tuple[float, float]],
) -> tuple[int, ...]:
    """Return section-critical cuts governed by the compensated-hold budget."""

    items = tuple(spans)
    if len(items) < 2 or not intervals:
        return ()
    return tuple(
        boundary_index
        for boundary_index, span in enumerate(items[:-1])
        if _direct_member_boundary_is_highlight(
            span.canonical_master_end,
            intervals,
        )
    )


def _densify_direct_full_frame_highlights(
    timing_segments: Sequence[DraftSegment],
    base_spans: Sequence[_DirectFullFrameSpan],
    highlight_intervals: Sequence[tuple[float, float]],
    *,
    minimum_span_count: int | None = None,
) -> tuple[_DirectFullFrameSpan, ...]:
    """Add musically bound cuts without weakening visual gates.

    The reference cadence remains roughly four timing units outside active
    sections.  Inside BUILD/CHORUS-like intervals, long holds are split only
    at boundaries already emitted by ``build_group_draft``. A one-unit child
    is eligible only when its real duration still reaches the 1.8-second floor.
    The ordinary target stays within 19.5/min; an explicit capacity minimum
    can use the 21/min hard ceiling. The visual selector must still
    independently approve every added cut. If
    a whole-edit minimum is supplied, the same musical-boundary split is also
    allowed outside annotated highlights so the generator can actually reach
    the professional cadence floor that the final gate enforces.
    """

    items = tuple(timing_segments)
    baseline = tuple(base_spans)
    if not items or not baseline:
        return baseline
    normalized = (
        _normalized_direct_member_highlight_intervals(
            highlight_intervals,
            range_start=items[0].canonical_master_start,
            range_end=items[-1].canonical_master_end,
        )
        if highlight_intervals
        else ()
    )
    if not normalized and minimum_span_count is None:
        return baseline
    total_duration = (
        items[-1].canonical_master_end - items[0].canonical_master_start
    )
    if minimum_span_count is not None and (
        isinstance(minimum_span_count, bool)
        or not isinstance(minimum_span_count, int)
        or minimum_span_count < 1
    ):
        raise ValueError("direct member minimum span count is invalid")
    hard_maximum_span_count = (
        math.floor(
            total_duration * _DIRECT_MEMBER_MAX_SWITCHES_PER_MINUTE / 60.0
            + 1e-9
        )
        + 1
    )
    target_span_count = len(baseline)
    if normalized:
        target_span_count = min(
            math.floor(
                total_duration
                * _DIRECT_MEMBER_INITIAL_MAX_SWITCHES_PER_MINUTE
                / 60.0
            )
            + 1,
            max(
                len(baseline),
                math.ceil(
                    total_duration
                    * _DIRECT_MEMBER_HIGHLIGHT_DENSE_SWITCHES_PER_MINUTE
                    / 60.0
                )
                + 1,
            ),
        )
    if minimum_span_count is not None:
        # Sparse all-source proofs need two reusable carrier slots so the
        # portrait performance sources can bridge the landscape inserts. Use
        # the last cadence slot only when that diversity contract needs it;
        # ordinary short excerpts retain the calmer 19.5/minute seed.
        target_span_count = max(
            target_span_count,
            min(minimum_span_count, hard_maximum_span_count),
        )
    counts = [span.timing_segment_count for span in baseline]
    while len(counts) < target_span_count:
        needs_global_capacity = (
            minimum_span_count is not None
            and len(counts) < min(minimum_span_count, hard_maximum_span_count)
        )
        candidates: list[
            tuple[
                tuple[float, float, int, float, int, int],
                int,
                int,
            ]
        ] = []
        unit_start = 0
        for span_index, count in enumerate(counts):
            if count < 2:
                unit_start += count
                continue
            group_start = items[unit_start].canonical_master_start
            group_end = items[unit_start + count - 1].canonical_master_end
            group_duration = group_end - group_start
            overlap = (
                _direct_member_interval_overlap_seconds(
                    group_start,
                    group_end,
                    normalized,
                )
                if normalized
                else 0.0
            )
            overlap_fraction = overlap / group_duration
            if overlap_fraction < 0.50 and not needs_global_capacity:
                unit_start += count
                continue
            for split_offset in range(1, count):
                boundary_unit = items[unit_start + split_offset - 1]
                boundary_seconds = boundary_unit.canonical_master_end
                is_highlight_cut = (
                    overlap_fraction >= 0.50
                    and _direct_member_boundary_is_highlight(
                        boundary_seconds,
                        normalized,
                    )
                )
                if not is_highlight_cut and not needs_global_capacity:
                    continue
                left_duration = boundary_seconds - group_start
                right_duration = group_end - boundary_seconds
                if (
                    min(left_duration, right_duration)
                    + 1e-9
                    < _DIRECT_MEMBER_HIGHLIGHT_MINIMUM_RUN_SECONDS
                ):
                    continue
                reasons = set(boundary_unit.end_boundary_reasons)
                musical_penalty = (
                    0
                    if "phrase" in reasons
                    else 1
                    if "strong_beat" in reasons
                    else 2
                    if "beat" in reasons
                    else 3
                )
                target_run_seconds = (
                    _DIRECT_MEMBER_HIGHLIGHT_TARGET_RUN_SECONDS
                    if is_highlight_cut
                    else _DIRECT_MEMBER_TARGET_RUN_SECONDS
                )
                target_errors = sorted(
                    (
                        abs(left_duration - target_run_seconds),
                        abs(right_duration - target_run_seconds),
                    )
                )
                candidates.append(
                    (
                        (
                            -overlap_fraction if is_highlight_cut else 1.0,
                            target_errors[0],
                            musical_penalty,
                            target_errors[1],
                            span_index,
                            split_offset,
                        ),
                        span_index,
                        split_offset,
                    )
                )
            unit_start += count
        if not candidates:
            break
        _score, span_index, split_offset = min(candidates)
        original_count = counts[span_index]
        counts[span_index : span_index + 1] = [
            split_offset,
            original_count - split_offset,
        ]
    return _direct_full_frame_spans_from_partition(items, counts)


def _direct_full_frame_base_partition_profile(
    timing_segments: Sequence[DraftSegment],
    *,
    highlight_intervals: Sequence[tuple[float, float]] = (),
    minimum_span_count: int | None = None,
) -> _DirectFullFramePartitionProfile:
    baseline = _coarsen_direct_full_frame_spans(timing_segments)
    spans = _densify_direct_full_frame_highlights(
        timing_segments,
        baseline,
        highlight_intervals,
        minimum_span_count=minimum_span_count,
    )
    return _DirectFullFramePartitionProfile(
        profile_id=(
            "all-source-capacity-highlight-dense-v1"
            if minimum_span_count is not None
            and len(spans) >= minimum_span_count
            and len(spans) > len(baseline)
            else "highlight-dense-reference-coarsening-v1"
            if len(spans) > len(baseline)
            else "base-reference-coarsening"
        ),
        unit_counts=tuple(span.timing_segment_count for span in spans),
        spans=spans,
    )


def _direct_member_short_proof_capacity_expansion_profiles(
    timing_segments: Sequence[DraftSegment],
    seed_profiles: Sequence[_DirectFullFramePartitionProfile],
    *,
    minimum_span_count: int,
    highlight_intervals: Sequence[tuple[float, float]] = (),
    excluded_unit_counts: Sequence[Sequence[int]] = (),
) -> tuple[_DirectFullFramePartitionProfile, ...]:
    """Add one musical carrier slot to proven sparse short-proof cadences.

    The ordinary highlight seed deliberately leaves headroom for a later
    repair.  With eight required fancams, however, a nine-span seed provides
    only one reusable carrier slot and can force the two landscape inserts
    through the same locally disconnected boundary.  Expand every exact
    input-bound nine-span seed at an existing musical boundary, keep the
    1.8-second flash-shot floor and 21/minute ceiling, and let the full visual
    selector prove each resulting path.  No cached source assignment or
    transition decision is reused.
    """

    items = tuple(timing_segments)
    seeds = tuple(seed_profiles)
    if not items or not seeds:
        return ()
    if (
        isinstance(minimum_span_count, bool)
        or not isinstance(minimum_span_count, int)
        or minimum_span_count < 2
    ):
        raise ValueError("short-proof capacity minimum span count is invalid")
    total_duration = (
        items[-1].canonical_master_end - items[0].canonical_master_start
    )
    if (
        total_duration <= 0.0
        or total_duration
        > _DIRECT_MEMBER_SHORT_PROOF_MAXIMUM_DURATION_SECONDS + 1e-9
    ):
        return ()
    hard_maximum_span_count = (
        math.floor(
            total_duration * _DIRECT_MEMBER_MAX_SWITCHES_PER_MINUTE / 60.0
            + 1e-9
        )
        + 1
    )
    target_span_count = min(minimum_span_count, hard_maximum_span_count)
    normalized_highlights = (
        _normalized_direct_member_highlight_intervals(
            highlight_intervals,
            range_start=items[0].canonical_master_start,
            range_end=items[-1].canonical_master_end,
        )
        if highlight_intervals
        else ()
    )
    excluded = {
        tuple(int(value) for value in values)
        for values in excluded_unit_counts
    }
    ranked: list[
        tuple[
            tuple[int, int, float, float, int, int, int],
            tuple[int, ...],
            tuple[_DirectFullFrameSpan, ...],
        ]
    ] = []
    seen = set(excluded)
    for seed_index, seed in enumerate(seeds):
        if len(seed.spans) != target_span_count - 1:
            continue
        unit_start = 0
        for span_index, unit_count in enumerate(seed.unit_counts):
            group_start = items[unit_start].canonical_master_start
            group_end = items[unit_start + unit_count - 1].canonical_master_end
            for split_offset in range(1, unit_count):
                boundary_unit = items[unit_start + split_offset - 1]
                boundary_seconds = boundary_unit.canonical_master_end
                left_duration = boundary_seconds - group_start
                right_duration = group_end - boundary_seconds
                if (
                    min(left_duration, right_duration) + 1e-9
                    < _DIRECT_MEMBER_HIGHLIGHT_MINIMUM_RUN_SECONDS
                ):
                    continue
                counts = list(seed.unit_counts)
                counts[span_index : span_index + 1] = [
                    split_offset,
                    unit_count - split_offset,
                ]
                signature = tuple(counts)
                if signature in seen:
                    continue
                try:
                    spans = _direct_full_frame_spans_from_partition(
                        items,
                        signature,
                    )
                except ValueError:
                    continue
                switches_per_minute = (
                    (len(spans) - 1) * 60.0 / total_duration
                )
                span_median = median(
                    span.duration_seconds for span in spans
                )
                if not (
                    switches_per_minute
                    <= _DIRECT_MEMBER_MAX_SWITCHES_PER_MINUTE + 1e-9
                    and _direct_member_median_run_is_valid(
                        total_duration,
                        span_median,
                    )
                ):
                    continue
                reasons = set(boundary_unit.end_boundary_reasons)
                musical_penalty = (
                    0
                    if "phrase" in reasons
                    else 1
                    if "strong_beat" in reasons
                    else 2
                    if "beat" in reasons
                    else 3
                )
                inside_highlight = _direct_member_boundary_is_highlight(
                    boundary_seconds,
                    normalized_highlights,
                )
                target_run = (
                    _DIRECT_MEMBER_HIGHLIGHT_TARGET_RUN_SECONDS
                    if inside_highlight
                    else _DIRECT_MEMBER_TARGET_RUN_SECONDS
                )
                ranked.append(
                    (
                        (
                            0 if inside_highlight else 1,
                            musical_penalty,
                            abs(left_duration - target_run)
                            + abs(right_duration - target_run),
                            abs(left_duration - right_duration),
                            seed_index,
                            span_index,
                            split_offset,
                        ),
                        signature,
                        spans,
                    )
                )
                seen.add(signature)
            unit_start += unit_count
    profiles: list[_DirectFullFramePartitionProfile] = []
    for _rank, counts, spans in sorted(ranked):
        signature = _direct_partition_signature_sha256(counts)
        profiles.append(
            _DirectFullFramePartitionProfile(
                profile_id=(
                    f"short-proof-all-source-capacity-{signature[:16]}"
                ),
                unit_counts=counts,
                spans=spans,
            )
        )
        if len(profiles) >= (
            _DIRECT_MEMBER_MAXIMUM_SHORT_PROOF_CAPACITY_SEED_PROFILE_COUNT
        ):
            break
    return tuple(profiles)


def _direct_member_in_run_preferred_partition_profile(
    timing_segments: Sequence[DraftSegment],
    unit_counts: Sequence[int] | None,
) -> _DirectFullFramePartitionProfile | None:
    """Rebuild the last selected cadence for a path-only feedback retry.

    Dense camera and decoded-proxy feedback usually invalidates one selected
    source pair, not the musical partition that surrounded it.  Rebuilding the
    exact in-memory partition lets the full visual selector replace that pair
    before the much larger proof-directed partition search is restarted.
    Every ordinary cadence gate is rechecked; this is only a search-order hint,
    never a relaxation or a reuse of the previous source path.
    """

    if unit_counts is None:
        return None
    items = tuple(timing_segments)
    counts = tuple(unit_counts)
    if not counts or any(
        isinstance(value, bool)
        or not isinstance(value, int)
        or value <= 0
        for value in counts
    ):
        raise ValueError("preferred direct partition counts must be positive integers")
    if sum(counts) != len(items):
        raise ValueError("preferred direct partition does not cover timing segments")
    spans = _direct_full_frame_spans_from_partition(items, counts)
    duration = sum(span.duration_seconds for span in spans)
    switches_per_minute = (len(spans) - 1) * 60.0 / duration
    span_median = median(span.duration_seconds for span in spans)
    if not (
        _DIRECT_MEMBER_MIN_SWITCHES_PER_MINUTE
        <= switches_per_minute
        <= _DIRECT_MEMBER_MAX_SWITCHES_PER_MINUTE
        and _direct_member_median_run_is_valid(duration, span_median)
        and max(span.duration_seconds for span in spans)
        <= _DIRECT_MEMBER_MAX_RUN_SECONDS + 1e-9
    ):
        raise ValueError("preferred direct partition fails cadence gates")
    signature = _direct_partition_signature_sha256(counts)
    return _DirectFullFramePartitionProfile(
        profile_id=f"in-run-path-retry-{signature[:16]}",
        unit_counts=counts,
        spans=spans,
    )


def _direct_partition_failure_bottlenecks(
    diagnostics: dict[str, Any],
    *,
    span_count: int,
) -> tuple[int, ...]:
    """Return proven fixed-boundary bottlenecks, final boundary first."""

    if span_count < 2:
        return ()
    candidates: list[int] = []
    connectivity = diagnostics.get("hard_boundary_connectivity", {})
    if isinstance(connectivity, dict):
        raw_zero = connectivity.get(
            "zero_local_nonsevere_transition_boundary_indices"
        )
        if raw_zero is None:
            # Compatibility for diagnostics written before localized hard-edge
            # counts were added. New runs never use global reachability zeros
            # to localize a partition shift.
            raw_zero = connectivity.get(
                "zero_reachable_transition_boundary_indices",
                (),
            )
        if isinstance(raw_zero, list):
            candidates.extend(
                int(value)
                for value in raw_zero
                if isinstance(value, int) and 0 <= value < span_count - 1
            )

    search = diagnostics.get("search", {})
    if isinstance(search, dict):
        exact = search.get("exact_lifeline", {})
        if isinstance(exact, dict):
            roots = exact.get("root_candidate_diagnostics", ())
            if (
                isinstance(roots, list)
                and roots
                and all(
                    isinstance(root, dict)
                    and root.get("search_outcome")
                    == "root_predecessor_exhausted"
                    for root in roots
                )
            ):
                candidates.append(span_count - 2)

    unique = sorted(
        set(candidates),
        key=lambda boundary: (
            boundary != span_count - 2,
            -boundary,
        ),
    )
    return tuple(unique[:_DIRECT_MEMBER_MAX_BOTTLENECK_BOUNDARY_COUNT])


def _direct_partition_failure_is_proven(
    diagnostics: dict[str, Any],
) -> bool:
    if diagnostics.get("failure") == "search_capacity_exhausted":
        return False
    if diagnostics.get("constraint_infeasibility_proven") is True:
        return True
    return diagnostics.get("failure") in {
        "content_validity_quota_precheck_failed",
        "boundary_diagnostic_eligible_pair_exhausted",
        "validity_quota_path_exhausted",
        "duration_balance_threshold_unsatisfied",
    }


def _direct_partition_failure_result(
    diagnostics: Mapping[str, Any],
) -> str:
    """Name a selector failure without calling an unproved result hard."""

    if _direct_partition_failure_is_proven(dict(diagnostics)):
        return "hard_infeasible"
    if diagnostics.get("failure") == "search_capacity_exhausted":
        return "capacity_exhausted"
    return "unproven_failure"


def _direct_partition_terminal_hold_failure_is_eligible(
    diagnostics: Mapping[str, Any],
) -> bool:
    """Return whether a bounded no-cut hold can change this failure.

    A same-source hold changes only boundary connectivity. It cannot make an
    invalid source/span usable, remove a native scene cut, restore missing
    focal evidence, or repair a source quota shortfall. Keeping those
    content-invalid profiles in the terminal cohort let their historical
    proof progress consume every audition slot ahead of genuinely repairable
    connectivity failures.
    """

    values = dict(diagnostics)
    failure = values.get("failure")
    if not (
        _direct_partition_failure_is_proven(values)
        and failure in _DIRECT_MEMBER_TERMINAL_HOLD_REPAIRABLE_FAILURES
    ):
        return False
    if failure == "role_aware_safe_hold_path_infeasible":
        role_constraints = values.get("role_constraints")
        return bool(
            isinstance(role_constraints, Mapping)
            and role_constraints.get("maximum_same_source_hold_count") == 0
        )
    return True


def _direct_partition_warm_terminal_audition_is_authorized(
    diagnostics: Mapping[str, Any],
    render_infeasible_transition_edges: Sequence[tuple[float, int, int]],
) -> bool:
    """Keep decoded-render repairs ahead of an early no-cut escape path."""

    return bool(
        not render_infeasible_transition_edges
        and _direct_partition_terminal_hold_failure_is_eligible(diagnostics)
    )


def _direct_partition_aggregate_outcome(
    statuses: Sequence[str],
    *,
    profile_cap_reached: bool,
) -> tuple[str, str, dict[str, int]]:
    """Summarize a bounded search without upgrading uncertainty to proof."""

    allowed = (
        "hard_infeasible",
        "capacity_exhausted",
        "unproven_failure",
    )
    items = tuple(str(status) for status in statuses)
    if any(status not in allowed for status in items):
        raise ValueError("direct partition aggregate received an unknown status")
    counts = {
        outcome: sum(status == outcome for status in items)
        for outcome in allowed
    }
    if profile_cap_reached:
        return (
            "direct_partition_search_capacity_exhausted",
            "profile_cap_reached",
            counts,
        )
    if counts["capacity_exhausted"]:
        return (
            "direct_partition_selector_capacity_exhausted",
            "selector_capacity_exhausted",
            counts,
        )
    if counts["unproven_failure"]:
        return (
            "direct_partition_unproven_failure",
            "unproven_failure",
            counts,
        )
    return (
        "direct_partition_profiles_exhausted",
        "bounded_hard_infeasible",
        counts,
    )


def _direct_counterfactual_secondary_signature_action(
    signature: tuple[int, ...],
    *,
    evaluated_signatures: set[tuple[int, ...]],
    queued_signatures: set[tuple[int, ...]],
    reserved_signatures: set[tuple[int, ...]],
    seen_signatures: set[tuple[int, ...]],
) -> str:
    """Decide whether a bounded secondary candidate is new or promoted.

    A canonical partition already waiting in the primary queue is promoted to
    the reserved +10 pass rather than discarded.  That distinction matters
    when the primary queue later reaches its static cap.
    """

    if signature in evaluated_signatures or signature in reserved_signatures:
        return "duplicate"
    if signature in queued_signatures:
        return "promote_queued"
    if signature in seen_signatures:
        return "duplicate"
    return "new"


@dataclass(frozen=True, slots=True)
class _DirectPartitionBoundaryProof:
    boundary_index: int
    trigger: str
    failure: str | None
    failed_segment_index: int | None
    forward_reachable_left_source_indices: tuple[int, ...]
    left_valid_source_indices: tuple[int, ...]
    right_valid_source_indices: tuple[int, ...]
    local_nonsevere_edge_count: int


def _direct_partition_exact_boundary_proof(
    diagnostics: dict[str, Any],
    *,
    boundary_index: int,
    trigger: str,
    span_count: int,
) -> _DirectPartitionBoundaryProof | None:
    """Bind a shift target to exact, scalar connectivity evidence."""

    if not _direct_partition_failure_is_proven(diagnostics):
        return None
    connectivity = diagnostics.get("hard_boundary_connectivity")
    if not isinstance(connectivity, dict) or connectivity.get(
        "analysis_basis"
    ) != "content_valid_nonsevere_no_repeat_reachability_v1":
        return None
    raw_boundaries = connectivity.get("boundaries")
    if not isinstance(raw_boundaries, list) or len(raw_boundaries) != span_count - 1:
        return None
    if not 0 <= boundary_index < len(raw_boundaries):
        return None
    item = raw_boundaries[boundary_index]
    if not isinstance(item, dict) or item.get("boundary_index") != boundary_index:
        return None
    left_valid = item.get("left_valid_source_indices")
    right_valid = item.get("right_valid_source_indices")
    forward = item.get("forward_reachable_left_source_indices")
    local_edges = item.get("nonsevere_cross_source_edge_count")
    if (
        not isinstance(left_valid, list)
        or not left_valid
        or not isinstance(right_valid, list)
        or not right_valid
        or not isinstance(forward, list)
        or not isinstance(local_edges, int)
        or local_edges < 0
    ):
        # Moving a cut cannot be used to conceal an empty/invalid content side.
        return None
    if trigger == "zero_local_nonsevere_transition_edges":
        raw_zero = connectivity.get(
            "zero_local_nonsevere_transition_boundary_indices"
        )
        if (
            not isinstance(raw_zero, list)
            or boundary_index not in raw_zero
            or local_edges != 0
        ):
            return None
    elif trigger == "proven_forward_connectivity_frontier_exhaustion":
        if local_edges <= 0 or _direct_partition_forward_exhaustion_bottleneck(
            diagnostics,
            span_count=span_count,
        ) != boundary_index:
            return None
    elif trigger == "post_alignment_highlight_forced_cut_infeasible":
        repair = diagnostics.get("highlight_hold_repair")
        forced = (
            repair.get("forced_cut_boundary_indices")
            if isinstance(repair, Mapping)
            else None
        )
        if not (
            isinstance(repair, Mapping)
            and repair.get("contract")
            == "post_alignment_density_constraint_generation_v1"
            and repair.get("attempted") is True
            and repair.get("result") == "repair_selection_infeasible"
            and isinstance(forced, list)
            and boundary_index in forced
        ):
            return None
    else:
        return None
    return _DirectPartitionBoundaryProof(
        boundary_index=boundary_index,
        trigger=trigger,
        failure=(
            str(diagnostics["failure"])
            if diagnostics.get("failure") is not None
            else None
        ),
        failed_segment_index=(
            boundary_index + 1
            if trigger == "post_alignment_highlight_forced_cut_infeasible"
            else int(diagnostics["failed_at_segment_index"])
            if isinstance(diagnostics.get("failed_at_segment_index"), int)
            else None
        ),
        forward_reachable_left_source_indices=tuple(int(value) for value in forward),
        left_valid_source_indices=tuple(int(value) for value in left_valid),
        right_valid_source_indices=tuple(int(value) for value in right_valid),
        local_nonsevere_edge_count=local_edges,
    )


def _direct_partition_exact_shift_proofs(
    diagnostics: dict[str, Any],
    *,
    span_count: int,
) -> tuple[_DirectPartitionBoundaryProof, ...]:
    """Return deterministic, independently proven targets for one parent."""

    connectivity = diagnostics.get("hard_boundary_connectivity")
    if not isinstance(connectivity, dict):
        return ()
    repair = diagnostics.get("highlight_hold_repair")
    raw_forced = (
        repair.get("forced_cut_boundary_indices")
        if isinstance(repair, Mapping)
        and repair.get("contract")
        == "post_alignment_density_constraint_generation_v1"
        and repair.get("attempted") is True
        and repair.get("result") == "repair_selection_infeasible"
        else None
    )
    forced_indices = (
        sorted(
            {
                int(value)
                for value in raw_forced
                if isinstance(value, int)
                and not isinstance(value, bool)
                and 0 <= value < span_count - 1
            }
        )
        if isinstance(raw_forced, list)
        else []
    )
    repair_proofs = tuple(
        proof
        for boundary_index in forced_indices
        if (
            proof := _direct_partition_exact_boundary_proof(
                diagnostics,
                boundary_index=boundary_index,
                trigger=(
                    "post_alignment_highlight_forced_cut_infeasible"
                ),
                span_count=span_count,
            )
        )
        is not None
    )
    if repair_proofs:
        return repair_proofs[
            :_DIRECT_MEMBER_MAX_BOTTLENECK_BOUNDARY_COUNT
        ]
    raw_zero = connectivity.get(
        "zero_local_nonsevere_transition_boundary_indices"
    )
    local_indices = (
        sorted(
            {
                int(value)
                for value in raw_zero
                if isinstance(value, int) and 0 <= value < span_count - 1
            },
            reverse=True,
        )
        if isinstance(raw_zero, list)
        else []
    )
    proofs: list[_DirectPartitionBoundaryProof] = []
    for boundary_index in local_indices:
        proof = _direct_partition_exact_boundary_proof(
            diagnostics,
            boundary_index=boundary_index,
            trigger="zero_local_nonsevere_transition_edges",
            span_count=span_count,
        )
        if proof is not None:
            proofs.append(proof)
        if len(proofs) >= _DIRECT_MEMBER_MAX_BOTTLENECK_BOUNDARY_COUNT:
            return tuple(proofs)
    if proofs:
        return tuple(proofs)
    frontier = _direct_partition_forward_exhaustion_bottleneck(
        diagnostics,
        span_count=span_count,
    )
    if frontier is None:
        return ()
    proof = _direct_partition_exact_boundary_proof(
        diagnostics,
        boundary_index=frontier,
        trigger="proven_forward_connectivity_frontier_exhaustion",
        span_count=span_count,
    )
    return (proof,) if proof is not None else ()


def _direct_partition_signature_sha256(unit_counts: Sequence[int]) -> str:
    return hashlib.sha256(
        json.dumps(
            [int(value) for value in unit_counts],
            ensure_ascii=False,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()


def _direct_member_stable_acquisition_source_identity_sha256(
    encoded_manifest: bytes,
    *,
    source_count: int,
) -> str:
    """Hash only acquired-source identity fields, never volatile search data."""

    try:
        manifest = json.loads(encoded_manifest.decode("utf-8"))
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError("direct member acquisition manifest is invalid") from exc
    if not isinstance(manifest, dict):
        raise ValueError("direct member acquisition manifest must be an object")
    selected = manifest.get("selected")
    if not (
        str(manifest.get("group", "")).strip().upper() == "IVE"
        and str(manifest.get("edit_mode", "")).strip().lower() == "member"
        and isinstance(manifest.get("song"), str)
        and manifest.get("song")
        and isinstance(manifest.get("target_member"), str)
        and manifest.get("target_member")
        and isinstance(selected, list)
        and len(selected) == source_count
    ):
        raise ValueError("direct member acquisition manifest scope mismatch")
    stable_sources: list[dict[str, Any]] = []
    for source_index, entry in enumerate(selected):
        if not isinstance(entry, dict):
            raise ValueError("direct member acquisition entry is invalid")
        integrity = entry.get("content_integrity")
        video_id = entry.get("video_id")
        broadcast_date = entry.get("broadcast_date")
        broadcast_program = entry.get("broadcast_program")
        if not (
            entry.get("source_index") == source_index
            and isinstance(video_id, str)
            and re.fullmatch(r"[0-9A-Za-z_-]{6,32}", video_id)
            and isinstance(broadcast_date, str)
            and re.fullmatch(r"\d{4}-\d{2}-\d{2}", broadcast_date)
            and isinstance(broadcast_program, str)
            and broadcast_program.strip()
            and isinstance(integrity, dict)
            and integrity.get("algorithm") == "sha256"
            and isinstance(integrity.get("sha256"), str)
            and re.fullmatch(r"[0-9a-f]{64}", integrity["sha256"])
            and isinstance(integrity.get("size_bytes"), int)
            and not isinstance(integrity.get("size_bytes"), bool)
            and integrity["size_bytes"] > 0
        ):
            raise ValueError("direct member acquisition source identity is invalid")
        stable_sources.append(
            {
                "source_index": source_index,
                "video_id": video_id,
                "broadcast_date": broadcast_date,
                "broadcast_program": broadcast_program.strip(),
                "source_content_sha256": integrity["sha256"],
                "source_size_bytes": integrity["size_bytes"],
            }
        )
    stable_identity = {
        "contract": "stable_automatic_member_acquisition_source_identity_v1",
        "group": "IVE",
        "song": manifest["song"],
        "edit_mode": "member",
        "target_member": manifest["target_member"],
        "sources": stable_sources,
    }
    return hashlib.sha256(
        json.dumps(
            stable_identity,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()


def _normalize_direct_member_dense_render_feedback_edges(
    edges: Sequence[tuple[float, int, int]],
    *,
    source_count: int,
    range_start: float,
    range_end: float,
) -> tuple[tuple[float, int, int], ...]:
    """Validate and deduplicate renderer-proven transition exclusions."""

    if (
        isinstance(source_count, bool)
        or not isinstance(source_count, int)
        or source_count < 2
    ):
        raise ValueError("dense-render feedback source count is invalid")
    if not (
        math.isfinite(range_start)
        and math.isfinite(range_end)
        and range_start < range_end
    ):
        raise ValueError("dense-render feedback range is invalid")
    normalized: list[tuple[float, int, int]] = []
    for raw in edges:
        if not isinstance(raw, (tuple, list)) or len(raw) != 3:
            raise ValueError("dense-render feedback edge is invalid")
        boundary_seconds, outgoing_source_index, incoming_source_index = raw
        if (
            isinstance(boundary_seconds, bool)
            or not isinstance(boundary_seconds, (int, float))
            or not math.isfinite(float(boundary_seconds))
            or not range_start - 1e-9
            <= float(boundary_seconds)
            <= range_end + 1e-9
            or isinstance(outgoing_source_index, bool)
            or not isinstance(outgoing_source_index, int)
            or isinstance(incoming_source_index, bool)
            or not isinstance(incoming_source_index, int)
            or not 0 <= outgoing_source_index < source_count
            or not 0 <= incoming_source_index < source_count
            or outgoing_source_index == incoming_source_index
        ):
            raise ValueError("dense-render feedback edge is invalid")
        edge = (
            float(boundary_seconds),
            outgoing_source_index,
            incoming_source_index,
        )
        if edge not in normalized:
            normalized.append(edge)
    if len(normalized) > _DIRECT_MEMBER_DENSE_RENDER_FEEDBACK_MAX_CERTIFICATE_COUNT:
        raise ValueError("dense-render feedback certificate limit exceeded")
    return tuple(normalized)


def _normalize_direct_member_proxy_feedback_penalties(
    edges: Sequence[tuple[float, int, int, float]],
    *,
    source_count: int,
    range_start: float,
    range_end: float,
) -> tuple[tuple[float, int, int, float], ...]:
    """Validate unique finite decoded-proxy edge penalties."""

    if (
        isinstance(source_count, bool)
        or not isinstance(source_count, int)
        or source_count < 2
    ):
        raise ValueError("decoded-proxy feedback source count is invalid")
    if not (
        math.isfinite(range_start)
        and math.isfinite(range_end)
        and range_start < range_end
    ):
        raise ValueError("decoded-proxy feedback range is invalid")
    normalized: list[tuple[float, int, int, float]] = []
    seen_keys: set[tuple[float, int, int]] = set()
    for raw in edges:
        if not isinstance(raw, (tuple, list)) or len(raw) != 4:
            raise ValueError("decoded-proxy feedback edge is invalid")
        (
            boundary_seconds,
            outgoing_source_index,
            incoming_source_index,
            penalty,
        ) = raw
        if (
            isinstance(boundary_seconds, bool)
            or not isinstance(boundary_seconds, (int, float))
            or not math.isfinite(float(boundary_seconds))
            or not range_start - 1e-9
            <= float(boundary_seconds)
            <= range_end + 1e-9
            or isinstance(outgoing_source_index, bool)
            or not isinstance(outgoing_source_index, int)
            or isinstance(incoming_source_index, bool)
            or not isinstance(incoming_source_index, int)
            or not 0 <= outgoing_source_index < source_count
            or not 0 <= incoming_source_index < source_count
            or outgoing_source_index == incoming_source_index
            or isinstance(penalty, bool)
            or not isinstance(penalty, (int, float))
            or not math.isfinite(float(penalty))
            or not 0.0 < float(penalty)
            <= _DIRECT_MEMBER_PROXY_FEEDBACK_MAXIMUM_ACCUMULATED_EDGE_PENALTY
        ):
            raise ValueError("decoded-proxy feedback edge is invalid")
        key = (
            float(boundary_seconds),
            outgoing_source_index,
            incoming_source_index,
        )
        if key in seen_keys:
            raise ValueError("decoded-proxy feedback edges must be unique")
        seen_keys.add(key)
        normalized.append((*key, float(penalty)))
    if len(normalized) > _DIRECT_MEMBER_PROXY_FEEDBACK_MAX_PENALTY_COUNT:
        raise ValueError("decoded-proxy feedback penalty limit exceeded")
    return tuple(normalized)


def _accumulate_direct_member_proxy_feedback_penalties(
    existing: Sequence[tuple[float, int, int, float]],
    updates: Sequence[tuple[float, int, int, float]],
    *,
    source_count: int,
    range_start: float,
    range_end: float,
) -> tuple[tuple[float, int, int, float], ...]:
    """Add bounded observations without turning them into hard exclusions."""

    normalized_existing = _normalize_direct_member_proxy_feedback_penalties(
        existing,
        source_count=source_count,
        range_start=range_start,
        range_end=range_end,
    )
    normalized_updates = _normalize_direct_member_proxy_feedback_penalties(
        updates,
        source_count=source_count,
        range_start=range_start,
        range_end=range_end,
    )
    penalties: dict[tuple[float, int, int], float] = {
        (boundary_seconds, outgoing_source_index, incoming_source_index): penalty
        for (
            boundary_seconds,
            outgoing_source_index,
            incoming_source_index,
            penalty,
        ) in normalized_existing
    }
    for (
        boundary_seconds,
        outgoing_source_index,
        incoming_source_index,
        penalty,
    ) in normalized_updates:
        key = (
            boundary_seconds,
            outgoing_source_index,
            incoming_source_index,
        )
        penalties[key] = min(
            _DIRECT_MEMBER_PROXY_FEEDBACK_MAXIMUM_ACCUMULATED_EDGE_PENALTY,
            penalties.get(key, 0.0) + penalty,
        )
    if len(penalties) > _DIRECT_MEMBER_PROXY_FEEDBACK_MAX_PENALTY_COUNT:
        raise ValueError("decoded-proxy feedback penalty limit exceeded")
    return tuple(
        (*key, penalty)
        for key, penalty in sorted(penalties.items())
    )


def _normalize_direct_member_proxy_rejected_paths(
    rejected_paths_by_partition: Mapping[
        Sequence[int], Sequence[Sequence[int]]
    ],
    *,
    source_count: int,
) -> tuple[tuple[tuple[int, ...], tuple[int, ...]], ...]:
    """Validate bounded exact path no-goods scoped to one beat partition."""

    if (
        isinstance(source_count, bool)
        or not isinstance(source_count, int)
        or source_count < 2
    ):
        raise ValueError("decoded-proxy rejected-path source count is invalid")
    normalized: list[tuple[tuple[int, ...], tuple[int, ...]]] = []
    for raw_unit_counts, raw_paths in rejected_paths_by_partition.items():
        unit_counts = tuple(raw_unit_counts)
        if (
            not unit_counts
            or any(
                isinstance(value, bool)
                or not isinstance(value, int)
                or value <= 0
                for value in unit_counts
            )
        ):
            raise ValueError(
                "decoded-proxy rejected-path partition is invalid"
            )
        for raw_path in raw_paths:
            path = tuple(raw_path)
            if (
                len(path) != len(unit_counts)
                or any(
                    isinstance(value, bool)
                    or not isinstance(value, int)
                    or not 0 <= value < source_count
                    for value in path
                )
            ):
                raise ValueError(
                    "decoded-proxy rejected source path is invalid"
                )
            item = (unit_counts, path)
            if item not in normalized:
                normalized.append(item)
    if (
        len(normalized)
        > _DIRECT_MEMBER_PROXY_FEEDBACK_MAX_REJECTED_PATH_COUNT
    ):
        raise ValueError("decoded-proxy rejected path limit exceeded")
    return tuple(normalized)


def _direct_member_dense_render_feedback_binding(
    feature_cache_directory: Path | None,
    *,
    timing_draft: GroupDraftTimeline,
    eligible_indices: Sequence[int],
    source_timewarps: Sequence[TimeWarpMap | None] | None,
    scene_cut_times: Sequence[Sequence[float]],
    eligible_source_frame_sizes: Sequence[tuple[int, int]],
    output_frame_size: tuple[int, int],
    output_fps: float,
    highlight_intervals: Sequence[tuple[float, float]],
    member_pose_dissolve_enabled: bool,
) -> tuple[dict[str, Any] | None, dict[str, Any]]:
    """Bind dense-render feedback to exact media, timing, and code state."""

    eligible = tuple(int(value) for value in eligible_indices)
    diagnostics: dict[str, Any] = {
        "contract": _DIRECT_MEMBER_DENSE_RENDER_FEEDBACK_CONTRACT,
        "requested": feature_cache_directory is not None,
        "cache_filename": _DIRECT_MEMBER_DENSE_RENDER_FEEDBACK_FILENAME,
        "visual_thresholds_relaxed": False,
    }
    if feature_cache_directory is None:
        diagnostics["status"] = "feature_cache_unavailable"
        return None, diagnostics
    if (
        len(eligible) < 2
        or len(set(eligible)) != len(eligible)
        or any(value < 0 for value in eligible)
        or len(scene_cut_times) != len(eligible)
        or len(eligible_source_frame_sizes) != len(eligible)
        or not math.isfinite(output_fps)
        or output_fps <= 0.0
    ):
        raise ValueError("dense-render feedback binding inputs are invalid")
    if source_timewarps is not None and max(eligible) >= len(source_timewarps):
        raise ValueError("dense-render feedback timewarps do not cover sources")
    manifest_path = Path(feature_cache_directory) / "acquisition-manifest.json"
    try:
        manifest_bytes, manifest_fingerprint = _read_stable_regular_file(
            manifest_path
        )
        source_identity_sha256 = (
            _direct_member_stable_acquisition_source_identity_sha256(
                manifest_bytes,
                source_count=len(eligible),
            )
        )
        implementation_sha256 = {
            path.name: source_content_sha256(path)
            for path in (
                Path(__file__).with_name("direct_member_visual.py"),
                Path(__file__).with_name("direct_member_transform.py"),
                Path(__file__).with_name("direct_member_bilateral_transform.py"),
                Path(__file__).with_name("member_bridge_contract.py"),
                Path(__file__).with_name("direct_member_transition.py"),
                Path(__file__).with_name(
                    "direct_member_editorial_motion.py"
                ),
                Path(__file__).with_name(
                    "direct_member_rendered_continuity.py"
                ),
                Path(__file__).with_name(
                    "direct_member_rendered_proxy.py"
                ),
                Path(__file__).with_name(
                    "direct_member_target_face.py"
                ),
                Path(__file__).with_name("direct_member_look.py"),
                Path(__file__).with_name("automatic_joint_dissolve.py"),
                Path(__file__).with_name("member_joint_camera_preflight.py"),
                Path(__file__).with_name("member_camera_search_feedback.py"),
                Path(__file__).with_name("joint_dissolve_registration.py"),
                Path(__file__).with_name("joint_dissolve_pose.py"),
                Path(__file__).with_name("focal_pixel_containment_support.py"),
                Path(__file__).with_name("focal_bracket_containment.py"),
                Path(__file__).with_name("member_dense_containment.py"),
                Path(__file__).with_name("disjoint_member_cameras.py"),
                Path(__file__).with_name("visible_hard_ramp.py"),
                Path(__file__).with_name("rendered_proxy_review.py"),
                Path(__file__).with_name("render.py"),
                Path(__file__).with_name("source_first_focal_geometry.py"),
                Path(__file__).with_name("source_first_model_assets.py"),
                Path(__file__).with_name("source_first_member_session.py"),
                Path(__file__).with_name("source_first_observation_batch.py"),
                Path(__file__).with_name("source_first_anchor_prefilter.py"),
                Path(__file__).with_name("member_boundary_observations.py"),
                Path(__file__).with_name("member_observation_search.py"),
                Path(__file__).with_name("member_cached_observations.py"),
                Path(__file__).with_name("member_path_flow.py"),
                Path(__file__).with_name("member_endpoint_exclusions.py"),
                Path(__file__).with_name("source_first_unresolved_memo.py"),
                Path(__file__).with_name("source_first_execution.py"),
                Path(__file__).with_name("source_first_published_cache.py"),
                Path(__file__).with_name("mps_body_appearance.py"),
                Path(__file__).with_name("focal_selector_geometry.py"),
                Path(__file__).with_name("focal_reference_consensus.py"),
                Path(__file__).with_name("focal_body_track.py"),
                Path(__file__).with_name("focal_body_track_provider.py"),
                Path(__file__).with_name("body_appearance.py"),
                Path(__file__).with_name("body_pose_2d.py"),
                Path(__file__).with_name("native_focal_faces.py"),
                Path(__file__).with_name("rendered_focal_geometry.py"),
                Path(__file__).with_name("rendered_body_reference.py"),
                Path(__file__).with_name("rendered_body_window.py"),
                Path(__file__).with_name("rendered_endpoint_component.py"),
                Path(__file__).with_name("post_render_perceptual_quality.py"),
            )
        }
        from .source_first_focal_geometry import SourceFirstFocalGeometryProvider
        from .source_first_execution import resolve_body_execution_device
        implementation_sha256['source_first_auto_body_device'] = hashlib.sha256(
            resolve_body_execution_device('auto').encode()).hexdigest()
        implementation_sha256["source_first_observation_semantics"] = (
            SourceFirstFocalGeometryProvider.observation_fingerprint()
        )
    except (OSError, ValueError) as exc:
        diagnostics.update(
            {
                "status": "binding_evidence_unavailable",
                "rejection": type(exc).__name__,
            }
        )
        return None, diagnostics
    selector_config = DirectMemberVisualConfig(
        boundary_search_radius_frames=6,
        boundary_search_step_frames=2,
        hold_cadence_basis="duration",
    )
    motion_config = (
        _direct_member_editorial_motion_config_from_visual_config(
            selector_config
        )
    )
    compact_timewarps = (
        [None for _index in eligible]
        if source_timewarps is None
        else [
            (
                source_timewarps[index].to_dict()
                if source_timewarps[index] is not None
                else None
            )
            for index in eligible
        ]
    )
    binding_evidence = {
        "contract": _DIRECT_MEMBER_DENSE_RENDER_FEEDBACK_CONTRACT,
        "feedback_application_policy": (
            "dense_joint_overlap_camera_boundary_pair_diagnostics_proxy_v9"
        ),
        "acquisition_source_identity_sha256": source_identity_sha256,
        "timing_draft": timing_draft.to_dict(),
        "eligible_request_source_indices": list(eligible),
        "source_timewarps": compact_timewarps,
        "scene_cut_times": [
            [float(value) for value in values]
            for values in scene_cut_times
        ],
        "eligible_source_frame_sizes": [
            [int(width), int(height)]
            for width, height in eligible_source_frame_sizes
        ],
        "output_frame_size": [
            int(output_frame_size[0]),
            int(output_frame_size[1]),
        ],
        "output_fps": float(output_fps),
        "highlight_intervals": [
            [float(start), float(end)]
            for start, end in highlight_intervals
        ],
        "member_pose_dissolve_enabled": bool(
            member_pose_dissolve_enabled
        ),
        "terminal_selector_config": selector_config.to_dict(),
        "strict_selector_config": replace(
            selector_config,
            maximum_same_source_hold_count=0,
        ).to_dict(),
        "dense_editorial_motion_config": asdict(motion_config),
        "implementation_sha256": implementation_sha256,
    }
    binding_evidence_sha256 = hashlib.sha256(
        json.dumps(
            binding_evidence,
            ensure_ascii=False,
            allow_nan=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    binding = {
        "contract": _DIRECT_MEMBER_DENSE_RENDER_FEEDBACK_CONTRACT,
        "binding_evidence_sha256": binding_evidence_sha256,
        "acquisition_source_identity_sha256": source_identity_sha256,
        "source_count": len(eligible),
        "range_start_seconds": float(timing_draft.common_master_start),
        "range_end_seconds": float(timing_draft.common_master_end),
    }
    binding_sha256 = hashlib.sha256(
        json.dumps(
            binding,
            ensure_ascii=False,
            allow_nan=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    binding["binding_sha256"] = binding_sha256
    compatible_predecessor_bindings: list[dict[str, Any]] = []
    current_selector_sha256 = implementation_sha256[
        "direct_member_visual.py"
    ]
    for predecessor_selector_sha256 in (
        _DIRECT_MEMBER_DENSE_FEEDBACK_SELECTOR_ONLY_HASH_TRANSITIONS.get(
            current_selector_sha256,
            (),
        )
    ):
        predecessor_implementation_sha256 = {
            **implementation_sha256,
            "direct_member_visual.py": predecessor_selector_sha256,
        }
        predecessor_evidence = {
            **binding_evidence,
            "implementation_sha256": predecessor_implementation_sha256,
        }
        predecessor_evidence_sha256 = hashlib.sha256(
            json.dumps(
                predecessor_evidence,
                ensure_ascii=False,
                allow_nan=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()
        predecessor_binding = {
            "contract": _DIRECT_MEMBER_DENSE_RENDER_FEEDBACK_CONTRACT,
            "binding_evidence_sha256": predecessor_evidence_sha256,
            "acquisition_source_identity_sha256": source_identity_sha256,
            "source_count": len(eligible),
            "range_start_seconds": float(
                timing_draft.common_master_start
            ),
            "range_end_seconds": float(timing_draft.common_master_end),
        }
        predecessor_binding["binding_sha256"] = hashlib.sha256(
            json.dumps(
                predecessor_binding,
                ensure_ascii=False,
                allow_nan=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()
        compatible_predecessor_bindings.append(
            {
                "binding": predecessor_binding,
                "migration_reason": (
                    _DIRECT_MEMBER_DENSE_FEEDBACK_SELECTOR_ONLY_MIGRATION_REASON
                ),
                "predecessor_direct_member_visual_sha256": (
                    predecessor_selector_sha256
                ),
                "current_direct_member_visual_sha256": (
                    current_selector_sha256
                ),
                "edge_measurement_implementation_hashes_unchanged": True,
                "visual_thresholds_relaxed": False,
            }
        )
    diagnostics.update(
        {
            "status": "binding_ready",
            "binding_sha256": binding_sha256,
            "binding_evidence_sha256": binding_evidence_sha256,
            "acquisition_manifest_file_sha256": (
                manifest_fingerprint["sha256"]
            ),
            "acquisition_source_identity_sha256": source_identity_sha256,
            "compatible_predecessor_bindings": (
                compatible_predecessor_bindings
            ),
        }
    )
    return binding, diagnostics


def _load_direct_member_dense_render_feedback_edges(
    feature_cache_directory: Path | None,
    binding: Mapping[str, Any] | None,
    *,
    compatible_predecessor_bindings: Sequence[Mapping[str, Any]] = (),
) -> tuple[tuple[tuple[float, int, int], ...], dict[str, Any]]:
    """Restore only certificates whose complete production binding matches."""

    diagnostics: dict[str, Any] = {
        "contract": _DIRECT_MEMBER_DENSE_RENDER_FEEDBACK_CONTRACT,
        "requested": feature_cache_directory is not None,
        "cache_filename": _DIRECT_MEMBER_DENSE_RENDER_FEEDBACK_FILENAME,
        "loaded_certificate_count": 0,
        "visual_thresholds_relaxed": False,
    }
    if feature_cache_directory is None or binding is None:
        diagnostics["status"] = "binding_unavailable"
        return (), diagnostics
    cache_path = (
        Path(feature_cache_directory)
        / _DIRECT_MEMBER_DENSE_RENDER_FEEDBACK_FILENAME
    )
    if not cache_path.exists():
        diagnostics["status"] = "cache_missing"
        return (), diagnostics
    try:
        encoded, fingerprint = _read_stable_regular_file(cache_path)
    except (OSError, ValueError) as exc:
        diagnostics.update(
            {"status": "cache_rejected", "rejection": type(exc).__name__}
        )
        return (), diagnostics
    if len(encoded) > _DIRECT_MEMBER_DENSE_RENDER_FEEDBACK_MAX_BYTES:
        diagnostics.update(
            {
                "status": "cache_rejected",
                "rejection": "cache_size_limit_exceeded",
            }
        )
        return (), diagnostics
    try:
        payload = json.loads(encoded.decode("utf-8"))
    except (UnicodeError, json.JSONDecodeError):
        diagnostics.update(
            {"status": "cache_rejected", "rejection": "invalid_json"}
        )
        return (), diagnostics
    if not (
        isinstance(payload, dict)
        and payload.get("schema_version") == 1
        and payload.get("contract")
        == _DIRECT_MEMBER_DENSE_RENDER_FEEDBACK_CONTRACT
        and isinstance(payload.get("entries"), list)
        and len(payload["entries"])
        <= _DIRECT_MEMBER_DENSE_RENDER_FEEDBACK_MAX_ENTRY_COUNT
    ):
        diagnostics.update(
            {"status": "cache_rejected", "rejection": "schema_mismatch"}
        )
        return (), diagnostics
    matching_entry = next(
        (
            entry
            for entry in payload["entries"]
            if isinstance(entry, dict)
            and all(entry.get(key) == value for key, value in binding.items())
        ),
        None,
    )
    compatible_predecessor_match: Mapping[str, Any] | None = None
    if matching_entry is None:
        if len(compatible_predecessor_bindings) > 4:
            diagnostics.update(
                {
                    "status": "cache_rejected",
                    "rejection": "compatible_predecessor_limit_exceeded",
                }
            )
            return (), diagnostics
        for candidate in compatible_predecessor_bindings:
            candidate_binding = candidate.get("binding")
            if not isinstance(candidate_binding, Mapping):
                continue
            predecessor_entry = next(
                (
                    entry
                    for entry in payload["entries"]
                    if isinstance(entry, dict)
                    and all(
                        entry.get(key) == value
                        for key, value in candidate_binding.items()
                    )
                ),
                None,
            )
            if predecessor_entry is None:
                continue
            matching_entry = predecessor_entry
            compatible_predecessor_match = candidate
            break
    if matching_entry is None:
        diagnostics.update(
            {
                "status": "no_matching_binding",
                "cache_file_sha256": fingerprint["sha256"],
            }
        )
        return (), diagnostics
    raw_certificates = matching_entry.get("certificates")
    if not (
        isinstance(raw_certificates, list)
        and len(raw_certificates)
        <= _DIRECT_MEMBER_DENSE_RENDER_FEEDBACK_MAX_CERTIFICATE_COUNT
    ):
        diagnostics.update(
            {"status": "cache_rejected", "rejection": "certificate_schema"}
        )
        return (), diagnostics
    raw_edges: list[tuple[float, int, int]] = []
    for certificate in raw_certificates:
        if not isinstance(certificate, dict):
            diagnostics.update(
                {"status": "cache_rejected", "rejection": "certificate_schema"}
            )
            return (), diagnostics
        raw_edges.append(
            (
                certificate.get("canonical_boundary_seconds"),
                certificate.get("outgoing_eligible_source_index"),
                certificate.get("incoming_eligible_source_index"),
            )
        )
    try:
        edges = _normalize_direct_member_dense_render_feedback_edges(
            raw_edges,
            source_count=int(binding["source_count"]),
            range_start=float(binding["range_start_seconds"]),
            range_end=float(binding["range_end_seconds"]),
        )
    except (KeyError, TypeError, ValueError) as exc:
        diagnostics.update(
            {"status": "cache_rejected", "rejection": type(exc).__name__}
        )
        return (), diagnostics
    if len(edges) != len(raw_certificates):
        diagnostics.update(
            {"status": "cache_rejected", "rejection": "duplicate_certificate"}
        )
        return (), diagnostics
    raw_preferred_counts = matching_entry.get(
        "preferred_partition_unit_counts"
    )
    raw_preferred_signature = matching_entry.get(
        "preferred_partition_signature_sha256"
    )
    try:
        preferred_counts = (
            _normalize_direct_member_dense_feedback_partition_unit_counts(
                raw_preferred_counts,
                source_count=int(binding["source_count"]),
            )
        )
        if preferred_counts is None:
            if raw_preferred_signature is not None:
                raise ValueError("partition signature has no counts")
            diagnostics["preferred_partition_status"] = "unavailable"
        elif raw_preferred_signature != _direct_partition_signature_sha256(
            preferred_counts
        ):
            raise ValueError("preferred partition signature mismatch")
        else:
            diagnostics.update(
                {
                    "preferred_partition_status": "loaded",
                    "preferred_partition_unit_counts": list(
                        preferred_counts
                    ),
                    "preferred_partition_signature_sha256": (
                        raw_preferred_signature
                    ),
                }
            )
    except (KeyError, TypeError, ValueError) as exc:
        diagnostics.update(
            {
                "preferred_partition_status": "rejected",
                "preferred_partition_rejection": type(exc).__name__,
            }
        )
    diagnostics.update(
        {
            "status": (
                "certificates_loaded_via_selector_only_migration"
                if compatible_predecessor_match is not None
                else "certificates_loaded"
            ),
            "cache_file_sha256": fingerprint["sha256"],
            "loaded_certificate_count": len(edges),
        }
    )
    if compatible_predecessor_match is not None:
        predecessor_binding = compatible_predecessor_match["binding"]
        diagnostics.update(
            {
                "migrated_from_binding_sha256": (
                    predecessor_binding.get("binding_sha256")
                ),
                "migrated_to_binding_sha256": binding.get(
                    "binding_sha256"
                ),
                "binding_migration_reason": (
                    compatible_predecessor_match.get(
                        "migration_reason"
                    )
                ),
                "edge_measurement_implementation_hashes_unchanged": (
                    compatible_predecessor_match.get(
                        "edge_measurement_implementation_hashes_unchanged"
                    )
                    is True
                ),
                "full_selector_recheck_required": True,
                "certified_edges_remain_forbidden": True,
            }
        )
    return edges, diagnostics


def _normalize_direct_member_dense_feedback_partition_unit_counts(
    raw_counts: Sequence[int] | None,
    *,
    source_count: int,
) -> tuple[int, ...] | None:
    """Validate an exact selected partition stored with render certificates."""

    if raw_counts is None:
        return None
    if (
        isinstance(source_count, bool)
        or not isinstance(source_count, int)
        or source_count < 2
        or not isinstance(raw_counts, (list, tuple))
        or len(raw_counts) < source_count
        or any(
            isinstance(value, bool)
            or not isinstance(value, int)
            or value <= 0
            for value in raw_counts
        )
    ):
        raise ValueError("dense-render preferred partition is invalid")
    return tuple(raw_counts)


def _persist_direct_member_dense_render_feedback_edges(
    feature_cache_directory: Path | None,
    binding: Mapping[str, Any] | None,
    edges: Sequence[tuple[float, int, int]],
    *,
    preferred_partition_unit_counts: Sequence[int] | None = None,
) -> dict[str, Any]:
    """Atomically checkpoint accumulated dense-render failure certificates."""

    diagnostics: dict[str, Any] = {
        "contract": _DIRECT_MEMBER_DENSE_RENDER_FEEDBACK_CONTRACT,
        "persisted": False,
        "visual_thresholds_relaxed": False,
    }
    if feature_cache_directory is None or binding is None:
        diagnostics["status"] = "binding_unavailable"
        return diagnostics
    try:
        normalized = _normalize_direct_member_dense_render_feedback_edges(
            edges,
            source_count=int(binding["source_count"]),
            range_start=float(binding["range_start_seconds"]),
            range_end=float(binding["range_end_seconds"]),
        )
        normalized_preferred_counts = (
            _normalize_direct_member_dense_feedback_partition_unit_counts(
                preferred_partition_unit_counts,
                source_count=int(binding["source_count"]),
            )
        )
    except (KeyError, TypeError, ValueError) as exc:
        diagnostics.update(
            {"status": "input_rejected", "rejection": type(exc).__name__}
        )
        return diagnostics
    cache_path = (
        Path(feature_cache_directory)
        / _DIRECT_MEMBER_DENSE_RENDER_FEEDBACK_FILENAME
    )
    entries: list[dict[str, Any]] = []
    existing_cache_replaced = False
    if cache_path.exists():
        try:
            encoded, _fingerprint = _read_stable_regular_file(cache_path)
            existing = json.loads(encoded.decode("utf-8"))
            if not (
                len(encoded)
                <= _DIRECT_MEMBER_DENSE_RENDER_FEEDBACK_MAX_BYTES
                and isinstance(existing, dict)
                and existing.get("schema_version") == 1
                and existing.get("contract")
                == _DIRECT_MEMBER_DENSE_RENDER_FEEDBACK_CONTRACT
                and isinstance(existing.get("entries"), list)
                and len(existing["entries"])
                <= _DIRECT_MEMBER_DENSE_RENDER_FEEDBACK_MAX_ENTRY_COUNT
            ):
                raise ValueError("dense-render feedback cache schema mismatch")
            entries = [
                item for item in existing["entries"] if isinstance(item, dict)
            ]
        except (
            OSError,
            ValueError,
            UnicodeError,
            json.JSONDecodeError,
        ):
            entries = []
            existing_cache_replaced = True
    previous_matching = next(
        (
            item
            for item in entries
            if all(item.get(key) == value for key, value in binding.items())
        ),
        None,
    )
    if isinstance(previous_matching, dict):
        raw_previous = previous_matching.get("certificates")
        if isinstance(raw_previous, list):
            previous_edges = [
                (
                    item.get("canonical_boundary_seconds"),
                    item.get("outgoing_eligible_source_index"),
                    item.get("incoming_eligible_source_index"),
                )
                for item in raw_previous
                if isinstance(item, dict)
            ]
            try:
                normalized = (
                    _normalize_direct_member_dense_render_feedback_edges(
                        (*previous_edges, *normalized),
                        source_count=int(binding["source_count"]),
                        range_start=float(binding["range_start_seconds"]),
                        range_end=float(binding["range_end_seconds"]),
                    )
                )
            except (KeyError, TypeError, ValueError):
                existing_cache_replaced = True
        if normalized_preferred_counts is None:
            try:
                previous_counts = (
                    _normalize_direct_member_dense_feedback_partition_unit_counts(
                        previous_matching.get(
                            "preferred_partition_unit_counts"
                        ),
                        source_count=int(binding["source_count"]),
                    )
                )
                previous_signature = previous_matching.get(
                    "preferred_partition_signature_sha256"
                )
                if previous_counts is not None and previous_signature == (
                    _direct_partition_signature_sha256(previous_counts)
                ):
                    normalized_preferred_counts = previous_counts
            except (KeyError, TypeError, ValueError):
                existing_cache_replaced = True
    entries = [
        item
        for item in entries
        if not all(item.get(key) == value for key, value in binding.items())
    ]
    new_entry = {
        **binding,
        "certificate_count": len(normalized),
        "certificates": [
            {
                "canonical_boundary_seconds": boundary_seconds,
                "outgoing_eligible_source_index": outgoing_source_index,
                "incoming_eligible_source_index": incoming_source_index,
                "origin": (
                    "failed_dense_camera_solve"
                ),
                "visual_thresholds_relaxed": False,
            }
            for (
                boundary_seconds,
                outgoing_source_index,
                incoming_source_index,
            ) in normalized
        ],
    }
    if normalized_preferred_counts is not None:
        new_entry.update(
            {
                "preferred_partition_unit_counts": list(
                    normalized_preferred_counts
                ),
                "preferred_partition_signature_sha256": (
                    _direct_partition_signature_sha256(
                        normalized_preferred_counts
                    )
                ),
            }
        )
    entries.insert(0, new_entry)
    payload = {
        "schema_version": 1,
        "contract": _DIRECT_MEMBER_DENSE_RENDER_FEEDBACK_CONTRACT,
        "entries": entries[
            :_DIRECT_MEMBER_DENSE_RENDER_FEEDBACK_MAX_ENTRY_COUNT
        ],
    }
    try:
        _write_analysis_manifest_atomically(cache_path, payload)
        _persisted, fingerprint = _read_stable_regular_file(cache_path)
    except (OSError, ValueError) as exc:
        diagnostics.update(
            {"status": "persistence_failed", "rejection": type(exc).__name__}
        )
        return diagnostics
    diagnostics.update(
        {
            "status": "persisted",
            "persisted": True,
            "certificate_count": len(normalized),
            "cache_file_sha256": fingerprint["sha256"],
            "existing_cache_replaced": existing_cache_replaced,
            "preferred_partition_persisted": (
                normalized_preferred_counts is not None
            ),
            "preferred_partition_signature_sha256": (
                _direct_partition_signature_sha256(
                    normalized_preferred_counts
                )
                if normalized_preferred_counts is not None
                else None
            ),
        }
    )
    return diagnostics


def _load_direct_member_proxy_feedback_penalties(
    feature_cache_directory: Path | None,
    binding: Mapping[str, Any] | None,
) -> tuple[tuple[tuple[float, int, int, float], ...], dict[str, Any]]:
    """Restore only finite decoded-proxy preferences for an exact binding."""

    diagnostics: dict[str, Any] = {
        "contract": _DIRECT_MEMBER_PROXY_FEEDBACK_CONTRACT,
        "requested": feature_cache_directory is not None,
        "cache_filename": _DIRECT_MEMBER_PROXY_FEEDBACK_FILENAME,
        "loaded_penalty_count": 0,
        "loaded_rejected_path_count": 0,
        "rejected_source_paths_by_partition_unit_counts": [],
        "hard_exclusions_added": False,
        "visual_thresholds_relaxed": False,
    }
    if feature_cache_directory is None or binding is None:
        diagnostics["status"] = "binding_unavailable"
        return (), diagnostics
    cache_path = (
        Path(feature_cache_directory)
        / _DIRECT_MEMBER_PROXY_FEEDBACK_FILENAME
    )
    if not cache_path.exists():
        diagnostics["status"] = "cache_missing"
        return (), diagnostics
    try:
        encoded, fingerprint = _read_stable_regular_file(cache_path)
        if len(encoded) > _DIRECT_MEMBER_PROXY_FEEDBACK_MAX_BYTES:
            raise ValueError("decoded-proxy feedback cache is too large")
        payload = json.loads(encoded.decode("utf-8"))
    except (OSError, ValueError, UnicodeError, json.JSONDecodeError) as exc:
        diagnostics.update(
            {"status": "cache_rejected", "rejection": type(exc).__name__}
        )
        return (), diagnostics
    if not (
        isinstance(payload, dict)
        and payload.get("schema_version") == 1
        and payload.get("contract")
        == _DIRECT_MEMBER_PROXY_FEEDBACK_CONTRACT
        and isinstance(payload.get("entries"), list)
        and len(payload["entries"])
        <= _DIRECT_MEMBER_PROXY_FEEDBACK_MAX_ENTRY_COUNT
    ):
        diagnostics.update(
            {"status": "cache_rejected", "rejection": "schema_mismatch"}
        )
        return (), diagnostics
    matching_entry = next(
        (
            entry
            for entry in payload["entries"]
            if isinstance(entry, dict)
            and all(entry.get(key) == value for key, value in binding.items())
        ),
        None,
    )
    if matching_entry is None:
        diagnostics.update(
            {
                "status": "no_matching_binding",
                "cache_file_sha256": fingerprint["sha256"],
            }
        )
        return (), diagnostics
    raw_penalties = matching_entry.get("penalties")
    if not (
        isinstance(raw_penalties, list)
        and len(raw_penalties)
        <= _DIRECT_MEMBER_PROXY_FEEDBACK_MAX_PENALTY_COUNT
    ):
        diagnostics.update(
            {"status": "cache_rejected", "rejection": "penalty_schema"}
        )
        return (), diagnostics
    raw_rejected_paths = matching_entry.get("rejected_paths", [])
    if not (
        isinstance(raw_rejected_paths, list)
        and len(raw_rejected_paths)
        <= _DIRECT_MEMBER_PROXY_FEEDBACK_MAX_REJECTED_PATH_COUNT
    ):
        diagnostics.update(
            {"status": "cache_rejected", "rejection": "rejected_path_schema"}
        )
        return (), diagnostics
    raw_edges: list[tuple[float, int, int, float]] = []
    for item in raw_penalties:
        if not isinstance(item, dict):
            diagnostics.update(
                {"status": "cache_rejected", "rejection": "penalty_schema"}
            )
            return (), diagnostics
        raw_edges.append(
            (
                item.get("canonical_boundary_seconds"),
                item.get("outgoing_eligible_source_index"),
                item.get("incoming_eligible_source_index"),
                item.get("accumulated_penalty"),
            )
        )
    try:
        penalties = _normalize_direct_member_proxy_feedback_penalties(
            raw_edges,
            source_count=int(binding["source_count"]),
            range_start=float(binding["range_start_seconds"]),
            range_end=float(binding["range_end_seconds"]),
        )
        rejected_paths_mapping: dict[
            tuple[int, ...], list[tuple[int, ...]]
        ] = {}
        for item in raw_rejected_paths:
            if not isinstance(item, dict):
                raise ValueError("decoded-proxy rejected path schema mismatch")
            unit_counts = tuple(item.get("partition_unit_counts", ()))
            source_indices = tuple(item.get("source_indices", ()))
            rejected_paths_mapping.setdefault(unit_counts, []).append(
                source_indices
            )
        rejected_paths = _normalize_direct_member_proxy_rejected_paths(
            rejected_paths_mapping,
            source_count=int(binding["source_count"]),
        )
    except (KeyError, TypeError, ValueError) as exc:
        diagnostics.update(
            {"status": "cache_rejected", "rejection": type(exc).__name__}
        )
        return (), diagnostics
    diagnostics.update(
        {
            "status": "penalties_loaded",
            "cache_file_sha256": fingerprint["sha256"],
            "loaded_penalty_count": len(penalties),
            "loaded_total_penalty": sum(item[3] for item in penalties),
            "loaded_rejected_path_count": len(rejected_paths),
            "rejected_source_paths_by_partition_unit_counts": [
                {
                    "partition_unit_counts": list(unit_counts),
                    "source_indices": list(source_indices),
                }
                for unit_counts, source_indices in rejected_paths
            ],
        }
    )
    return penalties, diagnostics


def _persist_direct_member_proxy_feedback_penalties(
    feature_cache_directory: Path | None,
    binding: Mapping[str, Any] | None,
    penalties: Sequence[tuple[float, int, int, float]],
    *,
    rejected_source_paths_by_partition_unit_counts: Mapping[
        Sequence[int], Sequence[Sequence[int]]
    ] | None = None,
) -> dict[str, Any]:
    """Persist finite edge costs and exact whole-path no-good constraints."""

    diagnostics: dict[str, Any] = {
        "contract": _DIRECT_MEMBER_PROXY_FEEDBACK_CONTRACT,
        "persisted": False,
        "hard_exclusions_added": False,
        "visual_thresholds_relaxed": False,
    }
    if feature_cache_directory is None or binding is None:
        diagnostics["status"] = "binding_unavailable"
        return diagnostics
    try:
        normalized = _normalize_direct_member_proxy_feedback_penalties(
            penalties,
            source_count=int(binding["source_count"]),
            range_start=float(binding["range_start_seconds"]),
            range_end=float(binding["range_end_seconds"]),
        )
        normalized_rejected_paths = (
            _normalize_direct_member_proxy_rejected_paths(
                rejected_source_paths_by_partition_unit_counts or {},
                source_count=int(binding["source_count"]),
            )
        )
    except (KeyError, TypeError, ValueError) as exc:
        diagnostics.update(
            {"status": "input_rejected", "rejection": type(exc).__name__}
        )
        return diagnostics
    cache_path = (
        Path(feature_cache_directory)
        / _DIRECT_MEMBER_PROXY_FEEDBACK_FILENAME
    )
    entries: list[dict[str, Any]] = []
    existing_cache_replaced = False
    if cache_path.exists():
        try:
            encoded, _fingerprint = _read_stable_regular_file(cache_path)
            existing = json.loads(encoded.decode("utf-8"))
            if not (
                len(encoded) <= _DIRECT_MEMBER_PROXY_FEEDBACK_MAX_BYTES
                and isinstance(existing, dict)
                and existing.get("schema_version") == 1
                and existing.get("contract")
                == _DIRECT_MEMBER_PROXY_FEEDBACK_CONTRACT
                and isinstance(existing.get("entries"), list)
                and len(existing["entries"])
                <= _DIRECT_MEMBER_PROXY_FEEDBACK_MAX_ENTRY_COUNT
            ):
                raise ValueError("decoded-proxy feedback cache schema mismatch")
            entries = [
                item for item in existing["entries"] if isinstance(item, dict)
            ]
        except (
            OSError,
            ValueError,
            UnicodeError,
            json.JSONDecodeError,
        ):
            entries = []
            existing_cache_replaced = True
    entries = [
        item
        for item in entries
        if not all(item.get(key) == value for key, value in binding.items())
    ]
    entries.insert(
        0,
        {
            **binding,
            "penalty_count": len(normalized),
            "total_penalty": sum(item[3] for item in normalized),
            "rejected_path_count": len(normalized_rejected_paths),
            "rejected_paths": [
                {
                    "partition_unit_counts": list(unit_counts),
                    "source_indices": list(source_indices),
                    "origin": "decoded_output_candidate_rejected",
                    "scope": "complete_path_only",
                    "individual_edges_hard_excluded": False,
                    "visual_thresholds_relaxed": False,
                }
                for unit_counts, source_indices in normalized_rejected_paths
            ],
            "penalties": [
                {
                    "canonical_boundary_seconds": boundary_seconds,
                    "outgoing_eligible_source_index": outgoing_source_index,
                    "incoming_eligible_source_index": incoming_source_index,
                    "accumulated_penalty": penalty,
                    "origin": "decoded_output_continuity_quality_feedback",
                    "hard_exclusion": False,
                    "visual_thresholds_relaxed": False,
                }
                for (
                    boundary_seconds,
                    outgoing_source_index,
                    incoming_source_index,
                    penalty,
                ) in normalized
            ],
        },
    )
    payload = {
        "schema_version": 1,
        "contract": _DIRECT_MEMBER_PROXY_FEEDBACK_CONTRACT,
        "entries": entries[:_DIRECT_MEMBER_PROXY_FEEDBACK_MAX_ENTRY_COUNT],
    }
    try:
        _write_analysis_manifest_atomically(cache_path, payload)
        _persisted, fingerprint = _read_stable_regular_file(cache_path)
    except (OSError, ValueError) as exc:
        diagnostics.update(
            {"status": "persistence_failed", "rejection": type(exc).__name__}
        )
        return diagnostics
    diagnostics.update(
        {
            "status": "persisted",
            "persisted": True,
            "penalty_count": len(normalized),
            "total_penalty": sum(item[3] for item in normalized),
            "rejected_path_count": len(normalized_rejected_paths),
            "cache_file_sha256": fingerprint["sha256"],
            "existing_cache_replaced": existing_cache_replaced,
        }
    )
    return diagnostics


def _direct_member_partition_warm_start_binding(
    feature_cache_directory: Path | None,
    base: _DirectFullFramePartitionProfile,
    *,
    source_count: int,
) -> tuple[dict[str, Any] | None, dict[str, Any]]:
    """Bind reusable cadence candidates to one exact acquired source set.

    A cached cadence is never a visual-selection result.  It only decides
    which existing musical partition receives an early, complete selector
    audition.  Binding it to the acquisition manifest and base partition
    avoids wasting that audition after sources or timing have changed.
    """

    diagnostics: dict[str, Any] = {
        "contract": _DIRECT_MEMBER_PARTITION_WARM_START_CONTRACT,
        "requested": feature_cache_directory is not None,
        "cache_filename": _DIRECT_MEMBER_PARTITION_WARM_START_FILENAME,
        "full_selector_recheck_required": True,
        "visual_gates_relaxed": False,
    }
    if feature_cache_directory is None:
        diagnostics["status"] = "feature_cache_unavailable"
        return None, diagnostics
    if isinstance(source_count, bool) or source_count <= 0:
        raise ValueError("direct member warm-start source count must be positive")
    manifest_path = Path(feature_cache_directory) / "acquisition-manifest.json"
    try:
        manifest_bytes, manifest_fingerprint = _read_stable_regular_file(
            manifest_path
        )
        source_identity_sha256 = (
            _direct_member_stable_acquisition_source_identity_sha256(
                manifest_bytes,
                source_count=source_count,
            )
        )
    except (OSError, ValueError) as exc:
        diagnostics.update(
            {
                "status": "acquisition_manifest_unavailable",
                "rejection": type(exc).__name__,
            }
        )
        return None, diagnostics
    binding_payload = {
        "contract": _DIRECT_MEMBER_PARTITION_WARM_START_CONTRACT,
        "acquisition_source_identity_sha256": source_identity_sha256,
        "base_partition_signature_sha256": (
            _direct_partition_signature_sha256(base.unit_counts)
        ),
        "timing_segment_count": sum(base.unit_counts),
        "source_count": int(source_count),
    }
    binding_sha256 = hashlib.sha256(
        json.dumps(
            binding_payload,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    binding = {**binding_payload, "binding_sha256": binding_sha256}
    diagnostics.update(
        {
            "status": "binding_ready",
            "acquisition_manifest_file_sha256": manifest_fingerprint["sha256"],
            "acquisition_source_identity_sha256": source_identity_sha256,
            "base_partition_signature_sha256": (
                binding_payload["base_partition_signature_sha256"]
            ),
            "binding_sha256": binding_sha256,
        }
    )
    return binding, diagnostics


def _direct_member_partition_failure_frontier_apply_operation(
    parent_unit_counts: Sequence[int],
    kind: str,
    operation: Any,
) -> tuple[int, ...] | None:
    """Replay one exact proof operation against its signed parent partition."""

    counts = tuple(int(value) for value in parent_unit_counts)
    if (
        not counts
        or any(value <= 0 for value in counts)
        or operation.parent_partition_signature_sha256
        != _direct_partition_signature_sha256(counts)
    ):
        return None
    output = list(counts)
    if kind == "boundary_shift" and isinstance(
        operation,
        _DirectFullFrameBoundaryShift,
    ):
        boundary_index = operation.boundary_index
        if not 0 <= boundary_index < len(counts) - 1:
            return None
        old_left, old_right = counts[boundary_index : boundary_index + 2]
        if not (
            operation.left_unit_count > 0
            and operation.right_unit_count > 0
            and operation.left_unit_count + operation.right_unit_count
            == old_left + old_right
            and operation.left_unit_count - old_left
            == operation.shift_units
            and operation.right_unit_count - old_right
            == -operation.shift_units
        ):
            return None
        output[boundary_index : boundary_index + 2] = [
            operation.left_unit_count,
            operation.right_unit_count,
        ]
    elif kind == "visual_frontier_split" and isinstance(
        operation,
        _DirectFullFrameVisualFrontierSplit,
    ):
        span_index = operation.parent_span_index
        if not 0 <= span_index < len(counts):
            return None
        if not (
            operation.left_unit_count > 0
            and operation.right_unit_count > 0
            and operation.split_unit_offset == operation.left_unit_count
            and operation.left_unit_count + operation.right_unit_count
            == counts[span_index]
        ):
            return None
        output[span_index : span_index + 1] = [
            operation.left_unit_count,
            operation.right_unit_count,
        ]
    else:
        return None
    return tuple(output)


def _direct_member_partition_failure_frontier_reverse_operation(
    child_unit_counts: Sequence[int],
    kind: str,
    operation: Any,
) -> tuple[int, ...] | None:
    """Reverse one operation and verify its recorded parent signature."""

    counts = tuple(int(value) for value in child_unit_counts)
    if not counts or any(value <= 0 for value in counts):
        return None
    parent = list(counts)
    if kind == "boundary_shift" and isinstance(
        operation,
        _DirectFullFrameBoundaryShift,
    ):
        boundary_index = operation.boundary_index
        if not 0 <= boundary_index < len(counts) - 1:
            return None
        if counts[boundary_index : boundary_index + 2] != (
            operation.left_unit_count,
            operation.right_unit_count,
        ):
            return None
        old_left = operation.left_unit_count - operation.shift_units
        old_right = operation.right_unit_count + operation.shift_units
        if old_left <= 0 or old_right <= 0:
            return None
        parent[boundary_index : boundary_index + 2] = [
            old_left,
            old_right,
        ]
    elif kind == "visual_frontier_split" and isinstance(
        operation,
        _DirectFullFrameVisualFrontierSplit,
    ):
        span_index = operation.parent_span_index
        if not 0 <= span_index < len(counts) - 1:
            return None
        if counts[span_index : span_index + 2] != (
            operation.left_unit_count,
            operation.right_unit_count,
        ):
            return None
        parent[span_index : span_index + 2] = [
            operation.left_unit_count + operation.right_unit_count
        ]
    else:
        return None
    result = tuple(parent)
    if (
        operation.parent_partition_signature_sha256
        != _direct_partition_signature_sha256(result)
    ):
        return None
    return result


def _direct_member_partition_failure_frontier_operation_sequence(
    profile: _DirectFullFramePartitionProfile,
) -> tuple[tuple[int, ...], tuple[tuple[str, Any], ...]] | None:
    """Recover a unique chronological lineage and its input-bound root."""

    if (
        profile.window_redistributions
        or profile.boundary_merges
        or not (profile.boundary_shifts or profile.visual_frontier_splits)
    ):
        return None
    remaining: list[tuple[str, Any]] = [
        *(("boundary_shift", item) for item in profile.boundary_shifts),
        *(
            ("visual_frontier_split", item)
            for item in profile.visual_frontier_splits
        ),
    ]
    current = profile.unit_counts
    reverse_ordered: list[tuple[str, Any]] = []
    while remaining:
        matches: list[tuple[int, str, Any, tuple[int, ...]]] = []
        for index, (kind, operation) in enumerate(remaining):
            parent = _direct_member_partition_failure_frontier_reverse_operation(
                current,
                kind,
                operation,
            )
            if parent is not None:
                matches.append((index, kind, operation, parent))
        if len(matches) != 1:
            return None
        index, kind, operation, current = matches[0]
        reverse_ordered.append((kind, operation))
        remaining.pop(index)
    ordered = tuple(reversed(reverse_ordered))
    if (
        profile.latest_operation_kind is None
        or profile.latest_operation_kind != ordered[-1][0]
    ):
        return None
    return current, ordered


def _direct_member_partition_failure_frontier_lineage(
    profile: _DirectFullFramePartitionProfile,
) -> dict[str, Any] | None:
    """Serialize a lossless, replayable proof-shift/visual-split frontier."""

    operations = _direct_member_partition_failure_frontier_operation_sequence(
        profile,
    )
    if operations is None:
        return None
    root_unit_counts, ordered_operations = operations
    return {
        "contract": (
            _DIRECT_MEMBER_PARTITION_FAILURE_FRONTIER_LINEAGE_CONTRACT
        ),
        "latest_operation_kind": ordered_operations[-1][0],
        "lineage_root_partition_unit_counts": list(root_unit_counts),
        "proof_operation_sequence": [
            {"kind": kind, "operation": operation.to_dict()}
            for kind, operation in ordered_operations
        ],
    }


def _restore_direct_member_partition_failure_frontier_lineage(
    entry: Mapping[str, Any],
    *,
    base_unit_counts: Sequence[int],
    expected_unit_counts: Sequence[int],
) -> tuple[
    tuple[_DirectFullFrameBoundaryShift, ...],
    tuple[_DirectFullFrameVisualFrontierSplit, ...],
    str | None,
]:
    """Restore and replay an exact input-bound proof frontier lineage."""

    raw_lineage = entry.get("search_lineage")
    is_frontier = (
        entry.get("origin")
        == _DIRECT_MEMBER_PARTITION_FAILURE_FRONTIER_ORIGIN
    )
    if raw_lineage is None:
        if is_frontier:
            raise ValueError("failure frontier cache entry lost its lineage")
        return (), (), None
    if not isinstance(raw_lineage, dict):
        raise ValueError("failure frontier lineage schema mismatch")

    def _integer(value: Any, *, minimum: int | None = None) -> int:
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError("failure frontier lineage integer is invalid")
        if minimum is not None and value < minimum:
            raise ValueError("failure frontier lineage integer is too small")
        return value

    def _finite(value: Any) -> float:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError("failure frontier lineage number is invalid")
        result = float(value)
        if not math.isfinite(result):
            raise ValueError("failure frontier lineage number is not finite")
        return result

    def _string(value: Any, *, optional: bool = False) -> str | None:
        if optional and value is None:
            return None
        if not isinstance(value, str) or not value:
            raise ValueError("failure frontier lineage string is invalid")
        return value

    def _integer_tuple(value: Any) -> tuple[int, ...]:
        if not isinstance(value, list):
            raise ValueError("failure frontier lineage integer list is invalid")
        return tuple(_integer(item, minimum=0) for item in value)

    def _string_tuple(value: Any) -> tuple[str, ...]:
        if not (
            isinstance(value, list)
            and all(isinstance(item, str) and item for item in value)
        ):
            raise ValueError("failure frontier lineage string list is invalid")
        return tuple(value)

    def _digest(value: Any) -> str:
        digest = _string(value)
        assert digest is not None
        if len(digest) != 64 or any(
            character not in "0123456789abcdef" for character in digest
        ):
            raise ValueError("failure frontier parent signature is invalid")
        return digest

    def _restore_shift(raw_shift: Any) -> _DirectFullFrameBoundaryShift:
        if not isinstance(raw_shift, dict):
            raise ValueError("failure frontier shift is not an object")
        replacement = raw_shift.get("replacement_unit_counts")
        proof = raw_shift.get("proof")
        if not (
            isinstance(replacement, list)
            and len(replacement) == 2
            and isinstance(proof, dict)
            and proof.get("constraint_infeasibility_proven") is True
        ):
            raise ValueError("failure frontier shift schema mismatch")
        parent_signature = _digest(
            raw_shift.get("parent_partition_signature_sha256")
        )
        proof_failure = _string(proof.get("failure"), optional=True)
        proof_failed_segment_index = proof.get("failed_segment_index")
        if proof_failed_segment_index is not None:
            proof_failed_segment_index = _integer(
                proof_failed_segment_index,
                minimum=0,
            )
        local_edge_count = proof.get(
            "local_nonsevere_cross_source_edge_count"
        )
        if local_edge_count is not None:
            local_edge_count = _integer(local_edge_count, minimum=0)
        left_count = _integer(replacement[0], minimum=1)
        right_count = _integer(replacement[1], minimum=1)
        operation = _DirectFullFrameBoundaryShift(
            boundary_index=_integer(
                raw_shift.get("boundary_index"), minimum=0
            ),
            shift_units=_integer(raw_shift.get("shift_units")),
            left_unit_count=left_count,
            right_unit_count=right_count,
            canonical_master_seconds=_finite(
                raw_shift.get("canonical_master_seconds")
            ),
            boundary_reasons=_string_tuple(
                raw_shift.get("boundary_reasons")
            ),
            trigger=str(_string(raw_shift.get("trigger"))),
            parent_profile_id=str(
                _string(raw_shift.get("parent_profile_id"))
            ),
            parent_partition_signature_sha256=parent_signature,
            proof_failure=proof_failure,
            proof_failed_segment_index=proof_failed_segment_index,
            proof_forward_reachable_left_source_indices=_integer_tuple(
                proof.get("forward_reachable_left_source_indices")
            ),
            proof_left_valid_source_indices=_integer_tuple(
                proof.get("left_valid_source_indices")
            ),
            proof_right_valid_source_indices=_integer_tuple(
                proof.get("right_valid_source_indices")
            ),
            proof_local_nonsevere_edge_count=local_edge_count,
        )
        if operation.shift_units == 0 or operation.to_dict() != raw_shift:
            raise ValueError("failure frontier shift canonical form mismatch")
        return operation

    def _restore_split(raw_split: Any) -> _DirectFullFrameVisualFrontierSplit:
        if not isinstance(raw_split, dict):
            raise ValueError("failure frontier visual split is not an object")
        replacement = raw_split.get("replacement_unit_counts")
        proof = raw_split.get("proof")
        evidence = raw_split.get("proposal_evidence")
        if not (
            isinstance(replacement, list)
            and len(replacement) == 2
            and isinstance(proof, dict)
            and proof.get("constraint_infeasibility_proven") is True
            and isinstance(evidence, dict)
            and evidence.get("proposal_only_full_selector_recheck_required")
            is True
        ):
            raise ValueError("failure frontier visual split schema mismatch")
        proof_failure = _string(proof.get("failure"), optional=True)
        proof_failed_segment_index = proof.get("failed_segment_index")
        if proof_failed_segment_index is not None:
            proof_failed_segment_index = _integer(
                proof_failed_segment_index,
                minimum=0,
            )
        evidence_master_seconds_raw = evidence.get("master_seconds")
        if not isinstance(evidence_master_seconds_raw, list):
            raise ValueError("failure frontier evidence times are invalid")
        evidence_master_seconds = tuple(
            _finite(value) for value in evidence_master_seconds_raw
        )
        evidence_bracket_raw = evidence.get("bracket_master_seconds")
        evidence_bracket: tuple[float, float] | None
        if evidence_bracket_raw is None:
            evidence_bracket = None
        elif isinstance(evidence_bracket_raw, list) and len(
            evidence_bracket_raw
        ) == 2:
            evidence_bracket = (
                _finite(evidence_bracket_raw[0]),
                _finite(evidence_bracket_raw[1]),
            )
            if evidence_bracket[0] > evidence_bracket[1]:
                raise ValueError("failure frontier evidence bracket is invalid")
        else:
            raise ValueError("failure frontier evidence bracket is invalid")
        left_count = _integer(replacement[0], minimum=1)
        right_count = _integer(replacement[1], minimum=1)
        operation = _DirectFullFrameVisualFrontierSplit(
            parent_span_index=_integer(
                raw_split.get("parent_span_index"),
                minimum=0,
            ),
            split_unit_offset=_integer(
                raw_split.get("split_unit_offset"),
                minimum=1,
            ),
            left_unit_count=left_count,
            right_unit_count=right_count,
            canonical_master_seconds=_finite(
                raw_split.get("canonical_master_seconds")
            ),
            boundary_reasons=_string_tuple(
                raw_split.get("boundary_reasons")
            ),
            trigger=str(_string(raw_split.get("trigger"))),
            parent_profile_id=str(
                _string(raw_split.get("parent_profile_id"))
            ),
            parent_partition_signature_sha256=_digest(
                raw_split.get("parent_partition_signature_sha256")
            ),
            proof_failure=proof_failure,
            proof_failed_segment_index=proof_failed_segment_index,
            proof_frontier_boundary_index=_integer(
                proof.get("frontier_boundary_index"),
                minimum=0,
            ),
            proof_forward_reachable_left_source_indices=_integer_tuple(
                proof.get("forward_reachable_left_source_indices")
            ),
            proof_right_valid_source_indices=_integer_tuple(
                proof.get("right_valid_source_indices")
            ),
            evidence_contract=str(_string(evidence.get("contract"))),
            evidence_kind=str(_string(evidence.get("kind"))),
            evidence_source_indices=_integer_tuple(
                evidence.get("eligible_source_indices")
            ),
            evidence_master_seconds=evidence_master_seconds,
            evidence_bracket_master_seconds=evidence_bracket,
        )
        if operation.to_dict() != raw_split:
            raise ValueError(
                "failure frontier visual split canonical form mismatch"
            )
        return operation

    contract = raw_lineage.get("contract")
    sequence: list[tuple[str, Any]] = []
    root_unit_counts: tuple[int, ...] | None = None
    if contract == _DIRECT_MEMBER_PARTITION_FAILURE_FRONTIER_LINEAGE_V1_CONTRACT:
        if not (
            set(raw_lineage)
            == {
                "contract",
                "latest_operation_kind",
                "proof_directed_boundary_shifts",
            }
            and raw_lineage.get("latest_operation_kind") == "boundary_shift"
            and isinstance(
                raw_lineage.get("proof_directed_boundary_shifts"), list
            )
            and 1
            <= len(raw_lineage["proof_directed_boundary_shifts"])
            <= (
                _DIRECT_MEMBER_PARTITION_FAILURE_FRONTIER_MAX_BOUNDARY_SHIFT_COUNT
            )
        ):
            raise ValueError("failure frontier lineage schema mismatch")
        sequence.extend(
            ("boundary_shift", _restore_shift(raw_shift))
            for raw_shift in raw_lineage["proof_directed_boundary_shifts"]
        )
    elif contract == _DIRECT_MEMBER_PARTITION_FAILURE_FRONTIER_LINEAGE_CONTRACT:
        raw_sequence = raw_lineage.get("proof_operation_sequence")
        if not (
            set(raw_lineage)
            == {
                "contract",
                "latest_operation_kind",
                "lineage_root_partition_unit_counts",
                "proof_operation_sequence",
            }
            and raw_lineage.get("latest_operation_kind")
            in {"boundary_shift", "visual_frontier_split"}
            and isinstance(raw_sequence, list)
            and 1
            <= len(raw_sequence)
            <= (
                _DIRECT_MEMBER_PARTITION_FAILURE_FRONTIER_MAX_BOUNDARY_SHIFT_COUNT
                + _DIRECT_MEMBER_MAX_VISUAL_FRONTIER_SPLITS_PER_PROFILE
            )
        ):
            raise ValueError("failure frontier lineage schema mismatch")
        raw_root_counts = raw_lineage[
            "lineage_root_partition_unit_counts"
        ]
        if not (
            isinstance(raw_root_counts, list)
            and raw_root_counts
            and all(
                isinstance(value, int)
                and not isinstance(value, bool)
                and value > 0
                for value in raw_root_counts
            )
        ):
            raise ValueError("failure frontier lineage root is invalid")
        root_unit_counts = tuple(raw_root_counts)
        for raw_item in raw_sequence:
            if not (
                isinstance(raw_item, dict)
                and set(raw_item) == {"kind", "operation"}
                and raw_item.get("kind")
                in {"boundary_shift", "visual_frontier_split"}
            ):
                raise ValueError("failure frontier operation schema mismatch")
            kind = raw_item["kind"]
            operation = (
                _restore_shift(raw_item["operation"])
                if kind == "boundary_shift"
                else _restore_split(raw_item["operation"])
            )
            sequence.append((kind, operation))
        if raw_lineage["latest_operation_kind"] != sequence[-1][0]:
            raise ValueError("failure frontier latest operation mismatch")
    else:
        raise ValueError("failure frontier lineage contract mismatch")

    shifts = tuple(
        operation
        for kind, operation in sequence
        if kind == "boundary_shift"
    )
    splits = tuple(
        operation
        for kind, operation in sequence
        if kind == "visual_frontier_split"
    )
    if (
        len(shifts)
        > _DIRECT_MEMBER_PARTITION_FAILURE_FRONTIER_MAX_BOUNDARY_SHIFT_COUNT
        or len(splits)
        > _DIRECT_MEMBER_MAX_VISUAL_FRONTIER_SPLITS_PER_PROFILE
    ):
        raise ValueError("failure frontier operation count is invalid")
    expected_counts = tuple(int(value) for value in expected_unit_counts)
    if root_unit_counts is None:
        current = expected_counts
        for kind, operation in reversed(sequence):
            parent = (
                _direct_member_partition_failure_frontier_reverse_operation(
                    current,
                    kind,
                    operation,
                )
            )
            if parent is None:
                raise ValueError("failure frontier legacy replay failed")
            current = parent
        root_unit_counts = current
    if (
        sum(root_unit_counts) != sum(int(value) for value in base_unit_counts)
        or len(root_unit_counts) < 2
    ):
        raise ValueError("failure frontier lineage root timing mismatch")
    current = root_unit_counts
    for kind, operation in sequence:
        output = _direct_member_partition_failure_frontier_apply_operation(
            current,
            kind,
            operation,
        )
        if output is None:
            raise ValueError("failure frontier operation replay failed")
        current = output
    if current != expected_counts:
        raise ValueError("failure frontier replayed partition mismatch")
    return shifts, splits, sequence[-1][0]


def _load_direct_member_partition_warm_start_profiles(
    feature_cache_directory: Path | None,
    timing_segments: Sequence[DraftSegment],
    base: _DirectFullFramePartitionProfile,
    *,
    source_count: int,
) -> tuple[tuple[_DirectFullFramePartitionProfile, ...], dict[str, Any]]:
    """Load exact-input-bound cadence candidates for a full visual recheck."""

    binding, diagnostics = _direct_member_partition_warm_start_binding(
        feature_cache_directory,
        base,
        source_count=source_count,
    )
    diagnostics.update(
        {
            "entry_count": 0,
            "matching_entry_count": 0,
            "loaded_candidate_count": 0,
            "rejected_entry_count": 0,
            "rejection_reason_counts": {},
        }
    )
    if binding is None or feature_cache_directory is None:
        return (), diagnostics
    cache_path = (
        Path(feature_cache_directory)
        / _DIRECT_MEMBER_PARTITION_WARM_START_FILENAME
    )
    if not cache_path.exists():
        diagnostics["status"] = "cache_missing"
        return (), diagnostics
    try:
        encoded, cache_fingerprint = _read_stable_regular_file(cache_path)
    except (OSError, ValueError) as exc:
        diagnostics.update(
            {
                "status": "cache_rejected",
                "rejection": type(exc).__name__,
            }
        )
        return (), diagnostics
    diagnostics.update(
        {
            "cache_file_size_bytes": len(encoded),
            "cache_write_size_limit_bytes": (
                _DIRECT_MEMBER_PARTITION_WARM_START_MAX_BYTES
            ),
            "cache_read_size_limit_bytes": (
                _DIRECT_MEMBER_PARTITION_WARM_START_MAX_READ_BYTES
            ),
            "cache_compaction_required": (
                len(encoded) > _DIRECT_MEMBER_PARTITION_WARM_START_MAX_BYTES
            ),
        }
    )
    if len(encoded) > _DIRECT_MEMBER_PARTITION_WARM_START_MAX_READ_BYTES:
        diagnostics.update(
            {
                "status": "cache_rejected",
                "rejection": "cache_read_size_limit_exceeded",
            }
        )
        return (), diagnostics
    try:
        payload = json.loads(encoded.decode("utf-8"))
    except (UnicodeError, json.JSONDecodeError):
        diagnostics.update(
            {"status": "cache_rejected", "rejection": "invalid_json"}
        )
        return (), diagnostics
    if not (
        isinstance(payload, dict)
        and payload.get("schema_version") == 1
        and payload.get("contract")
        == _DIRECT_MEMBER_PARTITION_WARM_START_CONTRACT
        and isinstance(payload.get("entries"), list)
        and len(payload["entries"])
        <= _DIRECT_MEMBER_PARTITION_WARM_START_MAX_ENTRY_COUNT
    ):
        diagnostics.update(
            {"status": "cache_rejected", "rejection": "schema_mismatch"}
        )
        return (), diagnostics

    entries = payload["entries"]
    indexed_entries = tuple(enumerate(entries))
    selected_anchor = next(
        (
            item
            for item in indexed_entries
            if isinstance(item[1], dict)
            and item[1].get("origin") == "full_visual_selector_feasible"
        ),
        None,
    )
    ordered_indices: list[int] = []
    if selected_anchor is not None:
        ordered_indices.append(selected_anchor[0])
    ordered_indices.extend(
        index
        for index, entry in indexed_entries
        if index not in ordered_indices
        and isinstance(entry, dict)
        and entry.get("origin") != "full_visual_selector_feasible"
    )
    ordered_indices.extend(
        index
        for index, _entry in indexed_entries
        if index not in ordered_indices
    )
    ordered_entries = tuple(entries[index] for index in ordered_indices)
    diagnostics["entry_count"] = len(entries)
    diagnostics["entry_order_contract"] = (
        "newest_fully_selected_anchor_then_failure_frontier_then_cache_"
        "order_v2"
    )
    diagnostics["fully_selected_entry_count"] = sum(
        1
        for entry in entries
        if isinstance(entry, dict)
        and entry.get("origin") == "full_visual_selector_feasible"
    )
    rejection_reasons: dict[str, int] = {}

    def _reject(reason: str) -> None:
        rejection_reasons[reason] = rejection_reasons.get(reason, 0) + 1

    items = tuple(timing_segments)
    candidates: list[_DirectFullFramePartitionProfile] = []
    seen_signatures = {base.unit_counts}
    for entry in ordered_entries:
        if not isinstance(entry, dict):
            _reject("entry_not_object")
            continue
        if any(entry.get(key) != value for key, value in binding.items()):
            _reject("input_binding_mismatch")
            continue
        diagnostics["matching_entry_count"] += 1
        raw_counts = entry.get("partition_unit_counts")
        if not (
            isinstance(raw_counts, list)
            and len(raw_counts) >= source_count
            and all(
                isinstance(value, int)
                and not isinstance(value, bool)
                and value > 0
                for value in raw_counts
            )
        ):
            _reject("invalid_partition_unit_counts")
            continue
        counts = tuple(raw_counts)
        signature_sha256 = _direct_partition_signature_sha256(counts)
        if entry.get("candidate_partition_signature_sha256") != signature_sha256:
            _reject("candidate_signature_mismatch")
            continue
        if counts in seen_signatures:
            _reject("duplicate_partition")
            continue
        try:
            spans = _direct_full_frame_spans_from_partition(items, counts)
        except ValueError:
            _reject("timing_partition_mismatch")
            continue
        try:
            (
                boundary_shifts,
                visual_frontier_splits,
                latest_operation_kind,
            ) = (
                _restore_direct_member_partition_failure_frontier_lineage(
                    entry,
                    base_unit_counts=base.unit_counts,
                    expected_unit_counts=counts,
                )
            )
        except ValueError:
            _reject("failure_frontier_lineage_invalid")
            continue
        if any(
            shift.boundary_index >= len(spans) - 1
            or not (
                spans[0].canonical_master_start
                < shift.canonical_master_seconds
                < spans[-1].canonical_master_end
            )
            for shift in boundary_shifts
        ):
            _reject("failure_frontier_lineage_out_of_range")
            continue
        if any(
            not (
                spans[0].canonical_master_start
                < split.canonical_master_seconds
                < spans[-1].canonical_master_end
            )
            for split in visual_frontier_splits
        ):
            _reject("failure_frontier_lineage_out_of_range")
            continue
        duration = sum(span.duration_seconds for span in spans)
        switches_per_minute = (len(spans) - 1) * 60.0 / duration
        span_median = median(span.duration_seconds for span in spans)
        if not (
            _DIRECT_MEMBER_MIN_SWITCHES_PER_MINUTE
            <= switches_per_minute
            <= _DIRECT_MEMBER_MAX_SWITCHES_PER_MINUTE
            and _direct_member_median_run_is_valid(duration, span_median)
            and max(span.duration_seconds for span in spans)
            <= _DIRECT_MEMBER_MAX_RUN_SECONDS + 1e-9
        ):
            _reject("cadence_gate_failed")
            continue
        candidates.append(
            _DirectFullFramePartitionProfile(
                profile_id=(
                    f"input-bound-failure-frontier-{signature_sha256[:16]}"
                    if entry.get("origin")
                    == _DIRECT_MEMBER_PARTITION_FAILURE_FRONTIER_ORIGIN
                    else f"input-bound-warm-start-{signature_sha256[:16]}"
                ),
                unit_counts=counts,
                spans=spans,
                boundary_shifts=boundary_shifts,
                visual_frontier_splits=visual_frontier_splits,
                latest_operation_kind=latest_operation_kind,
                warm_start_binding_sha256=binding["binding_sha256"],
                warm_start_cache_file_sha256=cache_fingerprint["sha256"],
            )
        )
        seen_signatures.add(counts)
        if len(candidates) >= _DIRECT_MEMBER_PARTITION_WARM_START_MAX_MATCH_COUNT:
            break
    diagnostics.update(
        {
            "status": "candidates_loaded" if candidates else "no_match",
            "cache_file_sha256": cache_fingerprint["sha256"],
            "loaded_candidate_count": len(candidates),
            "loaded_candidate_partition_signatures_sha256": [
                _direct_partition_signature_sha256(profile.unit_counts)
                for profile in candidates
            ],
            "rejected_entry_count": sum(rejection_reasons.values()),
            "rejection_reason_counts": rejection_reasons,
        }
    )
    return tuple(candidates), diagnostics


def _bounded_direct_member_partition_cache_payload(
    entries: Sequence[Mapping[str, Any]],
) -> tuple[dict[str, Any], dict[str, int]]:
    """Keep newest cache entries while enforcing count and serialized bytes."""

    retained_entries = [
        dict(entry)
        for entry in entries[:_DIRECT_MEMBER_PARTITION_WARM_START_MAX_ENTRY_COUNT]
    ]
    dropped_entry_count = max(0, len(entries) - len(retained_entries))
    while True:
        payload = {
            "schema_version": 1,
            "contract": _DIRECT_MEMBER_PARTITION_WARM_START_CONTRACT,
            "entries": retained_entries,
        }
        encoded, fingerprint = _bounded_pretty_json_bytes(
            payload,
            maximum_bytes=_DIRECT_MEMBER_PARTITION_WARM_START_MAX_BYTES,
        )
        if encoded is not None:
            return payload, {
                "retained_entry_count": len(retained_entries),
                "dropped_entry_count": dropped_entry_count,
                "serialized_size_bytes": int(
                    fingerprint["serialized_size_bytes"]
                ),
            }
        if not retained_entries:
            raise ValueError("partition cache envelope exceeds its byte bound")
        retained_entries.pop()
        dropped_entry_count += 1


def _persist_direct_member_partition_cache_candidates(
    feature_cache_directory: Path | None,
    base: _DirectFullFramePartitionProfile,
    candidates: Sequence[_DirectFullFramePartitionProfile],
    *,
    source_count: int,
    origin: str,
    preserve_failure_frontier_lineage: bool,
) -> dict[str, Any]:
    """Persist ordered exact-input-bound cadence candidates atomically."""

    binding, diagnostics = _direct_member_partition_warm_start_binding(
        feature_cache_directory,
        base,
        source_count=source_count,
    )
    diagnostics["persisted"] = False
    diagnostics["requested_candidate_count"] = len(candidates)
    if binding is None or feature_cache_directory is None:
        return diagnostics
    prepared: list[tuple[_DirectFullFramePartitionProfile, dict[str, Any] | None]] = []
    seen_signatures: set[tuple[int, ...]] = set()
    skipped_unsupported_lineage_count = 0
    for candidate in candidates:
        if candidate.unit_counts in seen_signatures:
            continue
        search_lineage = (
            _direct_member_partition_failure_frontier_lineage(candidate)
            if preserve_failure_frontier_lineage
            else None
        )
        if preserve_failure_frontier_lineage and search_lineage is None:
            skipped_unsupported_lineage_count += 1
            continue
        seen_signatures.add(candidate.unit_counts)
        prepared.append((candidate, search_lineage))
    diagnostics["skipped_unsupported_lineage_count"] = (
        skipped_unsupported_lineage_count
    )
    diagnostics["eligible_candidate_count"] = len(prepared)
    if not prepared:
        diagnostics["status"] = "no_eligible_candidate"
        return diagnostics
    cache_path = (
        Path(feature_cache_directory)
        / _DIRECT_MEMBER_PARTITION_WARM_START_FILENAME
    )
    entries: list[dict[str, Any]] = []
    if cache_path.exists():
        try:
            encoded, _fingerprint = _read_stable_regular_file(cache_path)
            if (
                len(encoded)
                > _DIRECT_MEMBER_PARTITION_WARM_START_MAX_READ_BYTES
            ):
                raise ValueError("cache_read_size_limit_exceeded")
            existing = json.loads(encoded.decode("utf-8"))
        except (OSError, ValueError, UnicodeError, json.JSONDecodeError) as exc:
            diagnostics.update(
                {
                    "status": "existing_cache_rejected",
                    "rejection": type(exc).__name__,
                }
            )
            return diagnostics
        diagnostics.update(
            {
                "existing_cache_size_bytes": len(encoded),
                "existing_cache_compaction_required": (
                    len(encoded)
                    > _DIRECT_MEMBER_PARTITION_WARM_START_MAX_BYTES
                ),
            }
        )
        if not (
            isinstance(existing, dict)
            and existing.get("schema_version") == 1
            and existing.get("contract")
            == _DIRECT_MEMBER_PARTITION_WARM_START_CONTRACT
            and isinstance(existing.get("entries"), list)
            and len(existing["entries"])
            <= _DIRECT_MEMBER_PARTITION_WARM_START_MAX_ENTRY_COUNT
        ):
            diagnostics.update(
                {
                    "status": "existing_cache_rejected",
                    "rejection": "schema_mismatch",
                }
            )
            return diagnostics
        entries = [item for item in existing["entries"] if isinstance(item, dict)]
    candidate_signatures = [
        _direct_partition_signature_sha256(candidate.unit_counts)
        for candidate, _lineage in prepared
    ]
    replaced_signatures = set(candidate_signatures)
    entries = [
        item
        for item in entries
        if not (
            item.get("binding_sha256") == binding["binding_sha256"]
            and item.get("candidate_partition_signature_sha256")
            in replaced_signatures
        )
    ]
    new_entries = []
    for (candidate, search_lineage), candidate_signature in zip(
        prepared,
        candidate_signatures,
        strict=True,
    ):
        entry = {
            **binding,
            "candidate_partition_signature_sha256": candidate_signature,
            "partition_unit_counts": list(candidate.unit_counts),
            "origin": origin,
            "full_selector_recheck_required_on_reuse": True,
            "visual_gates_relaxed": False,
        }
        if search_lineage is not None:
            entry["search_lineage"] = search_lineage
        new_entries.append(entry)
    entries = [*new_entries, *entries]
    payload, payload_diagnostics = (
        _bounded_direct_member_partition_cache_payload(entries)
    )
    retained_new_entry_count = min(
        len(new_entries),
        payload_diagnostics["retained_entry_count"],
    )
    if retained_new_entry_count < 1:
        diagnostics.update(
            {
                "status": "persistence_failed",
                "rejection": "new_candidate_exceeds_cache_size_limit",
                **payload_diagnostics,
            }
        )
        return diagnostics
    try:
        _write_analysis_manifest_atomically(cache_path, payload)
        persisted_bytes, fingerprint = _read_stable_regular_file(cache_path)
    except (OSError, ValueError) as exc:
        diagnostics.update(
            {"status": "persistence_failed", "rejection": type(exc).__name__}
        )
        return diagnostics
    if len(persisted_bytes) > _DIRECT_MEMBER_PARTITION_WARM_START_MAX_BYTES:
        raise RuntimeError("persisted partition cache exceeded its byte bound")
    persisted_candidate_signatures = candidate_signatures[
        :retained_new_entry_count
    ]
    diagnostics.update(
        {
            "status": "persisted",
            "persisted": True,
            "persisted_candidate_count": retained_new_entry_count,
            "candidate_partition_signatures_sha256": (
                persisted_candidate_signatures
            ),
            "requested_candidate_partition_signatures_sha256": (
                candidate_signatures
            ),
            "cache_file_sha256": fingerprint["sha256"],
            **payload_diagnostics,
        }
    )
    return diagnostics


def _persist_direct_member_partition_warm_start_profile(
    feature_cache_directory: Path | None,
    base: _DirectFullFramePartitionProfile,
    selected: _DirectFullFramePartitionProfile,
    *,
    source_count: int,
) -> dict[str, Any]:
    """Persist a fully selected cadence as a future exact-bound candidate."""

    diagnostics = _persist_direct_member_partition_cache_candidates(
        feature_cache_directory,
        base,
        (selected,),
        source_count=source_count,
        origin="full_visual_selector_feasible",
        preserve_failure_frontier_lineage=False,
    )
    signatures = diagnostics.get("candidate_partition_signatures_sha256")
    if isinstance(signatures, list) and signatures:
        diagnostics["candidate_partition_signature_sha256"] = signatures[0]
    return diagnostics


def _persist_direct_member_partition_failure_frontier_profiles(
    feature_cache_directory: Path | None,
    base: _DirectFullFramePartitionProfile,
    candidates: Sequence[_DirectFullFramePartitionProfile],
    *,
    source_count: int,
) -> dict[str, Any]:
    """Checkpoint a bounded proof frontier for restart-safe continuation."""

    return _persist_direct_member_partition_cache_candidates(
        feature_cache_directory,
        base,
        tuple(candidates)[:_DIRECT_MEMBER_PARTITION_FAILURE_FRONTIER_MAX_COUNT],
        source_count=source_count,
        origin=_DIRECT_MEMBER_PARTITION_FAILURE_FRONTIER_ORIGIN,
        preserve_failure_frontier_lineage=True,
    )


def _direct_member_partition_restart_frontier_profiles(
    queued_profiles: Sequence[_DirectFullFramePartitionProfile],
    evaluated_profiles: Sequence[_DirectFullFramePartitionProfile],
    *,
    excluded_signatures: set[tuple[int, ...]],
) -> tuple[_DirectFullFramePartitionProfile, ...]:
    """Choose novel queue leaves before already-evaluated failure leaves.

    The strict terminal budget can stop with a useful structural queue still
    pending.  Those candidates must be checkpointed ahead of a chain of
    already-evaluated ancestors; otherwise a restart spends its bounded warm
    slots replaying the same branch and never reaches the pending siblings.
    """

    ordered: list[_DirectFullFramePartitionProfile] = []
    seen_signatures = set(excluded_signatures)
    for profile in (*tuple(queued_profiles), *tuple(evaluated_profiles)):
        if profile.unit_counts in seen_signatures:
            continue
        if _direct_member_partition_failure_frontier_lineage(profile) is None:
            continue
        seen_signatures.add(profile.unit_counts)
        ordered.append(profile)

    def _lineage(
        profile: _DirectFullFramePartitionProfile,
    ) -> tuple[tuple[int, ...], tuple[tuple[str, Any], ...]]:
        restored = (
            _direct_member_partition_failure_frontier_operation_sequence(
                profile
            )
        )
        if restored is None:
            raise RuntimeError("restart frontier lost its supported lineage")
        return restored

    lineages = {profile.unit_counts: _lineage(profile) for profile in ordered}

    def _is_strict_ancestor(
        ancestor: _DirectFullFramePartitionProfile,
        descendant: _DirectFullFramePartitionProfile,
    ) -> bool:
        ancestor_root, ancestor_operations = lineages[ancestor.unit_counts]
        descendant_root, descendant_operations = lineages[
            descendant.unit_counts
        ]
        return bool(
            ancestor_root == descendant_root
            and len(ancestor_operations) < len(descendant_operations)
            and ancestor_operations
            == descendant_operations[: len(ancestor_operations)]
        )

    leaves = [
        profile
        for profile in ordered
        if not any(
            _is_strict_ancestor(profile, other)
            for other in ordered
            if other is not profile
        )
    ]
    return tuple(leaves[:_DIRECT_MEMBER_PARTITION_FAILURE_FRONTIER_MAX_COUNT])


def _direct_partition_queue_signature_digest(
    profiles: Sequence[_DirectFullFramePartitionProfile],
) -> str:
    """Hash one queue frontier independently of insertion order."""

    signatures = sorted(
        _direct_partition_signature_sha256(profile.unit_counts)
        for profile in profiles
    )
    if len(signatures) != len(set(signatures)):
        raise ValueError("direct partition queue contains duplicate signatures")
    return hashlib.sha256(
        json.dumps(
            signatures,
            ensure_ascii=False,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()


def _direct_partition_current_boundary_index_at_time(
    profile: _DirectFullFramePartitionProfile,
    canonical_master_seconds: float,
) -> int | None:
    """Resolve a lineage cut in the current partition's coordinate system."""

    if not math.isfinite(canonical_master_seconds):
        raise ValueError("direct partition lineage cut time must be finite")
    for boundary_index, span in enumerate(profile.spans[:-1]):
        if math.isclose(
            span.canonical_master_end,
            canonical_master_seconds,
            rel_tol=0.0,
            abs_tol=1e-7,
        ):
            return boundary_index
    return None


def _direct_partition_current_shifted_boundary_indices(
    profile: _DirectFullFramePartitionProfile,
) -> tuple[int, ...]:
    """Map every surviving moved cut after any index-changing merge."""

    return tuple(
        sorted(
            {
                boundary_index
                for canonical_master_seconds in (
                    tuple(
                        shift.canonical_master_seconds
                        for shift in profile.boundary_shifts
                    )
                    + tuple(
                        boundary_seconds
                        for redistribution in profile.window_redistributions
                        for boundary_seconds in (
                            redistribution.replacement_boundary_master_seconds
                        )
                    )
                )
                if (
                    boundary_index
                    := _direct_partition_current_boundary_index_at_time(
                        profile,
                        canonical_master_seconds,
                    )
                )
                is not None
            }
        )
    )


def _direct_partition_current_shift_by_boundary(
    profile: _DirectFullFramePartitionProfile,
) -> dict[int, _DirectFullFrameBoundaryShift]:
    """Map each surviving shifted cut to its latest exact operation."""

    result: dict[int, _DirectFullFrameBoundaryShift] = {}
    for shift in reversed(profile.boundary_shifts):
        boundary_index = _direct_partition_current_boundary_index_at_time(
            profile,
            shift.canonical_master_seconds,
        )
        if boundary_index is not None:
            result.setdefault(boundary_index, shift)
    return result


def _direct_partition_proof_directed_boundary_merge_limit(
    profile: _DirectFullFramePartitionProfile,
) -> int:
    """Derive the total merge budget from the professional density floor.

    Every admitted merge removes exactly one potential source switch.  The
    budget therefore stops at the first integer switch count that would fall
    below the 15-per-minute professional floor for this exact song range.  It
    is a search-capacity calculation only: materialized children must still
    pass the 7.2-second hold bound, median cadence, content, transition,
    source-balance, highlight, and rendered-continuity gates independently.
    """

    if not profile.spans:
        return len(profile.boundary_merges)
    duration = sum(span.duration_seconds for span in profile.spans)
    minimum_switch_count = math.ceil(
        _DIRECT_MEMBER_MIN_SWITCHES_PER_MINUTE * duration / 60.0 - 1e-9
    )
    current_switch_count = len(profile.spans) - 1
    remaining_density_capacity = max(
        0,
        current_switch_count - minimum_switch_count,
    )
    return len(profile.boundary_merges) + remaining_density_capacity


def _direct_partition_proof_directed_boundary_shift_limit(
    profile: _DirectFullFramePartitionProfile,
) -> int:
    """Grant one compensating proof-directed cut motion per admitted merge.

    The base seven-shift bound limits ordinary search branching.  A merge is
    different: it removes the proved cut and can expose either neighbouring
    cut as the next exact connectivity frontier.  Keeping the old fixed bound
    after such a merge made a saturated lineage jump directly to another
    merge or a visual split even when a cadence-preserving boundary shift was
    still available.  One additional moved-cut slot per independently admitted
    merge covers that newly exposed local frontier without relaxing any visual
    or cadence gate.  A three-span redistribution consumes two slots.  The
    number of surviving cuts remains an absolute bound.
    """

    return min(
        max(0, len(profile.spans) - 1),
        _DIRECT_MEMBER_MAX_SHIFTED_BOUNDARY_COUNT
        + len(profile.boundary_merges),
    )


def _direct_partition_future_operation_state_key(
    parent: _DirectFullFramePartitionProfile,
    diagnostics: dict[str, Any],
    children: Sequence[_DirectFullFramePartitionProfile],
) -> tuple[Any, ...]:
    """Return a lossless key for one proof-authorized expansion domain.

    This is intentionally stricter than a failure/frontier label.  The full
    parent partition, every surviving already-used physical cut, the most
    recent cut, remaining depth, exact scalar proof, and every cadence-valid
    child partition all participate.  Consequently two states are dominated
    only when every future operator available *now* is identical; visual
    feasibility is never inferred or merged.
    """

    proofs = _direct_partition_exact_shift_proofs(
        diagnostics,
        span_count=len(parent.spans),
    )
    used_boundaries = _direct_partition_current_shifted_boundary_indices(
        parent
    )
    last_boundary = (
        _direct_partition_current_boundary_index_at_time(
            parent,
            parent.boundary_shifts[-1].canonical_master_seconds,
        )
        if parent.boundary_shifts
        else None
    )
    proof_key = tuple(
        (
            proof.boundary_index,
            proof.trigger,
            proof.failure,
            proof.failed_segment_index,
            proof.forward_reachable_left_source_indices,
            proof.left_valid_source_indices,
            proof.right_valid_source_indices,
            proof.local_nonsevere_edge_count,
        )
        for proof in proofs
    )
    child_signatures = tuple(
        sorted(tuple(child.unit_counts) for child in children)
    )
    return (
        tuple(parent.unit_counts),
        used_boundaries,
        last_boundary,
        _direct_partition_proof_directed_boundary_shift_limit(parent)
        - parent.proof_directed_boundary_motion_count,
        tuple(
            (
                redistribution.window_start_span_index,
                redistribution.proof_frontier_boundary_index,
                redistribution.original_unit_counts,
                redistribution.replacement_unit_counts,
            )
            for redistribution in parent.window_redistributions
        ),
        tuple(
            (
                split.parent_span_index,
                split.split_unit_offset,
                split.proof_frontier_boundary_index,
                split.evidence_contract,
                split.evidence_kind,
            )
            for split in parent.visual_frontier_splits
        ),
        (
            _DIRECT_MEMBER_MAX_VISUAL_FRONTIER_SPLITS_PER_PROFILE
            - len(parent.visual_frontier_splits)
        ),
        tuple(
            (
                merge.boundary_index,
                merge.merged_unit_count,
                merge.trigger,
            )
            for merge in parent.boundary_merges
        ),
        (
            _direct_partition_proof_directed_boundary_merge_limit(parent)
            - len(parent.boundary_merges)
        ),
        proof_key,
        child_signatures,
    )


def _direct_full_frame_shifted_partition_profiles(
    timing_segments: Sequence[DraftSegment],
    base: _DirectFullFramePartitionProfile,
    bottleneck_boundaries: Sequence[int],
    *,
    parent_diagnostics: dict[str, Any] | None = None,
) -> tuple[_DirectFullFramePartitionProfile, ...]:
    """Move only diagnosed 4+4 boundaries by one timing unit."""

    items = tuple(timing_segments)
    profiles: list[_DirectFullFramePartitionProfile] = []
    seen_counts = {base.unit_counts}
    for boundary_index in bottleneck_boundaries:
        if not 0 <= boundary_index < len(base.unit_counts) - 1:
            continue
        if base.unit_counts[boundary_index : boundary_index + 2] != (4, 4):
            continue
        # At the final boundary prefer a shorter tail first.  Else keep a
        # stable later-then-earlier ordering for deterministic diagnostics.
        for left_count, right_count, shift_units in (
            (5, 3, 1),
            (3, 5, -1),
        ):
            counts = list(base.unit_counts)
            counts[boundary_index : boundary_index + 2] = [
                left_count,
                right_count,
            ]
            signature = tuple(counts)
            if signature in seen_counts:
                continue
            try:
                spans = _direct_full_frame_spans_from_partition(items, signature)
            except ValueError:
                continue
            duration = sum(span.duration_seconds for span in spans)
            switches_per_minute = (len(spans) - 1) * 60.0 / duration
            span_median = median(span.duration_seconds for span in spans)
            if not (
                _DIRECT_MEMBER_MIN_SWITCHES_PER_MINUTE
                <= switches_per_minute
                <= _DIRECT_MEMBER_MAX_SWITCHES_PER_MINUTE
                and _direct_member_median_run_is_valid(duration, span_median)
            ):
                continue
            new_boundary_unit_end = sum(signature[: boundary_index + 1])
            boundary_reasons = items[new_boundary_unit_end - 1].end_boundary_reasons
            exact_proof = next(
                (
                    proof
                    for proof in _direct_partition_exact_shift_proofs(
                        parent_diagnostics,
                        span_count=len(base.spans),
                    )
                    if proof.boundary_index == boundary_index
                ),
                None,
            ) if parent_diagnostics is not None else None
            shift = _DirectFullFrameBoundaryShift(
                boundary_index=boundary_index,
                shift_units=shift_units,
                left_unit_count=left_count,
                right_unit_count=right_count,
                canonical_master_seconds=(
                    spans[boundary_index].canonical_master_end
                ),
                boundary_reasons=boundary_reasons,
                trigger=(
                    exact_proof.trigger
                    if exact_proof is not None
                    else "caller_supplied_proven_bottleneck"
                ),
                parent_profile_id=base.profile_id,
                parent_partition_signature_sha256=(
                    _direct_partition_signature_sha256(base.unit_counts)
                ),
                proof_failure=(
                    exact_proof.failure if exact_proof is not None else None
                ),
                proof_failed_segment_index=(
                    exact_proof.failed_segment_index
                    if exact_proof is not None
                    else None
                ),
                proof_forward_reachable_left_source_indices=(
                    exact_proof.forward_reachable_left_source_indices
                    if exact_proof is not None
                    else ()
                ),
                proof_left_valid_source_indices=(
                    exact_proof.left_valid_source_indices
                    if exact_proof is not None
                    else ()
                ),
                proof_right_valid_source_indices=(
                    exact_proof.right_valid_source_indices
                    if exact_proof is not None
                    else ()
                ),
                proof_local_nonsevere_edge_count=(
                    exact_proof.local_nonsevere_edge_count
                    if exact_proof is not None
                    else None
                ),
            )
            profiles.append(
                _DirectFullFramePartitionProfile(
                    profile_id=(
                        f"boundary-{boundary_index}-"
                        f"{left_count}-plus-{right_count}"
                    ),
                    unit_counts=signature,
                    spans=spans,
                    boundary_shifts=base.boundary_shifts + (shift,),
                    window_redistributions=base.window_redistributions,
                    visual_frontier_splits=base.visual_frontier_splits,
                    boundary_merges=base.boundary_merges,
                    latest_operation_kind="boundary_shift",
                )
            )
            seen_counts.add(signature)
            if len(profiles) >= _DIRECT_MEMBER_MAX_PARTITION_PROFILE_COUNT - 1:
                return tuple(profiles)
    return tuple(profiles)


def _direct_member_render_feedback_partition_profiles(
    timing_segments: Sequence[DraftSegment],
    parent: _DirectFullFramePartitionProfile,
    certificates: Sequence[tuple[float, int, int]],
    *,
    source_count: int,
    config: DirectMemberVisualConfig,
) -> tuple[_DirectFullFramePartitionProfile, ...]:
    """Move renderer-proven problem cuts before unrelated global search.

    A dense camera certificate proves only that one source pair cannot be
    rendered near one measured cut; it does not prove that the whole musical
    boundary is unusable.  The selector already removes that pair.  When
    several alternatives at the same cut are exhausted, audition the two
    adjacent one-unit musical shifts from the exact warm partition before
    exploring proof frontiers elsewhere in the song.  Every proposal still
    runs the complete selector and dense renderer from scratch.
    """

    items = tuple(timing_segments)
    normalized = _normalize_direct_member_dense_render_feedback_edges(
        certificates,
        source_count=source_count,
        range_start=parent.spans[0].canonical_master_start,
        range_end=parent.spans[-1].canonical_master_end,
    )
    if not normalized:
        return ()
    boundary_tolerance_seconds = (
        config.boundary_search_radius_frames
        * config.sample_frame_step_seconds
        + 1e-7
    )
    evidence_by_boundary: dict[
        int,
        list[tuple[float, int, int]],
    ] = {}
    boundaries = tuple(
        span.canonical_master_end for span in parent.spans[:-1]
    )
    if not boundaries:
        return ()
    for certificate in normalized:
        measured_seconds = certificate[0]
        boundary_index = min(
            range(len(boundaries)),
            key=lambda index: abs(boundaries[index] - measured_seconds),
        )
        if (
            abs(boundaries[boundary_index] - measured_seconds)
            > boundary_tolerance_seconds
        ):
            continue
        evidence_by_boundary.setdefault(boundary_index, []).append(certificate)
    ranked_boundaries = sorted(
        evidence_by_boundary,
        key=lambda boundary_index: (
            -len(evidence_by_boundary[boundary_index]),
            boundary_index,
        ),
    )
    profiles: list[_DirectFullFramePartitionProfile] = []
    seen_counts = {parent.unit_counts}
    parent_signature = _direct_partition_signature_sha256(parent.unit_counts)
    for boundary_index in ranked_boundaries:
        left_count = parent.unit_counts[boundary_index]
        right_count = parent.unit_counts[boundary_index + 1]
        evidence = evidence_by_boundary[boundary_index]
        for shift_units in (1, -1):
            replacement_left = left_count + shift_units
            replacement_right = right_count - shift_units
            if replacement_left <= 0 or replacement_right <= 0:
                continue
            counts = list(parent.unit_counts)
            counts[boundary_index : boundary_index + 2] = [
                replacement_left,
                replacement_right,
            ]
            signature = tuple(counts)
            if signature in seen_counts:
                continue
            try:
                spans = _direct_full_frame_spans_from_partition(items, signature)
            except ValueError:
                continue
            duration = sum(span.duration_seconds for span in spans)
            switches_per_minute = (len(spans) - 1) * 60.0 / duration
            span_median = median(span.duration_seconds for span in spans)
            if not (
                _DIRECT_MEMBER_MIN_SWITCHES_PER_MINUTE
                <= switches_per_minute
                <= _DIRECT_MEMBER_MAX_SWITCHES_PER_MINUTE
                and _direct_member_median_run_is_valid(duration, span_median)
                and max(span.duration_seconds for span in spans)
                <= _DIRECT_MEMBER_MAX_RUN_SECONDS + 1e-9
            ):
                continue
            new_boundary_unit_end = sum(signature[: boundary_index + 1])
            boundary_reasons = items[
                new_boundary_unit_end - 1
            ].end_boundary_reasons
            shift = _DirectFullFrameBoundaryShift(
                boundary_index=boundary_index,
                shift_units=shift_units,
                left_unit_count=replacement_left,
                right_unit_count=replacement_right,
                canonical_master_seconds=(
                    spans[boundary_index].canonical_master_end
                ),
                boundary_reasons=boundary_reasons,
                trigger="dense_render_camera_infeasible_pair_cluster",
                parent_profile_id=parent.profile_id,
                parent_partition_signature_sha256=parent_signature,
                proof_failure="dense_render_camera_infeasible",
                proof_failed_segment_index=boundary_index + 1,
                proof_forward_reachable_left_source_indices=tuple(
                    sorted({item[1] for item in evidence})
                ),
                proof_left_valid_source_indices=tuple(
                    sorted({item[1] for item in evidence})
                ),
                proof_right_valid_source_indices=tuple(
                    sorted({item[2] for item in evidence})
                ),
                proof_local_nonsevere_edge_count=None,
            )
            profiles.append(
                _DirectFullFramePartitionProfile(
                    profile_id=(
                        "dense-render-feedback-boundary-"
                        f"{boundary_index}-{replacement_left}-plus-"
                        f"{replacement_right}"
                    ),
                    unit_counts=signature,
                    spans=spans,
                    boundary_shifts=parent.boundary_shifts + (shift,),
                    window_redistributions=parent.window_redistributions,
                    visual_frontier_splits=parent.visual_frontier_splits,
                    boundary_merges=parent.boundary_merges,
                    latest_operation_kind="boundary_shift",
                    warm_start_binding_sha256=(
                        parent.warm_start_binding_sha256
                    ),
                    warm_start_cache_file_sha256=(
                        parent.warm_start_cache_file_sha256
                    ),
                )
            )
            seen_counts.add(signature)
            if (
                len(profiles)
                >= _DIRECT_MEMBER_MAX_DENSE_RENDER_FEEDBACK_PROFILE_COUNT
            ):
                return tuple(profiles)
    return tuple(profiles)


def _direct_member_minimum_hold_feedback_boundary_indices(
    infeasibility_diagnostic: Mapping[str, Any],
    *,
    span_count: int,
) -> tuple[int, ...]:
    """Return representative clusters from a proved minimum-hold witness."""

    probe = infeasibility_diagnostic.get("minimum_hold_probe")
    if not isinstance(probe, Mapping):
        return ()
    strict_maximum = probe.get("strict_maximum_same_source_hold_count")
    minimum_required = probe.get("minimum_same_source_hold_count")
    witness = probe.get("feasible_witness")
    if not (
        probe.get("minimum_proven") is True
        and probe.get("success") is True
        and probe.get("strict_total_hold_budget_feasible") is False
        and isinstance(strict_maximum, int)
        and not isinstance(strict_maximum, bool)
        and isinstance(minimum_required, int)
        and not isinstance(minimum_required, bool)
        and minimum_required > strict_maximum
        and isinstance(witness, Mapping)
    ):
        return ()
    raw_boundaries = witness.get("same_source_hold_boundary_indices")
    if not isinstance(raw_boundaries, list):
        return ()
    boundaries = sorted(
        {
            value
            for value in raw_boundaries
            if isinstance(value, int)
            and not isinstance(value, bool)
            and 0 <= value < span_count - 1
        }
    )
    if not boundaries:
        return ()
    clusters: list[list[int]] = []
    for boundary_index in boundaries:
        if clusters and boundary_index == clusters[-1][-1] + 1:
            clusters[-1].append(boundary_index)
        else:
            clusters.append([boundary_index])
    clusters.sort(key=lambda cluster: (-len(cluster), cluster[0]))
    return tuple(cluster[(len(cluster) - 1) // 2] for cluster in clusters)


def _direct_member_minimum_hold_feedback_partition_profiles(
    timing_segments: Sequence[DraftSegment],
    parent: _DirectFullFramePartitionProfile,
    infeasibility_diagnostic: Mapping[str, Any],
) -> tuple[_DirectFullFramePartitionProfile, ...]:
    """Propose cadence-preserving shifts at proved minimum-hold clusters.

    The minimum-hold MILP is evidence for where the current partition forces
    long same-source runs, not permission to weaken a visual edge.  Each
    proposal therefore moves one existing timing-unit boundary and must pass
    the complete unrelaxed selector on the next run.
    """

    if (
        len(parent.boundary_shifts)
        >= _DIRECT_MEMBER_PARTITION_FAILURE_FRONTIER_MAX_BOUNDARY_SHIFT_COUNT
    ):
        return ()
    boundary_indices = _direct_member_minimum_hold_feedback_boundary_indices(
        infeasibility_diagnostic,
        span_count=len(parent.spans),
    )
    if not boundary_indices:
        return ()
    items = tuple(timing_segments)
    current_shifts = _direct_partition_current_shift_by_boundary(parent)
    parent_signature = _direct_partition_signature_sha256(parent.unit_counts)
    profiles: list[_DirectFullFramePartitionProfile] = []
    seen_counts = {parent.unit_counts}
    for boundary_index in boundary_indices:
        previous_shift = current_shifts.get(boundary_index)
        shift_directions = (
            (1 if previous_shift.shift_units > 0 else -1,)
            if previous_shift is not None
            else (1, -1)
        )
        left_count = parent.unit_counts[boundary_index]
        right_count = parent.unit_counts[boundary_index + 1]
        for shift_units in shift_directions:
            replacement_left = left_count + shift_units
            replacement_right = right_count - shift_units
            if replacement_left <= 0 or replacement_right <= 0:
                continue
            counts = list(parent.unit_counts)
            counts[boundary_index : boundary_index + 2] = [
                replacement_left,
                replacement_right,
            ]
            signature = tuple(counts)
            if signature in seen_counts:
                continue
            try:
                spans = _direct_full_frame_spans_from_partition(
                    items,
                    signature,
                )
            except ValueError:
                continue
            duration = sum(span.duration_seconds for span in spans)
            switches_per_minute = (len(spans) - 1) * 60.0 / duration
            span_median = median(span.duration_seconds for span in spans)
            if not (
                _DIRECT_MEMBER_MIN_SWITCHES_PER_MINUTE
                <= switches_per_minute
                <= _DIRECT_MEMBER_MAX_SWITCHES_PER_MINUTE
                and _direct_member_median_run_is_valid(duration, span_median)
                and max(span.duration_seconds for span in spans)
                <= _DIRECT_MEMBER_MAX_RUN_SECONDS + 1e-9
            ):
                continue
            new_boundary_unit_end = sum(signature[: boundary_index + 1])
            shift = _DirectFullFrameBoundaryShift(
                boundary_index=boundary_index,
                shift_units=shift_units,
                left_unit_count=replacement_left,
                right_unit_count=replacement_right,
                canonical_master_seconds=(
                    spans[boundary_index].canonical_master_end
                ),
                boundary_reasons=items[
                    new_boundary_unit_end - 1
                ].end_boundary_reasons,
                trigger="lexicographic_minimum_hold_witness_cluster",
                parent_profile_id=parent.profile_id,
                parent_partition_signature_sha256=parent_signature,
                proof_failure="cinematic_bridge_path_infeasible",
                proof_failed_segment_index=boundary_index + 1,
                proof_forward_reachable_left_source_indices=(),
                proof_left_valid_source_indices=(),
                proof_right_valid_source_indices=(),
                proof_local_nonsevere_edge_count=None,
            )
            profiles.append(
                _DirectFullFramePartitionProfile(
                    profile_id=(
                        f"{parent.profile_id}__minimum-hold-{boundary_index}-"
                        f"{replacement_left}-plus-{replacement_right}"
                    ),
                    unit_counts=signature,
                    spans=spans,
                    boundary_shifts=parent.boundary_shifts + (shift,),
                    window_redistributions=parent.window_redistributions,
                    visual_frontier_splits=parent.visual_frontier_splits,
                    boundary_merges=parent.boundary_merges,
                    latest_operation_kind="boundary_shift",
                    warm_start_binding_sha256=(
                        parent.warm_start_binding_sha256
                    ),
                    warm_start_cache_file_sha256=(
                        parent.warm_start_cache_file_sha256
                    ),
                )
            )
            seen_counts.add(signature)
            if (
                len(profiles)
                >= _DIRECT_MEMBER_MAX_MINIMUM_HOLD_FEEDBACK_PROFILE_COUNT
            ):
                return tuple(profiles)
    return tuple(profiles)


def _direct_partition_forward_exhaustion_bottleneck(
    diagnostics: dict[str, Any],
    *,
    span_count: int,
) -> int | None:
    """Locate one globally unreachable cut without weakening a local gate.

    ``forward_reachable_left_source_indices`` is the exact content-valid,
    nonsevere, no-repeat frontier before each fixed cut.  If it becomes empty
    after a boundary whose local cross-source graph still has edges, the
    current partition has proved a path-connectivity conflict rather than a
    bad-frame or severe-edge shortage.  The returned boundary may be moved and
    every visual gate recomputed; it never authorizes using the rejected edge.
    """

    if span_count < 3 or not _direct_partition_failure_is_proven(diagnostics):
        return None
    connectivity = diagnostics.get("hard_boundary_connectivity")
    if not isinstance(connectivity, dict) or connectivity.get(
        "analysis_basis"
    ) != "content_valid_nonsevere_no_repeat_reachability_v1":
        return None
    raw_boundaries = connectivity.get("boundaries")
    if not isinstance(raw_boundaries, list) or len(raw_boundaries) != span_count - 1:
        return None
    for boundary_index, boundary in enumerate(raw_boundaries):
        if not isinstance(boundary, dict):
            return None
        previous_frontier = boundary.get(
            "forward_reachable_left_source_indices"
        )
        current_frontier = boundary.get(
            "forward_reachable_right_source_indices"
        )
        if current_frontier is None and boundary_index + 1 < len(raw_boundaries):
            following = raw_boundaries[boundary_index + 1]
            current_frontier = (
                following.get("forward_reachable_left_source_indices")
                if isinstance(following, dict)
                else None
            )
        if not isinstance(previous_frontier, list) or not isinstance(current_frontier, list):
            return None
        if not previous_frontier or current_frontier:
            continue
        if boundary.get("boundary_index") != boundary_index:
            return None
        if int(boundary.get("nonsevere_cross_source_edge_count", 0)) <= 0:
            # A locally edge-free cut is handled by the primary proof-directed
            # shift.  This helper is only for the remaining global frontier
            # conflict after that primary repair.
            return None
        if not boundary.get("left_valid_source_indices") or not boundary.get(
            "right_valid_source_indices"
        ):
            return None
        return boundary_index
    return None


def _direct_full_frame_proof_directed_child_profiles(
    timing_segments: Sequence[DraftSegment],
    parent: _DirectFullFramePartitionProfile,
    diagnostics: dict[str, Any],
) -> tuple[_DirectFullFramePartitionProfile, ...]:
    """Create deterministic children from this parent's exact failure proof.

    The ordinary operator moves one independently proven boundary by one unit.
    When one moved cut exposes an adjacent exact failure, that adjacent cut may
    also move.  Adjacent moves are ordinary compositions of the final canonical
    partition: every materialized span and every visual, quota, cadence, and
    transition constraint is recomputed before selection.  If that complete
    recheck proves the already-moved physical cut still has zero usable
    cross-source edges, it may advance one more unit in the same direction.
    Reversal is forbidden, so a refinement cannot cycle back to an earlier
    partition or turn the bounded search into unconstrained timing drift.
    """

    if (
        parent.proof_directed_boundary_motion_count
        >= _direct_partition_proof_directed_boundary_shift_limit(parent)
    ):
        return ()
    proofs = _direct_partition_exact_shift_proofs(
        diagnostics,
        span_count=len(parent.spans),
    )
    if not proofs:
        return ()

    items = tuple(timing_segments)
    profiles: list[_DirectFullFramePartitionProfile] = []
    used_boundaries = set(
        _direct_partition_current_shifted_boundary_indices(parent)
    )
    current_shift_by_boundary = _direct_partition_current_shift_by_boundary(
        parent
    )
    seen_signatures: set[tuple[int, ...]] = set()
    for proof in proofs:
        boundary_index = proof.boundary_index
        previous_shift = current_shift_by_boundary.get(boundary_index)
        if boundary_index in used_boundaries and previous_shift is None:
            continue
        left_units, right_units = parent.unit_counts[
            boundary_index : boundary_index + 2
        ]
        if left_units < 1 or right_units < 1:
            continue
        # Unit counts are not durations: one draft unit can be a complete
        # 1.9-second musical phraselet.  Admit a one-unit side only when the
        # materialized span independently passes the real-time 1.8-second
        # professional floor below.  A globally exhausted frontier authorizes
        # every integer placement inside the same two-span window, nearest
        # first.  The former +/-2 cap skipped valid 3+5 and 2+6 placements
        # after a 6+2 merge even though total duration, cut count, and every
        # downstream visual/cadence gate were unchanged and fully rechecked.
        if previous_shift is not None:
            shift_options = (
                1 if previous_shift.shift_units > 0 else -1,
            )
        elif (
            proof.trigger
            == "proven_forward_connectivity_frontier_exhaustion"
        ):
            maximum_distance = max(left_units - 1, right_units - 1)
            shift_options = tuple(
                shift_units
                for distance in range(1, maximum_distance + 1)
                for shift_units in (distance, -distance)
            )
        else:
            shift_options = (1, -1)
        for shift_units in shift_options:
            left_count = left_units + shift_units
            right_count = right_units - shift_units
            if left_count < 1 or right_count < 1:
                continue
            counts = list(parent.unit_counts)
            counts[boundary_index : boundary_index + 2] = [
                left_count,
                right_count,
            ]
            signature = tuple(counts)
            if signature in seen_signatures:
                continue
            try:
                spans = _direct_full_frame_spans_from_partition(items, signature)
            except ValueError:
                continue
            if (
                min(
                    spans[boundary_index].duration_seconds,
                    spans[boundary_index + 1].duration_seconds,
                )
                + 1e-9
                < _DIRECT_MEMBER_HIGHLIGHT_MINIMUM_RUN_SECONDS
            ):
                continue
            duration = sum(span.duration_seconds for span in spans)
            switches_per_minute = (len(spans) - 1) * 60.0 / duration
            span_median = median(span.duration_seconds for span in spans)
            if not (
                _DIRECT_MEMBER_MIN_SWITCHES_PER_MINUTE
                <= switches_per_minute
                <= _DIRECT_MEMBER_MAX_SWITCHES_PER_MINUTE
                and _direct_member_median_run_is_valid(duration, span_median)
            ):
                continue
            new_boundary_unit_end = sum(signature[: boundary_index + 1])
            boundary_reasons = items[
                new_boundary_unit_end - 1
            ].end_boundary_reasons
            shift = _DirectFullFrameBoundaryShift(
                boundary_index=boundary_index,
                shift_units=shift_units,
                left_unit_count=left_count,
                right_unit_count=right_count,
                canonical_master_seconds=(
                    spans[boundary_index].canonical_master_end
                ),
                boundary_reasons=boundary_reasons,
                trigger=proof.trigger,
                parent_profile_id=parent.profile_id,
                parent_partition_signature_sha256=(
                    _direct_partition_signature_sha256(parent.unit_counts)
                ),
                proof_failure=proof.failure,
                proof_failed_segment_index=proof.failed_segment_index,
                proof_forward_reachable_left_source_indices=(
                    proof.forward_reachable_left_source_indices
                ),
                proof_left_valid_source_indices=proof.left_valid_source_indices,
                proof_right_valid_source_indices=proof.right_valid_source_indices,
                proof_local_nonsevere_edge_count=(
                    proof.local_nonsevere_edge_count
                ),
            )
            label = (
                "refine"
                if previous_shift is not None
                else "frontier"
                if proof.trigger
                == "proven_forward_connectivity_frontier_exhaustion"
                else "local"
            )
            profile_id = (
                f"boundary-{boundary_index}-{left_count}-plus-{right_count}"
                if not parent.boundary_shifts
                and not parent.window_redistributions
                and not parent.boundary_merges
                else (
                    f"{parent.profile_id}__{label}-{boundary_index}-"
                    f"{left_count}-plus-{right_count}"
                )
            )
            profiles.append(
                _DirectFullFramePartitionProfile(
                    profile_id=profile_id,
                    unit_counts=signature,
                    spans=spans,
                    boundary_shifts=parent.boundary_shifts + (shift,),
                    window_redistributions=parent.window_redistributions,
                    visual_frontier_splits=parent.visual_frontier_splits,
                    boundary_merges=parent.boundary_merges,
                    latest_operation_kind="boundary_shift",
                )
            )
            seen_signatures.add(signature)
    return tuple(profiles)


def _direct_full_frame_proof_directed_merge_profiles(
    timing_segments: Sequence[DraftSegment],
    parent: _DirectFullFramePartitionProfile,
    diagnostics: dict[str, Any],
) -> tuple[_DirectFullFramePartitionProfile, ...]:
    """Remove only a proven bottleneck after no new safe shift remains.

    A two-sided minimum-duration cadence such as ``2+2`` has no legal shifted
    representation: ``1+3`` would create a sub-1.8-second flash cut.  The
    repair dispatcher invokes this operator only after the shift operator has
    produced no new child for the exact current proof.  Merging the two
    adjacent spans is then the remaining non-relaxed local representation. The
    merged child is still sent through complete content, native-cut,
    transition, quota, duration, and highlight-density audits before render.
    """

    if (
        parent.visual_frontier_splits
        or len(parent.boundary_merges)
        >= _direct_partition_proof_directed_boundary_merge_limit(parent)
    ):
        return ()
    proofs = _direct_partition_exact_shift_proofs(
        diagnostics,
        span_count=len(parent.spans),
    )
    if not proofs:
        return ()
    items = tuple(timing_segments)
    profiles: list[_DirectFullFramePartitionProfile] = []
    for proof in proofs:
        boundary_index = proof.boundary_index
        if not 0 <= boundary_index < len(parent.unit_counts) - 1:
            continue
        left_count, right_count = parent.unit_counts[
            boundary_index : boundary_index + 2
        ]
        counts = list(parent.unit_counts)
        merged_count = left_count + right_count
        counts[boundary_index : boundary_index + 2] = [merged_count]
        signature = tuple(counts)
        try:
            spans = _direct_full_frame_spans_from_partition(items, signature)
        except ValueError:
            continue
        duration = sum(span.duration_seconds for span in spans)
        switches_per_minute = (len(spans) - 1) * 60.0 / duration
        span_median = median(span.duration_seconds for span in spans)
        if not (
            _DIRECT_MEMBER_MIN_SWITCHES_PER_MINUTE
            <= switches_per_minute
            <= _DIRECT_MEMBER_MAX_SWITCHES_PER_MINUTE
            and _direct_member_median_run_is_valid(duration, span_median)
        ):
            continue
        boundary_unit_end = sum(parent.unit_counts[: boundary_index + 1])
        boundary_reasons = items[boundary_unit_end - 1].end_boundary_reasons
        merge = _DirectFullFrameProofDirectedBoundaryMerge(
            boundary_index=boundary_index,
            left_unit_count=left_count,
            right_unit_count=right_count,
            merged_unit_count=merged_count,
            canonical_master_seconds=(
                parent.spans[boundary_index].canonical_master_end
            ),
            boundary_reasons=boundary_reasons,
            trigger=proof.trigger,
            parent_profile_id=parent.profile_id,
            parent_partition_signature_sha256=(
                _direct_partition_signature_sha256(parent.unit_counts)
            ),
            proof_failure=proof.failure,
            proof_failed_segment_index=proof.failed_segment_index,
            proof_forward_reachable_left_source_indices=(
                proof.forward_reachable_left_source_indices
            ),
            proof_left_valid_source_indices=proof.left_valid_source_indices,
            proof_right_valid_source_indices=proof.right_valid_source_indices,
            proof_local_nonsevere_edge_count=(
                proof.local_nonsevere_edge_count
            ),
        )
        profiles.append(
            _DirectFullFramePartitionProfile(
                profile_id=(
                    f"boundary-{boundary_index}-merge-{merged_count}"
                    if not parent.boundary_shifts
                    and not parent.window_redistributions
                    and not parent.boundary_merges
                    else (
                        f"{parent.profile_id}__merge-{boundary_index}-"
                        f"{merged_count}"
                    )
                ),
                unit_counts=signature,
                spans=spans,
                boundary_shifts=parent.boundary_shifts,
                window_redistributions=parent.window_redistributions,
                visual_frontier_splits=parent.visual_frontier_splits,
                boundary_merges=parent.boundary_merges + (merge,),
                latest_operation_kind="boundary_merge",
            )
        )
    return tuple(profiles)


def _direct_full_frame_proof_directed_window_profiles(
    timing_segments: Sequence[DraftSegment],
    parent: _DirectFullFramePartitionProfile,
    diagnostics: dict[str, Any],
) -> tuple[_DirectFullFramePartitionProfile, ...]:
    """Redistribute two cuts across three spans around an exact frontier.

    This operator is reached only after every cadence-valid placement inside
    the proved two-span window has been fully selected and rejected.  It keeps
    the surrounding three-span range and both cut counts fixed, moves the
    proved cut plus one previously untouched adjacent cut, and enumerates only
    existing timing-unit boundaries.  Every child is materialized through the
    ordinary duration/cadence gates here and the complete visual selector in
    the caller; no severe edge or visual threshold is relaxed.
    """

    if (
        parent.visual_frontier_splits
        or parent.proof_directed_boundary_motion_count + 2
        > _direct_partition_proof_directed_boundary_shift_limit(parent)
    ):
        return ()
    proofs = tuple(
        proof
        for proof in _direct_partition_exact_shift_proofs(
            diagnostics,
            span_count=len(parent.spans),
        )
        if proof.trigger
        == "proven_forward_connectivity_frontier_exhaustion"
    )
    if not proofs:
        return ()

    items = tuple(timing_segments)
    used_moved_boundaries = set(
        _direct_partition_current_shifted_boundary_indices(parent)
    )
    seen_signatures: set[tuple[int, ...]] = set()
    profiles: list[_DirectFullFramePartitionProfile] = []
    for proof in proofs:
        frontier = proof.boundary_index
        window_starts = tuple(
            start
            for start in (frontier, frontier - 1)
            if 0 <= start and start + 2 < len(parent.unit_counts)
        )
        for window_start in window_starts:
            adjacent_boundary_index = (
                window_start + 1
                if frontier == window_start
                else window_start
            )
            if adjacent_boundary_index in used_moved_boundaries:
                continue
            original = tuple(
                int(value)
                for value in parent.unit_counts[
                    window_start : window_start + 3
                ]
            )
            if len(original) != 3:
                continue
            original_first_boundary_units = original[0]
            original_second_boundary_units = original[0] + original[1]
            total_units = sum(original)
            for first_count in range(1, total_units - 1):
                for second_count in range(1, total_units - first_count):
                    third_count = total_units - first_count - second_count
                    replacement = (
                        first_count,
                        second_count,
                        third_count,
                    )
                    if replacement == original:
                        continue
                    if (
                        first_count == original_first_boundary_units
                        or first_count + second_count
                        == original_second_boundary_units
                    ):
                        # A three-span repair must move both cuts.  Single-cut
                        # placements were exhausted by the preceding operator.
                        continue
                    counts = list(parent.unit_counts)
                    counts[window_start : window_start + 3] = replacement
                    signature = tuple(counts)
                    if signature in seen_signatures:
                        continue
                    try:
                        spans = _direct_full_frame_spans_from_partition(
                            items,
                            signature,
                        )
                    except ValueError:
                        continue
                    if (
                        min(
                            span.duration_seconds
                            for span in spans[
                                window_start : window_start + 3
                            ]
                        )
                        + 1e-9
                        < _DIRECT_MEMBER_HIGHLIGHT_MINIMUM_RUN_SECONDS
                    ):
                        continue
                    duration = sum(span.duration_seconds for span in spans)
                    switches_per_minute = (len(spans) - 1) * 60.0 / duration
                    span_median = median(
                        span.duration_seconds for span in spans
                    )
                    if not (
                        _DIRECT_MEMBER_MIN_SWITCHES_PER_MINUTE
                        <= switches_per_minute
                        <= _DIRECT_MEMBER_MAX_SWITCHES_PER_MINUTE
                        and _direct_member_median_run_is_valid(
                            duration,
                            span_median,
                        )
                    ):
                        continue
                    first_unit_end = sum(signature[: window_start + 1])
                    second_unit_end = sum(signature[: window_start + 2])
                    replacement_reasons = (
                        items[first_unit_end - 1].end_boundary_reasons,
                        items[second_unit_end - 1].end_boundary_reasons,
                    )
                    redistribution = (
                        _DirectFullFrameProofDirectedWindowRedistribution(
                            window_start_span_index=window_start,
                            proof_frontier_boundary_index=frontier,
                            proof_frontier_offset_in_window=(
                                frontier - window_start
                            ),
                            original_unit_counts=original,
                            replacement_unit_counts=replacement,
                            original_boundary_master_seconds=(
                                parent.spans[
                                    window_start
                                ].canonical_master_end,
                                parent.spans[
                                    window_start + 1
                                ].canonical_master_end,
                            ),
                            replacement_boundary_master_seconds=(
                                spans[window_start].canonical_master_end,
                                spans[
                                    window_start + 1
                                ].canonical_master_end,
                            ),
                            replacement_boundary_reasons=(
                                tuple(replacement_reasons[0]),
                                tuple(replacement_reasons[1]),
                            ),
                            trigger=(
                                "proven_forward_connectivity_frontier_"
                                "three_span_redistribution"
                            ),
                            parent_profile_id=parent.profile_id,
                            parent_partition_signature_sha256=(
                                _direct_partition_signature_sha256(
                                    parent.unit_counts
                                )
                            ),
                            proof_failure=proof.failure,
                            proof_failed_segment_index=(
                                proof.failed_segment_index
                            ),
                            proof_forward_reachable_left_source_indices=(
                                proof.forward_reachable_left_source_indices
                            ),
                            proof_left_valid_source_indices=(
                                proof.left_valid_source_indices
                            ),
                            proof_right_valid_source_indices=(
                                proof.right_valid_source_indices
                            ),
                            proof_local_nonsevere_edge_count=(
                                proof.local_nonsevere_edge_count
                            ),
                        )
                    )
                    profiles.append(
                        _DirectFullFramePartitionProfile(
                            profile_id=(
                                f"{parent.profile_id}__window-{window_start}-"
                                f"{first_count}-plus-{second_count}-plus-"
                                f"{third_count}"
                            ),
                            unit_counts=signature,
                            spans=spans,
                            boundary_shifts=parent.boundary_shifts,
                            window_redistributions=(
                                parent.window_redistributions
                                + (redistribution,)
                            ),
                            visual_frontier_splits=(
                                parent.visual_frontier_splits
                            ),
                            boundary_merges=parent.boundary_merges,
                            latest_operation_kind="window_redistribution",
                        )
                    )
                    seen_signatures.add(signature)
    profiles.sort(
        key=lambda profile: (
            profile.window_redistributions[-1].boundary_displacement_units,
            profile.musical_boundary_penalty,
            profile.profile_id,
        )
    )
    return tuple(profiles)


def _direct_visual_split_sample_is_hard_safe_proposal_point(
    sample: dict[str, Any],
    *,
    quality_score: Any,
    lighting_rescue_applied: bool,
    config: DirectMemberVisualConfig,
) -> bool:
    """Recognize a strict sampled safe point without inferring identity.

    This is proposal evidence only.  It cannot make a source/span valid; the
    child partition is always sent through the complete selector again.
    """

    if sample.get("descriptor_available") is not True:
        return False
    human = bool(
        sample.get("attention_basis") is not None
        or int(sample.get("face_count", 0)) > 0
        or int(sample.get("detected_person_count", 0)) > 0
        or int(sample.get("formation_person_count", 0)) > 0
        or float(sample.get("silhouette_confidence", 0.0))
        >= config.minimum_silhouette_confidence
    )
    if not human:
        return False
    obstruction = sample.get("foreground_obstruction_score")
    if not isinstance(obstruction, (int, float)) or not math.isfinite(
        float(obstruction)
    ):
        return False
    if float(obstruction) >= config.foreground_obstruction_rejection_score:
        return False
    if lighting_rescue_applied:
        return True
    return bool(
        isinstance(quality_score, (int, float))
        and math.isfinite(float(quality_score))
        and float(quality_score) >= config.minimum_acceptable_quality_score
    )


def _direct_severe_counterfactual_retry_is_authorized(
    diagnostics: Mapping[str, Any],
    *,
    span_count: int,
) -> bool:
    """Accept only an integrity-bound, non-authoritative exact witness.

    The witness may propose one more timing partition, but it can never select
    a source path or relax a visual/transition gate.  Keeping this validation
    in the pipeline prevents a partial or stale diagnostic payload from
    silently expanding the production search.
    """

    if span_count < 3 or not _direct_partition_failure_is_proven(dict(diagnostics)):
        return False
    if diagnostics.get("constraint_infeasibility_proven") is not True:
        return False
    search = diagnostics.get("search")
    if not isinstance(search, dict):
        return False
    exact = search.get("exact_lifeline")
    if not isinstance(exact, dict) or not (
        exact.get("invoked") is True
        and exact.get("state_capacity_exhausted") is False
        and exact.get("duration_state_quantization_applied") is False
    ):
        return False
    counterfactual = search.get("severe_transition_counterfactual")
    if not isinstance(counterfactual, dict) or not (
        counterfactual.get("contract")
        == "diagnostic_only_severe_transition_counterfactual_v1"
        and counterfactual.get("optimization_contract")
        == (
            "exact_iterative_deepening_minimum_severe_transition_count_"
            "then_deterministic_backward_source_order_v1"
        )
        and counterfactual.get("severe_transition_cost_policy")
        == "one_per_adjacent_transition_with_any_original_severe_flag"
        and counterfactual.get("tie_break_contract")
        == (
            "final_source_order_then_reverse_predecessor_"
            "severe_cost_mismatch_cost_source_order_v1"
        )
        and counterfactual.get("invoked") is True
        and counterfactual.get("witness_found") is True
        and counterfactual.get("integrity_check_passed") is True
        and counterfactual.get("optimality_proven") is True
        and counterfactual.get("minimum_severe_transition_count") == 1
        and counterfactual.get(
            "production_single_split_proposal_authorized"
        ) is True
        and counterfactual.get("maximum_diagnostic_severe_transition_budget")
        == 3
        and counterfactual.get("state_capacity_exhausted") is False
        and counterfactual.get("duration_state_quantization_applied") is False
        and counterfactual.get("constraint_infeasibility_proven") is False
        and counterfactual.get("severe_transition_flags_disabled") is True
        and counterfactual.get("original_matrices_mutated") is False
        and counterfactual.get("selection_eligible") is False
        and counterfactual.get("render_authorized") is False
        and counterfactual.get("visual_gates_relaxed") is False
    ):
        return False
    unchanged_markers = (
        "candidate_validity_semantics_changed",
        "source_quota_semantics_changed",
        "exact_duration_semantics_changed",
        "source_order_semantics_changed",
        "no_adjacent_repeat_semantics_changed",
    )
    if any(counterfactual.get(name) is not False for name in unchanged_markers):
        return False

    digest_names = (
        "original_hard_constraint_sha256",
        "original_failure_certificate_sha256",
        "severe_disabled_hard_constraint_sha256",
        "severe_transition_budget_mask_sha256",
        "severe_disabled_witness_sha256",
        "minimum_witness_path_sha256",
    )
    digests = tuple(counterfactual.get(name) for name in digest_names)
    if any(
        not isinstance(value, str)
        or len(value) != 64
        or any(character not in "0123456789abcdef" for character in value)
        for value in digests
    ):
        return False
    if digests[0] == digests[2] or digests[4] != digests[5]:
        return False

    zero_budget = counterfactual.get("zero_budget_hard_proof")
    lower_budget_proofs = counterfactual.get("lower_budget_hard_proofs")
    budget_attempts = counterfactual.get("budget_attempts")
    if not (
        isinstance(zero_budget, dict)
        and zero_budget.get("severe_transition_budget") == 0
        and zero_budget.get("path_found") is False
        and zero_budget.get("state_capacity_exhausted") is False
        and zero_budget.get("constraint_infeasibility_proven") is True
        and zero_budget.get("duration_state_quantization_applied") is False
        and zero_budget.get("certificate_sha256") == digests[1]
        and isinstance(lower_budget_proofs, list)
        and len(lower_budget_proofs) == 1
        and lower_budget_proofs[0] == zero_budget
        and isinstance(budget_attempts, list)
        and len(budget_attempts) == 1
    ):
        return False
    minimum_attempt = budget_attempts[0]
    if not (
        isinstance(minimum_attempt, dict)
        and minimum_attempt.get("severe_transition_budget") == 1
        and minimum_attempt.get("path_found") is True
        and minimum_attempt.get("state_capacity_exhausted") is False
        and minimum_attempt.get("constraint_infeasibility_proven") is False
        and minimum_attempt.get("duration_state_quantization_applied") is False
        and isinstance(minimum_attempt.get("explored_state_count"), int)
        and minimum_attempt["explored_state_count"] > 0
        and isinstance(minimum_attempt.get("memoized_failed_state_count"), int)
        and minimum_attempt["memoized_failed_state_count"] >= 0
        and isinstance(minimum_attempt.get("certificate_sha256"), str)
        and len(minimum_attempt["certificate_sha256"]) == 64
        and all(
            character in "0123456789abcdef"
            for character in minimum_attempt["certificate_sha256"]
        )
        and isinstance(counterfactual.get("state_limit_per_budget"), int)
        and counterfactual["state_limit_per_budget"] > 0
    ):
        return False

    raw_indices = counterfactual.get("blocking_boundary_indices")
    raw_transitions = counterfactual.get("blocking_transitions")
    if not isinstance(raw_indices, list) or not isinstance(raw_transitions, list):
        return False
    indices = tuple(raw_indices)
    if (
        not indices
        or indices != tuple(sorted(set(indices)))
        or any(
            isinstance(value, bool)
            or not isinstance(value, int)
            or not 0 <= value < span_count - 1
            for value in indices
        )
    ):
        return False
    transition_indices: list[int] = []
    for transition in raw_transitions:
        if not isinstance(transition, dict):
            return False
        boundary_index = transition.get("boundary_index")
        outgoing = transition.get("outgoing_eligible_source_index")
        incoming = transition.get("incoming_eligible_source_index")
        flags = transition.get("original_severe_flags")
        if not (
            isinstance(boundary_index, int)
            and not isinstance(boundary_index, bool)
            and boundary_index in indices
            and isinstance(outgoing, int)
            and not isinstance(outgoing, bool)
            and outgoing >= 0
            and isinstance(incoming, int)
            and not isinstance(incoming, bool)
            and incoming >= 0
            and outgoing != incoming
            and isinstance(flags, list)
            and flags
            and all(isinstance(flag, str) and flag for flag in flags)
        ):
            return False
        transition_indices.append(boundary_index)
    if (
        tuple(sorted(set(transition_indices))) != indices
        or len(raw_transitions) != 1
        or len(indices) != 1
    ):
        return False
    maximum_deviation = counterfactual.get("maximum_duration_relative_deviation")
    return bool(
        isinstance(maximum_deviation, (int, float))
        and not isinstance(maximum_deviation, bool)
        and math.isfinite(float(maximum_deviation))
        and float(maximum_deviation) >= 0.0
    )


def _direct_counterfactual_boundary_proof(
    diagnostics: Mapping[str, Any],
    *,
    boundary_index: int,
    span_count: int,
) -> _DirectPartitionBoundaryProof | None:
    """Bind one severe-only witness edge to live hard-connectivity evidence."""

    if not _direct_severe_counterfactual_retry_is_authorized(
        diagnostics,
        span_count=span_count,
    ):
        return None
    search = diagnostics["search"]
    counterfactual = search["severe_transition_counterfactual"]
    if boundary_index not in counterfactual["blocking_boundary_indices"]:
        return None
    transitions = tuple(
        item
        for item in counterfactual["blocking_transitions"]
        if item["boundary_index"] == boundary_index
    )
    outgoing_sources = tuple(
        sorted({int(item["outgoing_eligible_source_index"]) for item in transitions})
    )
    incoming_sources = tuple(
        sorted({int(item["incoming_eligible_source_index"]) for item in transitions})
    )
    connectivity = diagnostics.get("hard_boundary_connectivity")
    if not isinstance(connectivity, dict) or connectivity.get(
        "analysis_basis"
    ) != "content_valid_nonsevere_no_repeat_reachability_v1":
        return None
    boundaries = connectivity.get("boundaries")
    if not isinstance(boundaries, list) or len(boundaries) != span_count - 1:
        return None
    item = boundaries[boundary_index]
    if not isinstance(item, dict) or item.get("boundary_index") != boundary_index:
        return None
    left_valid = item.get("left_valid_source_indices")
    right_valid = item.get("right_valid_source_indices")
    forward_reachable = item.get("forward_reachable_left_source_indices")
    local_edges = item.get("nonsevere_cross_source_edge_count")
    if not (
        isinstance(left_valid, list)
        and left_valid
        and all(
            isinstance(value, int) and not isinstance(value, bool) and value >= 0
            for value in left_valid
        )
        and isinstance(right_valid, list)
        and right_valid
        and all(
            isinstance(value, int) and not isinstance(value, bool) and value >= 0
            for value in right_valid
        )
        and isinstance(forward_reachable, list)
        and forward_reachable
        and all(
            isinstance(value, int) and not isinstance(value, bool) and value >= 0
            for value in forward_reachable
        )
        and isinstance(local_edges, int)
        and not isinstance(local_edges, bool)
        and local_edges >= 0
        and outgoing_sources
        and incoming_sources
        and set(outgoing_sources).issubset(left_valid)
        and set(outgoing_sources).issubset(forward_reachable)
        and set(incoming_sources).issubset(right_valid)
    ):
        return None
    return _DirectPartitionBoundaryProof(
        boundary_index=boundary_index,
        trigger="diagnostic_severe_transition_counterfactual_safe_bracket",
        failure=(
            str(diagnostics["failure"])
            if diagnostics.get("failure") is not None
            else None
        ),
        failed_segment_index=boundary_index + 1,
        forward_reachable_left_source_indices=tuple(
            int(value) for value in forward_reachable
        ),
        left_valid_source_indices=tuple(int(value) for value in left_valid),
        right_valid_source_indices=tuple(int(value) for value in right_valid),
        local_nonsevere_edge_count=local_edges,
    )


def _direct_full_frame_visual_frontier_split_child_profiles(
    timing_segments: Sequence[DraftSegment],
    parent: _DirectFullFramePartitionProfile,
    diagnostics: dict[str, Any],
    *,
    config: DirectMemberVisualConfig,
    allow_counterfactual_secondary_split: bool = False,
    _counterfactual_boundary_index: int | None = None,
) -> tuple[_DirectFullFramePartitionProfile, ...]:
    """Add one evidence-bound micro-boundary beside a proven path frontier.

    Native-cut timestamps are exact master-time events.  Sample-derived visual
    interval edges are deliberately represented only as brackets: no midpoint
    is promoted to an exact edge.  The selected cut is an existing timing-unit
    boundary inside that bracket (or within the local half-unit snap domain of
    an exact native cut).  This operator never admits content itself; the full
    content, native-cut, severe-edge, quota, duration, and transition selector
    is rerun for the child.
    """

    secondary_counterfactual = bool(
        allow_counterfactual_secondary_split
        and len(parent.visual_frontier_splits)
        == _DIRECT_MEMBER_COUNTERFACTUAL_SECONDARY_SPLIT_TRIGGER_COUNT
        and _direct_severe_counterfactual_retry_is_authorized(
            diagnostics,
            span_count=len(parent.spans),
        )
    )
    if len(parent.visual_frontier_splits) >= (
        _DIRECT_MEMBER_MAX_VISUAL_FRONTIER_SPLITS_PER_PROFILE
        + int(secondary_counterfactual)
    ):
        return ()
    if secondary_counterfactual and _counterfactual_boundary_index is None:
        counterfactual = diagnostics["search"][
            "severe_transition_counterfactual"
        ]
        for boundary_index in counterfactual["blocking_boundary_indices"]:
            children = _direct_full_frame_visual_frontier_split_child_profiles(
                timing_segments,
                parent,
                diagnostics,
                config=config,
                allow_counterfactual_secondary_split=True,
                _counterfactual_boundary_index=boundary_index,
            )
            if children:
                return children
        return ()
    if secondary_counterfactual:
        if _counterfactual_boundary_index is None:
            return ()
        proof = _direct_counterfactual_boundary_proof(
            diagnostics,
            boundary_index=_counterfactual_boundary_index,
            span_count=len(parent.spans),
        )
        if proof is None:
            return ()
    else:
        proofs = tuple(
            proof
            for proof in _direct_partition_exact_shift_proofs(
                diagnostics,
                span_count=len(parent.spans),
            )
            if proof.trigger == "proven_forward_connectivity_frontier_exhaustion"
        )
        if len(proofs) != 1:
            return ()
        proof = proofs[0]
    if proof.failed_segment_index != proof.boundary_index + 1:
        return ()

    raw_span_diagnostics = diagnostics.get("span_content_validity")
    if not isinstance(raw_span_diagnostics, list):
        return ()
    span_diagnostics = {
        int(raw["segment_index"]): raw
        for raw in raw_span_diagnostics
        if isinstance(raw, dict)
        and isinstance(raw.get("segment_index"), int)
    }
    items = tuple(timing_segments)
    if not items:
        return ()

    # One exact frontier may split only its incoming span or its immediately
    # outgoing neighbor.  The incoming side is preferred because it creates a
    # bridge after the proved forward frontier without perturbing normal spans.
    adjacent_span_indices = (
        proof.boundary_index + 1,
        proof.boundary_index,
    )
    proposals: list[
        tuple[
            tuple[float | int, ...],
            int,
            int,
            float,
            tuple[str, ...],
            str,
            tuple[int, ...],
            tuple[float, ...],
            tuple[float, float] | None,
        ]
    ] = []
    for side_rank, span_index in enumerate(adjacent_span_indices):
        if not 0 <= span_index < len(parent.unit_counts):
            continue
        unit_count = parent.unit_counts[span_index]
        if unit_count < 2:
            continue
        raw_span = span_diagnostics.get(span_index)
        if not isinstance(raw_span, dict):
            continue
        span = parent.spans[span_index]
        if not (
            math.isclose(
                float(raw_span.get("canonical_master_start", math.nan)),
                span.canonical_master_start,
                rel_tol=0.0,
                abs_tol=1e-7,
            )
            and math.isclose(
                float(raw_span.get("canonical_master_end", math.nan)),
                span.canonical_master_end,
                rel_tol=0.0,
                abs_tol=1e-7,
            )
        ):
            continue
        raw_sources = raw_span.get("sources")
        if not isinstance(raw_sources, list):
            continue

        exact_native_events: list[tuple[float, int]] = []
        sample_brackets: list[tuple[float, float, int]] = []
        hard_valid_sources: list[int] = []
        hard_valid_sample_ranges: list[tuple[float, float, int]] = []
        for raw_source in raw_sources:
            if not isinstance(raw_source, dict) or not isinstance(
                raw_source.get("eligible_source_index"),
                int,
            ):
                continue
            source_index = int(raw_source["eligible_source_index"])
            raw_cuts = raw_source.get("native_scene_cut_master_seconds", ())
            if isinstance(raw_cuts, list):
                exact_native_events.extend(
                    (float(value), source_index)
                    for value in raw_cuts
                    if isinstance(value, (int, float))
                    and math.isfinite(float(value))
                    and span.canonical_master_start
                    < float(value)
                    < span.canonical_master_end
                )
            samples = raw_source.get("samples")
            quality = raw_source.get("quality_sample_scores")
            if not isinstance(samples, list) or not isinstance(quality, list):
                continue
            if len(samples) != len(quality) or len(samples) < 2:
                continue
            lighting_rescue = bool(
                raw_source.get(
                    "portrait_fancam_lighting_quality_rescue_applied",
                    False,
                )
            )
            safe_flags = [
                _direct_visual_split_sample_is_hard_safe_proposal_point(
                    sample,
                    quality_score=quality[index],
                    lighting_rescue_applied=lighting_rescue,
                    config=config,
                )
                if isinstance(sample, dict)
                else False
                for index, sample in enumerate(samples)
            ]
            sample_times = [
                float(sample.get("canonical_master_seconds", math.nan))
                if isinstance(sample, dict)
                else math.nan
                for sample in samples
            ]
            if (
                all(math.isfinite(value) for value in sample_times)
                and all(
                    span.canonical_master_start - 1e-9
                    <= value
                    <= span.canonical_master_end + 1e-9
                    for value in sample_times
                )
                and all(
                    right > left
                    for left, right in zip(sample_times, sample_times[1:])
                )
            ):
                for sample_index in range(len(samples) - 1):
                    if safe_flags[sample_index] == safe_flags[sample_index + 1]:
                        continue
                    left_time, right_time = sorted(
                        (sample_times[sample_index], sample_times[sample_index + 1])
                    )
                    sample_brackets.append(
                        (left_time, right_time, source_index)
                    )
                if raw_source.get("valid") is True and all(safe_flags):
                    hard_valid_sources.append(source_index)
                    hard_valid_sample_ranges.append(
                        (sample_times[0], sample_times[-1], source_index)
                    )

        unit_cursor = sum(parent.unit_counts[:span_index])
        internal_boundaries: list[
            tuple[int, float, tuple[str, ...], float]
        ] = []
        for split_offset in range(1, unit_count):
            left_item = items[unit_cursor + split_offset - 1]
            right_item = items[unit_cursor + split_offset]
            boundary_seconds = left_item.canonical_master_end
            left_duration = (
                left_item.canonical_master_end
                - left_item.canonical_master_start
            )
            right_duration = (
                right_item.canonical_master_end
                - right_item.canonical_master_start
            )
            snap_tolerance = 0.5 * min(left_duration, right_duration)
            internal_boundaries.append(
                (
                    split_offset,
                    boundary_seconds,
                    left_item.end_boundary_reasons,
                    snap_tolerance,
                )
            )

        def _boundary_reason_penalty(reasons: Sequence[str]) -> int:
            values = set(reasons)
            if "phrase" in values:
                return 0
            if "strong_beat" in values:
                return 1
            if "beat" in values:
                return 2
            return 3

        for split_offset, boundary_seconds, reasons, snap_tolerance in (
            internal_boundaries
        ):
            left_count = split_offset
            right_count = unit_count - split_offset
            if (
                min(
                    boundary_seconds - span.canonical_master_start,
                    span.canonical_master_end - boundary_seconds,
                )
                + 1e-9
                < _DIRECT_MEMBER_HIGHLIGHT_MINIMUM_RUN_SECONDS
            ):
                continue
            one_unit_penalty = int(min(left_count, right_count) < 2)
            reason_penalty = _boundary_reason_penalty(reasons)
            native_matches = [
                (abs(boundary_seconds - event_seconds), event_seconds, source_index)
                for event_seconds, source_index in exact_native_events
                if abs(boundary_seconds - event_seconds)
                <= snap_tolerance + 1e-9
            ]
            if native_matches:
                distance, event_seconds, source_index = min(native_matches)
                proposals.append(
                    (
                        (
                            0,
                            distance,
                            reason_penalty,
                            one_unit_penalty,
                            side_rank,
                            boundary_seconds,
                        ),
                        span_index,
                        split_offset,
                        boundary_seconds,
                        reasons,
                        "confirmed_source_native_cut_master_time_snap",
                        (source_index,),
                        (event_seconds,),
                        None,
                    )
                )
                continue
            bracket_matches = [
                (left, right, source_index)
                for left, right, source_index in sample_brackets
                if left - 1e-9 <= boundary_seconds <= right + 1e-9
            ]
            if bracket_matches:
                left, right, source_index = min(
                    bracket_matches,
                    key=lambda value: (
                        abs(boundary_seconds - (value[0] + value[1]) / 2.0),
                        value[2],
                    ),
                )
                proposals.append(
                    (
                        (
                            1,
                            abs(boundary_seconds - (left + right) / 2.0),
                            reason_penalty,
                            one_unit_penalty,
                            side_rank,
                            boundary_seconds,
                        ),
                        span_index,
                        split_offset,
                        boundary_seconds,
                        reasons,
                        "sample_hard_safety_change_bracket",
                        (source_index,),
                        (),
                        (left, right),
                    )
                )
                continue

            # A globally exhausted frontier can need an intermediate source
            # even when every candidate is content-valid.  Use only the
            # complete hard-valid sample range and require a candidate outside
            # the current forward source set; this is still proposal evidence,
            # never permission to cross a severe edge.
            bridge_sources = sorted(
                set(hard_valid_sources)
                .intersection(proof.right_valid_source_indices)
                .difference(proof.forward_reachable_left_source_indices)
            )
            safe_ranges = [
                (left, right, source_index)
                for left, right, source_index in hard_valid_sample_ranges
                if source_index in bridge_sources
                and left - 1e-9 <= boundary_seconds <= right + 1e-9
            ]
            if proof.forward_reachable_left_source_indices and safe_ranges:
                left = max(value[0] for value in safe_ranges)
                right = min(value[1] for value in safe_ranges)
                if left <= boundary_seconds <= right:
                    proposals.append(
                        (
                            (
                                2,
                                reason_penalty,
                                one_unit_penalty,
                                abs(boundary_seconds - (left + right) / 2.0),
                                side_rank,
                                boundary_seconds,
                            ),
                            span_index,
                            split_offset,
                            boundary_seconds,
                            reasons,
                            "hard_valid_bridge_source_entry_exit_bracket",
                            tuple(
                                sorted(
                                    set(
                                        proof.forward_reachable_left_source_indices
                                    ).union(bridge_sources)
                                )
                            ),
                            (),
                            (left, right),
                        )
                    )

    if not proposals:
        return ()
    (
        _score,
        span_index,
        split_offset,
        boundary_seconds,
        boundary_reasons,
        evidence_kind,
        evidence_source_indices,
        evidence_master_seconds,
        evidence_bracket,
    ) = min(proposals, key=lambda item: item[0])
    original_count = parent.unit_counts[span_index]
    left_count = split_offset
    right_count = original_count - split_offset
    counts = list(parent.unit_counts)
    counts[span_index : span_index + 1] = [left_count, right_count]
    signature = tuple(counts)
    try:
        spans = _direct_full_frame_spans_from_partition(items, signature)
    except ValueError:
        return ()
    if (
        min(
            spans[span_index].duration_seconds,
            spans[span_index + 1].duration_seconds,
        )
        + 1e-9
        < _DIRECT_MEMBER_HIGHLIGHT_MINIMUM_RUN_SECONDS
    ):
        return ()
    duration = sum(span.duration_seconds for span in spans)
    switches_per_minute = (len(spans) - 1) * 60.0 / duration
    span_median = median(span.duration_seconds for span in spans)
    if not (
        _DIRECT_MEMBER_MIN_SWITCHES_PER_MINUTE
        <= switches_per_minute
        <= _DIRECT_MEMBER_MAX_SWITCHES_PER_MINUTE
        and _direct_member_median_run_is_valid(duration, span_median)
    ):
        return ()
    split = _DirectFullFrameVisualFrontierSplit(
        parent_span_index=span_index,
        split_unit_offset=split_offset,
        left_unit_count=left_count,
        right_unit_count=right_count,
        canonical_master_seconds=boundary_seconds,
        boundary_reasons=boundary_reasons,
        trigger=(
            "diagnostic_severe_counterfactual_visual_micro_split"
            if secondary_counterfactual
            else "proven_forward_connectivity_frontier_visual_micro_split"
        ),
        parent_profile_id=parent.profile_id,
        parent_partition_signature_sha256=(
            _direct_partition_signature_sha256(parent.unit_counts)
        ),
        proof_failure=proof.failure,
        proof_failed_segment_index=proof.failed_segment_index,
        proof_frontier_boundary_index=proof.boundary_index,
        proof_forward_reachable_left_source_indices=(
            proof.forward_reachable_left_source_indices
        ),
        proof_right_valid_source_indices=proof.right_valid_source_indices,
        evidence_contract=(
            "diagnostic_severe_counterfactual_bound_existing_timing_boundary_v1"
            if secondary_counterfactual
            else "visual_bracket_bound_existing_timing_boundary_v1"
        ),
        evidence_kind=evidence_kind,
        evidence_source_indices=evidence_source_indices,
        evidence_master_seconds=evidence_master_seconds,
        evidence_bracket_master_seconds=evidence_bracket,
    )
    return (
        _DirectFullFramePartitionProfile(
            profile_id=(
                f"{parent.profile_id}__visual-split-{span_index}-"
                f"{left_count}-plus-{right_count}"
            ),
            unit_counts=signature,
            spans=spans,
            boundary_shifts=parent.boundary_shifts,
            window_redistributions=parent.window_redistributions,
            visual_frontier_splits=parent.visual_frontier_splits + (split,),
            boundary_merges=parent.boundary_merges,
            latest_operation_kind="visual_frontier_split",
        ),
    )


def _direct_full_frame_proof_directed_repair_profiles(
    timing_segments: Sequence[DraftSegment],
    parent: _DirectFullFramePartitionProfile,
    diagnostics: dict[str, Any],
    *,
    config: DirectMemberVisualConfig,
) -> tuple[_DirectFullFramePartitionProfile, ...]:
    """Continue an exact frontier repair without leaving a dead-end gap.

    Boundary shifts remain the least structural repair. If every two-span
    placement is exhausted, an evidence-bound musical boundary is more local
    than redistributing unrelated neighboring cuts and is tried next. A wider
    fixed-count redistribution follows, while a merge is terminal because it
    removes a visible cut and can violate the final density contract. Every
    returned child is fully reselected by the caller.
    """

    children = _direct_full_frame_proof_directed_child_profiles(
        timing_segments,
        parent,
        diagnostics,
    )
    if not children:
        children = _direct_full_frame_visual_frontier_split_child_profiles(
            timing_segments,
            parent,
            diagnostics,
            config=config,
        )
    if not children:
        children = _direct_full_frame_proof_directed_window_profiles(
            timing_segments,
            parent,
            diagnostics,
        )
    if not children:
        children = _direct_full_frame_proof_directed_merge_profiles(
            timing_segments,
            parent,
            diagnostics,
        )
    return children


def _render_cadence_payload(
    segments: Sequence[RenderSegment],
) -> dict[str, Any]:
    items = tuple(segments)
    if not items:
        raise ValueError("render cadence needs at least one segment")
    run_durations: list[float] = []
    current_source = items[0].source_index
    current_duration = 0.0
    switch_count = 0
    for item in items:
        if item.source_index != current_source:
            run_durations.append(current_duration)
            current_source = item.source_index
            current_duration = 0.0
            switch_count += 1
        current_duration += item.duration
    run_durations.append(current_duration)
    duration = sum(item.duration for item in items)
    median_run_bounds = _direct_member_median_run_bounds(duration)
    return {
        "source_switch_count": switch_count,
        "source_switches_per_minute": switch_count * 60.0 / duration,
        "source_run_count": len(run_durations),
        "source_run_median_seconds": median(run_durations),
        "longest_source_run_seconds": max(run_durations),
        "target_source_switches_per_minute": [
            _DIRECT_MEMBER_MIN_SWITCHES_PER_MINUTE,
            _DIRECT_MEMBER_MAX_SWITCHES_PER_MINUTE,
        ],
        "target_source_run_median_seconds": [
            median_run_bounds[0],
            median_run_bounds[1],
        ],
        "maximum_source_run_seconds": _DIRECT_MEMBER_MAX_RUN_SECONDS,
    }


def _direct_member_maximum_hold_count_for_global_cadence(
    *,
    boundary_count: int,
    total_duration_seconds: float,
) -> int:
    """Return the no-cut budget that still meets the final visible-cut gate."""

    if (
        isinstance(boundary_count, bool)
        or not isinstance(boundary_count, int)
        or boundary_count < 0
    ):
        raise ValueError("direct member boundary count is invalid")
    if (
        not math.isfinite(total_duration_seconds)
        or total_duration_seconds <= 0.0
    ):
        raise ValueError("direct member cadence duration is invalid")
    minimum_visible_switch_count = math.ceil(
        _DIRECT_MEMBER_MIN_SWITCHES_PER_MINUTE
        * total_duration_seconds
        / 60.0
        - 1e-9
    )
    return max(0, boundary_count - minimum_visible_switch_count)


def _direct_member_highlight_cadence_payload(
    *,
    spans: Sequence[_DirectFullFrameSpan],
    visual_selection: DirectMemberVisualSelection,
    highlight_intervals: Sequence[tuple[float, float]],
) -> dict[str, Any]:
    """Audit the exact selected cuts separately inside active sections."""

    items = tuple(spans)
    if not items:
        raise ValueError("highlight cadence audit needs direct-member spans")
    if len(visual_selection.source_indices) != len(items):
        raise ValueError("highlight cadence selection does not match spans")
    if len(visual_selection.boundaries) != len(items) - 1:
        raise ValueError("highlight cadence boundary count does not match spans")
    normalized = (
        _normalized_direct_member_highlight_intervals(
            highlight_intervals,
            range_start=items[0].canonical_master_start,
            range_end=items[-1].canonical_master_end,
        )
        if highlight_intervals
        else ()
    )
    total_duration = (
        items[-1].canonical_master_end - items[0].canonical_master_start
    )
    highlight_duration = sum(end - start for start, end in normalized)
    non_highlight_duration = max(0.0, total_duration - highlight_duration)
    highlight_boundary_indices = tuple(
        index
        for index, span in enumerate(items[:-1])
        if _direct_member_boundary_is_highlight(
            span.canonical_master_end,
            normalized,
        )
    )
    highlight_boundary_set = frozenset(highlight_boundary_indices)
    applied_cut_indices = tuple(
        index
        for index, boundary in enumerate(visual_selection.boundaries)
        if boundary.cut_applied
    )
    highlight_cut_indices = tuple(
        index for index in applied_cut_indices if index in highlight_boundary_set
    )
    highlight_moving_cut_indices = tuple(
        index
        for index in highlight_cut_indices
        if bool(
            getattr(
                getattr(
                    getattr(
                        visual_selection.boundaries[index],
                        "mismatch",
                        None,
                    ),
                    "motion_connection",
                    None,
                ),
                "both_moving",
                False,
            )
        )
    )
    non_highlight_cut_indices = tuple(
        index for index in applied_cut_indices if index not in highlight_boundary_set
    )
    highlight_hold_indices = tuple(
        index
        for index in highlight_boundary_indices
        if not visual_selection.boundaries[index].cut_applied
    )
    highlight_switches_per_minute = (
        len(highlight_cut_indices) * 60.0 / highlight_duration
        if highlight_duration > 1e-9
        else 0.0
    )
    non_highlight_switches_per_minute = (
        len(non_highlight_cut_indices) * 60.0 / non_highlight_duration
        if non_highlight_duration > 1e-9
        else 0.0
    )
    highlight_moving_cuts_per_minute = (
        len(highlight_moving_cut_indices) * 60.0 / highlight_duration
        if highlight_duration > 1e-9
        else 0.0
    )
    highlight_moving_cut_fraction = (
        len(highlight_moving_cut_indices) / len(highlight_cut_indices)
        if highlight_cut_indices
        else 0.0
    )

    highlight_gap_seconds: list[float] = []
    highlight_cut_times = tuple(
        items[index].canonical_master_end for index in highlight_cut_indices
    )
    for interval_start, interval_end in normalized:
        points = [interval_start]
        points.extend(
            value
            for value in highlight_cut_times
            if interval_start + 1e-7 < value < interval_end - 1e-7
        )
        points.append(interval_end)
        highlight_gap_seconds.extend(
            right - left
            for left, right in zip(points, points[1:])
            if right > left + 1e-9
        )

    source_runs: list[tuple[float, float]] = []
    run_start = items[0].canonical_master_start
    for boundary_index, boundary in enumerate(visual_selection.boundaries):
        if boundary.cut_applied:
            run_end = items[boundary_index].canonical_master_end
            source_runs.append((run_start, run_end))
            run_start = run_end
    source_runs.append((run_start, items[-1].canonical_master_end))
    highlight_run_overlaps = [
        overlap
        for run_start, run_end in source_runs
        for interval_start, interval_end in normalized
        if (
            overlap := max(
                0.0,
                min(run_end, interval_end) - max(run_start, interval_start),
            )
        )
        > 1e-9
    ]

    audit_required = (
        highlight_duration
        >= _DIRECT_MEMBER_HIGHLIGHT_MINIMUM_AUDIT_DURATION_SECONDS
    )
    failure_reasons: list[str] = []
    if audit_required:
        if (
            highlight_switches_per_minute
            + 1e-9
            < _DIRECT_MEMBER_HIGHLIGHT_MINIMUM_SWITCHES_PER_MINUTE
        ):
            failure_reasons.append("highlight_switch_density_below_minimum")
        if (
            non_highlight_duration
            >= _DIRECT_MEMBER_HIGHLIGHT_MINIMUM_AUDIT_DURATION_SECONDS
            and highlight_switches_per_minute + 1e-9
            < non_highlight_switches_per_minute
            + _DIRECT_MEMBER_HIGHLIGHT_MINIMUM_DENSITY_LIFT_PER_MINUTE
        ):
            failure_reasons.append("highlight_density_lift_below_minimum")
        if (
            len(highlight_hold_indices)
            > _DIRECT_MEMBER_MAXIMUM_COMPENSATED_HIGHLIGHT_HOLD_COUNT
        ):
            failure_reasons.append(
                "compensated_highlight_hold_budget_exceeded"
            )
        if (
            highlight_moving_cut_fraction + 1e-9
            < _DIRECT_MEMBER_HIGHLIGHT_MINIMUM_MOVING_CUT_FRACTION
        ):
            failure_reasons.append(
                "highlight_moving_cut_fraction_below_minimum"
            )
        if (
            highlight_moving_cuts_per_minute + 1e-9
            < _DIRECT_MEMBER_HIGHLIGHT_MINIMUM_MOVING_CUTS_PER_MINUTE
        ):
            failure_reasons.append(
                "highlight_moving_cut_density_below_minimum"
            )
    return {
        "contract": "human_like_section_aware_member_cut_density_v1",
        "audit_required": audit_required,
        "passed": not failure_reasons,
        "failure_reasons": failure_reasons,
        "highlight_intervals": [list(value) for value in normalized],
        "highlight_duration_seconds": highlight_duration,
        "non_highlight_duration_seconds": non_highlight_duration,
        "planned_highlight_boundary_count": len(highlight_boundary_indices),
        "actual_highlight_cut_count": len(highlight_cut_indices),
        "actual_highlight_moving_cut_count": len(
            highlight_moving_cut_indices
        ),
        "highlight_moving_cut_boundary_indices": list(
            highlight_moving_cut_indices
        ),
        "actual_non_highlight_cut_count": len(non_highlight_cut_indices),
        "highlight_no_cut_hold_count": len(highlight_hold_indices),
        "highlight_no_cut_hold_boundary_indices": list(highlight_hold_indices),
        "maximum_compensated_highlight_hold_count": (
            _DIRECT_MEMBER_MAXIMUM_COMPENSATED_HIGHLIGHT_HOLD_COUNT
        ),
        "highlight_holds_require_redundant_cut_density": True,
        "highlight_source_switches_per_minute": (
            highlight_switches_per_minute
        ),
        "non_highlight_source_switches_per_minute": (
            non_highlight_switches_per_minute
        ),
        "density_lift_per_minute": (
            highlight_switches_per_minute
            - non_highlight_switches_per_minute
        ),
        "highlight_moving_cuts_per_minute": (
            highlight_moving_cuts_per_minute
        ),
        "highlight_moving_cut_fraction": highlight_moving_cut_fraction,
        "minimum_highlight_source_switches_per_minute": (
            _DIRECT_MEMBER_HIGHLIGHT_MINIMUM_SWITCHES_PER_MINUTE
        ),
        "minimum_density_lift_per_minute": (
            _DIRECT_MEMBER_HIGHLIGHT_MINIMUM_DENSITY_LIFT_PER_MINUTE
        ),
        "minimum_highlight_moving_cut_fraction": (
            _DIRECT_MEMBER_HIGHLIGHT_MINIMUM_MOVING_CUT_FRACTION
        ),
        "minimum_highlight_moving_cuts_per_minute": (
            _DIRECT_MEMBER_HIGHLIGHT_MINIMUM_MOVING_CUTS_PER_MINUTE
        ),
        "target_highlight_run_seconds": [1.8, 2.6],
        "highlight_cut_gap_median_seconds": (
            median(highlight_gap_seconds) if highlight_gap_seconds else None
        ),
        "highlight_cut_gap_maximum_seconds": (
            max(highlight_gap_seconds) if highlight_gap_seconds else None
        ),
        "highlight_longest_source_run_seconds": (
            max(highlight_run_overlaps) if highlight_run_overlaps else 0.0
        ),
        "cut_times_use_existing_musical_boundaries": True,
        "visual_gates_relaxed": False,
    }


def _direct_member_highlight_partition_capacity_payload(
    *,
    spans: Sequence[_DirectFullFrameSpan],
    highlight_intervals: Sequence[tuple[float, float]],
) -> dict[str, Any]:
    """Prove whether a fixed partition can supply the minimum active cuts."""

    items = tuple(spans)
    if not items:
        raise ValueError("highlight partition capacity needs direct-member spans")
    normalized = (
        _normalized_direct_member_highlight_intervals(
            highlight_intervals,
            range_start=items[0].canonical_master_start,
            range_end=items[-1].canonical_master_end,
        )
        if highlight_intervals
        else ()
    )
    highlight_duration_seconds = sum(end - start for start, end in normalized)
    audit_required = (
        highlight_duration_seconds
        >= _DIRECT_MEMBER_HIGHLIGHT_MINIMUM_AUDIT_DURATION_SECONDS
    )
    priority_boundary_indices = (
        _direct_member_highlight_priority_boundary_indices(items, normalized)
    )
    minimum_required_cut_count = (
        math.ceil(
            highlight_duration_seconds
            * _DIRECT_MEMBER_HIGHLIGHT_MINIMUM_SWITCHES_PER_MINUTE
            / 60.0
            - 1e-9
        )
        if audit_required
        else 0
    )
    maximum_switches_per_minute = (
        len(priority_boundary_indices) * 60.0 / highlight_duration_seconds
        if highlight_duration_seconds > 1e-9
        else 0.0
    )
    passed = bool(
        not audit_required
        or len(priority_boundary_indices) >= minimum_required_cut_count
    )
    return {
        "contract": "fixed_partition_highlight_cut_capacity_v1",
        "audit_required": audit_required,
        "passed": passed,
        "failure": (
            None if passed else "highlight_partition_cut_capacity_exhausted"
        ),
        "highlight_intervals": [list(value) for value in normalized],
        "highlight_duration_seconds": highlight_duration_seconds,
        "priority_cut_boundary_indices": list(priority_boundary_indices),
        "planned_highlight_boundary_count": len(priority_boundary_indices),
        "minimum_required_highlight_cut_count": minimum_required_cut_count,
        "maximum_possible_highlight_switches_per_minute": (
            maximum_switches_per_minute
        ),
        "minimum_highlight_source_switches_per_minute": (
            _DIRECT_MEMBER_HIGHLIGHT_MINIMUM_SWITCHES_PER_MINUTE
        ),
        "assignment_independent": True,
        "partition_change_required_when_failed": True,
        "visual_gates_relaxed": False,
    }


def _enforce_direct_member_highlight_cadence_selection_gate(
    *,
    spans: Sequence[_DirectFullFrameSpan],
    visual_selection: DirectMemberVisualSelection,
    highlight_intervals: Sequence[tuple[float, float]],
) -> dict[str, Any]:
    """Reject a selected path before it can escape to the final render audit."""

    payload = _direct_member_highlight_cadence_payload(
        spans=spans,
        visual_selection=visual_selection,
        highlight_intervals=highlight_intervals,
    )
    visual_selection.optimizer_search_diagnostics[
        "highlight_cut_density"
    ] = payload
    if payload["passed"]:
        return payload
    hold_indices = tuple(payload["highlight_no_cut_hold_boundary_indices"])
    raise DirectMemberVisualSelectionError(
        "direct member selected path missed human-like highlight cadence",
        {
            "failure": "highlight_cadence_gate_failed",
            # This audit rejects the exact selected path. Moving-cut evidence
            # and the placement of terminal holds are assignment-dependent,
            # so it must not be mislabeled as proof that the whole partition
            # has no feasible path.
            "constraint_infeasibility_proven": False,
            "failed_at_segment_index": (
                int(hold_indices[0]) + 1 if hold_indices else None
            ),
            "highlight_cut_density": payload,
            "selection_candidate_rejected": True,
            "selection_gate_matches_final_render_audit": True,
            "full_selector_recheck_completed": True,
            "render_started": False,
            "visual_gates_relaxed": False,
        },
    )


def _direct_member_highlight_hold_repair_boundary_indices(
    payload: Mapping[str, Any],
) -> tuple[int, ...]:
    """Return exact post-alignment holds that can repair a density miss.

    The source-path solver budgets highlight holds on canonical musical
    boundaries, while the later pose/action audition may move an actual cut a
    few frames across a section edge. That can invalidate the compensation
    assumed by the canonical budget. Feed only the observed highlight holds
    back as forced-cut constraints; motion-only failures need a different
    repair and must remain fail-closed here.
    """

    raw_reasons = payload.get("failure_reasons", ())
    reasons = (
        frozenset(value for value in raw_reasons if isinstance(value, str))
        if isinstance(raw_reasons, (list, tuple))
        else frozenset()
    )
    if not reasons.intersection(
        {
            "highlight_switch_density_below_minimum",
            "highlight_density_lift_below_minimum",
        }
    ):
        return ()
    raw_indices = payload.get("highlight_no_cut_hold_boundary_indices", ())
    if not isinstance(raw_indices, (list, tuple)):
        return ()
    return tuple(
        sorted(
            {
                int(value)
                for value in raw_indices
                if isinstance(value, int) and not isinstance(value, bool)
            }
        )
    )


def _direct_member_visual_payload(
    selection: DirectMemberVisualSelection,
    *,
    eligible_indices: Sequence[int],
) -> dict[str, Any]:
    """Add request-domain aliases without obscuring compact selector indices."""

    eligible = tuple(int(index) for index in eligible_indices)
    payload = selection.to_dict()
    for item in payload["source_usage"]:
        eligible_source_index = int(item["eligible_source_index"])
        item["request_source_index"] = eligible[eligible_source_index]
    for span in payload["span_content_validity"]:
        for item in span["sources"]:
            eligible_source_index = int(item["eligible_source_index"])
            item["request_source_index"] = eligible[eligible_source_index]
    for item in payload["boundaries"]:
        outgoing = int(item["outgoing_eligible_source_index"])
        incoming = int(item["incoming_eligible_source_index"])
        item["outgoing_request_source_index"] = eligible[outgoing]
        item["incoming_request_source_index"] = eligible[incoming]
    return payload


def _direct_member_selection_failure_summary(
    diagnostics: dict[str, Any],
) -> dict[str, Any]:
    """Compress selector diagnostics for one machine-readable error event."""

    reason_counts: dict[str, int] = {}
    affected_segments: set[int] = set()
    affected_sources: set[int] = set()
    invalid_candidate_count = 0
    spans = diagnostics.get("span_content_validity", ())
    if isinstance(spans, list):
        for span in spans:
            if not isinstance(span, dict):
                continue
            segment_index = span.get("segment_index")
            sources = span.get("sources", ())
            if not isinstance(sources, list):
                continue
            for source in sources:
                if not isinstance(source, dict) or source.get("valid") is not False:
                    continue
                invalid_candidate_count += 1
                if isinstance(segment_index, int):
                    affected_segments.add(segment_index)
                source_index = source.get("eligible_source_index")
                if isinstance(source_index, int):
                    affected_sources.add(source_index)
                reasons = source.get("rejection_reasons", ())
                if isinstance(reasons, list):
                    for reason in reasons:
                        if isinstance(reason, str):
                            reason_counts[reason] = reason_counts.get(reason, 0) + 1
    for shortfall in diagnostics.get("quota_shortfalls", ()):
        if isinstance(shortfall, dict):
            source_index = shortfall.get("eligible_source_index")
            if isinstance(source_index, int):
                affected_sources.add(source_index)
    failed_segment = diagnostics.get("failed_at_segment_index")
    if isinstance(failed_segment, int):
        affected_segments.add(failed_segment)
    return {
        "failure": diagnostics.get("failure", "unknown_direct_selection_failure"),
        "failed_segment_index": failed_segment,
        "invalid_candidate_count": invalid_candidate_count,
        "affected_segment_indices": sorted(affected_segments),
        "affected_eligible_source_indices": sorted(affected_sources),
        "rejection_reason_counts": dict(sorted(reason_counts.items())),
        "quota_shortfall_count": len(diagnostics.get("quota_shortfalls", ())),
        "empty_segment_count": len(diagnostics.get("empty_segment_indices", ())),
    }


def _canonical_json_content_fingerprint(value: Any) -> dict[str, Any]:
    """Hash canonical JSON without materializing another large string."""

    digest = hashlib.sha256()
    size_bytes = 0
    encoder = json.JSONEncoder(
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    )
    for text_chunk in encoder.iterencode(value):
        chunk = text_chunk.encode("utf-8")
        digest.update(chunk)
        size_bytes += len(chunk)
    return {
        "contract": _DIRECT_MEMBER_FAILURE_DIAGNOSTIC_FINGERPRINT_CONTRACT,
        "sha256": digest.hexdigest(),
        "canonical_size_bytes": size_bytes,
    }


def _bounded_pretty_json_bytes(
    value: Any,
    *,
    maximum_bytes: int,
) -> tuple[bytes | None, dict[str, Any]]:
    """Serialize at most ``maximum_bytes`` while hashing the full payload."""

    if maximum_bytes <= 0:
        raise ValueError("JSON byte bound must be positive")
    digest = hashlib.sha256()
    size_bytes = 0
    chunks: list[bytes] = []
    overflowed = False
    encoder = json.JSONEncoder(
        ensure_ascii=False,
        indent=2,
        allow_nan=False,
    )
    for text_chunk in encoder.iterencode(value):
        chunk = text_chunk.encode("utf-8")
        digest.update(chunk)
        size_bytes += len(chunk)
        if not overflowed and size_bytes <= maximum_bytes:
            chunks.append(chunk)
        else:
            overflowed = True
            chunks.clear()
    fingerprint = {
        "sha256": digest.hexdigest(),
        "serialized_size_bytes": size_bytes,
    }
    return (None if overflowed else b"".join(chunks), fingerprint)


def _direct_member_failure_report_fallback_payload(
    payload: Mapping[str, Any],
    *,
    oversized_report_fingerprint: Mapping[str, Any],
) -> dict[str, Any]:
    """Retain hash-bound scalar proof when a report exceeds its hard cap."""

    diagnostics_raw = payload.get("diagnostics", {})
    diagnostics = (
        diagnostics_raw if isinstance(diagnostics_raw, dict) else {}
    )
    partition_raw = diagnostics.get("partition_search", {})
    partition = partition_raw if isinstance(partition_raw, dict) else {}
    profiles_raw = partition.get("profiles_attempted", ())
    profiles = profiles_raw if isinstance(profiles_raw, list) else []
    compact_partition = {
        key: partition.get(key)
        for key in (
            "policy",
            "initial_profile_count",
            "maximum_profile_count",
            "static_profile_upper_bound",
            "absolute_profile_upper_bound",
            "maximum_profile_limit_expansion_count",
            "profile_limit_expansions",
            "maximum_shifted_boundary_count",
            "base_maximum_shifted_boundary_count",
            "shift_capacity_contract",
            "proof_directed_window_redistribution_enabled",
            "maximum_proof_directed_boundary_merge_count",
            "maximum_visual_frontier_split_count_per_profile",
            "maximum_counterfactual_visual_frontier_split_count_per_profile",
            "profile_cap_reached",
            "generated_profile_count",
            "canonical_signature_deduplication_count",
            "proof_equivalent_future_state_dominance_count",
            "future_operation_state_count",
            "shift_depth_pruned_parent_count",
            "input_bound_partition_warm_start",
            "exact_lifeline_capacity_retry",
            "strict_extra_quota_assignment_search",
            "last_resort_safe_hold_search",
            "severe_transition_counterfactual_secondary_partition",
            "queue_order",
            "render_started",
        )
        if key in partition
    }
    compact_partition["profiles_attempted_storage"] = {
        "records_persisted": False,
        "record_count": len(profiles),
        "omission_reason": "failure_report_hard_cap_exceeded",
        "content_fingerprint": _canonical_json_content_fingerprint(profiles),
    }
    compact_diagnostics = {
        "failure": diagnostics.get("failure"),
        "failed_at_segment_index": diagnostics.get("failed_at_segment_index"),
        "constraint_infeasibility_proven": diagnostics.get(
            "constraint_infeasibility_proven"
        ),
        "profile_outcome_counts": diagnostics.get("profile_outcome_counts"),
        "visual_gates_relaxed": diagnostics.get("visual_gates_relaxed", False),
        "latest_failure_summary": _direct_member_selection_failure_summary(
            diagnostics
        ),
        "original_diagnostics_content_fingerprint": (
            _canonical_json_content_fingerprint(diagnostics)
        ),
        "latest_severe_transition_counterfactual": (
            _compact_direct_severe_counterfactual(diagnostics)
        ),
        "partition_search": compact_partition,
    }
    return {
        key: value
        for key, value in payload.items()
        if key not in {"diagnostics", "report_storage"}
    } | {
        "diagnostics": compact_diagnostics,
        "report_storage": {
            "contract": _DIRECT_MEMBER_FAILURE_REPORT_STORAGE_CONTRACT,
            "hard_cap_bytes": _DIRECT_MEMBER_FAILURE_REPORT_MAX_BYTES,
            "bounded_fallback_used": True,
            "oversized_report_fingerprint": dict(
                oversized_report_fingerprint
            ),
        },
    }


def _persist_direct_member_selection_failure(
    error: DirectMemberVisualSelectionError,
    *,
    output_directory: Path,
    base_filename: str,
    target_member: str,
    eligible_indices: Sequence[int],
) -> tuple[Path, dict[str, Any]]:
    """Atomically preserve fail-closed selector evidence outside transient stderr."""

    summary = _direct_member_selection_failure_summary(error.diagnostics)
    payload = {
        "schema_version": 1,
        "created_at": datetime.now(UTC).isoformat(),
        "stage": "automatic_member_direct_visual_selection",
        "message": str(error),
        "diagnostics_source_index_domain": ELIGIBLE_SOURCE_INDEX_DOMAIN,
        "eligible_request_source_indices": [int(index) for index in eligible_indices],
        "summary": summary,
        "diagnostics": error.diagnostics,
        "privacy": {
            "face_identity_inference_used": False,
            "face_appearance_embeddings_persisted": False,
            "raw_pose_silhouette_layout_embeddings_persisted": False,
        },
        "report_storage": {
            "contract": _DIRECT_MEMBER_FAILURE_REPORT_STORAGE_CONTRACT,
            "hard_cap_bytes": _DIRECT_MEMBER_FAILURE_REPORT_MAX_BYTES,
            "bounded_fallback_used": False,
        },
    }
    path = output_directory / (
        f"{base_filename}-{_safe_slug(target_member)}-"
        "direct-selection-failure.json"
    )
    temporary = path.with_name(f".{path.name}.tmp")
    encoded, fingerprint = _bounded_pretty_json_bytes(
        payload,
        maximum_bytes=_DIRECT_MEMBER_FAILURE_REPORT_MAX_BYTES,
    )
    if encoded is None:
        fallback = _direct_member_failure_report_fallback_payload(
            payload,
            oversized_report_fingerprint=fingerprint,
        )
        encoded, _fallback_fingerprint = _bounded_pretty_json_bytes(
            fallback,
            maximum_bytes=_DIRECT_MEMBER_FAILURE_REPORT_MAX_BYTES,
        )
        if encoded is None:
            raise RuntimeError(
                "bounded direct-member failure manifest exceeds its hard cap"
            )
    temporary.write_bytes(encoded)
    temporary.replace(path)
    return (path, summary)


def _report_direct_member_selection_failure(
    error: DirectMemberVisualSelectionError,
    *,
    output_directory: Path,
    base_filename: str,
    target_member: str,
    eligible_indices: Sequence[int],
    reporter: EventReporter,
) -> DirectMemberVisualSelectionError:
    """Persist full evidence, emit its path, and retain it in CLI text."""

    diagnostics_path, failure_summary = _persist_direct_member_selection_failure(
        error,
        output_directory=output_directory,
        base_filename=base_filename,
        target_member=target_member,
        eligible_indices=eligible_indices,
    )
    reporter.emit(
        "error",
        message=(
            "직캠 시각 안전 조건과 소스 균형을 동시에 만족하지 "
            "못해 렌더를 시작하지 않았습니다. 진단: "
            f"{diagnostics_path}"
        ),
        diagnostics_path=str(diagnostics_path),
        failure_summary=failure_summary,
    )
    return DirectMemberVisualSelectionError(
        f"{error}; diagnostics: {diagnostics_path}",
        error.diagnostics,
    )


def _compact_direct_partition_failure(
    error: DirectMemberVisualSelectionError,
    *,
    span_count: int,
) -> dict[str, Any]:
    """Persist one bounded, hash-bound scalar failure record.

    Full selector diagnostics remain available to the in-process proof search,
    but are never copied once per attempted partition into the failure artifact.
    """

    diagnostics = error.diagnostics
    search = diagnostics.get("search", {})
    exact: dict[str, Any] = {}
    if isinstance(search, dict):
        raw_exact = search.get("exact_lifeline", {})
        if isinstance(raw_exact, dict):
            exact = {
                key: raw_exact.get(key)
                for key in (
                    "path_found",
                    "explored_state_count",
                    "memoized_failed_state_count",
                    "state_capacity_exhausted",
                    "duration_state_quantization_applied",
                )
                if key in raw_exact
            }
            roots = raw_exact.get("root_candidate_diagnostics", ())
            if isinstance(roots, list):
                outcome_counts: dict[str, int] = {}
                for root in roots:
                    if not isinstance(root, dict):
                        continue
                    outcome = root.get("search_outcome")
                    if isinstance(outcome, str):
                        outcome_counts[outcome] = outcome_counts.get(outcome, 0) + 1
                exact["root_candidate_count"] = len(roots)
                exact["root_search_outcome_counts"] = dict(
                    sorted(outcome_counts.items())
                )
    connectivity = diagnostics.get("hard_boundary_connectivity", {})
    zero_boundaries: list[int] = []
    if isinstance(connectivity, dict):
        raw_zero = connectivity.get(
            "zero_local_nonsevere_transition_boundary_indices"
        )
        if raw_zero is None:
            raw_zero = connectivity.get(
                "zero_reachable_transition_boundary_indices",
                (),
            )
        if isinstance(raw_zero, list):
            zero_boundaries = [
                int(value) for value in raw_zero if isinstance(value, int)
            ]
    next_proofs = _direct_partition_exact_shift_proofs(
        diagnostics,
        span_count=span_count,
    )
    raw_valid_counts = diagnostics.get("valid_count_by_source", ())
    compact_valid_counts: list[dict[str, int]] = []
    if isinstance(raw_valid_counts, list):
        for raw in raw_valid_counts:
            if not isinstance(raw, dict):
                continue
            scalar: dict[str, int] = {}
            for key in (
                "eligible_source_index",
                "quota",
                "valid_span_count",
                "invalid_span_count",
            ):
                value = raw.get(key)
                if isinstance(value, int) and not isinstance(value, bool):
                    scalar[key] = value
            if scalar:
                compact_valid_counts.append(scalar)
    boundary_local_search: dict[str, Any] | None = None
    if diagnostics.get("failure") in {
        "boundary_local_search_duration_infeasible",
        "boundary_local_search_single_state_infeasible",
        "boundary_local_search_solver_unavailable",
    }:
        raw_solver = diagnostics.get("solver")
        raw_snapshot = diagnostics.get("constraint_snapshot")
        boundary_local_search = {
            "solver": raw_solver if isinstance(raw_solver, dict) else None,
            "constraint_snapshot": (
                raw_snapshot if isinstance(raw_snapshot, dict) else None
            ),
        }
    raw_highlight_cut_density = diagnostics.get("highlight_cut_density")
    highlight_cut_density = (
        dict(raw_highlight_cut_density)
        if isinstance(raw_highlight_cut_density, Mapping)
        else None
    )
    raw_highlight_hold_repair = diagnostics.get("highlight_hold_repair")
    highlight_hold_repair = (
        dict(raw_highlight_hold_repair)
        if isinstance(raw_highlight_hold_repair, Mapping)
        else None
    )
    return {
        "storage_contract": "hash_bound_scalar_partition_failure_v1",
        "full_diagnostics_persisted": False,
        "diagnostics_content_fingerprint": (
            _canonical_json_content_fingerprint(diagnostics)
        ),
        "message": str(error),
        "failure": diagnostics.get("failure"),
        "failed_at_segment_index": diagnostics.get(
            "failed_at_segment_index"
        ),
        "constraint_infeasibility_proven": diagnostics.get(
            "constraint_infeasibility_proven",
            _direct_partition_failure_is_proven(diagnostics),
        ),
        "visual_gates_relaxed": False,
        "summary": _direct_member_selection_failure_summary(diagnostics),
        "zero_local_nonsevere_transition_boundary_indices": zero_boundaries,
        "next_exact_shift_proofs": [
            {
                "boundary_index": proof.boundary_index,
                "trigger": proof.trigger,
                "failed_segment_index": proof.failed_segment_index,
                "forward_reachable_left_source_indices": list(
                    proof.forward_reachable_left_source_indices
                ),
                "left_valid_source_indices": list(
                    proof.left_valid_source_indices
                ),
                "right_valid_source_indices": list(
                    proof.right_valid_source_indices
                ),
                "local_nonsevere_cross_source_edge_count": (
                    proof.local_nonsevere_edge_count
                ),
            }
            for proof in next_proofs
        ],
        "exact_lifeline": exact,
        "severe_transition_counterfactual": (
            _compact_direct_severe_counterfactual(diagnostics)
        ),
        # Per-segment index arrays remain available in the one latest runtime
        # diagnostic.  Repeating them for every attempted profile made an
        # otherwise scalar failure ledger grow quadratically with search depth.
        "valid_count_by_source": compact_valid_counts,
        "boundary_local_search": boundary_local_search,
        "highlight_cut_density": highlight_cut_density,
        "highlight_hold_repair": highlight_hold_repair,
    }


def _compact_direct_severe_counterfactual(
    diagnostics: Mapping[str, Any],
) -> dict[str, Any] | None:
    """Retain bounded minimum-severe proof scalars in compact reports."""

    search = diagnostics.get("search")
    if not isinstance(search, dict):
        return None
    raw = search.get("severe_transition_counterfactual")
    if not isinstance(raw, dict):
        return None
    compact = {
        key: raw.get(key)
        for key in (
            "contract",
            "optimization_contract",
            "severe_transition_cost_policy",
            "tie_break_contract",
            "invoked",
            "original_hard_constraint_sha256",
            "original_failure_certificate_sha256",
            "severe_disabled_hard_constraint_sha256",
            "severe_transition_budget_mask_sha256",
            "minimum_witness_path_sha256",
            "minimum_severe_transition_count",
            "minimum_severe_transition_count_lower_bound",
            "maximum_diagnostic_severe_transition_budget",
            "optimality_proven",
            "production_single_split_proposal_authorized",
            "witness_found",
            "integrity_check_passed",
            "blocking_boundary_indices",
            "blocking_transitions",
            "maximum_duration_relative_deviation",
            "state_limit_per_budget",
            "explored_state_count",
            "memoized_failed_state_count",
            "state_capacity_exhausted",
            "duration_state_quantization_applied",
            "selection_eligible",
            "render_authorized",
            "visual_gates_relaxed",
        )
        if key in raw
    }
    for key in (
        "zero_budget_hard_proof",
        "lower_budget_hard_proofs",
        "budget_attempts",
    ):
        value = raw.get(key)
        if isinstance(value, (dict, list)):
            compact[key] = value
    compact["full_counterfactual_content_fingerprint"] = (
        _canonical_json_content_fingerprint(raw)
    )
    return compact


def _direct_partition_selection_rank(
    profile: _DirectFullFramePartitionProfile,
    selection: DirectMemberVisualSelection,
) -> tuple[int, float, int, int, str]:
    payload = selection.to_dict()
    aggregate = payload.get("aggregate", {})
    warning_count = (
        int(aggregate.get("warning_boundary_count", 0))
        if isinstance(aggregate, dict)
        else 0
    )
    optimizer_cost = float(
        getattr(selection, "optimizer_cost", payload.get("optimizer_cost", 0.0))
    )
    return (
        warning_count,
        optimizer_cost,
        profile.changed_span_count,
        profile.musical_boundary_penalty,
        profile.profile_id,
    )


def _direct_partition_structural_search_cost(
    profile: _DirectFullFramePartitionProfile,
) -> tuple[int, int, int]:
    """Return the proof-preserving edit cost independent of queue order."""

    return (
        profile.structural_change_count,
        profile.total_unit_displacement,
        profile.musical_boundary_penalty,
    )


def _direct_partition_proof_progress(
    profile: _DirectFullFramePartitionProfile,
) -> int:
    """Return the furthest exact parent failure represented by a profile."""

    operation = profile.latest_proof_operation
    if operation is None:
        return -1
    candidates = [
        getattr(operation, "proof_failed_segment_index", None),
    ]
    frontier = getattr(operation, "proof_frontier_boundary_index", None)
    if isinstance(frontier, int):
        candidates.append(frontier + 1)
    boundary = getattr(operation, "boundary_index", None)
    if isinstance(boundary, int):
        candidates.append(boundary + 1)
    return max(
        (value for value in candidates if isinstance(value, int)),
        default=-1,
    )


def _direct_partition_terminal_candidate_progress(
    profile: _DirectFullFramePartitionProfile,
    error: DirectMemberVisualSelectionError,
) -> int:
    """Rank a terminal candidate by its current proved reachable prefix.

    A profile can contain an old repair at a far-away boundary while its latest
    full re-selection still fails near the start.  That historical operation
    location is useful for queue exploration, but must never outrank a profile
    whose current hard-feasible path actually reaches farther through the song.
    """

    failed = error.diagnostics.get("failed_at_segment_index")
    if (
        isinstance(failed, int)
        and not isinstance(failed, bool)
        and failed >= 0
    ):
        return failed
    return _direct_partition_proof_progress(profile)


def _direct_partition_has_render_feedback_lineage(
    profile: _DirectFullFramePartitionProfile,
) -> bool:
    return any(
        shift.trigger == "dense_render_camera_infeasible_pair_cluster"
        for shift in profile.boundary_shifts
    )


def _direct_partition_queue_priority(
    profile: _DirectFullFramePartitionProfile,
) -> tuple[int, int, int, int, int]:
    """Prefer decoded-render repairs, then proof progress and structural cost.

    A render-feedback profile is tied to an observed dense-camera or decoded
    continuity failure.  Its composed children must be explored before an
    unrelated base-partition branch whose historical proof happens to lie
    later in the song.  Persisted input-bound warm starts remain ahead of the
    generic base lineage.  Structural cost is retained separately and becomes
    the primary pruning axis after a feasible profile exists.
    """

    render_feedback_lineage = _direct_partition_has_render_feedback_lineage(
        profile
    )
    lineage_tier = (
        0
        if render_feedback_lineage
        else 1
        if profile.warm_start_binding_sha256 is not None
        else 2
    )
    return (
        lineage_tier,
        -_direct_partition_proof_progress(profile),
        *_direct_partition_structural_search_cost(profile),
    )


def _direct_member_render_feedback_strict_composition_limit(
    feedback_certificate_count: int,
) -> int:
    """Scale strict repair search without exceeding the global first cohort."""

    if (
        isinstance(feedback_certificate_count, bool)
        or not isinstance(feedback_certificate_count, int)
        or feedback_certificate_count < 0
    ):
        raise ValueError(
            "feedback_certificate_count must be a non-negative integer"
        )
    return (
        _DIRECT_MEMBER_MAX_PARTITION_PROFILE_COUNT
        if feedback_certificate_count
        else _DIRECT_MEMBER_MAX_STRICT_TERMINAL_AUDITION_COUNT
    )


def _direct_member_feedback_source_diversity_candidates(
    *,
    minimum_required_source_count: int,
    maximum_renderable_source_count: int,
    feedback_certificate_count: int,
) -> tuple[int, ...]:
    """Return the diversity floor for one joint feedback-aware solve.

    ``minimum_required_source_count`` is a floor, not a request to permanently
    exclude every lower-ranked source. Before decoded-render feedback exists,
    the bounded proof keeps its inexpensive minimum-size cohort. Once feedback
    exists, the selector treats this value as a hard lower bound while its MILP
    jointly chooses any source usage pattern from the complete renderable pool.
    Re-running exact 8, 7, and 6-source cohorts would repeat nearly identical
    partition searches and still miss cross-cohort source combinations.
    """

    for name, value in (
        ("minimum_required_source_count", minimum_required_source_count),
        ("maximum_renderable_source_count", maximum_renderable_source_count),
        ("feedback_certificate_count", feedback_certificate_count),
    ):
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError(f"{name} must be an integer")
    if minimum_required_source_count < 2:
        raise ValueError("minimum required source count must be at least two")
    if maximum_renderable_source_count < minimum_required_source_count:
        raise ValueError(
            "maximum renderable source count must cover the required minimum"
        )
    if feedback_certificate_count < 0:
        raise ValueError("feedback certificate count must be non-negative")
    return (minimum_required_source_count,)


def _direct_member_proxy_refinement_rank(
    preflight: DirectMemberRenderedProxyPreflight,
) -> tuple[int, int, int, float, int, int, float]:
    """Rank materialized attempts by member continuity before broad look noise."""

    if not isinstance(preflight, DirectMemberRenderedProxyPreflight):
        raise TypeError("member proxy refinement rank needs a preflight result")
    payload = preflight.payload
    quality_passed = bool(payload.get("member_output_quality_passed"))
    continuity_passed = bool(
        payload.get("direct_member_rendered_continuity_passed")
    )
    continuity = payload.get("rendered_continuity")
    continuity_payload = continuity if isinstance(continuity, Mapping) else {}
    metrics = continuity_payload.get("metrics")
    metric_payload = metrics if isinstance(metrics, Mapping) else {}
    thresholds = continuity_payload.get("thresholds")
    threshold_payload = thresholds if isinstance(thresholds, Mapping) else {}

    normalized_excess = 0.0
    for metric_name, threshold_name in (
        (
            "attention_position_mismatch_p95",
            "maximum_attention_position_mismatch_p95",
        ),
        (
            "attention_scale_mismatch_p95",
            "maximum_attention_scale_mismatch_p95",
        ),
        ("pose_mismatch_p95", "maximum_pose_mismatch_p95"),
        (
            "silhouette_mismatch_p95",
            "maximum_silhouette_mismatch_p95",
        ),
    ):
        value = metric_payload.get(metric_name)
        maximum = threshold_payload.get(threshold_name)
        if (
            isinstance(value, (int, float))
            and not isinstance(value, bool)
            and isinstance(maximum, (int, float))
            and not isinstance(maximum, bool)
            and float(maximum) > 0.0
        ):
            normalized_excess += max(
                0.0,
                float(value) / float(maximum) - 1.0,
            )

    generic = payload.get("rendered_proxy_review")
    generic_payload = generic if isinstance(generic, Mapping) else {}
    weighted_score = generic_payload.get("weighted_score")
    resolved_weighted_score = (
        float(weighted_score)
        if isinstance(weighted_score, (int, float))
        and not isinstance(weighted_score, bool)
        else float("-inf")
    )
    quality_failures = payload.get("member_output_quality_failure_reasons")
    quality_failure_count = (
        len(quality_failures) if isinstance(quality_failures, list) else 1
    )
    all_repair_targets = preflight.repair_target_boundary_indices
    raw_continuity_targets = payload.get(
        "continuity_repair_target_boundary_indices"
    )
    continuity_repair_count = (
        len(raw_continuity_targets)
        if isinstance(raw_continuity_targets, list)
        else len(all_repair_targets)
    )
    raw_generic_targets = payload.get("generic_repair_target_boundary_indices")
    generic_repair_count = (
        len(raw_generic_targets)
        if isinstance(raw_generic_targets, list)
        else len(all_repair_targets)
    )
    component_failure_count = int(not quality_passed) + int(
        not continuity_passed
    )
    return (
        int(not preflight.passed),
        component_failure_count,
        continuity_repair_count,
        normalized_excess,
        quality_failure_count,
        generic_repair_count,
        -resolved_weighted_score,
    )


def _direct_member_proxy_reserved_render_camera_refinement_is_authorized(
    payload: Mapping[str, Any],
    *,
    decoded_proxy_path_audition_count: int,
    decoded_proxy_render_count: int,
) -> bool:
    """Spend the final hard-cut proxy on a near-pass camera repair.

    The ordinary budget preserves one render for another source path. Once a
    second path has reached at most three geometry-only continuity failures,
    another global path is lower-value than correcting that decoded candidate
    in output space. Pose or technical-integrity failures remain ineligible.
    """

    if any(
        isinstance(value, bool) or not isinstance(value, int)
        for value in (
            decoded_proxy_path_audition_count,
            decoded_proxy_render_count,
        )
    ):
        raise TypeError("decoded proxy budget counters must be integers")
    if not (
        2
        <= decoded_proxy_path_audition_count
        < _DIRECT_MEMBER_MAXIMUM_DECODED_PROXY_PATH_AUDITIONS
        and decoded_proxy_render_count
        == _DIRECT_MEMBER_MAXIMUM_DECODED_HARDCUT_PROXY_RENDERS - 1
        and not bool(
            payload.get("direct_member_rendered_continuity_passed")
        )
    ):
        return False
    raw_targets = payload.get(
        "continuity_repair_target_boundary_indices"
    )
    if not (
        isinstance(raw_targets, list)
        and 1 <= len(raw_targets) <= 3
        and all(
            isinstance(value, int)
            and not isinstance(value, bool)
            and value >= 0
            for value in raw_targets
        )
        and len(set(raw_targets)) == len(raw_targets)
    ):
        return False
    continuity = payload.get("rendered_continuity")
    continuity_payload = (
        continuity if isinstance(continuity, Mapping) else {}
    )
    failures = continuity_payload.get("failure_boundary_indices")
    if not isinstance(failures, Mapping) or not failures:
        return False
    geometry_only_failure_reasons = {
        "rendered_boundary_position_discontinuity",
        "rendered_boundary_scale_discontinuity",
        "rendered_effect_endpoint_position_discontinuity",
        "rendered_effect_endpoint_scale_discontinuity",
    }
    return bool(
        set(str(reason) for reason in failures)
        <= geometry_only_failure_reasons
        and all(
            isinstance(indices, list)
            and all(
                isinstance(value, int)
                and not isinstance(value, bool)
                and value >= 0
                for value in indices
            )
            for indices in failures.values()
        )
    )


def _direct_member_dense_motion_feedback_boundary_indices(
    error: DirectMemberEditorialMotionError,
    *,
    maximum_count: int = (
        _DIRECT_MEMBER_MAXIMUM_DENSE_FEEDBACK_CONSTRAINTS_PER_RESELECTION
    ),
) -> tuple[int, ...]:
    """Choose the smallest strongest lazy constraint set for one retry.

    Dense review can expose several violations on one selected path. Forbidding
    all of them before re-optimizing overconstrains the graph and caused the
    26-second proof to expand into dozens of unrelated cadence profiles. One
    strongest violated edge is sufficient for a cutting-plane iteration; the
    complete dense review runs again on the replacement path.
    """

    if not isinstance(error, DirectMemberEditorialMotionError):
        raise TypeError("dense motion feedback needs a structured error")
    if (
        isinstance(maximum_count, bool)
        or not isinstance(maximum_count, int)
        or maximum_count < 1
    ):
        raise ValueError("dense motion feedback count must be positive")

    def reason_weight(reason: str) -> int:
        if any(
            token in reason
            for token in (
                "identity",
                "geometry_jump",
                "disagrees_with_audit",
            )
        ):
            return 4
        if any(
            token in reason
            for token in (
                "bounded_upscale",
                "transform_bound",
                "contain",
                "no_improving",
            )
        ):
            return 3
        if any(
            token in reason
            for token in (
                "track_gap",
                "evidence_missing",
            )
        ):
            return 2
        return 1

    ranked = sorted(
        set(error.missing_boundary_indices),
        key=lambda boundary_index: (
            -sum(
                reason_weight(reason)
                for reason in error.rejection_reasons.get(
                    boundary_index,
                    ("required_candidate_missing_without_reason",),
                )
            ),
            -len(error.rejection_reasons.get(boundary_index, ())),
            boundary_index,
        ),
    )
    return tuple(ranked[:maximum_count])


def _direct_member_proxy_look_refinement_is_eligible(
    payload: Mapping[str, Any],
) -> bool:
    """Refine color only after rendered geometry already passes.

    Look normalization cannot repair a bad pose, position, scale, or motion
    boundary. Re-encoding the same failed cut path before feeding those exact
    boundaries back to the selector only burns time and obscures the causal
    result.
    """

    if not isinstance(payload, Mapping):
        raise TypeError("member proxy look refinement needs a mapping")
    return bool(
        payload.get("direct_member_rendered_continuity_passed")
    ) and not bool(payload.get("member_output_quality_passed"))


def _direct_member_proxy_look_refinement_can_share_camera_iteration(
    payload: Mapping[str, Any],
) -> bool:
    """Use an already-required camera rerender to repair output look too.

    This does not authorize a color-only rerender while geometry is bad.  It
    only composes a bounded residual look onto a second decoded-output camera
    correction that is already going to consume the final proxy slot.  Keep
    technical-integrity and low-overall-quality failures out of this shortcut.
    """

    if not isinstance(payload, Mapping):
        raise TypeError("member proxy shared look refinement needs a mapping")
    if bool(payload.get("member_output_quality_passed")):
        return False
    raw_failures = payload.get("member_output_quality_failure_reasons")
    if not isinstance(raw_failures, list) or not raw_failures:
        return False
    repairable = {
        "member_proxy_source_quality_median_span",
        "member_proxy_perceptual_source_admission",
    }
    return all(
        isinstance(reason, str) and reason in repairable
        for reason in raw_failures
    )


def _direct_member_render_feedback_seed_profiles(
    base: _DirectFullFramePartitionProfile,
    in_run_preferred_profile: _DirectFullFramePartitionProfile | None,
    persisted_warm_start_profiles: Sequence[_DirectFullFramePartitionProfile],
) -> tuple[_DirectFullFramePartitionProfile, ...]:
    """Retain the base repair root across both in-run and restarted retries."""

    profiles: list[_DirectFullFramePartitionProfile] = []
    seen_signatures: set[tuple[int, ...]] = set()
    for profile in (
        *((in_run_preferred_profile,) if in_run_preferred_profile else ()),
        *persisted_warm_start_profiles,
        base,
    ):
        if profile.unit_counts in seen_signatures:
            continue
        seen_signatures.add(profile.unit_counts)
        profiles.append(profile)
    return tuple(profiles)


def _direct_partition_terminal_audition_due(
    *,
    evaluated_profile_count: int,
    feasible_profile_count: int,
    queued_profile_count: int,
    maximum_evaluation_count: int = (
        _DIRECT_MEMBER_MAX_STRICT_TERMINAL_AUDITION_COUNT
    ),
    evaluated_total_profile_count: int = 0,
    admitted_total_profile_limit: int = 0,
) -> bool:
    """Bound strict expansion before the audited hold/effect audition.

    Crossing this budget is not a visual-gate relaxation and is not reported
    as hard infeasibility: it transfers the best proven failures to the
    independently constrained terminal selector.
    """

    for name, value in (
        ("evaluated_profile_count", evaluated_profile_count),
        ("feasible_profile_count", feasible_profile_count),
        ("queued_profile_count", queued_profile_count),
        ("maximum_evaluation_count", maximum_evaluation_count),
        ("evaluated_total_profile_count", evaluated_total_profile_count),
        ("admitted_total_profile_limit", admitted_total_profile_limit),
    ):
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise ValueError(f"{name} must be a non-negative integer")
    if maximum_evaluation_count < 1:
        raise ValueError("maximum_evaluation_count must be positive")
    return bool(
        feasible_profile_count == 0
        and queued_profile_count > 0
        and evaluated_profile_count
        >= maximum_evaluation_count
        and evaluated_total_profile_count >= admitted_total_profile_limit
    )


def _direct_visual_split_exact_lifeline_retry_is_authorized(
    profile: _DirectFullFramePartitionProfile,
    error: DirectMemberVisualSelectionError,
    *,
    initial_state_limit: int,
) -> bool:
    """Authorize one larger exact search only on a proved capacity boundary."""

    if not profile.visual_frontier_splits:
        return False
    diagnostics = error.diagnostics
    if (
        diagnostics.get("failure") != "search_capacity_exhausted"
        or diagnostics.get("constraint_infeasibility_proven") is not False
    ):
        return False
    search = diagnostics.get("search")
    if not isinstance(search, dict):
        return False
    exact = search.get("exact_lifeline")
    if not isinstance(exact, dict):
        return False
    return bool(
        exact.get("invoked") is True
        and exact.get("state_capacity_exhausted") is True
        and exact.get("duration_state_quantization_applied") is False
        and exact.get("explored_state_count") == initial_state_limit
        and initial_state_limit
        < _DIRECT_MEMBER_VISUAL_SPLIT_EXACT_LIFELINE_RETRY_STATE_LIMIT
    )


def _direct_strict_extra_quota_assignment_candidates(
    *,
    span_count: int,
    source_count: int,
    source_order: Sequence[int],
    diagnostics: Mapping[str, Any],
) -> tuple[tuple[int, ...], ...]:
    """Enumerate omitted exactly-balanced quota owners by validity slack.

    Source order remains immutable.  Only the set receiving the remainder of
    ``span_count / source_count`` changes, so every candidate still uses every
    source either ``base`` or ``base + 1`` times.  Enumeration is admitted only
    when the complete combination domain fits the fixed finite bound and the
    selector supplied a valid-count certificate for every source.
    """

    order = tuple(int(index) for index in source_order)
    if (
        source_count < 2
        or len(order) != source_count
        or set(order) != set(range(source_count))
    ):
        return ()
    base, extra = divmod(int(span_count), source_count)
    if extra <= 0:
        return ()
    combination_count = math.comb(source_count, extra)
    if combination_count > _DIRECT_MEMBER_MAX_EXTRA_QUOTA_ASSIGNMENT_COUNT:
        return ()
    raw_valid_counts = diagnostics.get("valid_count_by_source")
    if not isinstance(raw_valid_counts, list):
        return ()
    valid_counts: dict[int, int] = {}
    for item in raw_valid_counts:
        if not isinstance(item, dict):
            continue
        source_index = item.get("eligible_source_index")
        valid_span_count = item.get("valid_span_count")
        if isinstance(source_index, int) and isinstance(valid_span_count, int):
            valid_counts[source_index] = valid_span_count
    if set(valid_counts) != set(range(source_count)):
        return ()

    order_rank = {source_index: rank for rank, source_index in enumerate(order)}
    default_extra_set = frozenset(order[:extra])
    candidates: list[tuple[tuple[Any, ...], tuple[int, ...]]] = []
    for raw_assignment in combinations(range(source_count), extra):
        assignment_set = frozenset(raw_assignment)
        if assignment_set == default_extra_set:
            continue
        assignment = tuple(
            source_index for source_index in order if source_index in assignment_set
        )
        slacks = sorted(
            valid_counts[source_index]
            - (base + int(source_index in assignment_set))
            for source_index in range(source_count)
        )
        # Maximize the weakest validity slack first, then the next weakest.
        # Source-order rank is only the deterministic final tie breaker.
        priority = (
            tuple(-value for value in slacks),
            tuple(order_rank[index] for index in assignment),
        )
        candidates.append((priority, assignment))
    candidates.sort(key=lambda item: item[0])
    return tuple(assignment for _priority, assignment in candidates)


def _direct_strict_extra_quota_assignment_failure_is_proven(
    diagnostics: Mapping[str, Any],
) -> bool:
    """Accept only hard, non-quantized evidence for an alternate quota set."""

    failure = diagnostics.get("failure")
    if failure == "content_validity_quota_precheck_failed":
        return True
    if failure == "boundary_diagnostic_eligible_pair_exhausted":
        return True
    if (
        failure
        not in {
            "validity_quota_path_exhausted",
            "duration_balance_threshold_unsatisfied",
        }
        or diagnostics.get("constraint_infeasibility_proven") is not True
    ):
        return False
    search = diagnostics.get("search")
    if not isinstance(search, dict):
        return False
    exact = search.get("exact_lifeline")
    return bool(
        isinstance(exact, dict)
        and exact.get("invoked") is True
        and exact.get("state_capacity_exhausted") is False
        and exact.get("duration_state_quantization_applied") is False
    )


def _direct_strict_extra_quota_assignment_search_is_authorized(
    *,
    represented_source_count: int,
    source_count: int,
    qualified_profile_count: int,
    diagnostics: Mapping[str, Any],
    duplicate_certificate_saturated: bool = False,
) -> bool:
    """Allow remainder-owner search from any exact hard proof.

    The base selector already runs its exact lifeline before reporting a hard
    quota failure. Requiring a *second* capacity-triggered lifeline retry made
    the alternate balanced-quota search unreachable for ordinary exact
    failures, even though changing only the one repeated source can restore a
    valid all-source path.
    """

    for name, value in (
        ("represented_source_count", represented_source_count),
        ("source_count", source_count),
        ("qualified_profile_count", qualified_profile_count),
    ):
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError(f"{name} must be an integer")
    if not isinstance(duplicate_certificate_saturated, bool):
        raise TypeError("duplicate certificate saturation must be boolean")
    return bool(
        source_count >= 2
        and represented_source_count == source_count
        and not duplicate_certificate_saturated
        and qualified_profile_count
        < _DIRECT_MEMBER_MAX_EXTRA_QUOTA_PROFILE_COUNT
        and _direct_strict_extra_quota_assignment_failure_is_proven(
            diagnostics
        )
    )


def _select_direct_member_partition_profile(
    *,
    timing_draft: GroupDraftTimeline,
    eligible_indices: Sequence[int],
    eligible_sources: Sequence[Path],
    source_timewarps: Sequence[TimeWarpMap | None] | None,
    scene_cut_times: Sequence[Sequence[float]],
    source_cycle: Sequence[int],
    highlight_intervals: Sequence[tuple[float, float]] = (),
    continuous_official_portrait_fancam_contract: bool = False,
    cinematic_bridge_enabled: bool = False,
    required_distinct_source_count: int | None = None,
    eligible_source_frame_sizes: Sequence[tuple[int, int]] | None = None,
    output_frame_size: tuple[int, int] = (1080, 1920),
    feature_cache_directory: Path | None = None,
    descriptor_provider: DescriptorProvider | None = None,
    render_infeasible_transition_edges: Sequence[
        tuple[float, int, int]
    ] = (),
    render_penalized_transition_edges: Sequence[
        tuple[float, int, int, float]
    ] = (),
    joint_camera_failed_proposals: Sequence[tuple[float, int, int, float]] = (),
    decoded_proxy_preferred_source_path: Sequence[int] | None = None,
    decoded_proxy_repair_target_boundary_indices: Sequence[int] = (),
    forbidden_source_paths_by_partition_unit_counts: Mapping[
        tuple[int, ...], Sequence[Sequence[int]]
    ] | None = None,
    preferred_partition_unit_counts: Sequence[int] | None = None,
    progress_callback: Callable[[dict[str, Any]], None] | None = None,
) -> tuple[
    _DirectFullFramePartitionProfile,
    DirectMemberVisualSelection,
    dict[str, Any],
]:
    """Try one fixed cadence, then bounded proof-directed beat partitions."""

    eligible = tuple(int(index) for index in eligible_indices)
    compact_timewarps = (
        tuple(source_timewarps[index] for index in eligible)
        if source_timewarps is not None
        else None
    )
    normalized_highlight_intervals = (
        _normalized_direct_member_highlight_intervals(
            highlight_intervals,
            range_start=timing_draft.common_master_start,
            range_end=timing_draft.common_master_end,
        )
        if highlight_intervals
        else ()
    )
    undensified_base_span_count = len(
        _coarsen_direct_full_frame_spans(timing_draft.segments)
    )
    selection_config = DirectMemberVisualConfig(
        boundary_search_radius_frames=6,
        boundary_search_step_frames=2,
        hold_cadence_basis="duration",
    )
    represented_source_count = (
        len(source_cycle)
        if required_distinct_source_count is None
        else int(required_distinct_source_count)
    )
    if not 2 <= represented_source_count <= len(source_cycle):
        raise ValueError("direct member represented source count is invalid")
    forbidden_paths_by_partition = {
        tuple(unit_counts): tuple(tuple(path) for path in paths)
        for unit_counts, paths in (
            forbidden_source_paths_by_partition_unit_counts or {}
        ).items()
    }
    if any(
        not unit_counts
        or any(
            isinstance(value, bool)
            or not isinstance(value, int)
            or value <= 0
            for value in unit_counts
        )
        for unit_counts in forbidden_paths_by_partition
    ):
        raise ValueError("direct member forbidden partition key is invalid")
    ordinary_base = _direct_full_frame_base_partition_profile(
        timing_draft.segments,
        highlight_intervals=normalized_highlight_intervals,
    )
    minimum_all_source_span_count = (
        represented_source_count
        + _DIRECT_MEMBER_MINIMUM_ALL_SOURCE_REUSE_SPAN_COUNT
    )
    performance_duration_seconds = (
        timing_draft.common_master_end - timing_draft.common_master_start
    )
    minimum_global_cadence_span_count = (
        math.ceil(
            performance_duration_seconds
            * _DIRECT_MEMBER_MIN_SWITCHES_PER_MINUTE
            / 60.0
            - 1e-9
        )
        + 1
    )
    minimum_seed_span_count = max(
        minimum_all_source_span_count,
        minimum_global_cadence_span_count,
    )
    base = _direct_full_frame_base_partition_profile(
        timing_draft.segments,
        highlight_intervals=normalized_highlight_intervals,
        minimum_span_count=minimum_seed_span_count,
    )
    in_run_preferred_profile = (
        _direct_member_in_run_preferred_partition_profile(
            timing_draft.segments,
            preferred_partition_unit_counts,
        )
    )
    if len(base.spans) < represented_source_count:
        raise RuntimeError(
            "coarse direct cadence cannot show every required source"
        )
    if continuous_official_portrait_fancam_contract:
        warm_start_profiles, warm_start_diagnostics = (
            _load_direct_member_partition_warm_start_profiles(
                feature_cache_directory,
                timing_draft.segments,
                base,
                source_count=len(eligible_sources),
            )
        )
        if ordinary_base.unit_counts != base.unit_counts:
            (
                ordinary_warm_start_profiles,
                ordinary_warm_start_diagnostics,
            ) = _load_direct_member_partition_warm_start_profiles(
                feature_cache_directory,
                timing_draft.segments,
                ordinary_base,
                source_count=len(eligible_sources),
            )
            capacity_seed_profiles = (
                _direct_member_short_proof_capacity_expansion_profiles(
                    timing_draft.segments,
                    (ordinary_base, *ordinary_warm_start_profiles),
                    minimum_span_count=minimum_seed_span_count,
                    highlight_intervals=normalized_highlight_intervals,
                    excluded_unit_counts=(base.unit_counts,),
                )
            )
        else:
            ordinary_warm_start_profiles = ()
            ordinary_warm_start_diagnostics = {
                "status": "base_already_has_all_source_capacity",
                "loaded_candidate_count": 0,
            }
            capacity_seed_profiles = ()
    else:
        warm_start_profiles = ()
        ordinary_warm_start_profiles = ()
        capacity_seed_profiles = ()
        ordinary_warm_start_diagnostics = {
            "status": "continuous_official_member_contract_required",
            "loaded_candidate_count": 0,
        }
        warm_start_diagnostics = {
            "contract": _DIRECT_MEMBER_PARTITION_WARM_START_CONTRACT,
            "requested": False,
            "status": "continuous_official_member_contract_required",
            "loaded_candidate_count": 0,
            "full_selector_recheck_required": True,
            "visual_gates_relaxed": False,
        }
    in_run_preferred_profiles = (
        (in_run_preferred_profile,)
        if in_run_preferred_profile is not None
        and in_run_preferred_profile.unit_counts != base.unit_counts
        else ()
    )
    preferred_signatures = (
        {in_run_preferred_profile.unit_counts}
        if in_run_preferred_profile is not None
        else set()
    )
    capacity_signatures = {
        profile.unit_counts for profile in capacity_seed_profiles
    }
    persisted_warm_start_profiles = tuple(
        profile
        for profile in warm_start_profiles
        if profile.unit_counts not in preferred_signatures
        and profile.unit_counts not in capacity_signatures
    )
    feedback_seed_profiles = _direct_member_render_feedback_seed_profiles(
        base,
        in_run_preferred_profile,
        (*capacity_seed_profiles, *persisted_warm_start_profiles),
    )
    render_feedback_profiles: list[_DirectFullFramePartitionProfile] = []
    render_feedback_seen_signatures = {
        *(profile.unit_counts for profile in feedback_seed_profiles),
    }
    if render_infeasible_transition_edges:
        for warm_profile in feedback_seed_profiles:
            for feedback_profile in (
                _direct_member_render_feedback_partition_profiles(
                    timing_draft.segments,
                    warm_profile,
                    render_infeasible_transition_edges,
                    source_count=len(eligible_sources),
                    config=selection_config,
                )
            ):
                if feedback_profile.unit_counts in render_feedback_seen_signatures:
                    continue
                render_feedback_profiles.append(feedback_profile)
                render_feedback_seen_signatures.add(feedback_profile.unit_counts)
                if (
                    len(render_feedback_profiles)
                    >= _DIRECT_MEMBER_MAX_DENSE_RENDER_FEEDBACK_PROFILE_COUNT
                ):
                    break
            if (
                len(render_feedback_profiles)
                >= _DIRECT_MEMBER_MAX_DENSE_RENDER_FEEDBACK_PROFILE_COUNT
            ):
                break
    warm_start_profiles = (
        *in_run_preferred_profiles,
        *capacity_seed_profiles,
        *persisted_warm_start_profiles,
        *render_feedback_profiles,
    )
    partition_search_strict_terminal_audition_limit = (
        _direct_member_render_feedback_strict_composition_limit(
            len(render_infeasible_transition_edges)
        )
    )
    warm_start_diagnostics.update(
        {
            "in_run_preferred_partition_requested": (
                preferred_partition_unit_counts is not None
            ),
            "in_run_preferred_partition_matches_base": bool(
                in_run_preferred_profile is not None
                and in_run_preferred_profile.unit_counts == base.unit_counts
            ),
            "in_run_preferred_partition_candidate_count": len(
                in_run_preferred_profiles
            ),
            "in_run_preferred_partition_signature_sha256": (
                _direct_partition_signature_sha256(
                    in_run_preferred_profile.unit_counts
                )
                if in_run_preferred_profile is not None
                else None
            ),
            "in_run_preferred_partition_full_selector_recheck_required": True,
            "in_run_preferred_partition_visual_gates_relaxed": False,
            "short_proof_all_source_capacity": {
                "contract": (
                    "input_bound_musical_carrier_slot_expansion_v1"
                ),
                "minimum_span_count": minimum_seed_span_count,
                "minimum_global_cadence_span_count": (
                    minimum_global_cadence_span_count
                ),
                "minimum_seed_span_count": minimum_seed_span_count,
                "ordinary_base_span_count": len(ordinary_base.spans),
                "capacity_base_span_count": len(base.spans),
                "ordinary_cache_status": (
                    ordinary_warm_start_diagnostics.get("status")
                ),
                "ordinary_cached_seed_count": len(
                    ordinary_warm_start_profiles
                ),
                "generated_candidate_count": len(capacity_seed_profiles),
                "generated_partition_signatures_sha256": [
                    _direct_partition_signature_sha256(profile.unit_counts)
                    for profile in capacity_seed_profiles
                ],
                "maximum_candidate_count": (
                    _DIRECT_MEMBER_MAXIMUM_SHORT_PROOF_CAPACITY_SEED_PROFILE_COUNT
                ),
                "existing_musical_boundaries_only": True,
                "minimum_child_duration_seconds": (
                    _DIRECT_MEMBER_HIGHLIGHT_MINIMUM_RUN_SECONDS
                ),
                "full_selector_recheck_required": True,
                "cached_source_assignment_reused": False,
                "visual_gates_relaxed": False,
            },
            "dense_render_feedback_certificate_count": len(
                render_infeasible_transition_edges
            ),
            "dense_render_feedback_seed_profile_count": len(
                feedback_seed_profiles
            ),
            "dense_render_feedback_base_seed_included": True,
            "dense_render_feedback_guided_candidate_count": len(
                render_feedback_profiles
            ),
            "dense_render_feedback_guided_partition_signatures_sha256": [
                _direct_partition_signature_sha256(profile.unit_counts)
                for profile in render_feedback_profiles
            ],
            "dense_render_feedback_guided_candidates_run_full_selector": True,
            "dense_render_feedback_visual_thresholds_relaxed": False,
            "strict_composition_evaluation_limit": (
                partition_search_strict_terminal_audition_limit
            ),
            "strict_composition_limit_basis": (
                "decoded_render_feedback_global_first_cohort"
                if render_infeasible_transition_edges
                else "default_bounded_terminal_cohort"
            ),
        }
    )
    warm_start_diagnostics["candidate_evaluations"] = []
    partition_search_max_boundary_merge_count = (
        _direct_partition_proof_directed_boundary_merge_limit(base)
    )
    partition_search_max_shifted_boundary_count = min(
        max(0, len(base.spans) - 1),
        _DIRECT_MEMBER_MAX_SHIFTED_BOUNDARY_COUNT
        + partition_search_max_boundary_merge_count,
    )
    partition_search_max_limit_expansion_count = (
        partition_search_max_shifted_boundary_count
        + partition_search_max_boundary_merge_count
    )

    owned_provider: _VideoDescriptorProvider | None = None
    provider = descriptor_provider
    if provider is None:
        owned_provider = _VideoDescriptorProvider(
            eligible_sources,
            feature_cache_directory=feature_cache_directory,
        )
        provider = owned_provider

    attempted: list[dict[str, Any]] = []
    feasible: list[
        tuple[_DirectFullFramePartitionProfile, DirectMemberVisualSelection]
    ] = []
    failure_count = 0
    all_failures_proven = True
    latest_failure_diagnostics: dict[str, Any] | None = None
    partition_search_cap_reached = False
    partition_search_evaluation_limit = min(
        _DIRECT_MEMBER_MAX_PARTITION_PROFILE_COUNT,
        _DIRECT_MEMBER_MAX_PARTITION_PROFILE_UPPER_BOUND,
    )
    partition_search_limit_expansions: list[dict[str, Any]] = []
    partition_search_generated_profile_count = 1 + len(warm_start_profiles)
    partition_search_signature_deduplication_count = 0
    partition_search_future_state_dominance_count = 0
    partition_search_future_operation_state_count = 0
    partition_search_shift_depth_pruned_count = 0
    partition_search_exact_lifeline_retry_count = 0
    partition_search_exact_lifeline_retry_success_count = 0
    partition_search_exact_lifeline_retry_capacity_exhausted_count = 0
    partition_search_extra_quota_profile_count = 0
    partition_search_extra_quota_assignment_evaluation_count = 0
    partition_search_extra_quota_feasible_profile_count = 0
    partition_search_extra_quota_exhausted_profile_count = 0
    partition_search_extra_quota_capacity_exhausted_profile_count = 0
    partition_search_extra_quota_duplicate_certificate_count = 0
    partition_search_extra_quota_duplicate_certificate_saturated = False
    partition_search_extra_quota_exhausted_certificates: set[str] = set()
    partition_search_counterfactual_qualified_parent_count = 0
    partition_search_counterfactual_generated_profile_count = 0
    partition_search_counterfactual_evaluation_count = 0
    partition_search_counterfactual_feasible_profile_count = 0
    partition_search_counterfactual_hard_infeasible_profile_count = 0
    partition_search_counterfactual_capacity_exhausted_profile_count = 0
    partition_search_counterfactual_unproven_failure_profile_count = 0
    partition_search_counterfactual_promoted_queued_profile_count = 0
    partition_search_terminal_safe_hold_candidate_count = 0
    partition_search_terminal_safe_hold_evaluation_count = 0
    partition_search_terminal_safe_hold_success_count = 0
    partition_search_terminal_safe_hold_ineligible_failure_counts: dict[
        str, int
    ] = {}
    partition_search_terminal_safe_hold_auditioned_signatures: set[
        tuple[int, ...]
    ] = set()
    partition_search_cinematic_milp_infeasibility_diagnostic: (
        dict[str, Any] | None
    ) = None
    partition_search_cinematic_milp_infeasibility_profile: (
        _DirectFullFramePartitionProfile | None
    ) = None
    partition_search_minimum_hold_feedback_profiles: tuple[
        _DirectFullFramePartitionProfile,
        ...,
    ] = ()
    partition_search_minimum_hold_feedback_evaluation_count = 0
    partition_search_strict_terminal_audition_limit_reached = False
    partition_search_strict_terminal_audition_pruned_profile_count = 0
    partition_search_post_feasible_cost_pruned_profile_count = 0
    partition_search_counterfactual_authorization_proofs: list[
        dict[str, Any]
    ] = []
    partition_search_primary_evaluation_count = 0
    partition_search_composed_profile_evaluation_count = 0
    partition_search_warm_failure_seed_count = 0
    partition_search_warm_failure_seed_child_count = 0
    warm_start_strict_failures: list[
        tuple[
            _DirectFullFramePartitionProfile,
            DirectMemberVisualSelectionError,
        ]
    ] = []
    partition_search_failure_frontier_candidates: dict[
        tuple[int, ...],
        tuple[
            _DirectFullFramePartitionProfile,
            DirectMemberVisualSelectionError,
        ],
    ] = {}
    partition_search_queued_frontier_profiles: tuple[
        _DirectFullFramePartitionProfile,
        ...,
    ] = ()

    def _emit_progress(**payload: Any) -> None:
        if progress_callback is not None:
            progress_callback(
                {
                    "schema_version": 1,
                    "event": "direct_member_partition_profile_evaluation",
                    **payload,
                }
            )

    def _profile_progress_payload(
        profile: _DirectFullFramePartitionProfile,
        *,
        evaluation_index: int,
    ) -> dict[str, Any]:
        latest_operation = profile.latest_proof_operation
        return {
            "evaluation_index": evaluation_index,
            "evaluation_limit": partition_search_evaluation_limit,
            "profile_id": profile.profile_id,
            "shift_depth": profile.proof_directed_boundary_motion_count,
            "ordinary_shift_count": len(profile.boundary_shifts),
            "window_redistribution_count": len(
                profile.window_redistributions
            ),
            "visual_frontier_split_count": len(
                profile.visual_frontier_splits
            ),
            "proof_directed_boundary_merge_count": len(
                profile.boundary_merges
            ),
            "changed_boundary_count": profile.structural_change_count,
            "total_unit_displacement": profile.total_unit_displacement,
            "partition_signature_sha256": (
                _direct_partition_signature_sha256(profile.unit_counts)
            ),
            "parent_profile_id": (
                latest_operation.parent_profile_id
                if latest_operation is not None
                else None
            ),
            "parent_failed_segment_index": (
                latest_operation.proof_failed_segment_index
                if latest_operation is not None
                else None
            ),
            "proof_frontier_boundary_index": (
                getattr(
                    latest_operation,
                    "proof_frontier_boundary_index",
                    getattr(latest_operation, "boundary_index", None),
                )
                if latest_operation is not None
                else None
            ),
            "shifted_boundaries": [
                {
                    "boundary_index": shift.boundary_index,
                    "shift_units": shift.shift_units,
                }
                for shift in profile.boundary_shifts
            ],
            "window_redistributions": [
                {
                    "window_start_span_index": (
                        redistribution.window_start_span_index
                    ),
                    "proof_frontier_boundary_index": (
                        redistribution.proof_frontier_boundary_index
                    ),
                    "original_unit_counts": list(
                        redistribution.original_unit_counts
                    ),
                    "replacement_unit_counts": list(
                        redistribution.replacement_unit_counts
                    ),
                    "boundary_displacement_units": (
                        redistribution.boundary_displacement_units
                    ),
                }
                for redistribution in profile.window_redistributions
            ],
            "visual_frontier_splits": [
                {
                    "parent_span_index": split.parent_span_index,
                    "split_unit_offset": split.split_unit_offset,
                    "canonical_master_seconds": split.canonical_master_seconds,
                    "evidence_contract": split.evidence_contract,
                    "evidence_kind": split.evidence_kind,
                }
                for split in profile.visual_frontier_splits
            ],
            "proof_directed_boundary_merges": [
                {
                    "boundary_index": merge.boundary_index,
                    "merged_unit_count": merge.merged_unit_count,
                    "canonical_master_seconds": (
                        merge.canonical_master_seconds
                    ),
                }
                for merge in profile.boundary_merges
            ],
        }

    def _select_profile_with_config(
        profile: _DirectFullFramePartitionProfile,
        config: DirectMemberVisualConfig,
        *,
        extra_quota_source_indices: Sequence[int] | None = None,
        allow_safe_hold_search: bool = False,
    ) -> DirectMemberVisualSelection:
        """Run one partition with the complete bounded policy in demand mode."""

        demand_driven_observations = bool(
            callable(getattr(provider, 'focal_geometry_at', None))
            and represented_source_count == len(eligible_sources)
        )
        defer_safe_hold_search = bool(
            continuous_official_portrait_fancam_contract
            and not allow_safe_hold_search
            and not demand_driven_observations
        )
        profile_duration_seconds = sum(
            span.duration_seconds for span in profile.spans
        )
        global_cadence_hold_limit = (
            _direct_member_maximum_hold_count_for_global_cadence(
                boundary_count=max(0, len(profile.spans) - 1),
                total_duration_seconds=profile_duration_seconds,
            )
        )
        effective_config = replace(
            config,
            maximum_same_source_hold_count=(
                0
                if defer_safe_hold_search
                else min(
                    config.maximum_same_source_hold_count,
                    global_cadence_hold_limit,
                )
            ),
        )
        highlight_partition_capacity = (
            _direct_member_highlight_partition_capacity_payload(
                spans=profile.spans,
                highlight_intervals=normalized_highlight_intervals,
            )
        )
        priority_cut_boundary_indices = tuple(
            highlight_partition_capacity["priority_cut_boundary_indices"]
        )
        minimum_required_highlight_cut_count = int(
            highlight_partition_capacity[
                "minimum_required_highlight_cut_count"
            ]
        )
        if not highlight_partition_capacity["passed"]:
            raise DirectMemberVisualSelectionError(
                "direct member partition cannot supply minimum highlight cuts",
                {
                    "failure": "highlight_partition_cut_capacity_exhausted",
                    "constraint_infeasibility_proven": True,
                    "failed_at_segment_index": None,
                    "highlight_partition_capacity": (
                        highlight_partition_capacity
                    ),
                    "assignment_independent": True,
                    "partition_change_required": True,
                    "full_selector_recheck_completed": True,
                    "render_started": False,
                    "visual_gates_relaxed": False,
                },
            )
        maximum_priority_cut_hold_count = min(
            _DIRECT_MEMBER_MAXIMUM_COMPENSATED_HIGHLIGHT_HOLD_COUNT,
            max(
                0,
                len(priority_cut_boundary_indices)
                - minimum_required_highlight_cut_count,
            ),
        )
        forced_highlight_cut_boundaries: set[int] = set()
        highlight_hold_repair_attempts: list[dict[str, Any]] = []
        maximum_repair_attempt_count = max(1, len(profile.spans) - 1)
        while True:
            try:
                selection = select_balanced_direct_member_sources(
                    sources=eligible_sources,
                    canonical_spans=tuple(
                        (span.canonical_master_start, span.canonical_master_end)
                        for span in profile.spans
                    ),
                    audio_offsets=timing_draft.audio_offsets,
                    source_timewarps=compact_timewarps,
                    source_scene_cut_times=scene_cut_times,
                    source_frame_sizes=eligible_source_frame_sizes,
                    output_frame_size=output_frame_size,
                    continuous_official_portrait_fancam_contract=(
                        continuous_official_portrait_fancam_contract
                    ),
                    cinematic_bridge_enabled=bool(
                        (allow_safe_hold_search or demand_driven_observations)
                        and cinematic_bridge_enabled
                    ),
                    required_distinct_source_count=represented_source_count,
                    preferred_source_order=source_cycle,
                    extra_quota_source_indices=extra_quota_source_indices,
                    priority_cut_boundary_indices=(
                        priority_cut_boundary_indices
                    ),
                    forbidden_same_source_hold_boundary_indices=tuple(
                        sorted(forced_highlight_cut_boundaries)
                    ),
                    maximum_priority_cut_hold_count=(
                        maximum_priority_cut_hold_count
                    ),
                    render_infeasible_transition_edges=(
                        render_infeasible_transition_edges
                    ),
                    render_penalized_transition_edges=(
                        render_penalized_transition_edges
                    ),
                    joint_camera_failed_proposals=joint_camera_failed_proposals,
                    decoded_proxy_preferred_source_path=(
                        decoded_proxy_preferred_source_path
                        if decoded_proxy_preferred_source_path is not None
                        and len(decoded_proxy_preferred_source_path)
                        == len(profile.spans)
                        else None
                    ),
                    decoded_proxy_repair_target_boundary_indices=(
                        decoded_proxy_repair_target_boundary_indices
                        if decoded_proxy_preferred_source_path is not None
                        and len(decoded_proxy_preferred_source_path)
                        == len(profile.spans)
                        else ()
                    ),
                    forbidden_source_paths=(
                        forbidden_paths_by_partition.get(
                            profile.unit_counts,
                            (),
                        )
                    ),
                    config=effective_config,
                    descriptor_provider=provider,
                    demand_driven_observations=demand_driven_observations,
                )
            except DirectMemberVisualSelectionError as error:
                if highlight_hold_repair_attempts:
                    error.diagnostics["highlight_hold_repair"] = {
                        "contract": (
                            "post_alignment_density_constraint_generation_v1"
                        ),
                        "attempted": True,
                        "attempt_count": len(highlight_hold_repair_attempts),
                        "forced_cut_boundary_indices": sorted(
                            forced_highlight_cut_boundaries
                        ),
                        "attempts": highlight_hold_repair_attempts,
                        "result": "repair_selection_infeasible",
                        "visual_gates_relaxed": False,
                    }
                raise
            selection.optimizer_search_diagnostics[
                "global_visible_cut_cadence"
            ] = {
                "minimum_switches_per_minute": (
                    _DIRECT_MEMBER_MIN_SWITCHES_PER_MINUTE
                ),
                "profile_boundary_count": max(0, len(profile.spans) - 1),
                "profile_duration_seconds": profile_duration_seconds,
                "maximum_same_source_hold_count": global_cadence_hold_limit,
                "enforced_during_path_optimization": True,
            }
            selection.optimizer_search_diagnostics[
                "highlight_partition_capacity"
            ] = highlight_partition_capacity
            cadence_spans = _materialize_direct_member_local_cut_times(
                profile.spans,
                selection,
            )
            selection.optimizer_search_diagnostics[
                "highlight_cadence_span_basis"
            ] = "selected_boundary_master_seconds_v1"
            try:
                _enforce_direct_member_highlight_cadence_selection_gate(
                    spans=cadence_spans,
                    visual_selection=selection,
                    highlight_intervals=normalized_highlight_intervals,
                )
            except DirectMemberVisualSelectionError as error:
                highlight_payload = error.diagnostics.get(
                    "highlight_cut_density"
                )
                repair_boundaries = (
                    _direct_member_highlight_hold_repair_boundary_indices(
                        highlight_payload
                    )
                    if isinstance(highlight_payload, Mapping)
                    else ()
                )
                newly_forced = tuple(
                    index
                    for index in repair_boundaries
                    if index not in forced_highlight_cut_boundaries
                )
                repair_authorized = bool(
                    allow_safe_hold_search
                    and newly_forced
                    and len(highlight_hold_repair_attempts)
                    < maximum_repair_attempt_count
                )
                if not repair_authorized:
                    if highlight_hold_repair_attempts:
                        error.diagnostics["highlight_hold_repair"] = {
                            "contract": (
                                "post_alignment_density_constraint_generation_v1"
                            ),
                            "attempted": True,
                            "attempt_count": len(
                                highlight_hold_repair_attempts
                            ),
                            "forced_cut_boundary_indices": sorted(
                                forced_highlight_cut_boundaries
                            ),
                            "attempts": highlight_hold_repair_attempts,
                            "result": "repair_exhausted",
                            "visual_gates_relaxed": False,
                        }
                    raise
                forced_highlight_cut_boundaries.update(newly_forced)
                highlight_hold_repair_attempts.append(
                    {
                        "attempt_index": len(highlight_hold_repair_attempts) + 1,
                        "trigger_failure_reasons": list(
                            highlight_payload.get("failure_reasons", ())
                        ),
                        "observed_highlight_hold_boundary_indices": list(
                            repair_boundaries
                        ),
                        "new_forced_cut_boundary_indices": list(newly_forced),
                        "next_priority_cut_boundary_indices": sorted(
                            priority_cut_boundary_indices
                        ),
                        "next_forbidden_same_source_hold_boundary_indices": (
                            sorted(forced_highlight_cut_boundaries)
                        ),
                        "next_maximum_priority_cut_hold_count": (
                            maximum_priority_cut_hold_count
                        ),
                    }
                )
                continue
            selection.optimizer_search_diagnostics[
                "highlight_hold_repair"
            ] = {
                "contract": (
                    "post_alignment_density_constraint_generation_v1"
                ),
                "attempted": bool(highlight_hold_repair_attempts),
                "attempt_count": len(highlight_hold_repair_attempts),
                "forced_cut_boundary_indices": sorted(
                    forced_highlight_cut_boundaries
                ),
                "attempts": highlight_hold_repair_attempts,
                "result": (
                    "repaired" if highlight_hold_repair_attempts else "not_needed"
                ),
                "visual_gates_relaxed": False,
            }
            return selection

    def _evaluate(
        profile: _DirectFullFramePartitionProfile,
    ) -> DirectMemberVisualSelectionError | None:
        nonlocal failure_count
        nonlocal all_failures_proven
        nonlocal latest_failure_diagnostics
        nonlocal partition_search_exact_lifeline_retry_count
        nonlocal partition_search_exact_lifeline_retry_success_count
        nonlocal partition_search_exact_lifeline_retry_capacity_exhausted_count
        nonlocal partition_search_extra_quota_profile_count
        nonlocal partition_search_extra_quota_assignment_evaluation_count
        nonlocal partition_search_extra_quota_feasible_profile_count
        nonlocal partition_search_extra_quota_exhausted_profile_count
        nonlocal partition_search_extra_quota_capacity_exhausted_profile_count
        nonlocal partition_search_extra_quota_duplicate_certificate_count
        nonlocal partition_search_extra_quota_duplicate_certificate_saturated
        evaluation_index = len(attempted) + 1
        progress_payload = _profile_progress_payload(
            profile,
            evaluation_index=evaluation_index,
        )
        _emit_progress(
            phase="started",
            result=None,
            **progress_payload,
        )

        selection: DirectMemberVisualSelection | None = None
        error: DirectMemberVisualSelectionError | None = None
        exact_lifeline_retry: dict[str, Any] | None = None
        strict_extra_quota_assignment_search: dict[str, Any] | None = None
        try:
            selection = _select_profile_with_config(profile, selection_config)
        except DirectMemberVisualSelectionError as caught:
            error = caught
        if error is not None and _direct_visual_split_exact_lifeline_retry_is_authorized(
            profile,
            error,
            initial_state_limit=selection_config.feasibility_lifeline_state_limit,
        ):
            retry_config = replace(
                selection_config,
                feasibility_lifeline_state_limit=(
                    _DIRECT_MEMBER_VISUAL_SPLIT_EXACT_LIFELINE_RETRY_STATE_LIMIT
                ),
            )
            original_exact = error.diagnostics.get("search", {}).get(
                "exact_lifeline",
                {},
            )
            exact_lifeline_retry = {
                "contract": (
                    "visual_frontier_exact_lifeline_capacity_retry_v1"
                ),
                "attempted": True,
                "initial_state_limit": (
                    selection_config.feasibility_lifeline_state_limit
                ),
                "retry_state_limit": (
                    retry_config.feasibility_lifeline_state_limit
                ),
                "trigger": "exact_lifeline_state_capacity_exhausted",
                "initial_explored_state_count": original_exact.get(
                    "explored_state_count"
                ) if isinstance(original_exact, dict) else None,
                "visual_gates_relaxed": False,
                "duration_state_quantization_applied": False,
            }
            partition_search_exact_lifeline_retry_count += 1
            _emit_progress(
                event="direct_member_visual_split_exact_lifeline_retry",
                phase="exact_lifeline_retry_started",
                result=None,
                **exact_lifeline_retry,
                **progress_payload,
            )
            try:
                selection = _select_profile_with_config(
                    profile,
                    retry_config,
                )
                error = None
            except DirectMemberVisualSelectionError as retry_error:
                error = retry_error
            final_exact = (
                error.diagnostics.get("search", {}).get(
                    "exact_lifeline",
                    {},
                )
                if error is not None
                else {}
            )
            retry_result = (
                "feasible"
                if error is None
                else "capacity_exhausted"
                if error.diagnostics.get("failure")
                == "search_capacity_exhausted"
                else "hard_infeasible"
            )
            exact_lifeline_retry.update(
                {
                    "result": retry_result,
                    "final_failure": (
                        error.diagnostics.get("failure")
                        if error is not None
                        else None
                    ),
                    "final_explored_state_count": (
                        final_exact.get("explored_state_count")
                        if isinstance(final_exact, dict)
                        else None
                    ),
                    "final_state_capacity_exhausted": (
                        final_exact.get("state_capacity_exhausted")
                        if isinstance(final_exact, dict)
                        else False
                    ),
                    "final_duration_state_quantization_applied": (
                        final_exact.get("duration_state_quantization_applied")
                        if isinstance(final_exact, dict)
                        else False
                    ),
                }
            )
            if error is None:
                partition_search_exact_lifeline_retry_success_count += 1
            elif error.diagnostics.get("failure") == "search_capacity_exhausted":
                partition_search_exact_lifeline_retry_capacity_exhausted_count += 1
            _emit_progress(
                event="direct_member_visual_split_exact_lifeline_retry",
                phase="exact_lifeline_retry_completed",
                **exact_lifeline_retry,
                **progress_payload,
            )
        if (
            error is not None
            and _direct_strict_extra_quota_assignment_search_is_authorized(
                represented_source_count=represented_source_count,
                source_count=len(eligible_sources),
                qualified_profile_count=(
                    partition_search_extra_quota_profile_count
                ),
                diagnostics=error.diagnostics,
                duplicate_certificate_saturated=(
                    partition_search_extra_quota_duplicate_certificate_saturated
                ),
            )
        ):
            quota_assignment_config = (
                retry_config
                if exact_lifeline_retry is not None
                and exact_lifeline_retry.get("result") == "hard_infeasible"
                else selection_config
            )
            extra_quota_assignments = (
                _direct_strict_extra_quota_assignment_candidates(
                    span_count=len(profile.spans),
                    source_count=len(eligible_sources),
                    source_order=source_cycle,
                    diagnostics=error.diagnostics,
                )
            )
            if extra_quota_assignments:
                _base_quota, extra_quota_count = divmod(
                    len(profile.spans),
                    len(eligible_sources),
                )
                default_extra_assignment = tuple(
                    int(index) for index in source_cycle[:extra_quota_count]
                )
                assignment_results: list[dict[str, Any]] = []
                feasible_assignments: list[
                    tuple[tuple[int, ...], DirectMemberVisualSelection]
                ] = []
                capacity_errors: list[DirectMemberVisualSelectionError] = []
                proven_errors: list[DirectMemberVisualSelectionError] = []
                unproven_errors: list[DirectMemberVisualSelectionError] = []
                partition_search_extra_quota_profile_count += 1
                _emit_progress(
                    event="direct_member_strict_extra_quota_assignment_search",
                    phase="extra_quota_assignment_search_started",
                    result=None,
                    contract="strict_balanced_extra_quota_assignment_search_v1",
                    default_extra_quota_source_indices=list(
                        default_extra_assignment
                    ),
                    alternative_assignment_count=len(extra_quota_assignments),
                    maximum_qualified_profile_count=(
                        _DIRECT_MEMBER_MAX_EXTRA_QUOTA_PROFILE_COUNT
                    ),
                    maximum_assignment_count=(
                        _DIRECT_MEMBER_MAX_EXTRA_QUOTA_ASSIGNMENT_COUNT
                    ),
                    source_search_order=list(source_cycle),
                    source_search_order_changed=False,
                    counts_differ_by_at_most_one=True,
                    visual_gates_relaxed=False,
                    **progress_payload,
                )
                for assignment_index, assignment in enumerate(
                    extra_quota_assignments,
                    start=1,
                ):
                    partition_search_extra_quota_assignment_evaluation_count += 1
                    alternate_selection: DirectMemberVisualSelection | None = None
                    alternate_error: DirectMemberVisualSelectionError | None = None
                    try:
                        alternate_selection = _select_profile_with_config(
                            profile,
                            quota_assignment_config,
                            extra_quota_source_indices=assignment,
                        )
                    except DirectMemberVisualSelectionError as caught:
                        alternate_error = caught
                    alternate_exact = (
                        alternate_error.diagnostics.get("search", {}).get(
                            "exact_lifeline",
                            {},
                        )
                        if alternate_error is not None
                        else {}
                    )
                    if alternate_selection is not None:
                        assignment_result = "feasible"
                        feasible_assignments.append(
                            (assignment, alternate_selection)
                        )
                    elif (
                        alternate_error is not None
                        and alternate_error.diagnostics.get("failure")
                        == "search_capacity_exhausted"
                    ):
                        assignment_result = "capacity_exhausted"
                        capacity_errors.append(alternate_error)
                    elif (
                        alternate_error is not None
                        and _direct_strict_extra_quota_assignment_failure_is_proven(
                            alternate_error.diagnostics
                        )
                    ):
                        assignment_result = "hard_infeasible"
                        proven_errors.append(alternate_error)
                    else:
                        assignment_result = "unproven_failure"
                        if alternate_error is not None:
                            unproven_errors.append(alternate_error)
                    item = {
                        "assignment_index": assignment_index,
                        "extra_quota_source_indices": list(assignment),
                        "result": assignment_result,
                        "failure": (
                            alternate_error.diagnostics.get("failure")
                            if alternate_error is not None
                            else None
                        ),
                        "constraint_infeasibility_proven": (
                            alternate_error.diagnostics.get(
                                "constraint_infeasibility_proven"
                            )
                            if alternate_error is not None
                            else False
                        ),
                        "exact_lifeline_explored_state_count": (
                            alternate_exact.get("explored_state_count")
                            if isinstance(alternate_exact, dict)
                            else None
                        ),
                        "exact_lifeline_state_capacity_exhausted": (
                            alternate_exact.get("state_capacity_exhausted")
                            if isinstance(alternate_exact, dict)
                            else False
                        ),
                        "duration_state_quantization_applied": (
                            alternate_exact.get(
                                "duration_state_quantization_applied"
                            )
                            if isinstance(alternate_exact, dict)
                            else False
                        ),
                    }
                    assignment_results.append(item)
                    _emit_progress(
                        event=(
                            "direct_member_strict_extra_quota_assignment_search"
                        ),
                        phase="extra_quota_assignment_evaluated",
                        **item,
                        **progress_payload,
                    )

                total_assignment_domain_count = math.comb(
                    len(eligible_sources),
                    extra_quota_count,
                )
                assignment_domain_complete = (
                    not capacity_errors
                    and not unproven_errors
                    and len(assignment_results) == len(extra_quota_assignments)
                    and len(extra_quota_assignments) + 1
                    == total_assignment_domain_count
                )
                selected_assignment: tuple[int, ...] | None = None
                if capacity_errors:
                    selection = None
                    error = capacity_errors[0]
                    partition_search_extra_quota_capacity_exhausted_profile_count += 1
                elif unproven_errors:
                    selection = None
                    error = unproven_errors[0]
                elif feasible_assignments and assignment_domain_complete:
                    selected_assignment, selection = min(
                        feasible_assignments,
                        key=lambda item: (
                            _direct_partition_selection_rank(profile, item[1]),
                            item[0],
                        ),
                    )
                    error = None
                    partition_search_extra_quota_feasible_profile_count += 1
                else:
                    selection = None
                    if proven_errors:
                        error = proven_errors[-1]
                    partition_search_extra_quota_exhausted_profile_count += 1
                certificate_payload = {
                    "default_extra_quota_source_indices": list(
                        default_extra_assignment
                    ),
                    "total_assignment_domain_count": (
                        total_assignment_domain_count
                    ),
                    "alternative_assignments": assignment_results,
                }
                assignment_certificate_sha256 = hashlib.sha256(
                    json.dumps(
                        certificate_payload,
                        ensure_ascii=False,
                        sort_keys=True,
                        separators=(",", ":"),
                    ).encode("utf-8")
                ).hexdigest()
                all_alternatives_proven_hard_infeasible = bool(
                    assignment_domain_complete
                    and not feasible_assignments
                    and len(proven_errors) == len(extra_quota_assignments)
                )
                duplicate_exhausted_certificate = bool(
                    all_alternatives_proven_hard_infeasible
                    and assignment_certificate_sha256
                    in partition_search_extra_quota_exhausted_certificates
                )
                if all_alternatives_proven_hard_infeasible:
                    partition_search_extra_quota_exhausted_certificates.add(
                        assignment_certificate_sha256
                    )
                if duplicate_exhausted_certificate:
                    partition_search_extra_quota_duplicate_certificate_count += 1
                    partition_search_extra_quota_duplicate_certificate_saturated = (
                        True
                    )
                strict_extra_quota_assignment_search = {
                    "contract": (
                        "strict_balanced_extra_quota_assignment_search_v1"
                    ),
                    "trigger": (
                        "exact_default_quota_assignment_hard_infeasible"
                    ),
                    "state_limit": (
                        quota_assignment_config.feasibility_lifeline_state_limit
                    ),
                    "state_limit_expanded": bool(
                        quota_assignment_config.feasibility_lifeline_state_limit
                        > selection_config.feasibility_lifeline_state_limit
                    ),
                    "source_search_order": list(source_cycle),
                    "source_search_order_changed": False,
                    "base_quota": _base_quota,
                    "extra_quota_count": extra_quota_count,
                    "default_extra_quota_source_indices": list(
                        default_extra_assignment
                    ),
                    "alternative_assignment_count": len(
                        extra_quota_assignments
                    ),
                    "total_assignment_domain_count": (
                        total_assignment_domain_count
                    ),
                    "maximum_assignment_count": (
                        _DIRECT_MEMBER_MAX_EXTRA_QUOTA_ASSIGNMENT_COUNT
                    ),
                    "maximum_qualified_profile_count": (
                        _DIRECT_MEMBER_MAX_EXTRA_QUOTA_PROFILE_COUNT
                    ),
                    "assignments_evaluated": assignment_results,
                    "complete_assignment_domain_evaluated": (
                        assignment_domain_complete
                    ),
                    "default_assignment_proven_hard_infeasible": True,
                    "all_alternatives_proven_hard_infeasible": bool(
                        all_alternatives_proven_hard_infeasible
                    ),
                    "duplicate_exhausted_assignment_certificate": (
                        duplicate_exhausted_certificate
                    ),
                    "further_profile_search_saturated": (
                        partition_search_extra_quota_duplicate_certificate_saturated
                    ),
                    "capacity_exhausted": bool(capacity_errors),
                    "feasible_assignment_count": len(feasible_assignments),
                    "selected_extra_quota_source_indices": (
                        list(selected_assignment)
                        if selected_assignment is not None
                        else None
                    ),
                    "assignment_certificate_sha256": (
                        assignment_certificate_sha256
                    ),
                    "counts_differ_by_at_most_one": True,
                    "visual_gates_relaxed": False,
                }
                if error is not None:
                    error = DirectMemberVisualSelectionError(
                        str(error),
                        {
                            **error.diagnostics,
                            "strict_extra_quota_assignment_search": (
                                strict_extra_quota_assignment_search
                            ),
                        },
                    )
                _emit_progress(
                    event="direct_member_strict_extra_quota_assignment_search",
                    phase="extra_quota_assignment_search_completed",
                    result=(
                        "capacity_exhausted"
                        if capacity_errors
                        else "feasible"
                        if selection is not None
                        else "all_assignments_hard_infeasible"
                    ),
                    complete_assignment_domain_evaluated=(
                        assignment_domain_complete
                    ),
                    alternative_assignment_count=len(
                        extra_quota_assignments
                    ),
                    total_assignment_domain_count=(
                        total_assignment_domain_count
                    ),
                    feasible_assignment_count=len(feasible_assignments),
                    selected_extra_quota_source_indices=(
                        list(selected_assignment)
                        if selected_assignment is not None
                        else None
                    ),
                    assignment_certificate_sha256=(
                        strict_extra_quota_assignment_search[
                            "assignment_certificate_sha256"
                        ]
                    ),
                    duplicate_exhausted_assignment_certificate=(
                        duplicate_exhausted_certificate
                    ),
                    further_profile_search_saturated=(
                        partition_search_extra_quota_duplicate_certificate_saturated
                    ),
                    visual_gates_relaxed=False,
                    **progress_payload,
                )
        if error is not None:
            failure_count += 1
            failure_is_proven = _direct_partition_failure_is_proven(
                error.diagnostics
            )
            all_failures_proven = all_failures_proven and failure_is_proven
            latest_failure_diagnostics = error.diagnostics
            failure_result = _direct_partition_failure_result(error.diagnostics)
            attempted.append(
                {
                    **profile.to_dict(),
                    "status": failure_result,
                    "hard_violation_count": None,
                    "visual_gates_relaxed": False,
                    **(
                        {"exact_lifeline_retry": exact_lifeline_retry}
                        if exact_lifeline_retry is not None
                        else {}
                    ),
                    **(
                        {
                            "strict_extra_quota_assignment_search": (
                                strict_extra_quota_assignment_search
                            )
                        }
                        if strict_extra_quota_assignment_search is not None
                        else {}
                    ),
                    "diagnostics": _compact_direct_partition_failure(
                        error,
                        span_count=len(profile.spans),
                    ),
                }
            )
            next_proofs = _direct_partition_exact_shift_proofs(
                error.diagnostics,
                span_count=len(profile.spans),
            )
            _emit_progress(
                phase="completed",
                result=failure_result,
                failure=error.diagnostics.get("failure"),
                failed_segment_index=error.diagnostics.get(
                    "failed_at_segment_index"
                ),
                next_proven_frontier_boundary_indices=[
                    proof.boundary_index for proof in next_proofs
                ],
                profile_cap_reached=False,
                **progress_payload,
            )
            return error
        if selection is None:
            raise RuntimeError("direct member selector returned no result")
        feasible.append((profile, selection))
        rank = _direct_partition_selection_rank(profile, selection)
        attempted.append(
            {
                **profile.to_dict(),
                "status": "feasible",
                "hard_violation_count": 0,
                "visual_gates_relaxed": False,
                **(
                    {"exact_lifeline_retry": exact_lifeline_retry}
                    if exact_lifeline_retry is not None
                    else {}
                ),
                **(
                    {
                        "strict_extra_quota_assignment_search": (
                            strict_extra_quota_assignment_search
                        )
                    }
                    if strict_extra_quota_assignment_search is not None
                    else {}
                ),
                "selection_rank": {
                    "warning_boundary_count": rank[0],
                    "optimizer_cost": rank[1],
                    "changed_span_count": rank[2],
                    "musical_boundary_penalty": rank[3],
                },
            }
        )
        _emit_progress(
            phase="completed",
            result="feasible",
            failed_segment_index=None,
            next_proven_frontier_boundary_indices=[],
            profile_cap_reached=False,
            **progress_payload,
        )
        return None

    try:
        base_error = _evaluate(base)
        partition_search_primary_evaluation_count = len(attempted)
        if (
            continuous_official_portrait_fancam_contract
            and not feasible
            and base_error is not None
            and _direct_partition_failure_is_proven(base_error.diagnostics)
            and warm_start_profiles
        ):
            for warm_start_index, warm_profile in enumerate(
                warm_start_profiles,
                start=1,
            ):
                warm_signature = _direct_partition_signature_sha256(
                    warm_profile.unit_counts
                )
                warm_error = _evaluate(warm_profile)
                partition_search_primary_evaluation_count = len(attempted)
                warm_evaluation: dict[str, Any] = {
                    "candidate_index": warm_start_index,
                    "candidate_count": len(warm_start_profiles),
                    "partition_signature_sha256": warm_signature,
                    "strict_result": (
                        "feasible" if warm_error is None else "infeasible"
                    ),
                    "strict_failure": (
                        warm_error.diagnostics.get("failure")
                        if warm_error is not None
                        else None
                    ),
                    "strict_constraint_infeasibility_proven": (
                        _direct_partition_failure_is_proven(
                            warm_error.diagnostics
                        )
                        if warm_error is not None
                        else False
                    ),
                    "terminal_audition_attempted": False,
                    "full_selector_recheck_completed": True,
                    "visual_gates_relaxed": False,
                }
                warm_start_diagnostics["candidate_evaluations"].append(
                    warm_evaluation
                )
                if warm_error is None:
                    warm_evaluation["result"] = "strict_feasible"
                    break
                if not _direct_partition_failure_is_proven(
                    warm_error.diagnostics
                ):
                    warm_evaluation["result"] = (
                        "strict_failure_not_terminal_authorized"
                    )
                    continue
                # Retain every proved warm-start failure as a structural seed.
                # With decoded-render feedback present, its exact repair
                # children must run before any no-cut terminal escape; an
                # early hold can otherwise discard the requested visible cut
                # and repeat the same dense-render failure on the next pass.
                warm_start_strict_failures.append(
                    (warm_profile, warm_error)
                )
                warm_evaluation["render_feedback_lineage"] = bool(
                    _direct_partition_has_render_feedback_lineage(
                        warm_profile
                    )
                )

                if not _direct_partition_warm_terminal_audition_is_authorized(
                    warm_error.diagnostics,
                    render_infeasible_transition_edges,
                ):
                    render_feedback_defers_terminal = bool(
                        render_infeasible_transition_edges
                        and _direct_partition_terminal_hold_failure_is_eligible(
                            warm_error.diagnostics
                        )
                    )
                    warm_evaluation.update(
                        {
                            "terminal_audition_authorized": False,
                            "terminal_audition_ineligible_failure": (
                                warm_error.diagnostics.get("failure")
                            ),
                            "terminal_audition_ineligible_reason": (
                                "decoded_render_feedback_requires_strict_"
                                "structural_repair_first"
                                if render_feedback_defers_terminal
                                else "same_source_hold_cannot_repair_content_"
                                "or_quota_validity_failure"
                            ),
                            "result": (
                                "strict_failure_dense_feedback_search_seed"
                                if render_feedback_defers_terminal
                                else "strict_failure_search_seed"
                            ),
                        }
                    )
                    continue

                partition_search_terminal_safe_hold_candidate_count += 1
                partition_search_terminal_safe_hold_evaluation_count += 1
                partition_search_terminal_safe_hold_auditioned_signatures.add(
                    warm_profile.unit_counts
                )
                warm_evaluation["terminal_audition_attempted"] = True
                terminal_payload = {
                    "contract": (
                        "exact_input_bound_partition_warm_start_"
                        "independent_safe_hold_effect_audition_v2"
                    ),
                    "attempted": True,
                    "trigger": "exact_input_binding_and_strict_hard_failure",
                    "candidate_count": len(warm_start_profiles),
                    "evaluation_index": warm_start_index,
                    "evaluation_limit": len(warm_start_profiles),
                    "selected_profile_id": warm_profile.profile_id,
                    "selected_partition_signature_sha256": warm_signature,
                    "selected_strict_failed_segment_index": (
                        warm_error.diagnostics.get("failed_at_segment_index")
                    ),
                    "full_selector_recheck_required": True,
                    "visual_gates_relaxed": False,
                }
                _emit_progress(
                    event="direct_member_input_bound_partition_warm_start",
                    phase="terminal_audition_started",
                    result=None,
                    **terminal_payload,
                )
                terminal_selection: DirectMemberVisualSelection | None = None
                terminal_hold_error: DirectMemberVisualSelectionError | None = None
                try:
                    terminal_selection = _select_profile_with_config(
                        warm_profile,
                        selection_config,
                        allow_safe_hold_search=True,
                    )
                except DirectMemberVisualSelectionError as caught:
                    terminal_hold_error = caught
                terminal_payload["result"] = (
                    "feasible"
                    if terminal_selection is not None
                    else "infeasible"
                )
                terminal_payload["final_failure"] = (
                    terminal_hold_error.diagnostics.get("failure")
                    if terminal_hold_error is not None
                    else None
                )
                attempted_item = attempted[-1]
                if (
                    attempted_item.get("partition_signature_sha256")
                    != warm_signature
                ):
                    raise RuntimeError(
                        "warm-start strict attempt lost its terminal binding"
                    )
                attempted_item["input_bound_warm_start_audition"] = dict(
                    terminal_payload
                )
                warm_evaluation.update(
                    {
                        "terminal_result": terminal_payload["result"],
                        "terminal_failure": terminal_payload["final_failure"],
                        "result": terminal_payload["result"],
                    }
                )
                if terminal_selection is not None:
                    partition_search_terminal_safe_hold_success_count += 1
                    feasible.append((warm_profile, terminal_selection))
                    terminal_rank = _direct_partition_selection_rank(
                        warm_profile,
                        terminal_selection,
                    )
                    attempted_item[
                        "strict_status_before_input_bound_warm_start_audition"
                    ] = attempted_item.get("status")
                    strict_diagnostics = attempted_item.pop("diagnostics", None)
                    if strict_diagnostics is not None:
                        attempted_item[
                            "strict_failure_before_input_bound_warm_start_audition"
                        ] = strict_diagnostics
                    attempted_item["status"] = "feasible"
                    attempted_item["hard_violation_count"] = 0
                    attempted_item["selection_rank"] = {
                        "warning_boundary_count": terminal_rank[0],
                        "optimizer_cost": terminal_rank[1],
                        "changed_span_count": terminal_rank[2],
                        "musical_boundary_penalty": terminal_rank[3],
                    }
                else:
                    assert terminal_hold_error is not None
                    latest_failure_diagnostics = terminal_hold_error.diagnostics
                    all_failures_proven = bool(
                        all_failures_proven
                        and _direct_partition_failure_is_proven(
                            terminal_hold_error.diagnostics
                        )
                    )
                    attempted_item["input_bound_warm_start_failure"] = (
                        _compact_direct_partition_failure(
                            terminal_hold_error,
                            span_count=len(warm_profile.spans),
                        )
                    )
                _emit_progress(
                    event="direct_member_input_bound_partition_warm_start",
                    phase="terminal_audition_completed",
                    **terminal_payload,
                )
                if terminal_selection is not None:
                    break
        if (
            continuous_official_portrait_fancam_contract
            and not feasible
            and base_error is not None
            and _direct_partition_failure_is_proven(base_error.diagnostics)
        ):
            # Bounded best-first search over causally generated children.  A
            # signature enters the queue once, every child is bound to its
            # parent's exact connectivity proof, and a failed child may move
            # only one new proof-authorized boundary before being fully rechecked.
            queued: list[
                tuple[
                    tuple[int, int, int, int, int],
                    int,
                    _DirectFullFramePartitionProfile,
                ]
            ] = []
            queued_sequence = 0
            seen_signatures = {
                base.unit_counts,
                *(profile.unit_counts for profile in warm_start_profiles),
            }
            evaluated_signatures = set(seen_signatures)
            seen_future_operation_states: set[tuple[Any, ...]] = set()
            counterfactual_secondary_profiles: list[
                _DirectFullFramePartitionProfile
            ] = []
            terminal_safe_hold_candidates = (
                partition_search_failure_frontier_candidates
            )

            def _record_terminal_safe_hold_candidate(
                profile: _DirectFullFramePartitionProfile,
                error: DirectMemberVisualSelectionError,
            ) -> None:
                if not _direct_partition_failure_is_proven(error.diagnostics):
                    return
                if not _direct_partition_terminal_hold_failure_is_eligible(
                    error.diagnostics
                ):
                    failure = str(
                        error.diagnostics.get("failure", "unknown")
                    )
                    partition_search_terminal_safe_hold_ineligible_failure_counts[
                        failure
                    ] = (
                        partition_search_terminal_safe_hold_ineligible_failure_counts.get(
                            failure,
                            0,
                        )
                        + 1
                    )
                    return
                terminal_safe_hold_candidates.setdefault(
                    profile.unit_counts,
                    (profile, error),
                )

            def _collect_counterfactual_secondary_profile(
                parent: _DirectFullFramePartitionProfile,
                error: DirectMemberVisualSelectionError,
            ) -> None:
                nonlocal partition_search_generated_profile_count
                nonlocal partition_search_signature_deduplication_count
                nonlocal partition_search_counterfactual_qualified_parent_count
                nonlocal partition_search_counterfactual_generated_profile_count
                nonlocal partition_search_counterfactual_promoted_queued_profile_count
                if (
                    len(counterfactual_secondary_profiles)
                    >= _DIRECT_MEMBER_MAX_COUNTERFACTUAL_SECONDARY_SPLIT_PROFILE_COUNT
                    or partition_search_counterfactual_qualified_parent_count
                    >= _DIRECT_MEMBER_MAX_COUNTERFACTUAL_SECONDARY_SPLIT_PROFILE_COUNT
                    or len(parent.visual_frontier_splits)
                    != _DIRECT_MEMBER_COUNTERFACTUAL_SECONDARY_SPLIT_TRIGGER_COUNT
                    or not _direct_severe_counterfactual_retry_is_authorized(
                        error.diagnostics,
                        span_count=len(parent.spans),
                    )
                ):
                    return
                partition_search_counterfactual_qualified_parent_count += 1
                children = _direct_full_frame_visual_frontier_split_child_profiles(
                    timing_draft.segments,
                    parent,
                    error.diagnostics,
                    config=selection_config,
                    allow_counterfactual_secondary_split=True,
                )
                if len(children) > 1:
                    raise RuntimeError(
                        "counterfactual secondary split generated multiple children"
                    )
                for child in children:
                    action = _direct_counterfactual_secondary_signature_action(
                        child.unit_counts,
                        evaluated_signatures=evaluated_signatures,
                        queued_signatures={
                            item[2].unit_counts for item in queued
                        },
                        reserved_signatures={
                            item.unit_counts
                            for item in counterfactual_secondary_profiles
                        },
                        seen_signatures=seen_signatures,
                    )
                    if action == "duplicate":
                        partition_search_signature_deduplication_count += 1
                        continue
                    if action == "promote_queued":
                        queued[:] = [
                            item
                            for item in queued
                            if item[2].unit_counts != child.unit_counts
                        ]
                        partition_search_counterfactual_promoted_queued_profile_count += 1
                    else:
                        seen_signatures.add(child.unit_counts)
                        partition_search_generated_profile_count += 1
                    counterfactual_secondary_profiles.append(child)
                    partition_search_counterfactual_generated_profile_count += 1
                    compact_authorization = (
                        _compact_direct_severe_counterfactual(
                            error.diagnostics
                        )
                    )
                    if compact_authorization is None:
                        raise RuntimeError(
                            "authorized counterfactual secondary split lost "
                            "its compact minimum-severe proof"
                        )
                    partition_search_counterfactual_authorization_proofs.append(
                        {
                            "parent_profile_id": parent.profile_id,
                            "parent_partition_signature_sha256": (
                                _direct_partition_signature_sha256(
                                    parent.unit_counts
                                )
                            ),
                            "child_profile_id": child.profile_id,
                            "child_partition_signature_sha256": (
                                _direct_partition_signature_sha256(
                                    child.unit_counts
                                )
                            ),
                            "authorization": compact_authorization,
                        }
                    )
                    _emit_progress(
                        event=(
                            "direct_member_severe_counterfactual_secondary_split"
                        ),
                        phase="secondary_profile_queued",
                        result=None,
                        contract=(
                            "bounded_diagnostic_severe_counterfactual_"
                            "secondary_partition_v1"
                        ),
                        parent_profile_id=parent.profile_id,
                        profile_id=child.profile_id,
                        maximum_profile_count=(
                            _DIRECT_MEMBER_MAX_COUNTERFACTUAL_SECONDARY_SPLIT_PROFILE_COUNT
                        ),
                        queued_profile_count=len(counterfactual_secondary_profiles),
                        witness_selection_eligible=False,
                        witness_render_authorized=False,
                        full_selector_recheck_required=True,
                        visual_gates_relaxed=False,
                    )

            def _enqueue_children(
                parent: _DirectFullFramePartitionProfile,
                error: DirectMemberVisualSelectionError,
            ) -> int:
                nonlocal queued_sequence
                nonlocal partition_search_generated_profile_count
                nonlocal partition_search_signature_deduplication_count
                nonlocal partition_search_future_state_dominance_count
                nonlocal partition_search_future_operation_state_count
                nonlocal partition_search_shift_depth_pruned_count
                children = _direct_full_frame_proof_directed_repair_profiles(
                    timing_draft.segments,
                    parent,
                    error.diagnostics,
                    config=selection_config,
                )
                if (
                    not children
                    and parent.proof_directed_boundary_motion_count
                    >= _direct_partition_proof_directed_boundary_shift_limit(
                        parent
                    )
                ):
                    partition_search_shift_depth_pruned_count += 1
                    return 0
                future_state = _direct_partition_future_operation_state_key(
                    parent,
                    error.diagnostics,
                    children,
                )
                if future_state in seen_future_operation_states:
                    partition_search_future_state_dominance_count += 1
                    return 0
                seen_future_operation_states.add(future_state)
                partition_search_future_operation_state_count += 1
                enqueued_count = 0
                for child in children:
                    if child.unit_counts in seen_signatures:
                        partition_search_signature_deduplication_count += 1
                        continue
                    seen_signatures.add(child.unit_counts)
                    priority = _direct_partition_queue_priority(child)
                    queued.append((priority, queued_sequence, child))
                    queued_sequence += 1
                    partition_search_generated_profile_count += 1
                    enqueued_count += 1
                return enqueued_count

            _record_terminal_safe_hold_candidate(base, base_error)
            _enqueue_children(base, base_error)
            for warm_profile, warm_error in warm_start_strict_failures:
                _record_terminal_safe_hold_candidate(
                    warm_profile,
                    warm_error,
                )
                partition_search_warm_failure_seed_count += 1
                partition_search_warm_failure_seed_child_count += (
                    _enqueue_children(warm_profile, warm_error)
                )
            warm_start_diagnostics.update(
                {
                    "proven_failure_search_seed_count": (
                        partition_search_warm_failure_seed_count
                    ),
                    "proven_failure_search_seed_child_count": (
                        partition_search_warm_failure_seed_child_count
                    ),
                    "proven_failure_search_seed_full_selector_recheck": True,
                    "visual_gates_relaxed": False,
                }
            )
            # Once one feasible profile exists, prune only strictly deeper or
            # more displaced structural edits.  Musical-boundary penalty is a
            # selection tie-breaker after the real visual optimizer cost is
            # known; using it here would discard an unevaluated peer that may
            # have markedly better decoded continuity.
            minimum_feasible_structural_cost: tuple[int, int] | None = None
            while queued:
                if _direct_partition_terminal_audition_due(
                    evaluated_profile_count=(
                        partition_search_composed_profile_evaluation_count
                    ),
                    feasible_profile_count=len(feasible),
                    queued_profile_count=len(queued),
                    maximum_evaluation_count=(
                        partition_search_strict_terminal_audition_limit
                    ),
                    evaluated_total_profile_count=len(attempted),
                    admitted_total_profile_limit=(
                        partition_search_evaluation_limit
                        if partition_search_limit_expansions
                        else 0
                    ),
                ):
                    partition_search_strict_terminal_audition_limit_reached = True
                    partition_search_strict_terminal_audition_pruned_profile_count = (
                        len(queued)
                    )
                    _emit_progress(
                        event=(
                            "direct_member_strict_terminal_audition_completed"
                        ),
                        phase="strict_terminal_audition_completed",
                        result="bounded_terminal_cohort_ready",
                        evaluated_terminal_candidate_count=len(
                            terminal_safe_hold_candidates
                        ),
                        ineligible_terminal_candidate_count=sum(
                            partition_search_terminal_safe_hold_ineligible_failure_counts.values()
                        ),
                        ineligible_terminal_candidate_failure_counts=dict(
                            sorted(
                                partition_search_terminal_safe_hold_ineligible_failure_counts.items()
                            )
                        ),
                        maximum_terminal_candidate_count=(
                            partition_search_strict_terminal_audition_limit
                        ),
                        admitted_total_profile_limit=(
                            partition_search_evaluation_limit
                            if partition_search_limit_expansions
                            else 0
                        ),
                        composed_profile_evaluation_count=(
                            partition_search_composed_profile_evaluation_count
                        ),
                        maximum_proof_progress=max(
                            (
                                _direct_partition_terminal_candidate_progress(
                                    item[0], item[1]
                                )
                                for item in terminal_safe_hold_candidates.values()
                            ),
                            default=-1,
                        ),
                        unevaluated_structural_profile_count=len(queued),
                        visual_gates_relaxed=False,
                    )
                    break
                if minimum_feasible_structural_cost is None:
                    queued.sort(key=lambda item: (item[0], item[1]))
                else:
                    eligible_queue = [
                        item
                        for item in queued
                        if item[0][2:4] <= minimum_feasible_structural_cost
                    ]
                    partition_search_post_feasible_cost_pruned_profile_count += (
                        len(queued) - len(eligible_queue)
                    )
                    queued = eligible_queue
                    if not queued:
                        break
                    queued.sort(
                        key=lambda item: (
                            item[0][2:4],
                            item[0][0:2],
                            item[0][4],
                            item[1],
                        )
                    )
                if len(attempted) >= partition_search_evaluation_limit:
                    if (
                        len(partition_search_limit_expansions)
                        >= partition_search_max_limit_expansion_count
                    ):
                        partition_search_cap_reached = True
                        break
                    queued_profiles = tuple(item[2] for item in queued)
                    queued_unique_count = len(
                        {profile.unit_counts for profile in queued_profiles}
                    )
                    if queued_unique_count != len(queued_profiles):
                        raise RuntimeError(
                            "direct partition queue canonical deduplication drifted"
                        )
                    next_limit = len(attempted) + queued_unique_count
                    if next_limit <= partition_search_evaluation_limit:
                        partition_search_cap_reached = True
                        break
                    previous_limit = partition_search_evaluation_limit
                    admitted_limit = min(
                        next_limit,
                        _DIRECT_MEMBER_MAX_PARTITION_PROFILE_UPPER_BOUND,
                    )
                    if admitted_limit <= previous_limit:
                        partition_search_cap_reached = True
                        break
                    epoch = len(partition_search_limit_expansions) + 1
                    expansion = {
                        "epoch": epoch,
                        "max_epochs": (
                            partition_search_max_limit_expansion_count
                        ),
                        "initial_limit": (
                            _DIRECT_MEMBER_MAX_PARTITION_PROFILE_COUNT
                        ),
                        "previous_limit": previous_limit,
                        "evaluated_at_expansion": len(attempted),
                        "queued_unique_profile_count": queued_unique_count,
                        "queue_signature_digest_sha256": (
                            _direct_partition_queue_signature_digest(
                                queued_profiles
                            )
                        ),
                        "minimum_queued_shift_depth": min(
                            profile.proof_directed_boundary_motion_count
                            for profile in queued_profiles
                        ),
                        "maximum_queued_shift_depth": max(
                            profile.proof_directed_boundary_motion_count
                            for profile in queued_profiles
                        ),
                        "exact_frontier_continuation_upper_bound": next_limit,
                        "static_profile_upper_bound": (
                            _DIRECT_MEMBER_MAX_PARTITION_PROFILE_UPPER_BOUND
                        ),
                        "truncated_by_static_upper_bound": (
                            admitted_limit < next_limit
                        ),
                        "new_limit": admitted_limit,
                        "basis": (
                            "already_generated_parent_proof_bound_"
                            "canonical_queue_snapshot"
                        ),
                    }
                    partition_search_limit_expansions.append(expansion)
                    partition_search_evaluation_limit = admitted_limit
                    _emit_progress(
                        event=(
                            "direct_member_partition_search_limit_extended"
                        ),
                        phase="search_limit_extended",
                        result="exact_frontier_continuation_admitted",
                        evaluation_index=len(attempted),
                        evaluation_limit=partition_search_evaluation_limit,
                        **expansion,
                    )
                priority, _sequence, profile = queued.pop(0)
                error = _evaluate(profile)
                partition_search_composed_profile_evaluation_count += 1
                evaluated_signatures.add(profile.unit_counts)
                if error is None:
                    # Proof progress orders equal-cost exploration only.  It
                    # must not prune another candidate with the same changed
                    # boundary count and displacement.  Musical penalty is
                    # intentionally excluded because that candidate may win
                    # the actual warning/optimizer rank.
                    structural_cost = priority[2:4]
                    if (
                        minimum_feasible_structural_cost is None
                        or structural_cost < minimum_feasible_structural_cost
                    ):
                        minimum_feasible_structural_cost = structural_cost
                    continue
                _collect_counterfactual_secondary_profile(profile, error)
                if _direct_partition_failure_is_proven(error.diagnostics):
                    if minimum_feasible_structural_cost is None:
                        _record_terminal_safe_hold_candidate(profile, error)
                    # A feasible sibling must not suppress proof-authorized
                    # children of this fully evaluated peer.  Its children may
                    # have the same structural edit cost yet win on decoded
                    # continuity/optimizer score; the queue's bounded
                    # post-feasible filter decides whether they remain
                    # admissible.
                    _enqueue_children(profile, error)
            if (
                not feasible
                and queued
                and len(attempted) >= partition_search_evaluation_limit
                and not partition_search_strict_terminal_audition_limit_reached
            ):
                partition_search_cap_reached = True
            partition_search_primary_evaluation_count = len(attempted)
            if not feasible and counterfactual_secondary_profiles:
                partition_search_evaluation_limit = max(
                    partition_search_evaluation_limit,
                    partition_search_primary_evaluation_count
                    + len(counterfactual_secondary_profiles),
                )
                for profile in counterfactual_secondary_profiles:
                    partition_search_counterfactual_evaluation_count += 1
                    error = _evaluate(profile)
                    evaluated_signatures.add(profile.unit_counts)
                    if error is None:
                        partition_search_counterfactual_feasible_profile_count += 1
                    elif _direct_partition_failure_result(error.diagnostics) == (
                        "hard_infeasible"
                    ):
                        partition_search_counterfactual_hard_infeasible_profile_count += 1
                    elif _direct_partition_failure_result(error.diagnostics) == (
                        "capacity_exhausted"
                    ):
                        partition_search_counterfactual_capacity_exhausted_profile_count += 1
                    else:
                        partition_search_counterfactual_unproven_failure_profile_count += 1
                    if error is not None:
                        _record_terminal_safe_hold_candidate(profile, error)
                _emit_progress(
                    event="direct_member_severe_counterfactual_secondary_split",
                    phase="secondary_search_completed",
                    result=(
                        "feasible"
                        if feasible
                        else "capacity_exhausted"
                        if partition_search_counterfactual_capacity_exhausted_profile_count
                        else "unproven_failure"
                        if partition_search_counterfactual_unproven_failure_profile_count
                        else "hard_infeasible"
                    ),
                    contract=(
                        "bounded_diagnostic_severe_counterfactual_"
                        "secondary_partition_v1"
                    ),
                    primary_evaluated_profile_count=(
                        partition_search_primary_evaluation_count
                    ),
                    qualified_parent_count=(
                        partition_search_counterfactual_qualified_parent_count
                    ),
                    generated_profile_count=(
                        partition_search_counterfactual_generated_profile_count
                    ),
                    evaluated_profile_count=(
                        partition_search_counterfactual_evaluation_count
                    ),
                    feasible_profile_count=(
                        partition_search_counterfactual_feasible_profile_count
                    ),
                    hard_infeasible_profile_count=(
                        partition_search_counterfactual_hard_infeasible_profile_count
                    ),
                    capacity_exhausted_profile_count=(
                        partition_search_counterfactual_capacity_exhausted_profile_count
                    ),
                    unproven_failure_profile_count=(
                        partition_search_counterfactual_unproven_failure_profile_count
                    ),
                    promoted_queued_profile_count=(
                        partition_search_counterfactual_promoted_queued_profile_count
                    ),
                    maximum_profile_count=(
                        _DIRECT_MEMBER_MAX_COUNTERFACTUAL_SECONDARY_SPLIT_PROFILE_COUNT
                    ),
                    witness_selection_eligible=False,
                    witness_render_authorized=False,
                    every_profile_fully_reselected=True,
                    visual_gates_relaxed=False,
                )
            if (
                not feasible
                and (
                    not queued
                    or partition_search_strict_terminal_audition_limit_reached
                )
                and not partition_search_cap_reached
                and terminal_safe_hold_candidates
            ):
                partition_search_terminal_safe_hold_candidate_count = max(
                    partition_search_terminal_safe_hold_candidate_count,
                    len(terminal_safe_hold_candidates),
                )
                remaining_terminal_evaluation_limit = max(
                    0,
                    _DIRECT_MEMBER_MAX_SAFE_HOLD_PROFILE_COUNT
                    - partition_search_terminal_safe_hold_evaluation_count,
                )
                terminal_candidates = list(
                    sorted(
                        (
                            item
                            for signature, item in (
                                terminal_safe_hold_candidates.items()
                            )
                            if signature
                            not in partition_search_terminal_safe_hold_auditioned_signatures
                        ),
                        key=lambda item: (
                            -_direct_partition_terminal_candidate_progress(
                                item[0], item[1]
                            ),
                            item[0].structural_change_count,
                            item[0].total_unit_displacement,
                            item[0].musical_boundary_penalty,
                            item[0].profile_id,
                        ),
                    )[:remaining_terminal_evaluation_limit]
                )
                terminal_contract = (
                    "proof_progress_ordered_strict_terminal_audition_"
                    "then_bounded_safe_hold_cohort_v4"
                )
                terminal_trigger = (
                    "bounded_strict_terminal_audition_completed"
                    if partition_search_strict_terminal_audition_limit_reached
                    else "global_structural_candidate_queue_exhausted"
                )
                for terminal_evaluation_index, (
                    terminal_profile,
                    terminal_error,
                ) in enumerate(terminal_candidates, start=1):
                    terminal_global_evaluation_index = (
                        partition_search_terminal_safe_hold_evaluation_count + 1
                    )
                    terminal_signature = _direct_partition_signature_sha256(
                        terminal_profile.unit_counts
                    )
                    attempted_index = next(
                        (
                            index
                            for index, item in enumerate(attempted)
                            if item.get("partition_signature_sha256")
                            == terminal_signature
                        ),
                        None,
                    )
                    if attempted_index is None:
                        raise RuntimeError(
                            "terminal safe-hold candidate has no strict attempt"
                        )
                    terminal_payload = {
                        "contract": terminal_contract,
                        "attempted": True,
                        "trigger": terminal_trigger,
                        "candidate_count": (
                            partition_search_terminal_safe_hold_candidate_count
                        ),
                        "evaluation_index": terminal_global_evaluation_index,
                        "evaluation_limit": min(
                            partition_search_terminal_safe_hold_candidate_count,
                            _DIRECT_MEMBER_MAX_SAFE_HOLD_PROFILE_COUNT,
                        ),
                        "maximum_safe_hold_profile_count": (
                            _DIRECT_MEMBER_MAX_SAFE_HOLD_PROFILE_COUNT
                        ),
                        "maximum_strict_terminal_audition_count": (
                            partition_search_strict_terminal_audition_limit
                        ),
                        "strict_terminal_audition_limit_reached": (
                            partition_search_strict_terminal_audition_limit_reached
                        ),
                        "unevaluated_structural_profile_count": (
                            partition_search_strict_terminal_audition_pruned_profile_count
                        ),
                        "selected_profile_id": terminal_profile.profile_id,
                        "selected_partition_signature_sha256": terminal_signature,
                        "selected_strict_failed_segment_index": (
                            terminal_error.diagnostics.get(
                                "failed_at_segment_index"
                            )
                        ),
                        "selected_proof_progress": (
                            _direct_partition_terminal_candidate_progress(
                                terminal_profile,
                                terminal_error,
                            )
                        ),
                        "selection_policy": (
                            "hold_repairable_failure_only_then_proof_progress_"
                            "ranked_terminal_profiles_then_best_feasible_"
                            "visual_rank"
                        ),
                        "visual_gates_relaxed": False,
                    }
                    partition_search_terminal_safe_hold_evaluation_count += 1
                    partition_search_terminal_safe_hold_auditioned_signatures.add(
                        terminal_profile.unit_counts
                    )
                    _emit_progress(
                        event="direct_member_last_resort_safe_hold_search",
                        phase="last_resort_safe_hold_started",
                        result=None,
                        **terminal_payload,
                    )
                    terminal_selection: DirectMemberVisualSelection | None = None
                    terminal_hold_error: (
                        DirectMemberVisualSelectionError | None
                    ) = None
                    request_infeasibility_diagnostic = bool(
                        partition_search_cinematic_milp_infeasibility_diagnostic
                        is None
                        and terminal_evaluation_index == 1
                    )
                    terminal_config = (
                        replace(
                            selection_config,
                            diagnose_cinematic_milp_infeasibility=True,
                        )
                        if request_infeasibility_diagnostic
                        else selection_config
                    )
                    try:
                        terminal_selection = _select_profile_with_config(
                            terminal_profile,
                            terminal_config,
                            allow_safe_hold_search=True,
                        )
                    except DirectMemberVisualSelectionError as caught:
                        terminal_hold_error = caught
                        if request_infeasibility_diagnostic:
                            retained_diagnostic = find_member_infeasibility_relaxation(
                                caught.diagnostics
                            )
                            if retained_diagnostic is not None:
                                raw_diagnostic, diagnostic_origin = retained_diagnostic
                                partition_search_cinematic_milp_infeasibility_diagnostic = {
                                    "diagnostic_origin": diagnostic_origin,
                                    "profile_id": terminal_profile.profile_id,
                                    "partition_signature_sha256": (
                                        terminal_signature
                                    ),
                                    "proof_progress": (
                                        _direct_partition_terminal_candidate_progress(
                                            terminal_profile,
                                            terminal_error,
                                        )
                                    ),
                                    "diagnostic": dict(raw_diagnostic),
                                }
                                partition_search_cinematic_milp_infeasibility_profile = (
                                    terminal_profile
                                )
                    terminal_payload["result"] = (
                        "feasible"
                        if terminal_selection is not None
                        else "infeasible"
                    )
                    terminal_payload["final_failure"] = (
                        terminal_hold_error.diagnostics.get("failure")
                        if terminal_hold_error is not None
                        else None
                    )
                    attempted_item = attempted[attempted_index]
                    attempted_item["last_resort_safe_hold_search"] = dict(
                        terminal_payload
                    )
                    if terminal_selection is not None:
                        partition_search_terminal_safe_hold_success_count += 1
                        feasible.append((terminal_profile, terminal_selection))
                        terminal_rank = _direct_partition_selection_rank(
                            terminal_profile,
                            terminal_selection,
                        )
                        attempted_item[
                            "strict_status_before_last_resort_safe_hold"
                        ] = attempted_item.get("status")
                        strict_diagnostics = attempted_item.pop(
                            "diagnostics",
                            None,
                        )
                        if strict_diagnostics is not None:
                            attempted_item[
                                "strict_failure_before_last_resort_safe_hold"
                            ] = strict_diagnostics
                        attempted_item["status"] = "feasible"
                        attempted_item["hard_violation_count"] = 0
                        attempted_item["selection_rank"] = {
                            "warning_boundary_count": terminal_rank[0],
                            "optimizer_cost": terminal_rank[1],
                            "changed_span_count": terminal_rank[2],
                            "musical_boundary_penalty": terminal_rank[3],
                        }
                    else:
                        assert terminal_hold_error is not None
                        latest_failure_diagnostics = (
                            terminal_hold_error.diagnostics
                        )
                        all_failures_proven = bool(
                            all_failures_proven
                            and _direct_partition_failure_is_proven(
                                terminal_hold_error.diagnostics
                            )
                        )
                        attempted_item["last_resort_safe_hold_failure"] = (
                            _compact_direct_partition_failure(
                                terminal_hold_error,
                                span_count=len(terminal_profile.spans),
                            )
                        )
                        repair_child_evaluations: list[dict[str, Any]] = []
                        if len(terminal_candidates) < (
                            remaining_terminal_evaluation_limit
                        ):
                            repair_children = (
                                _direct_full_frame_proof_directed_child_profiles(
                                    timing_draft.segments,
                                    terminal_profile,
                                    terminal_hold_error.diagnostics,
                                )
                            )
                            for child in repair_children:
                                if len(terminal_candidates) >= (
                                    remaining_terminal_evaluation_limit
                                ):
                                    break
                                child_signature = (
                                    _direct_partition_signature_sha256(
                                        child.unit_counts
                                    )
                                )
                                if child.unit_counts in seen_signatures:
                                    partition_search_signature_deduplication_count += 1
                                    repair_child_evaluations.append(
                                        {
                                            "profile_id": child.profile_id,
                                            "partition_signature_sha256": (
                                                child_signature
                                            ),
                                            "result": "duplicate",
                                        }
                                    )
                                    continue
                                seen_signatures.add(child.unit_counts)
                                partition_search_generated_profile_count += 1
                                partition_search_composed_profile_evaluation_count += 1
                                child_error = _evaluate(child)
                                evaluated_signatures.add(child.unit_counts)
                                child_result = (
                                    "strict_feasible"
                                    if child_error is None
                                    else "strict_infeasible"
                                )
                                child_evaluation = {
                                    "profile_id": child.profile_id,
                                    "partition_signature_sha256": (
                                        child_signature
                                    ),
                                    "result": child_result,
                                    "terminal_audition_queued": False,
                                    "full_selector_recheck_completed": True,
                                    "visual_gates_relaxed": False,
                                }
                                repair_child_evaluations.append(
                                    child_evaluation
                                )
                                _emit_progress(
                                    event=(
                                        "direct_member_post_alignment_"
                                        "highlight_repair"
                                    ),
                                    phase="repair_child_evaluated",
                                    result=child_result,
                                    parent_profile_id=(
                                        terminal_profile.profile_id
                                    ),
                                    profile_id=child.profile_id,
                                    partition_signature_sha256=(
                                        child_signature
                                    ),
                                    full_selector_recheck_completed=True,
                                    visual_gates_relaxed=False,
                                )
                                if child_error is None:
                                    continue
                                if not (
                                    _direct_partition_failure_is_proven(
                                        child_error.diagnostics
                                    )
                                    and _direct_partition_terminal_hold_failure_is_eligible(
                                        child_error.diagnostics
                                    )
                                ):
                                    child_evaluation["result"] = (
                                        "strict_failure_not_terminal_authorized"
                                    )
                                    continue
                                terminal_safe_hold_candidates[
                                    child.unit_counts
                                ] = (child, child_error)
                                terminal_candidates.append(
                                    (child, child_error)
                                )
                                partition_search_terminal_safe_hold_candidate_count = max(
                                    partition_search_terminal_safe_hold_candidate_count,
                                    len(terminal_safe_hold_candidates),
                                )
                                child_evaluation[
                                    "terminal_audition_queued"
                                ] = True
                        if repair_child_evaluations:
                            attempted_item[
                                "post_alignment_highlight_repair_children"
                            ] = repair_child_evaluations
                    _emit_progress(
                        event="direct_member_last_resort_safe_hold_search",
                        phase="last_resort_safe_hold_completed",
                        **terminal_payload,
                    )
                if (
                    partition_search_terminal_safe_hold_success_count == 0
                    and partition_search_strict_terminal_audition_limit_reached
                    and queued
                ):
                    # Every authorized hold cohort member failed while bounded
                    # structural siblings remain. Report search capacity, never
                    # claim those unevaluated siblings were hard-infeasible.
                    partition_search_cap_reached = True
            if (
                not feasible
                and partition_search_strict_terminal_audition_limit_reached
                and queued
                and not terminal_safe_hold_candidates
            ):
                # The strict budget is a real capacity wall. If every proved
                # failure is content-invalid rather than hold-repairable, do
                # not claim the still-queued structural profiles were globally
                # infeasible merely because there was nothing valid to audition.
                partition_search_cap_reached = True
            if (
                not feasible
                and partition_search_cinematic_milp_infeasibility_profile
                is not None
                and isinstance(
                    partition_search_cinematic_milp_infeasibility_diagnostic,
                    Mapping,
                )
            ):
                raw_diagnostic = (
                    partition_search_cinematic_milp_infeasibility_diagnostic.get(
                        "diagnostic"
                    )
                )
                if isinstance(raw_diagnostic, Mapping):
                    hold_feedback_profiles = (
                        _direct_member_minimum_hold_feedback_partition_profiles(
                            timing_draft.segments,
                            partition_search_cinematic_milp_infeasibility_profile,
                            raw_diagnostic,
                        )
                    )
                    admitted_hold_feedback_profiles: list[
                        _DirectFullFramePartitionProfile
                    ] = []
                    for profile in hold_feedback_profiles:
                        if profile.unit_counts in seen_signatures:
                            partition_search_signature_deduplication_count += 1
                            continue
                        seen_signatures.add(profile.unit_counts)
                        partition_search_generated_profile_count += 1
                        admitted_hold_feedback_profiles.append(profile)
                    partition_search_minimum_hold_feedback_profiles = tuple(
                        admitted_hold_feedback_profiles
                    )
                    minimum_hold_feedback_feasible_count = 0
                    for profile in admitted_hold_feedback_profiles:
                        error = _evaluate(profile)
                        partition_search_minimum_hold_feedback_evaluation_count += 1
                        partition_search_composed_profile_evaluation_count += 1
                        evaluated_signatures.add(profile.unit_counts)
                        if error is None:
                            minimum_hold_feedback_feasible_count += 1
                            break
                        if _direct_partition_failure_is_proven(
                            error.diagnostics
                        ):
                            _record_terminal_safe_hold_candidate(
                                profile,
                                error,
                            )
                            _enqueue_children(profile, error)
                    minimum_hold_probe = raw_diagnostic.get(
                        "minimum_hold_probe"
                    )
                    _emit_progress(
                        event=(
                            "direct_member_minimum_hold_feedback_partition"
                        ),
                        phase="minimum_hold_feedback_evaluated",
                        result=(
                            "feasible"
                            if minimum_hold_feedback_feasible_count
                            else "all_candidates_infeasible"
                            if admitted_hold_feedback_profiles
                            else "no_novel_candidate"
                        ),
                        generated_profile_count=len(
                            admitted_hold_feedback_profiles
                        ),
                        evaluated_profile_count=(
                            partition_search_minimum_hold_feedback_evaluation_count
                        ),
                        feasible_profile_count=(
                            minimum_hold_feedback_feasible_count
                        ),
                        strict_maximum_same_source_hold_count=(
                            minimum_hold_probe.get(
                                "strict_maximum_same_source_hold_count"
                            )
                            if isinstance(minimum_hold_probe, Mapping)
                            else None
                        ),
                        minimum_same_source_hold_count=(
                            minimum_hold_probe.get(
                                "minimum_same_source_hold_count"
                            )
                            if isinstance(minimum_hold_probe, Mapping)
                            else None
                        ),
                        full_selector_recheck_required=True,
                        visual_gates_relaxed=False,
                    )
            partition_search_queued_frontier_profiles = tuple(
                item[2]
                for item in sorted(
                    queued,
                    key=lambda item: (
                        0
                        if any(
                            shift.trigger
                            == "lexicographic_minimum_hold_witness_cluster"
                            for shift in item[2].boundary_shifts
                        )
                        else 1,
                        item[0],
                        item[1],
                    ),
                )
            )
        elif not feasible and base_error is not None:
            if _direct_partition_failure_is_proven(base_error.diagnostics):
                bottlenecks = _direct_partition_failure_bottlenecks(
                    base_error.diagnostics,
                    span_count=len(base.spans),
                )
                primary_profiles = _direct_full_frame_shifted_partition_profiles(
                    timing_draft.segments,
                    base,
                    bottlenecks,
                    parent_diagnostics=base_error.diagnostics,
                )
                for profile in primary_profiles:
                    _evaluate(profile)
                partition_search_primary_evaluation_count = len(attempted)
    finally:
        if owned_provider is not None:
            provider_cache_diagnostics = owned_provider.cache_diagnostics()
            owned_provider.close()
        else:
            cache_method = getattr(provider, "cache_diagnostics", None)
            provider_cache_diagnostics = (
                cache_method() if callable(cache_method) else None
            )

